import Foundation

func readUInt16LE(_ data: [UInt8], _ offset: Int) -> UInt16 {
    return UInt16(data[offset]) | (UInt16(data[offset+1]) << 8)
}

func readInt32LE(_ data: [UInt8], _ offset: Int) -> Int32 {
    return Int32(bitPattern: UInt32(data[offset]) | (UInt32(data[offset+1]) << 8) | (UInt32(data[offset+2]) << 16) | (UInt32(data[offset+3]) << 24))
}

func readUInt32LE(_ data: [UInt8], _ offset: Int) -> UInt32 {
    return UInt32(data[offset]) | (UInt32(data[offset+1]) << 8) | (UInt32(data[offset+2]) << 16) | (UInt32(data[offset+3]) << 24)
}

func trailingZeros(_ mask: UInt32) -> Int {
    if mask == 0 { return 32 }
    var count = 0
    var m = mask
    while m & 1 == 0 {
        count += 1
        m >>= 1
    }
    return count
}

func popcount(_ mask: UInt32) -> Int {
    var count = 0
    var m = mask
    while m != 0 {
        count += Int(m & 1)
        m >>= 1
    }
    return count
}

func extractChannel(_ pixel: UInt32, mask: UInt32) -> UInt8 {
    let s = trailingZeros(mask)
    let n = popcount(mask)
    let m = UInt32((1 << n) - 1)
    let v = (pixel & mask) >> s
    return UInt8((v * 255 + m / 2) / m)
}

func isDark(r: UInt8, g: UInt8, b: UInt8) -> Bool {
    return (299 * Int(r) + 587 * Int(g) + 114 * Int(b)) / 1000 < 128
}

func processFile(path: String, fileName: String) {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)

    guard bytes.count >= 14 else { return }
    if bytes[0] != 0x42 || bytes[1] != 0x4D { return }

    let bfOffBits = Int(readUInt32LE(bytes, 10))

    let dibSize = Int(readUInt32LE(bytes, 14))
    guard dibSize == 40 || dibSize == 108 || dibSize == 124 else { return }

    let width = Int(readInt32LE(bytes, 18))
    let heightRaw = Int(readInt32LE(bytes, 22))
    let height = abs(heightRaw)
    let bottomUp = heightRaw > 0

    let bitsPerPixel = Int(readUInt16LE(bytes, 28))
    let compression = Int(readUInt32LE(bytes, 30))
    let coloursUsed = Int(readUInt32LE(bytes, 46))

    if compression != 0 && compression != 3 {
        print("== \(fileName)")
        print("error: unsupported compression \(compression)")
        return
    }

    var redMask: UInt32 = 0xFF
    var greenMask: UInt32 = 0xFF00
    var blueMask: UInt32 = 0xFF0000

    if compression == 3 {
        if dibSize == 40 {
            redMask = readUInt32LE(bytes, 54)
            greenMask = readUInt32LE(bytes, 58)
            blueMask = readUInt32LE(bytes, 62)
        } else {
            redMask = readUInt32LE(bytes, 14 + 40)
            greenMask = readUInt32LE(bytes, 14 + 44)
            blueMask = readUInt32LE(bytes, 14 + 48)
        }
    }

    let paletteOffset = 14 + dibSize
    var palette: [(UInt8, UInt8, UInt8)] = []
    if bitsPerPixel <= 8 {
        let numColors = coloursUsed > 0 ? coloursUsed : (1 << bitsPerPixel)
        for i in 0..<numColors {
            let off = paletteOffset + i * 4
            let b = bytes[off]
            let g = bytes[off + 1]
            let r = bytes[off + 2]
            palette.append((r, g, b))
        }
    }

    let pixelDataOffset = bfOffBits
    let rowBytes = ((width * bitsPerPixel + 31) / 32) * 4

    var ink = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)

    for y in 0..<height {
        let storedRow = bottomUp ? (height - 1 - y) : y
        let rowOffset = pixelDataOffset + storedRow * rowBytes

        for x in 0..<width {
            var r: UInt8 = 0, g: UInt8 = 0, b: UInt8 = 0

            switch bitsPerPixel {
            case 1:
                let byteIdx = x / 8
                let bitIdx = 7 - (x % 8)
                let idx = Int((bytes[rowOffset + byteIdx] >> bitIdx) & 1)
                (r, g, b) = palette[idx]
            case 4:
                let byteIdx = x / 2
                let nibbleIdx = x % 2
                let byte = bytes[rowOffset + byteIdx]
                let idx = Int(nibbleIdx == 0 ? (byte >> 4) : (byte & 0x0F))
                (r, g, b) = palette[idx]
            case 8:
                let idx = Int(bytes[rowOffset + x])
                (r, g, b) = palette[idx]
            case 24:
                let off = rowOffset + x * 3
                b = bytes[off]
                g = bytes[off + 1]
                r = bytes[off + 2]
            case 32:
                let off = rowOffset + x * 4
                if compression == 0 {
                    b = bytes[off]
                    g = bytes[off + 1]
                    r = bytes[off + 2]
                } else {
                    let pixel = readUInt32LE(bytes, off)
                    r = extractChannel(pixel, mask: redMask)
                    g = extractChannel(pixel, mask: greenMask)
                    b = extractChannel(pixel, mask: blueMask)
                }
            default:
                break
            }

            ink[y][x] = isDark(r: r, g: g, b: b)
        }
    }

    var inkCount = 0
    for y in 0..<height {
        for x in 0..<width {
            if ink[y][x] { inkCount += 1 }
        }
    }

    var visited = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)

    struct Component {
        var firstX: Int
        var firstY: Int
        var minX: Int
        var minY: Int
        var maxX: Int
        var maxY: Int
        var count: Int
    }

    var components: [Component] = []

    let dx = [-1, 0, 1, -1, 1, -1, 0, 1]
    let dy = [-1, -1, -1, 0, 0, 1, 1, 1]

    for y in 0..<height {
