            if (minorUnits > 0) {
                sb.append('.');
                for (int i = 0; i < minorUnits; i++) sb.append('0');
            }
            return sb.toString();
        }

        String sign = "";
        if (value.signum() < 0) {
            sign = "-";
            value = value.negate();
        }

        String plain = value.toPlainString();
        String intPart;
        String decPart;
        int dotPos = plain.indexOf('.');
        if (dotPos >= 0) {
            intPart = plain.substring(0, dotPos);
            decPart = plain.substring(dotPos + 1);
        } else {
            intPart = plain;
            decPart = "";
        }

        StringBuilder formatted = new StringBuilder();
        int len = intPart.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                formatted.append(',');
            }
            formatted.append(intPart.charAt(i));
        }

        if (minorUnits > 0) {
            formatted.append('.');
            if (decPart.length() > minorUnits) {
                decPart = decPart.substring(0, minorUnits);
            }
            while (decPart.length() < minorUnits) {
                decPart += "0";
            }
            formatted.append(decPart);
        }

        return sign + formatted.toString();
    }
