                } else if (b == '\\') {
                    sb.append("\\\\");
                } else if (b >= 0x20 && b <= 0x7E) {
                    sb.append((char) b);
                } else {
                    sb.append(String.format("\\%03d", b));
                }
            }
            sb.append('"');
            pos += strLen;
        }

        return sb.toString();
