import sys
import json
import base64
import hmac
import hashlib
import re


def is_valid_base64url(s):
    if not s:
        return False
    if not re.fullmatch(r'[A-Za-z0-9\-_]+', s):
        return False
    if len(s) % 4 == 1:
        return False
    return True


def decode_base64url(s):
    padding = 4 - (len(s) % 4)
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)


def verify_token(token, keys, now, leeway, issuer, audience):
    # Rule 1: MALFORMED
    parts = token.split('.')
    if len(parts) != 3:
        return 'MALFORMED'

    header_b64, payload_b64, sig_b64 = parts

    for seg in parts:
        if not is_valid_base64url(seg):
            return 'MALFORMED'

    try:
        header_bytes = decode_base64url(header_b64)
        payload_bytes = decode_base64url(payload_b64)
    except Exception:
        return 'MALFORMED'

    try:
        header = json.loads(header_bytes.decode('utf-8'))
        payload = json.loads(payload_bytes.decode('utf-8'))
    except Exception:
        return 'MALFORMED'

    if not isinstance(header, dict) or not isinstance(payload, dict):
        return 'MALFORMED'

    # Rule 2: UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
        return 'UNSUPPORTED_ALG'

    # Rule 3: UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys:
        return 'UNKNOWN_KEY'

    key = keys[kid]

    # Rule 4: ALG_MISMATCH
    if key['alg'] != alg:
        return 'ALG_MISMATCH'

    # Rule 5: BAD_SIGNATURE
    sig_bytes = decode_base64url(sig_b64)
    signing_input = (header_b64 + '.' + payload_b64).encode('ascii')
    secret = decode_base64url(key['k'])

    hash_func = {'HS256': hashlib.sha256, 'HS384': hashlib.sha384, 'HS512': hashlib.sha512}[alg]
    expected_sig = hmac.new(secret, signing_input, hash_func).digest()

    if sig_bytes != expected_sig:
        return 'BAD_SIGNATURE'

    # Rule 6: EXPIRED
    if 'exp' in payload:
        exp = payload['exp']
        if now >= exp + leeway:
            return 'EXPIRED'

    # Rule 7: NOT_YET_VALID
    if 'nbf' in payload:
        nbf = payload['nbf']
        if now + leeway < nbf:
            return 'NOT_YET_VALID'

    # Rule 8: BAD_ISSUER
    if 'iss' not in payload:
        return 'BAD_ISSUER'
    iss = payload['iss']
    if not isinstance(iss, str) or iss != issuer:
        return 'BAD_ISSUER'

    # Rule 9: BAD_AUDIENCE
    if 'aud' not in payload:
        return 'BAD_AUDIENCE'
    aud = payload['aud']
    if isinstance(aud, str):
        if aud != audience:
            return 'BAD_AUDIENCE'
    elif isinstance(aud, list):
        if audience not in aud:
            return 'BAD_AUDIENCE'
    else:
        return 'BAD_AUDIENCE'

    # VALID
    sub = payload['sub']
    scope = payload.get('scope')
    if isinstance(scope, str):
        scopes = [s for s in scope.split(' ') if s]
        scopes = sorted(set(scopes))
        scopes_str = ','.join(scopes)
    else:
        scopes_str = ''

    return f"VALID sub={sub} scope={scopes_str}"


def main():
    directory = sys.argv[1]

    with open(f"{directory}/config.json", 'r', encoding='utf-8') as f:
        config = json.load(f)

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = {k['kid']: k for k in config['keys']}

    with open(f"{directory}/tokens.txt", 'r', encoding='utf-8') as f:
        content = f.read()

    lines = content.split('\n')

    valid_count = 0
    invalid_count = 0
    results = []
    token_num = 0

    for line in lines:
        stripped = line.strip(' \t')
        if not stripped:
            continue
        token_num += 1

        result = verify_token(stripped, keys, now, leeway, issuer, audience)

        if result.startswith('VALID'):
            valid_count += 1
        else:
            invalid_count += 1

        results.append(f"{token_num}: {result}")

    for r in results:
        print(r)

    print()
    print(f"valid={valid_count} invalid={invalid_count}")


if __name__ == '__main__':
    main()

