func parseResponse(_ data: [UInt8]) -> (rcode: Int, tc: Bool, records: [AnswerRecord]) {
    let flags = (Int(data[2]) << 8) | Int(data[3])
    let rcode = flags & 0xF
    let tc = (flags >> 9) & 1
    let qdcount = (Int(data[4]) << 8) | Int(data[5])
    let ancount = (Int(data[6]) << 8) | Int(data[7])

    var off = 12
    // skip questions
    for _ in 0..<qdcount {
        _ = parseDNSName(data, &off)
        off += 4
    }

    var records: [AnswerRecord] = []
    for _ in 0..<ancount {
        let name = parseDNSName(data, &off)
        let rtype = (UInt16(data[off]) << 8) | UInt16(data[off+1])
        // class at off+2..off+3
        let ttl = (UInt32(data[off+4]) << 24) | (UInt32(data[off+5]) << 16) | (UInt32(data[off+6]) << 8) | UInt32(data[off+7])
        off += 8
        let rdlen = (Int(data[off]) << 8) | Int(data[off+1])
        off += 2
        let rdataOff = off
        let rdata = Array(data[off..<off+rdlen])
        off += rdlen
        records.append(AnswerRecord(name: name, ttl: ttl, type: rtype, rdata: rdata, rdataOffset: rdataOff))
    }
    return (rcode, tc == 1, records)
}

func formatRData(type: UInt16, rdata: [UInt8], fullMsg: [UInt8], rdataOff: Int) -> String {
    switch type {
    case 1: // A
        guard rdata.count >= 4 else { return "" }
        return "\(rdata[0]).\(rdata[1]).\(rdata[2]).\(rdata[3])"
    case 28: // AAAA
        guard rdata.count >= 16 else { return "" }
        return formatIPv6(rdata)
    case 5: // CNAME
        var o = rdataOff
        return parseDNSName(fullMsg, &o)
    case 15: // MX
        guard rdata.count >= 2 else { return "" }
        let pref = (Int(rdata[0]) << 8) | Int(rdata[1])
        var o = rdataOff + 2
        let exch = parseDNSName(fullMsg, &o)
        return "\(pref) \(exch)"
    case 16: // TXT
        var parts: [String] = []
        var p = 0
        while p < rdata.count {
            let len = Int(rdata[p]); p += 1
            let s = Array(rdata[p..<p+len]); p += len
            parts.append(escapeTXT(s))
        }
        return parts.joined(separator: " ")
    default:
        if rdata.isEmpty {
            return "\\# 0"
        } else {
            let hex = rdata.map { String(format: "%02x", $0) }.joined()
            return "\\# \(rdata.count) \(hex)"
        }
    }
}

