        int len = Math.min(ba.length, bb.length);
        for (int i = 0; i < len; i++) {
            int cmp = (ba[i] & 0xFF) - (bb[i] & 0xFF);
            if (cmp != 0) return cmp;
        }
        return ba.length - bb.length;
    }

