            Set<Err> errors = new HashSet<>();
            validate(rootSchema, instances.aVal.get(n), "#", "#", errors);

            if (errors.isEmpty()) {
                System.out.println(n + ": valid");
                validCount++;
            } else {
                System.out.println(n + ": invalid (" + errors.size() + ")");
                List<Err> sorted = new ArrayList<>(errors);
                sorted.sort((a, b) -> {
                    int c = compareBytes(a.iloc(), b.iloc());
                    if (c != 0) return c;
                    return compareBytes(a.sloc(), b.sloc());
                });
                for (Err e : sorted) {
                    System.out.println("  " + e.iloc() + " " + e.sloc());
                }
                invalidCount++;
            }
        }

