            }
        }
    }

    // Object keywords
    if (type === 'object') {
        const keys = Object.keys(instance);

        if ('properties' in schema) {
            const props = schema['properties'];
            for (const key of keys) {
                if (key in props) {
                    errors.push(...validate(instance[key], props[key],
                        instLoc + '/' + encodeToken(key),
                        schemaLoc + '/properties/' + encodeToken(key), rootSchema));
                }
            }
        }

        if ('required' in schema) {
            const req = schema['required'];
            for (let j = 0; j < req.length; j++) {
                if (!(req[j] in instance)) {
                    errors.push({ inst: instLoc, schema: schemaLoc + '/required/' + j });
                }
            }
        }

        if ('additionalProperties' in schema) {
            const propKeys: Set<string> = 'properties' in schema
                ? new Set(Object.keys(schema['properties']))
                : new Set();
            for (const key of keys) {
                if (!propKeys.has(key)) {
                    errors.push(...validate(instance[key], schema['additionalProperties'],
                        instLoc + '/' + encodeToken(key),
                        schemaLoc + '/additionalProperties', rootSchema));
                }
            }
        }

        if ('minProperties' in schema && keys.length < schema['minProperties']) {
            errors.push({ inst: instLoc, schema: schemaLoc + '/minProperties' });
        }
        if ('maxProperties' in schema && keys.length > schema['maxProperties']) {
            errors.push({ inst: instLoc, schema: schemaLoc + '/maxProperties' });
        }
    }

    // Applicators
    if ('allOf' in schema) {
        const subs = schema['allOf'];
        for (let i = 0; i < subs.length; i++) {
            errors.push(...validate(instance, subs[i], instLoc, schemaLoc + '/allOf/' + i, rootSchema));
        }
    }

    if ('anyOf' in schema) {
        const subs = schema['anyOf'];
        let anyAccepted = false;
        for (let i = 0; i < subs.length; i++) {
            const subErrors = validate(instance, subs[i], instLoc, schemaLoc + '/anyOf/' + i, rootSchema);
            if (subErrors.length === 0) { anyAccepted = true; break; }
        }
        if (!anyAccepted) {
            errors.push({ inst: instLoc, schema: schemaLoc + '/anyOf' });
        }
    }

    if ('oneOf' in schema) {
        const subs = schema['oneOf'];
        let count = 0;
        for (let i = 0; i < subs.length; i++) {
            const subErrors = validate(instance, subs[i], instLoc, schemaLoc + '/oneOf/' + i, rootSchema);
            if (subErrors.length === 0) count++;
        }
        if (count !== 1) {
            errors.push({ inst: instLoc, schema: schemaLoc + '/oneOf' });
        }
    }

    if ('not' in schema) {
        const notErrors = validate(instance, schema['not'], instLoc, schemaLoc + '/not', rootSchema);
        if (notErrors.length === 0) {
            errors.push({ inst: instLoc, schema: schemaLoc + '/not' });
        }
    }

    if ('if' in schema) {
        const ifErrors = validate(instance, schema['if'], instLoc, schemaLoc + '/if', rootSchema);
        if (ifErrors.length === 0) {
            if ('then' in schema) {
                errors.push(...validate(instance, schema['then'], instLoc, schemaLoc + '/then', rootSchema));
            }
        } else {
            if ('else' in schema) {
                errors.push(...validate(instance, schema['else'], instLoc, schemaLoc + '/else', rootSchema));
            }
        }
    }

    return errors;
}

function compareByCodePoints(a: string, b: string): number {
    const aArr = [...a];
    const bArr = [...b];
    const minLen = Math.min(aArr.length, bArr.length);
    for (let i = 0; i < minLen; i++) {
        const ca = aArr[i].codePointAt(0)!;
        const cb = bArr[i].codePointAt(0)!;
        if (ca !== cb) return ca < cb ? -1 : 1;
    }
    return aArr.length - bArr.length;
}

