import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class Main {

    static String jsonStr;
    static int jpos;

    static Object parseJson(String s) {
        jsonStr = s;
        jpos = 0;
        return parseValue();
    }

    static void skipWs() {
        while (jpos < jsonStr.length() && (jsonStr.charAt(jpos) == ' ' || jsonStr.charAt(jpos) == '\t'
                || jsonStr.charAt(jpos) == '\n' || jsonStr.charAt(jpos) == '\r')) {
            jpos++;
        }
    }

    static Object parseValue() {
        skipWs();
        char c = jsonStr.charAt(jpos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't') { jpos += 4; return Boolean.TRUE; }
        if (c == 'f') { jpos += 5; return Boolean.FALSE; }
        if (c == 'n') { jpos += 4; return null; }
        return parseNumber();
    }

    @SuppressWarnings("unchecked")
    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        jpos++; // skip {
        skipWs();
        if (jsonStr.charAt(jpos) == '}') { jpos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            jpos++; // skip :
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            if (jsonStr.charAt(jpos) == '}') { jpos++; break; }
            jpos++; // skip ,
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        jpos++; // skip [
        skipWs();
        if (jsonStr.charAt(jpos) == ']') { jpos++; return list; }
        while (true) {
            list.add(parseValue());
            skipWs();
            if (jsonStr.charAt(jpos) == ']') { jpos++; break; }
            jpos++; // skip ,
        }
        return list;
    }

    static String parseString() {
        jpos++; // skip opening "
        StringBuilder sb = new StringBuilder();
        while (jsonStr.charAt(jpos) != '"') {
            if (jsonStr.charAt(jpos) == '\\') {
                jpos++;
                char esc = jsonStr.charAt(jpos);
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        String hex = jsonStr.substring(jpos + 1, jpos + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        jpos += 4;
                        break;
                    default: sb.append(esc);
                }
            } else {
                sb.append(jsonStr.charAt(jpos));
            }
            jpos++;
        }
        jpos++; // skip closing "
        return sb.toString();
    }

    static Double parseNumber() {
        int start = jpos;
        if (jsonStr.charAt(jpos) == '-') jpos++;
        while (jpos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jpos))) jpos++;
        if (jpos < jsonStr.length() && jsonStr.charAt(jpos) == '.') {
            jpos++;
            while (jpos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jpos))) jpos++;
        }
        if (jpos < jsonStr.length() && (jsonStr.charAt(jpos) == 'e' || jsonStr.charAt(jpos) == 'E')) {
            jpos++;
            if (jsonStr.charAt(jpos) == '+' || jsonStr.charAt(jpos) == '-') jpos++;
            while (jpos < jsonStr.length() && Character.isDigit(jsonStr.charAt(jpos))) jpos++;
        }
        return Double.parseDouble(jsonStr.substring(start, jpos));
    }

    static boolean isValidBase64url(String s) {
        if (s.length() % 4 == 1) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_')) {
                return false;
            }
        }
        return true;
    }

    static byte[] base64urlDecode(String s) {
        String std = s.replace('-', '+').replace('_', '/');
        int pad = (4 - std.length() % 4) % 4;
        if (pad > 0) std += "=".repeat(pad);
        return Base64.getDecoder().decode(std);
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dir = args[0];

        String configContent = new String(Files.readAllBytes(Paths.get(dir, "config.json")), StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) parseJson(configContent);

