use std::collections::HashSet;
use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<JsonValue>),
    Obj(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_ws();
        match self.peek() {
            Some(b'n') => { self.pos += 4; JsonValue::Null }
            Some(b't') => { self.pos += 4; JsonValue::Bool(true) }
            Some(b'f') => { self.pos += 5; JsonValue::Bool(false) }
            Some(b'"') => JsonValue::Str(self.parse_string()),
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_object(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1; // skip "
        let mut result = String::new();
        loop {
            let c = self.input[self.pos];
            self.pos += 1;
            match c {
                b'"' => break,
                b'\\' => {
                    let e = self.input[self.pos];
                    self.pos += 1;
                    match e {
                        b'"' => result.push('"'),
                        b'\\' => result.push('\\'),
                        b'/' => result.push('/'),
                        b'b' => result.push('\u{0008}'),
                        b'f' => result.push('\u{000C}'),
                        b'n' => result.push('\n'),
                        b'r' => result.push('\r'),
                        b't' => result.push('\t'),
                        b'u' => {
                            let cp = self.parse_hex4();
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                assert!(self.input[self.pos] == b'\\');
                                assert!(self.input[self.pos + 1] == b'u');
                                self.pos += 2;
                                let lo = self.parse_hex4();
                                let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                result.push(char::from_u32(combined).unwrap());
                            } else {
                                result.push(char::from_u32(cp).unwrap());
                            }
                        }
                        _ => unreachable!(),
                    }
                }
                _ => {
                    self.pos -= 1;
                    let start = self.pos;
                    let len = if c < 0x80 { 1 }
                              else if c < 0xE0 { 2 }
                              else if c < 0xF0 { 3 }
                              else { 4 };
                    self.pos += len;
                    let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
                    result.push_str(s);
                }
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.input[self.pos];
            self.pos += 1;
            val = val * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => unreachable!(),
            };
        }
        val
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        if self.input[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        s.parse::<f64>().unwrap()
    }

    fn parse_array(&mut self) -> JsonValue {
        self.pos += 1;
        let mut arr = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return JsonValue::Arr(arr); }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            if self.peek() == Some(b']') { self.pos += 1; break; }
            self.pos += 1;
        }
        JsonValue::Arr(arr)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.pos += 1;
        let mut obj = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return JsonValue::Obj(obj); }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.pos += 1; // skip :
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            if self.peek() == Some(b'}') { self.pos += 1; break; }
            self.pos += 1; // skip ,
        }
        JsonValue::Obj(obj)
    }
}

fn get_key<'a>(obj: &'a [(String, JsonValue)], key: &str) -> Option<&'a JsonValue> {
    obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
}

fn is_integer(n: f64) -> bool {
    n == n.trunc()
}

fn type_matches(instance: &JsonValue, tname: &str) -> bool {
    match tname {
        "null" => matches!(instance, JsonValue::Null),
        "boolean" => matches!(instance, JsonValue::Bool(_)),
        "number" => matches!(instance, JsonValue::Num(_)),
        "integer" => matches!(instance, JsonValue::Num(n) if is_integer(*n)),
        "string" => matches!(instance, JsonValue::Str(_)),
        "array" => matches!(instance, JsonValue::Arr(_)),
        "object" => matches!(instance, JsonValue::Obj(_)),
        _ => false,
    }
}

fn deep_eq(a: &JsonValue, b: &JsonValue) -> bool {
    match (a, b) {
        (JsonValue::Null, JsonValue::Null) => true,
        (JsonValue::Bool(x), JsonValue::Bool(y)) => x == y,
        (JsonValue::Num(x), JsonValue::Num(y)) => x == y,
        (JsonValue::Str(x), JsonValue::Str(y)) => x == y,
        (JsonValue::Arr(x), JsonValue::Arr(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| deep_eq(a, b))
        }
        (JsonValue::Obj(x), JsonValue::Obj(y)) => {
            if x.len() != y.len() { return false; }
            x.iter().all(|(k, v)| {
                y.iter().any(|(k2, v2)| k == k2 && deep_eq(v, v2))
            })
        }
        _ => false,
    }
}

fn escape_token(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '~' => result.push_str("~0"),
            '/' => result.push_str("~1"),
            _ => result.push(c),
        }
    }
    result
}

fn unescape_token(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '~' {
            match chars.peek() {
                Some('0') => { chars.next(); result.push('~'); }
                Some('1') => { chars.next(); result.push('/'); }
                _ => result.push('~'),
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn resolve_ref<'a>(ref_str: &str, root: &'a JsonValue) -> (&'a JsonValue, String) {
    if ref_str == "#" {
        return (root, "#".to_string());
    }
    // #/$defs/<name>
    let prefix = "#/$defs/";
    assert!(ref_str.starts_with(prefix));
    let name_escaped = &ref_str[prefix.len()..];
    let name = unescape_token(name_escaped);
    if let JsonValue::Obj(root_obj) = root {
        if let Some(defs) = get_key(root_obj, "$defs") {
            if let JsonValue::Obj(defs_obj) = defs {
                if let Some(target) = get_key(defs_obj, &name) {
                    return (target, format!("#/$defs/{}", name_escaped));
                }
            }
        }
    }
    panic!("Cannot resolve $ref: {}", ref_str);
}

fn validate(
    instance: &JsonValue,
    schema: &JsonValue,
    inst_loc: &str,
    sch_loc: &str,
    root: &JsonValue,
    errors: &mut HashSet<(String, String)>,
) {
    match schema {
        JsonValue::Bool(true) => {}
        JsonValue::Bool(false) => {
            errors.insert((inst_loc.to_string(), sch_loc.to_string()));
        }
        JsonValue::Obj(keywords) => {
            process_keywords(keywords, instance, inst_loc, sch_loc, root, errors);
        }
        _ => {}
    }
}

fn process_keywords(
    keywords: &[(String, JsonValue)],
    instance: &JsonValue,
    inst_loc: &str,
    sch_loc: &str,
    root: &JsonValue,
    errors: &mut HashSet<(String, String)>,
) {
    // type
    if let Some(type_val) = get_key(keywords, "type") {
        let matches = match type_val {
            JsonValue::Str(t) => type_matches(instance, t),
            JsonValue::Arr(types) => types.iter().any(|t| {
                if let JsonValue::Str(name) = t { type_matches(instance, name) } else { false }
            }),
            _ => true,
        };
        if !matches {
            errors.insert((inst_loc.to_string(), format!("{}/type", sch_loc)));
        }
    }

    // enum
    if let Some(enum_val) = get_key(keywords, "enum") {
        if let JsonValue::Arr(candidates) = enum_val {
            if !candidates.iter().any(|c| deep_eq(instance, c)) {
                errors.insert((inst_loc.to_string(), format!("{}/enum", sch_loc)));
            }
        }
    }

    // const
    if let Some(const_val) = get_key(keywords, "const") {
        if !deep_eq(instance, const_val) {
            errors.insert((inst_loc.to_string(), format!("{}/const", sch_loc)));
        }
    }

    // Number keywords
    if let JsonValue::Num(n) = instance {
        if let Some(v) = get_key(keywords, "minimum") {
            if let JsonValue::Num(min) = v {
                if *n < *min {
                    errors.insert((inst_loc.to_string(), format!("{}/minimum", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "maximum") {
            if let JsonValue::Num(max) = v {
                if *n > *max {
                    errors.insert((inst_loc.to_string(), format!("{}/maximum", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "exclusiveMinimum") {
            if let JsonValue::Num(min) = v {
                if *n <= *min {
                    errors.insert((inst_loc.to_string(), format!("{}/exclusiveMinimum", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "exclusiveMaximum") {
            if let JsonValue::Num(max) = v {
                if *n >= *max {
                    errors.insert((inst_loc.to_string(), format!("{}/exclusiveMaximum", sch_loc)));
                }
            }
        }
    }

    // String keywords
    if let JsonValue::Str(s) = instance {
        let len = s.chars().count() as f64;
        if let Some(v) = get_key(keywords, "minLength") {
            if let JsonValue::Num(min) = v {
                if len < *min {
                    errors.insert((inst_loc.to_string(), format!("{}/minLength", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "maxLength") {
            if let JsonValue::Num(max) = v {
                if len > *max {
                    errors.insert((inst_loc.to_string(), format!("{}/maxLength", sch_loc)));
                }
            }
        }
    }

    // Array keywords
    if let JsonValue::Arr(items) = instance {
        let count = items.len();
        if let Some(v) = get_key(keywords, "minItems") {
            if let JsonValue::Num(min) = v {
                if (count as f64) < *min {
                    errors.insert((inst_loc.to_string(), format!("{}/minItems", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "maxItems") {
            if let JsonValue::Num(max) = v {
                if (count as f64) > *max {
                    errors.insert((inst_loc.to_string(), format!("{}/maxItems", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "uniqueItems") {
            if let JsonValue::Bool(true) = v {
                let mut has_dup = false;
                'outer: for i in 0..count {
                    for j in (i + 1)..count {
                        if deep_eq(&items[i], &items[j]) {
                            has_dup = true;
                            break 'outer;
                        }
                    }
                }
                if has_dup {
                    errors.insert((inst_loc.to_string(), format!("{}/uniqueItems", sch_loc)));
                }
            }
        }

        // prefixItems
        let prefix_len: usize = if let Some(pi) = get_key(keywords, "prefixItems") {
            if let JsonValue::Arr(schemas) = pi {
                for (i, sub_schema) in schemas.iter().enumerate() {
                    if i < count {
                        let child_inst_loc = format!("{}/{}", inst_loc, i);
                        let child_sch_loc = format!("{}/prefixItems/{}", sch_loc, i);
                        validate(&items[i], sub_schema, &child_inst_loc, &child_sch_loc, root, errors);
                    }
                }
                schemas.len()
            } else { 0 }
        } else { 0 };

        // items
        if let Some(items_schema) = get_key(keywords, "items") {
            for i in prefix_len..count {
                let child_inst_loc = format!("{}/{}", inst_loc, i);
                let child_sch_loc = format!("{}/items", sch_loc);
                validate(&items[i], items_schema, &child_inst_loc, &child_sch_loc, root, errors);
            }
        }
    }

    // Object keywords
    if let JsonValue::Obj(members) = instance {
        let member_count = members.len();

        if let Some(v) = get_key(keywords, "minProperties") {
            if let JsonValue::Num(min) = v {
                if (member_count as f64) < *min {
                    errors.insert((inst_loc.to_string(), format!("{}/minProperties", sch_loc)));
                }
            }
        }
        if let Some(v) = get_key(keywords, "maxProperties") {
            if let JsonValue::Num(max) = v {
                if (member_count as f64) > *max {
                    errors.insert((inst_loc.to_string(), format!("{}/maxProperties", sch_loc)));
                }
            }
        }

        // required
        if let Some(req) = get_key(keywords, "required") {
            if let JsonValue::Arr(names) = req {
                for (j, name) in names.iter().enumerate() {
                    if let JsonValue::Str(n) = name {
                        if !members.iter().any(|(k, _)| k == n) {
                            errors.insert((inst_loc.to_string(), format!("{}/required/{}", sch_loc, j)));
                        }
                    }
                }
            }
        }

        // properties
        let prop_keys: Vec<String> = if let Some(props) = get_key(keywords, "properties") {
            if let JsonValue::Obj(props_obj) = props {
                for (name, sub_schema) in props_obj {
                    if let Some((_, val)) = members.iter().find(|(k, _)| k == name) {
                        let child_inst_loc = format!("{}/{}", inst_loc, escape_token(name));
                        let child_sch_loc = format!("{}/properties/{}", sch_loc, escape_token(name));
                        validate(val, sub_schema, &child_inst_loc, &child_sch_loc, root, errors);
                    }
                }
                props_obj.iter().map(|(k, _)| k.clone()).collect()
            } else { vec![] }
        } else { vec![] };

        // additionalProperties
        if let Some(additional) = get_key(keywords, "additionalProperties") {
            for (name, val) in members {
                if !prop_keys.contains(name) {
                    let child_inst_loc = format!("{}/{}", inst_loc, escape_token(name));
                    let child_sch_loc = format!("{}/additionalProperties", sch_loc);
                    validate(val, additional, &child_inst_loc, &child_sch_loc, root, errors);
                }
            }
        }
    }

    // allOf
    if let Some(v) = get_key(keywords, "allOf") {
        if let JsonValue::Arr(schemas) = v {
            for (i, sub) in schemas.iter().enumerate() {
                let child_sch_loc = format!("{}/allOf/{}", sch_loc, i);
                validate(instance, sub, inst_loc, &child_sch_loc, root, errors);
            }
        }
    }

    // anyOf
    if let Some(v) = get_key(keywords, "anyOf") {
        if let JsonValue::Arr(schemas) = v {
            let accepted = schemas.iter().any(|sub| {
                let mut tmp = HashSet::new();
                validate(instance, sub, inst_loc, "", root, &mut tmp);
                tmp.is_empty()
            });
            if !accepted {
                errors.insert((inst_loc.to_string(), format!("{}/anyOf", sch_loc)));
            }
        }
    }

    // oneOf
    if let Some(v) = get_key(keywords, "oneOf") {
        if let JsonValue::Arr(schemas) = v {
            let count_accepted = schemas.iter().filter(|sub| {
                let mut tmp = HashSet::new();
                validate(instance, sub, inst_loc, "", root, &mut tmp);
                tmp.is_empty()
            }).count();
            if count_accepted != 1 {
                errors.insert((inst_loc.to_string(), format!("{}/oneOf", sch_loc)));
            }
        }
    }

    // not
    if let Some(v) = get_key(keywords, "not") {
        let mut tmp = HashSet::new();
        validate(instance, v, inst_loc, "", root, &mut tmp);
        if tmp.is_empty() {
            errors.insert((inst_loc.to_string(), format!("{}/not", sch_loc)));
        }
    }

    // if/then/else
    if let Some(if_schema) = get_key(keywords, "if") {
        let mut if_tmp = HashSet::new();
        validate(instance, if_schema, inst_loc, "", root, &mut if_tmp);
        if if_tmp.is_empty() {
            if let Some(then) = get_key(keywords, "then") {
                let child_sch_loc = format!("{}/then", sch_loc);
                validate(instance, then, inst_loc, &child_sch_loc, root, errors);
            }
        } else {
            if let Some(else_) = get_key(keywords, "else") {
                let child_sch_loc = format!("{}/else", sch_loc);
                validate(instance, else_, inst_loc, &child_sch_loc, root, errors);
            }
        }
    }

    // $ref
    if let Some(v) = get_key(keywords, "$ref") {
        if let JsonValue::Str(ref_str) = v {
            let (target_schema, target_loc) = resolve_ref(ref_str, root);
            validate(instance, target_schema, inst_loc, &target_loc, root, errors);
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let schema = Parser::new(&schema_str).parse_value();
    let instances = Parser::new(&instances_str).parse_value();

    let instances_arr = match &instances {
        JsonValue::Arr(arr) => arr,
        _ => panic!("instances.json must be an array"),
    };

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for (n, inst) in instances_arr.iter().enumerate() {
        let mut errors: HashSet<(String, String)> = HashSet::new();
        validate(inst, &schema, "#", "#", &schema, &mut errors);

        if errors.is_empty() {
            println!("{}: valid", n);
            valid_count += 1;
        } else {
            let mut sorted: Vec<(String, String)> = errors.into_iter().collect();
            sorted.sort();
            println!("{}: invalid ({})", n, sorted.len());
            for (inst_ptr, sch_ptr) in &sorted {
                println!("  {} {}", inst_ptr, sch_ptr);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

