let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
struct Account {
    var code: String
    var balance: Dec
    var limit: Dec
}
var accounts: [String: Account] = [:]
var rejections: [(Int, String)] = []

for (idx, rawLine) in lines.enumerated() {
    let lineNum = idx + 1
    let trimmed = rawLine.drop(while: { $0 == " " })
    if trimmed.isEmpty || trimmed.first == "#" { continue }

    let parts = rawLine.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
    if parts.isEmpty { continue }

    let cmd = parts[0]

    switch cmd {
    case "currency":
        let code = parts[1]
        let minor = Int(parts[2])!
        currencies[code] = minor

    case "open":
        let name = parts[1]
        let code = parts[2]
        let minor = currencies[code]!
        if accounts[name] != nil {
            rejections.append((lineNum, "account exists \(name)"))
            continue
        }
        var limit = Dec.zero
        if parts.count > 3 {
            limit = Dec.parse(Substring(parts[3])).round(to: minor)
        }
        accounts[name] = Account(code: code, balance: Dec.zero, limit: limit)

    case "deposit":
        let name = parts[1]
        guard accounts[name] != nil else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.code]!
        let amount = Dec.parse(Substring(parts[2])).round(to: minor)
        if !amount.isPositive {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        accounts[name]!.balance = accounts[name]!.balance + amount

    case "withdraw":
        let name = parts[1]
        guard accounts[name] != nil else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.code]!
        let amount = Dec.parse(Substring(parts[2])).round(to: minor)
        if !amount.isPositive {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = accounts[name]!.balance - amount
        let check = newBal + accounts[name]!.limit
        if check.neg {
            rejections.append((lineNum, "insufficient funds \(name)"))
            continue
        }
        accounts[name]!.balance = newBal

    case "transfer":
        let from = parts[1]
        let to = parts[2]
        var unknownName: String? = nil
        if accounts[from] == nil { unknownName = from }
        else if accounts[to] == nil { unknownName = to }
        if unknownName != nil {
            rejections.append((lineNum, "unknown account \(unknownName!)"))
            continue
        }
        if accounts[from]!.code != accounts[to]!.code {
            rejections.append((lineNum, "currency mismatch"))
            continue
        }
        let minor = currencies[accounts[from]!.code]!
        let amount = Dec.parse(Substring(parts[3])).round(to: minor)
        if !amount.isPositive {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = accounts[from]!.balance - amount
        let check = newBal + accounts[from]!.limit
        if check.neg {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        accounts[from]!.balance = newBal
        accounts[to]!.balance = accounts[to]!.balance + amount

    case "convert":
        let from = parts[1]
        let to = parts[2]
        var unknownName: String? = nil
        if accounts[from] == nil { unknownName = from }
        else if accounts[to] == nil { unknownName = to }
        if unknownName != nil {
            rejections.append((lineNum, "unknown account \(unknownName!)"))
            continue
        }
        let fromMinor = currencies[accounts[from]!.code]!
        let toMinor = currencies[accounts[to]!.code]!
        let amount = Dec.parse(Substring(parts[3])).round(to: fromMinor)
        if !amount.isPositive {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }
        let newBal = accounts[from]!.balance - amount
        let check = newBal + accounts[from]!.limit
        if check.neg {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }
        let rate = Dec.parse(Substring(parts[4]))
        let received = (amount * rate).round(to: toMinor)
        accounts[from]!.balance = newBal
        accounts[to]!.balance = accounts[to]!.balance + received

    case "interest":
        let name = parts[1]
        guard accounts[name] != nil else {
            rejections.append((lineNum, "unknown account \(name)"))
            continue
        }
        let minor = currencies[accounts[name]!.code]!
        let rate = Dec.parse(Substring(parts[2]))
        let bal = accounts[name]!.balance
        let interest = (bal * rate).round(to: minor)
        accounts[name]!.balance = bal + interest

    case "split":
        let from = parts[1]
        let amountStr = parts[2]
        var targets: [(String, BigUInt)] = []
        for i in 3..<parts.count {
            let colonPos = parts[i].firstIndex(of: ":")!
            let tName = String(parts[i][parts[i].startIndex..<colonPos])
            let wStr = parts[i][parts[i].index(after: colonPos)...]
            targets.append((tName, BigUInt.parse(wStr)))
        }

        var unknownName: String? = nil
        if accounts[from] == nil { unknownName = from }
        if unknownName == nil {
            for t in targets {
                if accounts[t.0] == nil { unknownName = t.0; break }
            }
        }
        if unknownName != nil {
            rejections.append((lineNum, "unknown account \(unknownName!)"))
            continue
        }

        let fromCode = accounts[from]!.code
        var mismatch = false
        for t in targets {
            if accounts[t.0]!.code != fromCode { mismatch = true; break }
        }
        if mismatch {
            rejections.append((lineNum, "currency mismatch"))
            continue
        }

        let minor = currencies[fromCode]!
        let amount = Dec.parse(Substring(amountStr)).round(to: minor)
        if !amount.isPositive {
            rejections.append((lineNum, "non-positive amount"))
            continue
        }

        let newBal = accounts[from]!.balance - amount
        let check = newBal + accounts[from]!.limit
        if check.neg {
            rejections.append((lineNum, "insufficient funds \(from)"))
            continue
        }

        let A: BigUInt
        if minor == 0 {
            A = amount.unscaled
        } else {
            let (q, _) = BigUInt.divMod(amount.unscaled, pow10(minor))
            A = q
        }

        var W = BigUInt()
        for t in targets { W = W + t.1 }

        var bases: [BigUInt] = []
        var rems: [BigUInt] = []
        var sumBase = BigUInt()
        for t in targets {
            let prod = A * t.1
            let (q, r) = BigUInt.divMod(prod, W)
            bases.append(q)
            rems.append(r)
            sumBase = sumBase + q
        }

        let leftover = A - sumBase
        let leftoverInt = Int(leftover.toUInt64())

        let n = targets.count
        var indices = Array(0..<n)
        indices.sort { i, j in
            if rems[i] != rems[j] { return rems[i] > rems[j] }
            return i < j
        }

        accounts[from]!.balance = newBal
        for idx in 0..<n {
            var share = bases[idx]
            if idx < leftoverInt {
                share = share + BigUInt(UInt64(1))
            }
            let shareDec: Dec
            if minor == 0 {
                shareDec = Dec.make(neg: false, unscaled: share, scale: 0)
            } else {
                let unscaled = share * pow10(minor)
                shareDec = Dec.make(neg: false, unscaled: unscaled, scale: minor)
            }
            let tName = targets[idx].0
            accounts[tName]!.balance = accounts[tName]!.balance + shareDec
        }

    default:
        break
    }
}

// Output
var output = ""

for (ln, reason) in rejections {
    output += "line \(ln): REJECT \(reason)\n"
}
output += "\n"

let sortedAccounts = accounts.keys.sorted { $0 < $1 }
for name in sortedAccounts {
    let acc = accounts[name]!
    let minor = currencies[acc.code]!
    output += "\(name) \(acc.code) \(acc.balance.format(minorUnits: minor))\n"
}
output += "\n"

var currencyTotals: [String: (Dec, Int)] = [:]
for name in sortedAccounts {
    let acc = accounts[name]!
    let code = acc.code
    if currencyTotals[code] == nil {
        currencyTotals[code] = (Dec.zero, 0)
    }
    currencyTotals[code]!.0 = currencyTotals[code]!.0 + acc.balance
    currencyTotals[code]!.1 += 1
}

let sortedCodes = currencyTotals.keys.sorted { $0 < $1 }
for code in sortedCodes {
    let (total, count) = currencyTotals[code]!
    let minor = currencies[code]!
    output += "total \(code) \(total.format(minorUnits: minor)) (\(count) accounts)\n"
}

