                PropDef { name: "value", ptype: "string", min_len: None },
            ],
            required: vec!["key", "value"],
            has_output: false,
        },
        ToolDef {
            name: "kv_get",
            props: vec![
                PropDef { name: "key", ptype: "string", min_len: Some(1) },
            ],
