function findValueEnd(line: string, start: number): number {
  let i = start;
  if (i >= line.length) return i;
  const ch = line[i];
  if (ch === '"') {
    i++;
    while (i < line.length) {
      if (line[i] === '\\') { i += 2; continue; }
      if (line[i] === '"') { i++; return i; }
      i++;
