function compareByCodePoint(a: string, b: string): number {
  const ca = [...a];
  const cb = [...b];
  const minLen = Math.min(ca.length, cb.length);
  for (let i = 0; i < minLen; i++) {
    const pa = ca[i].codePointAt(0)!;
    const pb = cb[i].codePointAt(0)!;
    if (pa < pb) return -1;
    if (pa > pb) return 1;
  }
  return ca.length - cb.length;
