        static JVal ofInt(long n){JVal v=new JVal();v.type=3;v.isInt=true;v.lval=n;return v;}
        static JVal ofDbl(double d){JVal v=new JVal();v.type=3;v.isInt=false;v.dval=d;return v;}
        static JVal ofArr(ArrayList<JVal> a){JVal v=new JVal();v.type=4;v.arr=a;return v;}
        static JVal ofObj(LinkedHashMap<String,JVal> o){JVal v=new JVal();v.type=5;v.obj=o;return v;}
    }

    // ---- JSON Parser ----
    static class PErr extends RuntimeException{PErr(String m){super(m);}}
    static class JP{
        String s;int pos,len;
        JP(String s){this.s=s;pos=0;len=s.length();}
        JVal parse(){skipWs();JVal v=parseVal();skipWs();if(pos!=len)throw new PErr("trail");return v;}
        void skipWs(){while(pos<len){char c=s.charAt(pos);if(c==' '||c=='\t'||c=='\n'||c=='\r')pos++;else break;}}
        JVal parseVal(){
            if(pos>=len)throw new PErr("eof");
            char c=s.charAt(pos);
            if(c=='{')return parseObj();
            if(c=='[')return parseArr();
            if(c=='"')return parseStr();
            if(c=='t'){expect("true");return JVal.ofBool(true);}
            if(c=='f'){expect("false");return JVal.ofBool(false);}
            if(c=='n'){expect("null");return JVal.ofNull();}
            if(c=='-'||(c>='0'&&c<='9'))return parseNum();
            throw new PErr("bad");
        }
        void expect(String lit){if(!s.startsWith(lit,pos))throw new PErr("exp");pos+=lit.length();}
        JVal parseObj(){
            pos++;LinkedHashMap<String,JVal> m=new LinkedHashMap<>();skipWs();
            if(pos<len&&s.charAt(pos)=='}'){pos++;return JVal.ofObj(m);}
            while(true){skipWs();if(pos>=len||s.charAt(pos)!='"')throw new PErr("key");
                JVal k=parseStr();skipWs();if(pos>=len||s.charAt(pos)!=':')throw new PErr("colon");pos++;skipWs();
                JVal v=parseVal();m.put(k.sval,v);skipWs();
                if(pos<len&&s.charAt(pos)==','){pos++;continue;}
                if(pos<len&&s.charAt(pos)=='}'){pos++;break;}
                throw new PErr("comma/brace");
            }return JVal.ofObj(m);
        }
        JVal parseArr(){
            pos++;ArrayList<JVal> a=new ArrayList<>();skipWs();
            if(pos<len&&s.charAt(pos)==']'){pos++;return JVal.ofArr(a);}
            while(true){skipWs();a.add(parseVal());skipWs();
                if(pos<len&&s.charAt(pos)==','){pos++;continue;}
                if(pos<len&&s.charAt(pos)==']'){pos++;break;}
                throw new PErr("comma/bracket");
            }return JVal.ofArr(a);
        }
        JVal parseStr(){
            pos++;StringBuilder sb=new StringBuilder();
            while(pos<len){char c=s.charAt(pos);
                if(c=='"'){pos++;return JVal.ofStr(sb.toString());}
                if(c=='\\'){pos++;if(pos>=len)throw new PErr("esc");char e=s.charAt(pos);pos++;
                    if(e=='"')sb.append('"');else if(e=='\\')sb.append('\\');else if(e=='/')sb.append('/');
                    else if(e=='b')sb.append('\b');else if(e=='f')sb.append('\f');else if(e=='n')sb.append('\n');
                    else if(e=='r')sb.append('\r');else if(e=='t')sb.append('\t');
                    else if(e=='u'){if(pos+4>len)throw new PErr("uni");String h=s.substring(pos,pos+4);
                        for(int i=0;i<4;i++){char hc=h.charAt(i);if(!((hc>='0'&&hc<='9')||(hc>='a'&&hc<='f')||(hc>='A'&&hc<='F')))throw new PErr("hex");}
                        sb.append((char)Integer.parseInt(h,16));pos+=4;}
                    else throw new PErr("badesc");
                }else if(c<0x20)throw new PErr("ctrl");
                else{sb.append(c);pos++;}
            }throw new PErr("unterm");
        }
        JVal parseNum(){
            int st=pos;boolean isInt=true;
            if(pos<len&&s.charAt(pos)=='-')pos++;
            if(pos>=len)throw new PErr("num");
            char c=s.charAt(pos);
            if(c=='0')pos++;
            else if(c>='1'&&c<='9'){while(pos<len&&s.charAt(pos)>='0'&&s.charAt(pos)<='9')pos++;}
            else throw new PErr("num");
            if(pos<len&&s.charAt(pos)=='.'){isInt=false;pos++;
                if(pos>=len||s.charAt(pos)<'0'||s.charAt(pos)>'9')throw new PErr("frac");
                while(pos<len&&s.charAt(pos)>='0'&&s.charAt(pos)<='9')pos++;}
            if(pos<len&&(s.charAt(pos)=='e'||s.charAt(pos)=='E')){isInt=false;pos++;
                if(pos<len&&(s.charAt(pos)=='+'||s.charAt(pos)=='-'))pos++;
                if(pos>=len||s.charAt(pos)<'0'||s.charAt(pos)>'9')throw new PErr("exp");
                while(pos<len&&s.charAt(pos)>='0'&&s.charAt(pos)<='9')pos++;}
            String raw=s.substring(st,pos);
            if(isInt)return JVal.ofInt(Long.parseLong(raw));
            return JVal.ofDbl(Double.parseDouble(raw));
        }
    }

    // ---- JSON Serializer ----
    static String toJson(JVal v){StringBuilder sb=new StringBuilder();wJ(v,sb);return sb.toString();}
    static void wJ(JVal v,StringBuilder sb){
        if(v==null||v.type==0){sb.append("null");return;}
        switch(v.type){
            case 1:sb.append(v.bval?"true":"false");break;
            case 2:wS(v.sval,sb);break;
            case 3:if(v.isInt)sb.append(v.lval);else{String ds=Double.toString(v.dval);if(ds.endsWith(".0"))ds=ds.substring(0,ds.length()-2);sb.append(ds);}break;
            case 4:sb.append('[');for(int i=0;i<v.arr.size();i++){if(i>0)sb.append(',');wJ(v.arr.get(i),sb);}sb.append(']');break;
            case 5:sb.append('{');boolean f=true;for(Map.Entry<String,JVal> e:v.obj.entrySet()){if(!f)sb.append(',');f=false;wS(e.getKey(),sb);sb.append(':');wJ(e.getValue(),sb);}sb.append('}');break;
        }
    }
    static void wS(String s,StringBuilder sb){
        sb.append('"');
        for(int i=0;i<s.length();i++){char c=s.charAt(i);
            if(c=='"')sb.append("\\\"");else if(c=='\\')sb.append("\\\\");
            else if(c=='\n')sb.append("\\n");else if(c=='\r')sb.append("\\r");
            else if(c=='\t')sb.append("\\t");else if(c=='\b')sb.append("\\b");
            else if(c=='\f')sb.append("\\f");
            else if(c<0x20)sb.append(String.format("\\u%04x",(int)c));
            else sb.append(c);
        }sb.append('"');
    }

    // ---- Helpers ----
    static JVal getMember(JVal obj,String key){
        if(obj==null||obj.type!=5)return null;
        return obj.obj.get(key);
    }
    static boolean isValidId(JVal id){
        if(id==null)return false;
        if(id.type==2)return true;
        if(id.type==3&&id.isInt)return true;
        return false;
    }
    static JVal idForOutput(JVal id){
        if(id==null)return JVal.ofNull();
        if(id.type==2)return id;
        if(id.type==3&&id.isInt)return id;
        return JVal.ofNull();
    }
    static int cmpCP(String a,String b){
        int i=0,j=0;
        while(i<a.length()&&j<b.length()){
            int ca=a.codePointAt(i),cb=b.codePointAt(j);
            if(ca!=cb)return Integer.compare(ca,cb);
            i+=Character.charCount(ca);j+=Character.charCount(cb);
        }
        if(i<a.length())return 1;if(j<b.length())return -1;return 0;
    }

