fn parse_name(msg: &[u8], offset: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = offset;
    let mut next_offset: Option<usize> = None;
    let mut visited: HashSet<usize> = HashSet::new();

    loop {
        if pos >= msg.len() {
            break;
        }
        if !visited.insert(pos) {
            break;
        }

        let byte = msg[pos];
        if byte & 0xC0 == 0xC0 {
            if pos + 1 >= msg.len() {
                break;
            }
            let ptr = ((byte as usize & 0x3F) << 8) | msg[pos + 1] as usize;
            if next_offset.is_none() {
                next_offset = Some(pos + 2);
            }
            pos = ptr;
        } else if byte == 0 {
            if next_offset.is_none() {
                next_offset = Some(pos + 1);
            }
            break;
        } else {
            let len = byte as usize;
            if pos + 1 + len > msg.len() {
                break;
            }
            let label = String::from_utf8_lossy(&msg[pos + 1..pos + 1 + len]).to_lowercase();
            labels.push(label);
            pos += 1 + len;
        }
    }

    let name = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    };

    (name, next_offset.unwrap_or(pos + 1))
