    let mut s = bi.digits[last].to_string();
    for i in (0..last).rev() {
        s.push_str(&format!("{:09}", bi.digits[i]));
    }
    s
}

fn add_commas(s: &str) -> String {
    let mut result = String::new();
    let len = s.len();
    for (i, ch) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 { result.push(','); }
        result.push(ch);
    }
    result
}

fn format_money(bi: &BigInt, minor: usize) -> String {
    if bi.is_zero() {
        if minor == 0 { return "0".to_string(); }
        return format!("0.{}", "0".repeat(minor));
    }
    let neg = bi.is_negative();
    let abs_bi = if neg { bi.negate() } else { bi.clone() };
    let abs_str = bigint_to_str(&abs_bi);
    let int_str;
    let frac_str;
    if minor == 0 {
        int_str = abs_str;
        frac_str = String::new();
    } else if abs_str.len() <= minor {
        int_str = "0".to_string();
        frac_str = format!("{}{}", "0".repeat(minor - abs_str.len()), abs_str);
    } else {
        let sp = abs_str.len() - minor;
        int_str = abs_str[..sp].to_string();
        frac_str = abs_str[sp..].to_string();
    }
    let mut out = String::new();
    if neg { out.push('-'); }
    out.push_str(&add_commas(&int_str));
    if minor > 0 { out.push('.'); out.push_str(&frac_str); }
    out
}

