                }
                // Distribute in minor units
                let a_minor = &amount.value; // positive BigInt
                let mut w_sum = BigInt::zero();
                for (_, w) in &targets {
                    w_sum = w_sum.add(w);
                }
                let n = targets.len();
                let mut base_vals: Vec<BigInt> = vec![];
                let mut rems: Vec<BigInt> = vec![];
                let mut sum_base = BigInt::zero();
                for (_, w) in &targets {
                    let prod = a_minor.mul(w);
                    let (q, r) = BigInt::div_mod_pos(&prod, &w_sum);
                    base_vals.push(q.clone());
                    rems.push(r);
                    sum_base = sum_base.add(&q);
                }
                let leftover = a_minor.sub(&sum_base);
                let leftover_count = if leftover.is_zero() { 0 } else {
                    // leftover is small (0..n-1), convert to usize
                    let mut v: usize = 0;
                    for d in &leftover.digits { v = v * (BASE as usize) + (*d as usize); }
                    v
                };
                // sort indices by remainder desc, ties by original order
                let mut indices: Vec<usize> = (0..n).collect();
                indices.sort_by(|&a, &b| {
                    let cmp = rems[b].cmp_abs(&rems[a]);
                    match cmp {
                        std::cmp::Ordering::Equal => a.cmp(&b),
                        o => o,
                    }
                });
                // distribute leftover
                for &idx in indices.iter().take(leftover_count) {
                    base_vals[idx] = base_vals[idx].add(&BigInt::from_u32(1));
                }
                // apply
                accounts.get_mut(&from).unwrap().balance = new_bal;
                for i in 0..n {
                    let tname = &targets[i].0;
                    let add_val = FixedPoint { value: base_vals[i].clone(), scale: minor };
                    let tb = accounts[tname].balance.add(&add_val);
                    accounts.get_mut(tname).unwrap().balance = tb;
                }
            }
            _ => {}
        }
    }

    // Output
    let mut out = String::new();
    for r in &rejections {
        out.push_str(r);
        out.push('\n');
    }
    out.push('\n');
    for (name, acc) in &accounts {
        let minor = currencies[&acc.currency];
        out.push_str(&format!("{} {} {}\n", name, acc.currency, format_money(&acc.balance.value, minor)));
    }
    out.push('\n');
    let mut totals: BTreeMap<String, (BigInt, usize)> = BTreeMap::new();
    for acc in accounts.values() {
        let code = &acc.currency;
        let entry = totals.entry(code.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance.value);
        entry.1 += 1;
    }
    for (code, (sum, count)) in &totals {
        let minor = currencies[code];
        out.push_str(&format!("total {} {} ({} accounts)\n", code, format_money(&sum, minor), count));
    }
    print!("{}", out);
