            }
        }
        return NIL;
    }

    static void execBlock(List<Stmt>body,Scope sc){
        for(Stmt s:body)execStmt(s,sc);
    }

    static void execStmt(Stmt s,Scope sc){
        if(s instanceof SLet){
            SLet st=(SLet)s;Object v=eval(st.val,sc);sc.vars.put(st.name,v);return;
        }
        if(s instanceof SFn){
            SFn st=(SFn)s;TernFn fn=new TernFn(st.params,st.body,sc);sc.vars.put(st.name,fn);return;
        }
