            else len=((String)obj).length();
            if(i<0||i>=len)throw new TErr(ix.ln,"index "+i+" out of range for length "+len);
            if(obj instanceof ArrayList)return((ArrayList<?>)obj).get((int)i);
            return String.valueOf(((String)obj).charAt((int)i));
