    const body = this.parseBlock();
    return {k:'fnDecl',name,params,body,line:t.line};
  }

  parseParams(): string[] {
    const p: string[] = [];
    if (this.peek().type === 'IDENT') {
      p.push(this.advance().value);
      while (this.peek().type === 'COMMA') { this.advance(); p.push(this.expect('IDENT').value); }
    }
    return p;
  }

  parseIf(): Stmt {
    const t = this.advance();
    const cond = this.parseExpr();
    const then = this.parseBlock();
    let els: Stmt[]|null = null;
    if (this.peek().type === 'KW' && this.peek().value === 'else') {
      this.advance();
      if (this.peek().type === 'KW' && this.peek().value === 'if') els = [this.parseIf()];
      else els = this.parseBlock();
    }
    return {k:'if',cond,then,els,line:t.line};
  }

  parseWhile(): Stmt {
    const t = this.advance();
    const cond = this.parseExpr();
    const body = this.parseBlock();
    return {k:'while',cond,body,line:t.line};
  }

  parseFor(): Stmt {
    const t = this.advance();
    const varName = this.expect('IDENT').value;
    this.expect('KW','in');
    const iter = this.parseExpr();
    const body = this.parseBlock();
    return {k:'for',varName,iter,body,line:t.line};
  }

  parseReturn(): Stmt {
    const t = this.advance();
    let val: Expr|null = null;
    if (this.peek().type !== 'SEMI') val = this.parseExpr();
    this.expect('SEMI');
    return {k:'return',val,line:t.line};
  }

  parseAssignOrExpr(): Stmt {
    if (this.peek().type === 'IDENT' && this.tokens[this.pos+1].type === 'OP' && this.tokens[this.pos+1].value === '=') {
      const nameTok = this.advance();
      this.advance();
      const val = this.parseExpr();
      this.expect('SEMI');
      return {k:'assign',name:nameTok.value,val,line:nameTok.line};
    }
    const expr = this.parseExpr();
    if (this.peek().type === 'OP' && this.peek().value === '=') {
      this.advance();
      const val = this.parseExpr();
      this.expect('SEMI');
      if (expr.k === 'index') return {k:'idxAssign',obj:expr.obj,idx:expr.idx,val,line:expr.line};
    }
    this.expect('SEMI');
    return {k:'expr',e:expr,line:expr.line};
  }

  parseExpr(): Expr { return this.parseOr(); }
  parseOr(): Expr {
    let l = this.parseAnd();
    while (this.peek().type==='KW'&&this.peek().value==='or') { const t=this.advance(); l={k:'binary',op:'or',l,r:this.parseAnd(),line:t.line}; }
    return l;
  }
  parseAnd(): Expr {
    let l = this.parseNot();
    while (this.peek().type==='KW'&&this.peek().value==='and') { const t=this.advance(); l={k:'binary',op:'and',l,r:this.parseNot(),line:t.line}; }
    return l;
  }
  parseNot(): Expr {
    if (this.peek().type==='KW'&&this.peek().value==='not') { const t=this.advance(); return {k:'unary',op:'not',arg:this.parseNot(),line:t.line}; }
    return this.parseCmp();
  }
  parseCmp(): Expr {
    let l = this.parseAdd();
    while (this.peek().type==='OP'&&['==','!=','<','<=','>','>='].includes(this.peek().value)) { const t=this.advance(); l={k:'binary',op:t.value,l,r:this.parseAdd(),line:t.line}; }
    return l;
  }
  parseAdd(): Expr {
    let l = this.parseMul();
    while (this.peek().type==='OP'&&(this.peek().value==='+'||this.peek().value==='-')) { const t=this.advance(); l={k:'binary',op:t.value,l,r:this.parseMul(),line:t.line}; }
    return l;
  }
  parseMul(): Expr {
    let l = this.parseUnary();
    while (this.peek().type==='OP'&&(this.peek().value==='*'||this.peek().value==='/'||this.peek().value==='%')) { const t=this.advance(); l={k:'binary',op:t.value,l,r:this.parseUnary(),line:t.line}; }
    return l;
  }
  parseUnary(): Expr {
    if (this.peek().type==='OP'&&this.peek().value==='-') { const t=this.advance(); return {k:'unary',op:'-',arg:this.parseUnary(),line:t.line}; }
    return this.parsePostfix();
  }
  parsePostfix(): Expr {
    let e = this.parsePrimary();
    while (true) {
      if (this.peek().type==='LPAREN') {
        const t=this.advance(); const args:Expr[]=[];
        if (this.peek().type!=='RPAREN') { args.push(this.parseExpr()); while(this.peek().type==='COMMA'){this.advance();args.push(this.parseExpr());} }
        this.expect('RPAREN'); e={k:'call',callee:e,args,line:t.line};
      } else if (this.peek().type==='LBRACKET') {
        const t=this.advance(); const idx=this.parseExpr(); this.expect('RBRACKET'); e={k:'index',obj:e,idx,line:t.line};
      } else break;
    }
    return e;
  }
  parsePrimary(): Expr {
    const t = this.peek();
    if (t.type==='INT') { this.advance(); return {k:'int',v:BigInt(t.value),line:t.line}; }
    if (t.type==='STR') { this.advance(); return {k:'str',v:t.value,line:t.line}; }
    if (t.type==='KW') {
      if (t.value==='true') { this.advance(); return {k:'bool',v:true,line:t.line}; }
      if (t.value==='false') { this.advance(); return {k:'bool',v:false,line:t.line}; }
      if (t.value==='nil') { this.advance(); return {k:'nil',line:t.line}; }
      if (t.value==='fn') {
        this.advance(); this.expect('LPAREN');
        const params=this.parseParams(); this.expect('RPAREN');
        const body=this.parseBlock();
        return {k:'fn',params,body,line:t.line};
      }
    }
    if (t.type==='IDENT') { this.advance(); return {k:'ident',name:t.value,line:t.line}; }
    if (t.type==='LPAREN') { this.advance(); const e=this.parseExpr(); this.expect('RPAREN'); return e; }
    if (t.type==='LBRACKET') {
      this.advance(); const elems:Expr[]=[];
      if (this.peek().type!=='RBRACKET') { elems.push(this.parseExpr()); while(this.peek().type==='COMMA'){this.advance();elems.push(this.parseExpr());} }
      this.expect('RBRACKET');
      return {k:'list',elems,line:t.line};
    }
    throw new Error(`unexpected token ${t.type} ${t.value} line ${t.line}`);
  }
}

// ===== VALUES & INTERPRETER =====

interface FnVal { t:'fn'; params:string[]; body:Stmt[]; scope:Scope; }
interface BuiltinVal { t:'builtin'; name:string; fn:(args:Val[])=>Val; minArgs:number; maxArgs:number; }
type Val =
  | { t:'int'; v:bigint }
  | { t:'bool'; v:boolean }
  | { t:'str'; v:string }
  | { t:'list'; v:Val[] }
  | FnVal
  | BuiltinVal
  | { t:'nil' };

const NIL: Val = {t:'nil'};
const TRUE: Val = {t:'bool',v:true};
const FALSE: Val = {t:'bool',v:false};
const INT_MIN = -(1n<<63n);
const INT_MAX = (1n<<63n)-1n;

class Scope {
  vars: Map<string,Val>;
  parent: Scope|null;
  constructor(parent: Scope|null) { this.vars = new Map(); this.parent = parent; }
}

class TernError { line:number; msg:string; constructor(line:number,msg:string){this.line=line;this.msg=msg;} }
class BreakSig {}
class ContSig {}
class RetSig { val:Val; constructor(v:Val){this.val=v;} }

function typeName(v:Val):string {
  switch(v.t){case'int':return'int';case'bool':return'bool';case'str':return'string';case'list':return'list';case'fn':case'builtin':return'function';case'nil':return'nil';}
}

function truthy(v:Val):boolean {
  switch(v.t){case'bool':return v.v;case'nil':return false;case'int':return v.v!==0n;case'str':return v.v.length>0;case'list':return v.v.length>0;default:return true;}
}

function valEq(a:Val,b:Val):boolean {
  if (a.t!==b.t) return false;
  switch(a.t){
    case'int':return(a as any).v===(b as any).v;
    case'bool':return(a as any).v===(b as any).v;
    case'str':return(a as any).v===(b as any).v;
    case'nil':return true;
    case'list':{
      const la=(a as any).v as Val[], lb=(b as any).v as Val[];
      if(la.length!==lb.length)return false;
      for(let i=0;i<la.length;i++)if(!valEq(la[i],lb[i]))return false;
      return true;
    }
    case'fn':case'builtin':return a===b;
  }
  return false;
}

function quoteStr(s:string):string {
  let r='"';
  for(let i=0;i<s.length;i++){
    const c=s[i];
    if(c==='\\')r+='\\\\';else if(c==='"')r+='\\"';else if(c==='\n')r+='\\n';else if(c==='\t')r+='\\t';else r+=c;
  }
  return r+'"';
}

function displayVal(v:Val,inList:boolean,seen:Set<object>):string {
  switch(v.t){
    case'int':return(v as any).v.toString();
    case'bool':return(v as any).v?'true':'false';
    case'nil':return'nil';
    case'str':return inList?quoteStr((v as any).v):(v as any).v;
    case'fn':case'builtin':return'<fn>';
    case'list':{
      const lst=(v as any).v as Val[];
      if(seen.has(v))return'[...]';
      seen.add(v);
      let r='[';
      for(let i=0;i<lst.length;i++){if(i>0)r+=', ';r+=displayVal(lst[i],true,seen);}
      r+=']';
      seen.delete(v);
      return r;
    }
  }
  return'';
}

function checkInt(v:bigint,line:number):Val {
  if(v<INT_MIN||v>INT_MAX) throw new TernError(line,'integer overflow');
  return {t:'int',v};
}

function lookup(scope:Scope,name:string,line:number):Val {
  let s:Scope|null=scope;
  while(s){if(s.vars.has(name))return s.vars.get(name)!;s=s.parent;}
  throw new TernError(line,`undefined variable ${name}`);
}

function assignVar(scope:Scope,name:string,val:Val,line:number):void {
  let s:Scope|null=scope;
  while(s){if(s.vars.has(name)){s.vars.set(name,val);return;}s=s.parent;}
  throw new TernError(line,`undefined variable ${name}`);
}

// Builtins
function makeBuiltins():Map<string,Val>{
  const m=new Map<string,Val>();
  m.set('print',{t:'builtin',name:'print',minArgs:0,maxArgs:Infinity,fn:(args:Val[])=>{
    const parts=args.map(a=>displayVal(a,false,new Set()));
    process.stdout.write(parts.join(' ')+'\n');
    return NIL;
  }});
  m.set('str',{t:'builtin',name:'str',minArgs:1,maxArgs:1,fn:(args:Val[])=>({t:'str',v:displayVal(args[0],false,new Set())})});
  m.set('type',{t:'builtin',name:'type',minArgs:1,maxArgs:1,fn:(args:Val[])=>({t:'str',v:typeName(args[0])})});
  m.set('len',{t:'builtin',name:'len',minArgs:1,maxArgs:1,fn:(args:Val[])=>{
    const a=args[0];
    if(a.t==='str')return{t:'int',v:BigInt(a.v.length)};
    if(a.t==='list')return{t:'int',v:BigInt(a.v.length)};
    throw new TernError(0,'bad argument to len');
  }});
  m.set('push',{t:'builtin',name:'push',minArgs:2,maxArgs:2,fn:(args:Val[])=>{
    const a=args[0];
    if(a.t!=='list')throw new TernError(0,'bad argument to push');
    a.v.push(args[1]);return NIL;
  }});
  m.set('pop',{t:'builtin',name:'pop',minArgs:1,maxArgs:1,fn:(args:Val[])=>{
    const a=args[0];
    if(a.t!=='list'||a.v.length===0)throw new TernError(0,'bad argument to pop');
    return a.v.pop()!;
  }});
  m.set('range',{t:'builtin',name:'range',minArgs:2,maxArgs:2,fn:(args:Val[])=>{
    const a=args[0],b=args[1];
    if(a.t!=='int'||b.t!=='int')throw new TernError(0,'bad argument to range');
    const elems:Val[]=[];
    for(let i=a.v;i<b.v;i++)elems.push({t:'int',v:i});
    return{t:'list',v:elems};
  }});
  m.set('slice',{t:'builtin',name:'slice',minArgs:3,maxArgs:3,fn:(args:Val[])=>{
    const x=args[0],a=args[1],b=args[2];
    if(x.t!=='str'&&x.t!=='list')throw new TernError(0,'bad argument to slice');
    if(a.t!=='int'||b.t!=='int')throw new TernError(0,'bad argument to slice');
    const ai=Number(a.v),bi=Number(b.v);
    if(x.t==='str')return{t:'str',v:x.v.slice(ai,bi)};
    return{t:'list',v:x.v.slice(ai,bi)};
  }});
  return m;
}

let builtinScope:Scope;

function evalExpr(e:Expr,scope:Scope):Val {
  switch(e.k){
    case'int':return{t:'int',v:e.v};
    case'str':return{t:'str',v:e.v};
    case'bool':return e.v?TRUE:FALSE;
    case'nil':return NIL;
    case'ident':return lookup(scope,e.name,e.line);
    case'unary':{
      if(e.op==='not'){const v=evalExpr(e.arg,scope);return truthy(v)?FALSE:TRUE;}
      // '-'
      const v=evalExpr(e.arg,scope);
      if(v.t!=='int')throw new TernError(e.line,`cannot apply - to ${typeName(v)}`);
      return checkInt(-v.v,e.line);
    }
    case'binary':{
      const op=e.op;
      if(op==='and'){const l=evalExpr(e.l,scope);if(!truthy(l))return l;return evalExpr(e.r,scope);}
      if(op==='or'){const l=evalExpr(e.l,scope);if(truthy(l))return l;return evalExpr(e.r,scope);}
      const l=evalExpr(e.l,scope);
      const r=evalExpr(e.r,scope);
      return applyBinary(op,l,r,e.line);
    }
    case'call':{
      const callee=evalExpr(e.callee,scope);
      const args:Val[]=[];
      for(const a of e.args)args.push(evalExpr(a,scope));
      return doCall(callee,args,e.line);
    }
    case'index':{
      const obj=evalExpr(e.obj,scope);
      const idx=evalExpr(e.idx,scope);
      if(obj.t!=='list'&&obj.t!=='str')throw new TernError(e.line,`cannot index ${typeName(obj)} with ${typeName(idx)}`);
      if(idx.t!=='int')throw new TernError(e.line,`cannot index ${typeName(obj)} with ${typeName(idx)}`);
      const i=Number(idx.v);
      const len=obj.t==='str'?obj.v.length:obj.v.length;
      if(i<0||i>=len)throw new TernError(e.line,`index ${i} out of range for length ${len}`);
      if(obj.t==='str')return{t:'str',v:obj.v[i]};
      return obj.v[i];
    }
    case'list':{
      const elems:Val[]=[];
      for(const el of e.elems)elems.push(evalExpr(el,scope));
      return{t:'list',v:elems};
    }
    case'fn':return{t:'fn',params:e.params,body:e.body,scope};
  }
  return NIL;
}

function applyBinary(op:string,l:Val,r:Val,line:number):Val {
  switch(op){
    case'==':return valEq(l,r)?TRUE:FALSE;
    case'!=':return valEq(l,r)?FALSE:TRUE;
    case'+':{
      if(l.t==='int'&&r.t==='int')return checkInt(l.v+r.v,line);
      if(l.t==='str'&&r.t==='str')return{t:'str',v:l.v+r.v};
      if(l.t==='list'&&r.t==='list')return{t:'list',v:[...l.v,...r.v]};
      throw new TernError(line,`cannot apply + to ${typeName(l)} and ${typeName(r)}`);
    }
    case'-':{
      if(l.t==='int'&&r.t==='int')return checkInt(l.v-r.v,line);
      throw new TernError(line,`cannot apply - to ${typeName(l)} and ${typeName(r)}`);
    }
    case'*':{
      if(l.t==='int'&&r.t==='int')return checkInt(l.v*r.v,line);
      throw new TernError(line,`cannot apply * to ${typeName(l)} and ${typeName(r)}`);
    }
    case'/':{
      if(l.t==='int'&&r.t==='int'){
        if(r.v===0n)throw new TernError(line,'division by zero');
        return checkInt(l.v/r.v,line);
      }
      throw new TernError(line,`cannot apply / to ${typeName(l)} and ${typeName(r)}`);
    }
    case'%':{
      if(l.t==='int'&&r.t==='int'){
        if(r.v===0n)throw new TernError(line,'division by zero');
        return checkInt(l.v-(l.v/r.v)*r.v,line);
      }
      throw new TernError(line,`cannot apply % to ${typeName(l)} and ${typeName(r)}`);
    }
    case'<':{
      if(l.t==='int'&&r.t==='int')return l.v<r.v?TRUE:FALSE;
      if(l.t==='str'&&r.t==='str')return l.v<r.v?TRUE:FALSE;
      throw new TernError(line,`cannot apply < to ${typeName(l)} and ${typeName(r)}`);
    }
    case'<=':{
      if(l.t==='int'&&r.t==='int')return l.v<=r.v?TRUE:FALSE;
      if(l.t==='str'&&r.t==='str')return l.v<=r.v?TRUE:FALSE;
      throw new TernError(line,`cannot apply <= to ${typeName(l)} and ${typeName(r)}`);
    }
    case'>':{
      if(l.t==='int'&&r.t==='int')return l.v>r.v?TRUE:FALSE;
      if(l.t==='str'&&r.t==='str')return l.v>r.v?TRUE:FALSE;
      throw new TernError(line,`cannot apply > to ${typeName(l)} and ${typeName(r)}`);
    }
    case'>=':{
      if(l.t==='int'&&r.t==='int')return l.v>=r.v?TRUE:FALSE;
      if(l.t==='str'&&r.t==='str')return l.v>=r.v?TRUE:FALSE;
      throw new TernError(line,`cannot apply >= to ${typeName(l)} and ${typeName(r)}`);
    }
  }
  throw new TernError(line,`cannot apply ${op} to ${typeName(l)} and ${typeName(r)}`);
}

function doCall(callee:Val,args:Val[],line:number):Val {
  if(callee.t==='fn'){
    if(args.length!==callee.params.length)
      throw new TernError(line,`expected ${callee.params.length} arguments, got ${args.length}`);
    const callScope=new Scope(callee.scope);
    for(let i=0;i<callee.params.length;i++)callScope.vars.set(callee.params[i],args[i]);
    try{
      execBlock(callee.body,callScope);
    }catch(e){
      if(e instanceof RetSig)return e.val;
      throw e;
    }
    return NIL;
  }
  if(callee.t==='builtin'){
    const n=args.length;
    if(n<callee.minArgs||n>callee.maxArgs)
      throw new TernError(line,`expected ${callee.minArgs===callee.maxArgs?callee.minArgs:callee.minArgs} arguments, got ${n}`);
    try{
      return callee.fn(args);
    }catch(e){
      if(e instanceof TernError){e.line=line;throw e;}
      throw e;
    }
  }
  throw new TernError(line,`cannot call ${typeName(callee)}`);
}

function execBlock(stmts:Stmt[],scope:Scope):void {
  for(const s of stmts)execStmt(s,scope);
}

function execStmt(s:Stmt,scope:Scope):void {
  switch(s.k){
    case'let':{
      const v=evalExpr(s.val,scope);
      scope.vars.set(s.name,v);
      break;
    }
    case'fnDecl':{
      const fv:FnVal={t:'fn',params:s.params,body:s.body,scope};
      scope.vars.set(s.name,fv);
      break;
    }
    case'if':{
      if(truthy(evalExpr(s.cond,scope))){
        execBlock(s.then,new Scope(scope));
      }else if(s.els){
        execBlock(s.els,new Scope(scope));
      }
      break;
    }
    case'while':{
      while(truthy(evalExpr(s.cond,scope))){
        try{execBlock(s.body,new Scope(scope));}
        catch(e){if(e instanceof BreakSig)break;if(e instanceof ContSig)continue;throw e;}
      }
      break;
    }
    case'for':{
      const iterVal=evalExpr(s.iter,scope);
      if(iterVal.t!=='list')throw new TernError(s.line,`cannot iterate ${typeName(iterVal)}`);
      const list=iterVal.v;
      let i=0;
      while(i<list.length){
        const iterScope=new Scope(scope);
        iterScope.vars.set(s.varName,list[i]);
        try{execBlock(s.body,iterScope);}
        catch(e){if(e instanceof BreakSig)break;if(e instanceof ContSig){i++;continue;}throw e;}
        i++;
      }
      break;
    }
    case'return':{
      const v=s.val?evalExpr(s.val,scope):NIL;
      throw new RetSig(v);
    }
    case'break':throw new BreakSig();
    case'continue':throw new ContSig();
    case'assign':{
      const v=evalExpr(s.val,scope);
      assignVar(scope,s.name,v,s.line);
      break;
    }
    case'idxAssign':{
      const obj=evalExpr(s.obj,scope);
      const idx=evalExpr(s.idx,scope);
      const val=evalExpr(s.val,scope);
      if(obj.t!=='list')throw new TernError(s.line,`cannot assign into ${typeName(obj)}`);
      if(idx.t!=='int')throw new TernError(s.line,`cannot index list with ${typeName(idx)}`);
      const i=Number(idx.v);
      if(i<0||i>=obj.v.length)throw new TernError(s.line,`index ${i} out of range for length ${obj.v.length}`);
      obj.v[i]=val;
      break;
    }
    case'expr':evalExpr(s.e,scope);break;
  }
}

// ===== MAIN =====

const dir=process.argv[2];
const src=fs.readFileSync(path.join(dir,'program.tern'),'utf-8');
const tokens=lex(src);
const parser=new Parser(tokens);
const program=parser.parseProgram();

builtinScope=new Scope(null);
const builtins=makeBuiltins();
for(const[k,v]of builtins)builtinScope.vars.set(k,v);

const globalScope=new Scope(builtinScope);

try{
  execBlock(program,globalScope);
}catch(e){
  if(e instanceof TernError){
    process.stdout.write(`error at line ${e.line}: ${e.msg}\n`);
  }else{
    throw e;
  }
}
process.exit(0);
