import Foundation

// MARK: - Values

final class TernList {
    var elements: [Val]
    init(_ elements: [Val] = []) { self.elements = elements }
}

final class TernFunc {
    let params: [String]
    let body: [Stmt]
    let capturedScope: Scope
    init(params: [String], body: [Stmt], capturedScope: Scope) {
        self.params = params; self.body = body; self.capturedScope = capturedScope
    }
}

final class BuiltinFunc {
    let name: String
    let minArgs: Int
    let maxArgs: Int // -1 = unlimited
    let call: ([Val]) throws -> Val
    init(name: String, minArgs: Int, maxArgs: Int, call: @escaping ([Val]) throws -> Val) {
        self.name = name; self.minArgs = minArgs; self.maxArgs = maxArgs; self.call = call
    }
}

enum Val {
    case int(Int64)
    case bool(Bool)
    case str(String)
    case list(TernList)
    case func_(TernFunc)
    case builtin(BuiltinFunc)
    case nilVal
}

// MARK: - Scope

final class Scope {
    var vars: [String: Val]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }
    func lookup(_ name: String) -> Val? {
        var s: Scope? = self
        while let sc = s { if let v = sc.vars[name] { return v }; s = sc.parent }
        return nil
    }
    func assign(_ name: String, _ val: Val) -> Bool {
        var s: Scope? = self
        while let sc = s { if sc.vars[name] != nil { sc.vars[name] = val; return true }; s = sc.parent }
        return false
    }
}

