}

enum Stmt {
    case letStmt(String, Expr, Int)
    case fnDecl(String, [String], [Stmt], Int)
    case ifStmt(Expr, [Stmt], ElseClause?, Int)
    case whileStmt(Expr, [Stmt], Int)
    case forStmt(String, Expr, [Stmt], Int)
    case returnStmt(Expr?, Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assignStmt(String, Expr, Int)
    case indexAssign(Expr, Expr, Expr, Int)
    case exprStmt(Expr, Int)
}

enum ElseClause {
    case if_(Stmt)
    case block([Stmt])
}

// MARK: - Lexer

func lex(_ src: String) -> [Token] {
    var tokens: [Token] = []
    let chars = Array(src)
    let n = chars.count
    var pos = 0
    var line = 1
    while pos < n {
        let c = chars[pos]
        if c == " " || c == "\t" || c == "\r" { pos += 1; continue }
        if c == "\n" { line += 1; pos += 1; continue }
        if c == "#" { while pos < n && chars[pos] != "\n" { pos += 1 }; continue }
        if c >= "0" && c <= "9" {
            var s = ""
            while pos < n && chars[pos] >= "0" && chars[pos] <= "9" { s.append(chars[pos]); pos += 1 }
            tokens.append(Token(type: .int, text: s, line: line)); continue
        }
        if c == "\"" {
            pos += 1; var s = ""
            while pos < n && chars[pos] != "\"" {
                if chars[pos] == "\\" {
                    pos += 1
                    if pos < n {
                        switch chars[pos] {
                        case "n": s.append("\n"); case "t": s.append("\t")
                        case "\"": s.append("\""); case "\\": s.append("\\")
                        default: s.append(chars[pos])
                        }
                        pos += 1
                    }
                } else { s.append(chars[pos]); pos += 1 }
            }
            if pos < n { pos += 1 }
            tokens.append(Token(type: .str, text: s, line: line)); continue
        }
        if (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c == "_" {
            var id = ""
            while pos < n {
                let ch = chars[pos]
                if (ch >= "a" && ch <= "z") || (ch >= "A" && ch <= "Z") || (ch >= "0" && ch <= "9") || ch == "_" {
                    id.append(ch); pos += 1
                } else { break }
            }
            let tt: TT
            switch id {
            case "let": tt = .kw_let; case "fn": tt = .kw_fn; case "if": tt = .kw_if
            case "else": tt = .kw_else; case "while": tt = .kw_while; case "for": tt = .kw_for
            case "in": tt = .kw_in; case "return": tt = .kw_return; case "break": tt = .kw_break
            case "continue": tt = .kw_continue; case "and": tt = .kw_and; case "or": tt = .kw_or
            case "not": tt = .kw_not; case "true": tt = .kw_true; case "false": tt = .kw_false
            case "nil": tt = .kw_nil; default: tt = .ident
            }
            tokens.append(Token(type: tt, text: id, line: line)); continue
        }
        if pos + 1 < n {
            let c2 = chars[pos + 1]
            if c == "=" && c2 == "=" { tokens.append(Token(type: .op_eq, text: "==", line: line)); pos += 2; continue }
            if c == "!" && c2 == "=" { tokens.append(Token(type: .op_neq, text: "!=", line: line)); pos += 2; continue }
            if c == "<" && c2 == "=" { tokens.append(Token(type: .op_le, text: "<=", line: line)); pos += 2; continue }
            if c == ">" && c2 == "=" { tokens.append(Token(type: .op_ge, text: ">=", line: line)); pos += 2; continue }
        }
        switch c {
        case "<": tokens.append(Token(type: .op_lt, text: "<", line: line))
        case ">": tokens.append(Token(type: .op_gt, text: ">", line: line))
        case "=": tokens.append(Token(type: .op_assign, text: "=", line: line))
        case "+": tokens.append(Token(type: .op_plus, text: "+", line: line))
        case "-": tokens.append(Token(type: .op_minus, text: "-", line: line))
        case "*": tokens.append(Token(type: .op_star, text: "*", line: line))
        case "/": tokens.append(Token(type: .op_slash, text: "/", line: line))
        case "%": tokens.append(Token(type: .op_percent, text: "%", line: line))
        case "(": tokens.append(Token(type: .lparen, text: "(", line: line))
        case ")": tokens.append(Token(type: .rparen, text: ")", line: line))
        case "[": tokens.append(Token(type: .lbracket, text: "[", line: line))
        case "]": tokens.append(Token(type: .rbracket, text: "]", line: line))
        case "{": tokens.append(Token(type: .lbrace, text: "{", line: line))
        case "}": tokens.append(Token(type: .rbrace, text: "}", line: line))
        case ",": tokens.append(Token(type: .comma, text: ",", line: line))
        case ";": tokens.append(Token(type: .semicolon, text: ";", line: line))
        default: pos += 1; continue
        }
        pos += 1
    }
    tokens.append(Token(type: .eof, text: "", line: line))
    return tokens
}

// MARK: - Parser

final class Parser {
    let tokens: [Token]
    var pos: Int = 0
    init(_ tokens: [Token]) { self.tokens = tokens }
    func peek() -> Token { tokens[pos] }
    func peekType() -> TT { tokens[pos].type }
    @discardableResult func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ tt: TT) { pos += 1 }
    func match(_ tt: TT) -> Bool { if tokens[pos].type == tt { pos += 1; return true }; return false }

    func parseProgram() -> [Stmt] {
        var stmts: [Stmt] = []
        while peekType() != .eof { stmts.append(parseStmt()) }
        return stmts
    }

    func parseBlock() -> [Stmt] {
        expect(.lbrace)
        var stmts: [Stmt] = []
        while peekType() != .rbrace { stmts.append(parseStmt()) }
        expect(.rbrace)
        return stmts
    }

    func parseParams() -> [String] {
        var params: [String] = []
        if peekType() != .rparen {
            params.append(advance().text)
            while match(.comma) { params.append(advance().text) }
        }
        return params
    }

    func parseStmt() -> Stmt {
        switch peekType() {
        case .kw_let:
            advance()
            let name = advance().text
            expect(.op_assign)
            let expr = parseExpr()
            expect(.semicolon)
            return .letStmt(name, expr, 0)
        case .kw_fn where tokens[pos + 1].type == .ident:
            advance()
            let name = advance().text
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name, params, body, 0)
        case .kw_if:
            return parseIfStmt()
        case .kw_while:
            let line = peek().line
            advance()
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond, body, line)
        case .kw_for:
            let line = peek().line
            advance()
            let varName = advance().text
            expect(.kw_in)
            let iter = parseExpr()
            let body = parseBlock()
            return .forStmt(varName, iter, body, line)
        case .kw_return:
            let line = peek().line
            advance()
            if peekType() == .semicolon { expect(.semicolon); return .returnStmt(nil, line) }
            let expr = parseExpr()
            expect(.semicolon)
            return .returnStmt(expr, line)
        case .kw_break:
            let line = peek().line
            advance(); expect(.semicolon); return .breakStmt(line)
        case .kw_continue:
            let line = peek().line
            advance(); expect(.semicolon); return .continueStmt(line)
        default:
            let expr = parseExpr()
            if peekType() == .op_assign {
                advance()
                let val = parseExpr()
                expect(.semicolon)
                switch expr {
                case .ident(let name, let line): return .assignStmt(name, val, line)
                case .index(let obj, let idx, let line): return .indexAssign(obj, idx, val, line)
                default: fatalError()
                }
            }
            expect(.semicolon)
            return .exprStmt(expr, exprLine(expr))
        }
    }

    func parseIfStmt() -> Stmt {
        let line = peek().line
        expect(.kw_if)
        let cond = parseExpr()
        let body = parseBlock()
        var elseClause: ElseClause? = nil
        if peekType() == .kw_else {
            advance()
            if peekType() == .kw_if { elseClause = .if_(parseIfStmt()) }
            else { elseClause = .block(parseBlock()) }
        }
        return .ifStmt(cond, body, elseClause, line)
    }

    func exprLine(_ e: Expr) -> Int {
        switch e {
        case .intLit(_, let l): return l; case .strLit(_, let l): return l
        case .boolLit(_, let l): return l; case .nilLit(let l): return l
        case .ident(_, let l): return l; case .binary(_, _, _, let l): return l
        case .unaryNot(_, let l): return l; case .unaryNeg(_, let l): return l
        case .andE(_, _, let l): return l; case .orE(_, _, let l): return l
        case .call(_, _, let l): return l; case .index(_, _, let l): return l
        case .listLit(_, let l): return l; case .fnLit(_, _, let l): return l
        }
    }

    func parseExpr() -> Expr { parseOr() }
    func parseOr() -> Expr {
        var left = parseAnd()
        while peekType() == .kw_or { let l = peek().line; advance(); left = .orE(left, parseAnd(), l) }
        return left
    }
    func parseAnd() -> Expr {
        var left = parseNot()
        while peekType() == .kw_and { let l = peek().line; advance(); left = .andE(left, parseNot(), l) }
        return left
    }
    func parseNot() -> Expr {
        if peekType() == .kw_not { let l = peek().line; advance(); return .unaryNot(parseNot(), l) }
        return parseComparison()
    }
    func parseComparison() -> Expr {
        var left = parseAddSub()
        while peekType() == .op_eq || peekType() == .op_neq || peekType() == .op_lt || peekType() == .op_le || peekType() == .op_gt || peekType() == .op_ge {
            let t = advance(); left = .binary(t.text, left, parseAddSub(), t.line)
        }
        return left
    }
    func parseAddSub() -> Expr {
        var left = parseMulDiv()
        while peekType() == .op_plus || peekType() == .op_minus {
            let t = advance(); left = .binary(t.text, left, parseMulDiv(), t.line)
        }
        return left
    }
    func parseMulDiv() -> Expr {
        var left = parseUnaryNeg()
        while peekType() == .op_star || peekType() == .op_slash || peekType() == .op_percent {
            let t = advance(); left = .binary(t.text, left, parseUnaryNeg(), t.line)
        }
        return left
    }
    func parseUnaryNeg() -> Expr {
        if peekType() == .op_minus { let l = peek().line; advance(); return .unaryNeg(parseUnaryNeg(), l) }
        return parsePostfix()
    }
    func parsePostfix() -> Expr {
        var expr = parsePrimary()
        while true {
            if peekType() == .lparen {
                let l = peek().line; advance()
                var args: [Expr] = []
                if peekType() != .rparen { args.append(parseExpr()); while match(.comma) { args.append(parseExpr()) } }
                expect(.rparen); expr = .call(expr, args, l)
            } else if peekType() == .lbracket {
                let l = peek().line; advance()
                let idx = parseExpr(); expect(.rbracket); expr = .index(expr, idx, l)
            } else { break }
        }
        return expr
    }
    func parsePrimary() -> Expr {
        switch peekType() {
        case .int: let t = advance(); return .intLit(Int64(t.text)!, t.line)
        case .str: let t = advance(); return .strLit(t.text, t.line)
        case .kw_true: let t = advance(); return .boolLit(true, t.line)
        case .kw_false: let t = advance(); return .boolLit(false, t.line)
        case .kw_nil: let t = advance(); return .nilLit(t.line)
        case .ident: let t = advance(); return .ident(t.text, t.line)
        case .lparen: advance(); let e = parseExpr(); expect(.rparen); return e
        case .lbracket:
            let l = peek().line; advance()
            var elems: [Expr] = []
            if peekType() != .rbracket { elems.append(parseExpr()); while match(.comma) { elems.append(parseExpr()) } }
            expect(.rbracket); return .listLit(elems, l)
        case .kw_fn:
            let l = peek().line; advance(); expect(.lparen)
            let params = parseParams(); expect(.rparen)
            let body = parseBlock(); return .fnLit(params, body, l)
        default: fatalError("unexpected token \(peek())")
        }
    }
}

// MARK: - Type name

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"; case .bool: return "bool"; case .str: return "string"
    case .list: return "list"; case .func_: return "function"; case .builtin: return "function"
    case .nilVal: return "nil"
    }
}

// MARK: - Equality

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.str(let x), .str(let y)): return x == y
    case (.nilVal, .nilVal): return true
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count { if !valEqual(x.elements[i], y.elements[i]) { return false } }
        return true
    case (.func_(let x), .func_(let y)): return x === y
    case (.builtin(let x), .builtin(let y)): return x === y
    default: return false
    }
}

// MARK: - Display

func escapeStr(_ s: String) -> String {
    var r = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": r += "\\\\"; case "\"": r += "\\\""
        case "\n": r += "\\n"; case "\t": r += "\\t"
        default: r.unicodeScalars.append(c)
        }
    }
    return r
}

func displayVal(_ v: Val, inList: Bool, visited: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let n): return String(n)
    case .bool(let b): return b ? "true" : "false"
    case .str(let s): return inList ? "\"" + escapeStr(s) + "\"" : s
    case .nilVal: return "nil"
    case .func_: return "<fn>"
    case .builtin: return "<fn>"
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if visited.contains(oid) { return "[...]" }
        visited.insert(oid)
        var parts: [String] = []
        parts.reserveCapacity(l.elements.count)
        for e in l.elements { parts.append(displayVal(e, inList: true, visited: &visited)) }
        visited.remove(oid)
        return "[" + parts.joined(separator: ", ") + "]"
    }
}

// MARK: - Truthiness

func truthy(_ v: Val) -> Bool {
    switch v {
    case .bool(let b): return b
    case .nilVal: return false
    case .int(let n): return n != 0
    case .str(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    default: return true
    }
}

// MARK: - Interpreter

final class Interpreter {
    let builtinScope: Scope
    let globalScope: Scope
    var out: String = ""

    init() {
        builtinScope = Scope(parent: nil)
        globalScope = Scope(parent: builtinScope)
        setupBuiltins()
    }

    func setupBuiltins() {
        let scope = builtinScope
        scope.vars["print"] = .builtin(BuiltinFunc(name: "print", minArgs: 0, maxArgs: -1) { args in
            var parts: [String] = []
            for a in args { var v = Set<ObjectIdentifier>(); parts.append(displayVal(a, inList: false, visited: &v)) }
            self.out += parts.joined(separator: " ") + "\n"
            return .nilVal
        })
        scope.vars["str"] = .builtin(BuiltinFunc(name: "str", minArgs: 1, maxArgs: 1) { args in
            var v = Set<ObjectIdentifier>()
            return .str(displayVal(args[0], inList: false, visited: &v))
        })
        scope.vars["type"] = .builtin(BuiltinFunc(name: "type", minArgs: 1, maxArgs: 1) { args in
            return .str(typeName(args[0]))
        })
        scope.vars["len"] = .builtin(BuiltinFunc(name: "len", minArgs: 1, maxArgs: 1) { args in
            switch args[0] {
            case .str(let s): return .int(Int64(s.count))
            case .list(let l): return .int(Int64(l.elements.count))
            default: throw TernSignal.runtime("bad argument to len")
            }
        })
        scope.vars["push"] = .builtin(BuiltinFunc(name: "push", minArgs: 2, maxArgs: 2) { args in
            switch args[0] {
            case .list(let l): l.elements.append(args[1]); return .nilVal
            default: throw TernSignal.runtime("bad argument to push")
            }
        })
        scope.vars["pop"] = .builtin(BuiltinFunc(name: "pop", minArgs: 1, maxArgs: 1) { args in
            switch args[0] {
            case .list(let l):
                if l.elements.isEmpty { throw TernSignal.runtime("bad argument to pop") }
                return l.elements.removeLast()
            default: throw TernSignal.runtime("bad argument to pop")
            }
        })
        scope.vars["range"] = .builtin(BuiltinFunc(name: "range", minArgs: 2, maxArgs: 2) { args in
            guard case .int(let a) = args[0], case .int(let b) = args[1] else {
                throw TernSignal.runtime("bad argument to range")
            }
            if b <= a { return .list(TernList()) }
            var elems: [Val] = []
            elems.reserveCapacity(Int(b - a))
            var i = a
            while i < b { elems.append(.int(i)); i += 1 }
            return .list(TernList(elems))
        })
        scope.vars["slice"] = .builtin(BuiltinFunc(name: "slice", minArgs: 3, maxArgs: 3) { args in
            guard case .int(let a) = args[1], case .int(let b) = args[2] else {
                throw TernSignal.runtime("bad argument to slice")
            }
            switch args[0] {
            case .str(let s):
                let chars = Array(s)
                let ai = Int(a), bi = Int(b)
                if ai < 0 || bi > chars.count || ai > bi { throw TernSignal.runtime("bad argument to slice") }
                return .str(String(chars[ai..<bi]))
            case .list(let l):
                let ai = Int(a), bi = Int(b)
                if ai < 0 || bi > l.elements.count || ai > bi { throw TernSignal.runtime("bad argument to slice") }
                return .list(TernList(Array(l.elements[ai..<bi])))
            default: throw TernSignal.runtime("bad argument to slice")
            }
        })
    }

    func run(_ stmts: [Stmt]) {
        do {
            try execBlock(stmts, globalScope)
        } catch TernSignal.runtime(let msg) {
            // already handled
            _ = msg
        } catch {
            // shouldn't happen
        }
    }

    func execBlock(_ stmts: [Stmt], _ scope: Scope) throws {
        for s in stmts { try execStmt(s, scope) }
    }

    func execStmt(_ s: Stmt, _ scope: Scope) throws {
        switch s {
        case .letStmt(let name, let expr, _):
            let v = try eval(expr, scope)
            scope.vars[name] = v
        case .fnDecl(let name, let params, let body, _):
            let f = TernFunc(params: params, body: body, capturedScope: scope)
            scope.vars[name] = .func_(f)
        case .ifStmt(let cond, let body, let elseClause, _):
            let cv = try eval(cond, scope)
            if truthy(cv) {
                let newScope = Scope(parent: scope)
                try execBlock(body, newScope)
            } else if let ec = elseClause {
                switch ec {
                case .if_(let stmt): try execStmt(stmt, scope)
                case .block(let b):
                    let newScope = Scope(parent: scope)
                    try execBlock(b, newScope)
                }
            }
        case .whileStmt(let cond, let body, _):
            while true {
                let cv = try eval(cond, scope)
                if !truthy(cv) { break }
                let newScope = Scope(parent: scope)
                do { try execBlock(body, newScope) }
                catch TernSignal.cont { continue }
                catch TernSignal.brk { break }
            }
        case .forStmt(let varName, let iterExpr, let body, let line):
            let iterVal = try eval(iterExpr, scope)
            guard case .list(let lst) = iterVal else {
                throw TernSignal.runtime("cannot iterate \(typeName(iterVal))")
            }
            // line is the line of 'for' keyword - but we stored it differently
            // Actually we need the line of 'for' for the error. Let me fix: the error token is 'for'.
            // We'll pass it via the Stmt. Let me use the stored line.
            // Actually I stored it in the Stmt already. Let me just use it.
            var i = 0
            while i < lst.elements.count {
                let newScope = Scope(parent: scope)
                newScope.vars[varName] = lst.elements[i]
                do { try execBlock(body, newScope) }
                catch TernSignal.cont { i += 1; continue }
                catch TernSignal.brk { break }
                i += 1
            }
        case .returnStmt(let expr, _):
            if let e = expr { throw TernSignal.ret(try eval(e, scope)) }
            else { throw TernSignal.ret(.nilVal) }
        case .breakStmt(_): throw TernSignal.brk
        case .continueStmt(_): throw TernSignal.cont
        case .assignStmt(let name, let valExpr, let line):
            let v = try eval(valExpr, scope)
            if !scope.assign(name, v) {
                throw TernSignal.runtime("undefined variable \(name)")
            }
            _ = line
        case .indexAssign(let objExpr, let idxExpr, let valExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            let v = try eval(valExpr, scope)
            // checks
            guard case .list(let l) = obj else {
                throw TernSignal.runtime("cannot assign into \(typeName(obj))")
            }
            guard case .int(let i) = idx else {
                throw TernSignal.runtime("cannot index list with \(typeName(idx))")
            }
            let ii = Int(i)
            if ii < 0 || ii >= l.elements.count {
                throw TernSignal.runtime("index \(i) out of range for length \(l.elements.count)")
            }
            l.elements[ii] = v
            _ = line
        case .exprStmt(let expr, _):
            _ = try eval(expr, scope)
        }
    }

    func eval(_ e: Expr, _ scope: Scope) throws -> Val {
        switch e {
        case .intLit(let v, _): return .int(v)
        case .strLit(let v, _): return .str(v)
        case .boolLit(let v, _): return .bool(v)
        case .nilLit(_): return .nilVal
        case .ident(let name, _):
            if let v = scope.lookup(name) { return v }
            throw TernSignal.runtime("undefined variable \(name)")
        case .andE(let l, let r, _):
            let lv = try eval(l, scope)
            if !truthy(lv) { return lv }
            return try eval(r, scope)
        case .orE(let l, let r, _):
            let lv = try eval(l, scope)
            if truthy(lv) { return lv }
            return try eval(r, scope)
        case .unaryNot(let expr, _):
            let v = try eval(expr, scope)
            return .bool(!truthy(v))
        case .unaryNeg(let expr, let line):
            let v = try eval(expr, scope)
            guard case .int(let n) = v else {
                throw TernSignal.runtime("cannot apply - to \(typeName(v))")
            }
            if n == Int64.min { throw TernSignal.runtime("integer overflow") }
            _ = line
            return .int(-n)
        case .binary(let op, let le, let re, let line):
            let lv = try eval(le, scope)
            let rv = try eval(re, scope)
            return try applyBinary(op, lv, rv, line)
        case .call(let calleeExpr, let argExprs, let line):
            let callee = try eval(calleeExpr, scope)
            var args: [Val] = []
            args.reserveCapacity(argExprs.count)
            for ae in argExprs { args.append(try eval(ae, scope)) }
            return try doCall(callee, args, line)
        case .index(let objExpr, let idxExpr, let line):
            let obj = try eval(objExpr, scope)
            let idx = try eval(idxExpr, scope)
            return try doIndex(obj, idx, line)
        case .listLit(let elems, _):
            var vals: [Val] = []
            vals.reserveCapacity(elems.count)
            for el in elems { vals.append(try eval(el, scope)) }
            return .list(TernList(vals))
        case .fnLit(let params, let body, _):
            return .func_(TernFunc(params: params, body: body, capturedScope: scope))
        }
    }

