                throw TernSignal.runtime("cannot apply - to \(typeName(lv)) and \(typeName(rv))")
            }
            let (r, ov) = a.subtractingReportingOverflow(b)
            if ov { throw TernSignal.runtime("integer overflow") }
            return .int(r)
        case "*":
            guard case .int(let a) = lv, case .int(let b) = rv else {
                throw TernSignal.runtime("cannot apply * to \(typeName(lv)) and \(typeName(rv))")
            }
            let (r, ov) = a.multipliedReportingOverflow(by: b)
            if ov { throw TernSignal.runtime("integer overflow") }
            return .int(r)
        case "/":
            guard case .int(let a) = lv, case .int(let b) = rv else {
                throw TernSignal.runtime("cannot apply / to \(typeName(lv)) and \(typeName(rv))")
            }
            if b == 0 { throw TernSignal.runtime("division by zero") }
            if a == Int64.min && b == -1 { throw TernSignal.runtime("integer overflow") }
            return .int(a / b)
        case "%":
            guard case .int(let a) = lv, case .int(let b) = rv else {
                throw TernSignal.runtime("cannot apply % to \(typeName(lv)) and \(typeName(rv))")
            }
            if b == 0 { throw TernSignal.runtime("division by zero") }
            if b == -1 { return .int(0) }
            return .int(a % b)
        default: fatalError("unknown op \(op)")
        }
    }

    func doCall(_ callee: Val, _ args: [Val], _ line: Int) throws -> Val {
        switch callee {
        case .func_(let f):
            if args.count != f.params.count {
                throw TernSignal.runtime("expected \(f.params.count) arguments, got \(args.count)")
            }
            let callScope = Scope(parent: f.capturedScope)
            for i in 0..<f.params.count { callScope.vars[f.params[i]] = args[i] }
            do {
                try execBlock(f.body, callScope)
            } catch TernSignal.ret(let v) { return v }
            return .nilVal
        case .builtin(let b):
            if b.maxArgs == -1 {
                if args.count < b.minArgs {
                    throw TernSignal.runtime("expected \(b.minArgs) arguments, got \(args.count)")
                }
            } else {
                if args.count != b.minArgs {
                    throw TernSignal.runtime("expected \(b.minArgs) arguments, got \(args.count)")
                }
            }
            return try b.call(args)
        default:
            throw TernSignal.runtime("cannot call \(typeName(callee))")
        }
    }

    func doIndex(_ obj: Val, _ idx: Val, _ line: Int) throws -> Val {
        _ = line
        switch obj {
        case .list(let l):
            guard case .int(let i) = idx else {
                throw TernSignal.runtime("cannot index list with \(typeName(idx))")
            }
            let ii = Int(i)
            if ii < 0 || ii >= l.elements.count {
                throw TernSignal.runtime("index \(i) out of range for length \(l.elements.count)")
            }
            return l.elements[ii]
        case .str(let s):
            guard case .int(let i) = idx else {
                throw TernSignal.runtime("cannot index string with \(typeName(idx))")
            }
            let chars = Array(s)
            let ii = Int(i)
            if ii < 0 || ii >= chars.count {
                throw TernSignal.runtime("index \(i) out of range for length \(chars.count)")
            }
            return .str(String(chars[ii]))
        default:
            throw TernSignal.runtime("cannot index \(typeName(obj)) with \(typeName(idx))")
        }
    }
}

