/* ============ LEXER ============ */
typedef enum {
    TK_INT, TK_STR, TK_IDENT,
    TK_LET, TK_FN, TK_IF, TK_ELSE, TK_WHILE, TK_FOR, TK_IN,
    TK_RETURN, TK_BREAK, TK_CONTINUE, TK_AND, TK_OR, TK_NOT,
    TK_TRUE, TK_FALSE, TK_NIL,
    TK_EQ, TK_NE, TK_LE, TK_GE, TK_LT, TK_GT,
    TK_ASSIGN, TK_PLUS, TK_MINUS, TK_STAR, TK_SLASH, TK_PERCENT,
    TK_LPAREN, TK_RPAREN, TK_LBRACKET, TK_RBRACKET, TK_LBRACE, TK_RBRACE,
    TK_COMMA, TK_SEMI, TK_EOF
} TokType;

typedef struct {
    TokType type;
    int64_t ival;
    char *sval;
    int line;
} Token;

static Token *g_toks;
static int g_ntoks, g_pos;

static TokType kw_lookup(const char *s) {
    if(!strcmp(s,"let"))return TK_LET; if(!strcmp(s,"fn"))return TK_FN;
    if(!strcmp(s,"if"))return TK_IF; if(!strcmp(s,"else"))return TK_ELSE;
    if(!strcmp(s,"while"))return TK_WHILE; if(!strcmp(s,"for"))return TK_FOR;
    if(!strcmp(s,"in"))return TK_IN; if(!strcmp(s,"return"))return TK_RETURN;
    if(!strcmp(s,"break"))return TK_BREAK; if(!strcmp(s,"continue"))return TK_CONTINUE;
    if(!strcmp(s,"and"))return TK_AND; if(!strcmp(s,"or"))return TK_OR;
    if(!strcmp(s,"not"))return TK_NOT; if(!strcmp(s,"true"))return TK_TRUE;
    if(!strcmp(s,"false"))return TK_FALSE; if(!strcmp(s,"nil"))return TK_NIL;
    return TK_IDENT;
}

static void lex(const char *src) {
    int cap = 1024, n = 0;
    g_toks = malloc(cap * sizeof(Token));
    int line = 1;
    const char *p = src;
    while (*p) {
        if (*p=='\n') { line++; p++; continue; }
        if (*p==' '||*p=='\t'||*p=='\r') { p++; continue; }
        if (*p=='#') { while(*p && *p!='\n') p++; continue; }
        if (n >= cap) { cap*=2; g_toks=realloc(g_toks,cap*sizeof(Token)); }
        Token *t = &g_toks[n];
        t->line = line;
        t->sval = NULL;
        if (isdigit(*p)) {
            int64_t v=0;
            while(isdigit(*p)) { v = v*10 + (*p-'0'); p++; }
            t->type=TK_INT; t->ival=v; n++; continue;
        }
        if (*p=='"') {
            p++;
            int scap=64, sl=0;
            char *sb=malloc(scap);
            while(*p && *p!='"') {
                if(*p=='\\') {
                    p++;
                    if(*p=='n') { sb[sl++]='\n'; p++; }
                    else if(*p=='t') { sb[sl++]='\t'; p++; }
                    else if(*p=='"') { sb[sl++]='"'; p++; }
                    else if(*p=='\\') { sb[sl++]='\\'; p++; }
                    else { sb[sl++]=*p; p++; }
                } else { sb[sl++]=*p; p++; }
                if(sl>=scap-1){scap*=2;sb=realloc(sb,scap);}
            }
            sb[sl]='\0'; p++;
            t->type=TK_STR; t->sval=sb; n++; continue;
        }
        if (isalpha(*p)||*p=='_') {
            int scap=32, sl=0;
            char *sb=malloc(scap);
            while(isalnum(*p)||*p=='_') { sb[sl++]=*p; p++; if(sl>=scap-1){scap*=2;sb=realloc(sb,scap);} }
            sb[sl]='\0';
            t->type=kw_lookup(sb); t->sval=sb; n++; continue;
        }
        /* operators */
        if(*p=='='&&p[1]=='='){t->type=TK_EQ;p+=2;n++;continue;}
        if(*p=='!'&&p[1]=='='){t->type=TK_NE;p+=2;n++;continue;}
        if(*p=='<'&&p[1]=='='){t->type=TK_LE;p+=2;n++;continue;}
        if(*p=='>'&&p[1]=='='){t->type=TK_GE;p+=2;n++;continue;}
        if(*p=='<'&&p[1]=='>'){t->type=TK_NE;p+=2;n++;continue;}
        if(*p=='='&&p[1]!='='){t->type=TK_ASSIGN;p++;n++;continue;}
        if(*p=='<'){t->type=TK_LT;p++;n++;continue;}
        if(*p=='>'){t->type=TK_GT;p++;n++;continue;}
        if(*p=='+'){t->type=TK_PLUS;p++;n++;continue;}
        if(*p=='-'){t->type=TK_MINUS;p++;n++;continue;}
        if(*p=='*'){t->type=TK_STAR;p++;n++;continue;}
        if(*p=='/'){t->type=TK_SLASH;p++;n++;continue;}
        if(*p=='%'){t->type=TK_PERCENT;p++;n++;continue;}
        if(*p=='('){t->type=TK_LPAREN;p++;n++;continue;}
        if(*p==')'){t->type=TK_RPAREN;p++;n++;continue;}
        if(*p=='['){t->type=TK_LBRACKET;p++;n++;continue;}
        if(*p==']'){t->type=TK_RBRACKET;p++;n++;continue;}
        if(*p=='{'){t->type=TK_LBRACE;p++;n++;continue;}
        if(*p=='}'){t->type=TK_RBRACE;p++;n++;continue;}
        if(*p==','){t->type=TK_COMMA;p++;n++;continue;}
        if(*p==';'){t->type=TK_SEMI;p++;n++;continue;}
        p++; /* skip unknown */
    }
    if(n>=cap){cap++;g_toks=realloc(g_toks,cap*sizeof(Token));}
    g_toks[n].type=TK_EOF; g_toks[n].line=line; g_toks[n].sval=NULL;
    g_ntoks=n+1; g_pos=0;
}

static Token *peek(void){return &g_toks[g_pos];}
static Token *peek2(void){return &g_toks[g_pos+1];}
static Token *advance(void){return &g_toks[g_pos++];}
static bool match(TokType t){if(g_toks[g_pos].type==t){g_pos++;return true;}return false;}
static void expect(TokType t){g_pos++;}

/* ============ AST ============ */
typedef enum {
    ST_LET, ST_FNDECL, ST_IF, ST_WHILE, ST_FOR, ST_RETURN,
    ST_BREAK, ST_CONTINUE, ST_ASSIGN, ST_IDXASSIGN, ST_EXPR,
    EX_INT, EX_STR, EX_BOOL, EX_NIL, EX_IDENT, EX_LIST, EX_FN,
    EX_CALL, EX_INDEX, EX_BIN, EX_UN, EX_AND, EX_OR
} NType;

typedef struct Node Node;
struct Node {
    NType type;
    int line;
    /* generic fields */
    char *name;
    char *name2;
    int64_t ival;
    bool bval;
    int op;
    Node *a, *b, *c;
    Node **kids;
    int nkids;
    char **params;
    int nparams;
    bool has_else;
};

static Node *mk_node(NType t, int line) {
    Node *n = calloc(1, sizeof(Node));
    n->type=t; n->line=line;
    return n;
}

/* ============ PARSER ============ */
static Node *parse_expr(void);
static Node *parse_or(void);
static Node **parse_block(int *nout);
static Node *parse_stmt(void);
static Node **parse_stmts_until_rbrace(int *nout);

static Node *parse_params(void) {
    /* returns via global temp - we'll handle inline */
    return NULL;
}

static void parse_params_into(char ***params, int *np) {
    int cap=8; *params=malloc(cap*sizeof(char*)); *np=0;
    if(peek()->type==TK_IDENT){
        (*params)[(*np)++]=peek()->sval; advance();
        while(match(TK_COMMA)){
            if(*np>=cap){cap*=2;*params=realloc(*params,cap*sizeof(char*));}
            (*params)[(*np)++]=peek()->sval; advance();
        }
    }
}

static Node *parse_primary(void) {
    Token *t = peek();
    Node *n;
    switch(t->type){
    case TK_INT: n=mk_node(EX_INT,t->line); n->ival=t->ival; advance(); return n;
    case TK_STR: n=mk_node(EX_STR,t->line); n->name=t->sval; advance(); return n;
    case TK_TRUE: n=mk_node(EX_BOOL,t->line); n->bval=true; advance(); return n;
    case TK_FALSE: n=mk_node(EX_BOOL,t->line); n->bval=false; advance(); return n;
    case TK_NIL: n=mk_node(EX_NIL,t->line); advance(); return n;
    case TK_IDENT: n=mk_node(EX_IDENT,t->line); n->name=t->sval; advance(); return n;
    case TK_LPAREN: advance(); n=parse_or(); expect(TK_RPAREN); return n;
    case TK_LBRACKET: {
        advance();
        n=mk_node(EX_LIST,t->line);
        int cap=8; n->kids=malloc(cap*sizeof(Node*)); n->nkids=0;
        if(peek()->type!=TK_RBRACKET){
            n->kids[n->nkids++]=parse_or();
            while(match(TK_COMMA)){
                if(n->nkids>=cap){cap*=2;n->kids=realloc(n->kids,cap*sizeof(Node*));}
                n->kids[n->nkids++]=parse_or();
            }
        }
        expect(TK_RBRACKET);
        return n;
    }
    case TK_FN: {
        advance();
        n=mk_node(EX_FN,t->line);
        expect(TK_LPAREN);
        parse_params_into(&n->params,&n->nparams);
        expect(TK_RPAREN);
        n->kids=parse_block(&n->nkids);
        return n;
    }
    default:
        n=mk_node(EX_NIL,t->line); advance(); return n;
    }
}

static Node *parse_postfix(void) {
    Node *n = parse_primary();
    for(;;){
        if(peek()->type==TK_LPAREN){
            int ln=peek()->line; advance();
            Node *c=mk_node(EX_CALL,ln); c->a=n;
            int cap=8; c->kids=malloc(cap*sizeof(Node*)); c->nkids=0;
            if(peek()->type!=TK_RPAREN){
                c->kids[c->nkids++]=parse_or();
                while(match(TK_COMMA)){
                    if(c->nkids>=cap){cap*=2;c->kids=realloc(c->kids,cap*sizeof(Node*));}
                    c->kids[c->nkids++]=parse_or();
                }
            }
            expect(TK_RPAREN);
            n=c;
        } else if(peek()->type==TK_LBRACKET){
            int ln=peek()->line; advance();
            Node *c=mk_node(EX_INDEX,ln); c->a=n; c->b=parse_or();
            expect(TK_RBRACKET);
            n=c;
        } else break;
    }
    return n;
}

static Node *parse_unary(void) {
    if(peek()->type==TK_MINUS){
        int ln=peek()->line; advance();
        Node *n=mk_node(EX_UN,ln); n->op=TK_MINUS; n->a=parse_unary(); return n;
    }
    return parse_postfix();
}

static Node *parse_mul(void) {
    Node *n=parse_unary();
    while(peek()->type==TK_STAR||peek()->type==TK_SLASH||peek()->type==TK_PERCENT){
        int ln=peek()->line; int op=peek()->type; advance();
        Node *c=mk_node(EX_BIN,ln); c->op=op; c->a=n; c->b=parse_unary(); n=c;
    }
    return n;
}

static Node *parse_add(void) {
    Node *n=parse_mul();
    while(peek()->type==TK_PLUS||peek()->type==TK_MINUS){
        int ln=peek()->line; int op=peek()->type; advance();
        Node *c=mk_node(EX_BIN,ln); c->op=op; c->a=n; c->b=parse_mul(); n=c;
    }
    return n;
}

static Node *parse_cmp(void) {
    Node *n=parse_add();
    while(peek()->type==TK_EQ||peek()->type==TK_NE||peek()->type==TK_LT||
          peek()->type==TK_LE||peek()->type==TK_GT||peek()->type==TK_GE){
        int ln=peek()->line; int op=peek()->type; advance();
        Node *c=mk_node(EX_BIN,ln); c->op=op; c->a=n; c->b=parse_add(); n=c;
    }
    return n;
}

static Node *parse_not(void) {
    if(peek()->type==TK_NOT){
        int ln=peek()->line; advance();
        Node *n=mk_node(EX_UN,ln); n->op=TK_NOT; n->a=parse_not(); return n;
    }
    return parse_cmp();
}

static Node *parse_and(void) {
    Node *n=parse_not();
    while(peek()->type==TK_AND){
        int ln=peek()->line; advance();
        Node *c=mk_node(EX_AND,ln); c->a=n; c->b=parse_not(); n=c;
    }
    return n;
}

static Node *parse_or(void) {
    Node *n=parse_and();
    while(peek()->type==TK_OR){
        int ln=peek()->line; advance();
        Node *c=mk_node(EX_OR,ln); c->a=n; c->b=parse_and(); n=c;
    }
    return n;
}

static Node *parse_expr(void){ return parse_or(); }

static Node **parse_block(int *nout) {
    expect(TK_LBRACE);
    Node **r = parse_stmts_until_rbrace(nout);
    expect(TK_RBRACE);
    return r;
}

static Node **parse_stmts_until_rbrace(int *nout) {
    int cap=16; *nout=0;
    Node **arr=malloc(cap*sizeof(Node*));
    while(peek()->type!=TK_RBRACE && peek()->type!=TK_EOF){
        if(*nout>=cap){cap*=2;arr=realloc(arr,cap*sizeof(Node*));}
        arr[(*nout)++]=parse_stmt();
    }
    return arr;
}

static Node *parse_stmt(void) {
    Token *t=peek();
    Node *n;
    switch(t->type){
    case TK_LET: {
        advance();
        n=mk_node(ST_LET,t->line);
        n->name=peek()->sval; advance();
        expect(TK_ASSIGN);
        n->a=parse_expr();
        expect(TK_SEMI);
        return n;
    }
    case TK_FN: {
        if(peek2()->type==TK_IDENT){
            advance();
            n=mk_node(ST_FNDECL,t->line);
            n->name=peek()->sval; advance();
            expect(TK_LPAREN);
            parse_params_into(&n->params,&n->nparams);
            expect(TK_RPAREN);
            n->kids=parse_block(&n->nkids);
            return n;
        }
        goto expr_stmt;
    }
    case TK_IF: {
        n=mk_node(ST_IF,t->line);
        advance();
        n->a=parse_expr();
        n->kids=parse_block(&n->nkids);
        if(peek()->type==TK_ELSE){
            advance();
            if(peek()->type==TK_IF){
                n->b=parse_stmt();
                n->has_else=true;
            } else {
                n->b=NULL;
                n->c=parse_block(&n->nkids); /* reuse nkids? no... */
                /* store else block differently */
                /* Let me use a separate field */
                n->has_else=true;
                /* Actually I'll store else block in a different way */
                /* Use: if n->b is a node of type ST_IF, it's else-if */
                /* Otherwise n->c is else block, n->nkids is then count */
                /* Hmm this is getting messy. Let me restructure. */
                /* I'll store else body in n->kids and n->nkids for then,
                   and use a separate allocation for else. */
                /* Actually let me just use: n->a=cond, n->kids/n->nkids=then,
                   n->b=else_if_node or NULL, n->c=else_body, n->nkids2=else_count */
                /* Too complex. Let me use a different approach. */
                /* I'll just put else-if as a single statement in n->b */
                /* and else-block as a block node in n->b */
                /* Let me restructure the if node: */
                /* n->a = cond */
                /* n->kids, n->nkids = then body */
                /* n->b = else body as a single Node* (either ST_IF or a special block) */
                /* For else block, I'll wrap it in a special node */
                /* Actually simplest: store else body as kids2/nkids2 */
                /* Let me just add more fields to Node */
                /* I'll handle this differently - store else block in a wrapper */
                /* For now, let me just use: if else is a block, create a synthetic ST_BLOCK node */
                /* Actually, the simplest: I'll store else body in n->kids after then body */
                /* No, that's confusing. Let me just add fields. */
                /* I'll add: Node **kids2; int nkids2; */
                /* But I already defined Node... let me just use the existing fields creatively */
                /* n->a=cond, n->kids/n->nkids=then, n->b=else_node_or_null, n->c=else_block, n->name2=(char*)(intptr_t)nkids2 */
                /* This is too hacky. Let me just add fields to Node. */
                /* I'll redefine Node to have more fields. */
                /* OK I'll just handle it: for else block, store in n->c and count in n->nkids (reuse) */
                /* No wait, nkids is used for then. Let me just add two more fields. */
                /* Actually I'll just make the else body a single-element array trick */
                /* You know what, let me just store else body as a block wrapped in a special node */
                /* I'll create a "block" pseudo-statement */
                /* Actually the cleanest: I'll just put else-if as n->b (a ST_IF node),
                   and else-block as a ST_BLOCK node in n->b */
                /* Let me add ST_BLOCK to my enum */
                /* Hmm I didn't add ST_BLOCK. Let me just use the existing structure differently. */
                /* For else block: I'll store it as n->c (Node**) and use n->nkids for then count,
                   and I'll add a field nkids2. Let me just add it. */
                /* I'll fix the Node struct. */
                /* For now, let me just handle it with the fields I have: */
                /* I'll store else body in a global or use a different encoding */
                /* OK I'm overcomplicating this. Let me just add fields to Node. */
                goto else_block_handling;
            }
        }
        return n;
    }
    case TK_WHILE: {
        advance();
        n=mk_node(ST_WHILE,t->line);
        n->a=parse_expr();
        n->kids=parse_block(&n->nkids);
        return n;
    }
    case TK_FOR: {
        n=mk_node(ST_FOR,t->line);
        advance();
        n->name=peek()->sval; advance();
        expect(TK_IN);
        n->a=parse_expr();
        n->kids=parse_block(&n->nkids);
        return n;
    }
    case TK_RETURN: {
        advance();
        n=mk_node(ST_RETURN,t->line);
        if(peek()->type!=TK_SEMI) n->a=parse_expr();
        expect(TK_SEMI);
        return n;
    }
    case TK_BREAK: advance(); expect(TK_SEMI); return mk_node(ST_BREAK,t->line);
    case TK_CONTINUE: advance(); expect(TK_SEMI); return mk_node(ST_CONTINUE,t->line);
    case TK_IDENT: {
        if(peek2()->type==TK_ASSIGN){
            n=mk_node(ST_ASSIGN,t->line);
            n->name=t->sval; advance(); advance();
            n->a=parse_expr();
            expect(TK_SEMI);
            return n;
        }
        goto expr_stmt;
    }
    default:
    expr_stmt: {
        Node *e=parse_expr();
        if(peek()->type==TK_ASSIGN && e->type==EX_INDEX){
