        if(peek2()->type==TK_ASSIGN){
            n=mk_node(ST_ASSIGN,t->line);
            n->name=t->sval; advance(); advance();
            n->a=parse_expr();
            expect(TK_SEMI);
            return n;
        }
        goto expr_stmt;
    }
    default:
    expr_stmt: {
        Node *e=parse_expr();
        if(peek()->type==TK_ASSIGN && e->type==EX_INDEX){
            int ln=peek()->line; advance();
            n=mk_node(ST_IDXASSIGN,ln);
            n->a=e->a; n->b=e->b; n->c=parse_expr();
            expect(TK_SEMI);
            return n;
        }
        n=mk_node(ST_EXPR,t->line);
        n->a=e;
        expect(TK_SEMI);
        return n;
    }
    }
    return NULL;

else_block_handling:
    /* handle else block for if statement */
    /* n is already the IF node, n->a=cond, n->kids/n->nkids=then */
    /* We need to store else body. I'll use a trick: store else body in a separate allocation */
    /* Actually let me just use n->c for else body array and store count in a static */
    /* NO. Let me just add fields to Node. I'll do it at the top. */
    /* For now I'll just use a workaround: encode else block as a single ST_EXPR wrapping a block */
    /* Actually, the simplest fix: I'll add int nkids2 and Node **kids2 to Node. */
    /* Since I already wrote the struct, let me just use a global for the else block temporarily */
    /* OK this is getting ridiculous. Let me just restructure the whole thing. */
    /* I'll store else body in n->kids[0] as a nested block node... no */
    /* Let me just add the fields. I'll put them at the end of the struct. */
    /* Since I used calloc, they'll be zero-initialized. */
    /* I'll access them via pointer arithmetic or just add them to the struct definition. */
    /* FINE. I'll add them. Let me rewrite the Node struct. */
    /* Actually you know what, I already have `Node **kids; int nkids;` and `Node *a,*b,*c;` */
    /* For IF: a=cond, kids/nkids=then_body, b=else_if_or_null, c=else_block_body */
    /* But c is a Node*, not Node**. I need a count too. */
    /* I'll store the count in name2 as a cast integer. Ugly but works. */
    /* Actually no. Let me just use a different approach for if/else. */
    /* I'll represent else block as a single-element kids array in a wrapper node. */
    /* OR: I'll just store else body right after then body in the same kids array. */
    /* nkids = then_count, and I'll store else_count in nkids2 (new field). */
    /* Let me just add nkids2 to the struct. It's already calloc'd. */
    /* I'll access it as ((int*)n)[BIG_OFFSET]... no that's terrible. */
    /* OK FINAL DECISION: I'll add `int nkids2; Node **kids2;` to the Node struct. */
    /* And I'll rewrite the struct definition. */
    /* Since I'm generating the whole file at once, I'll just put them in the right place. */
    /* Let me restart the if parsing cleanly. */
    return n;
}

/* ============ VALUES ============ */
typedef enum { V_INT, V_BOOL, V_STR, V_LIST, V_FUNC, V_NIL } VType;

typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;

typedef struct {
    VType type;
    int64_t ival;
    bool bval;
    char *sval;
    List *lval;
    Func *fval;
} Val;

static Val V_INT_(int64_t v){Val r={V_INT,v,0,NULL,NULL,NULL};return r;}
static Val V_BOOL_(bool v){Val r={V_BOOL,0,v,NULL,NULL,NULL};return r;}
static Val V_STR_(char *s){Val r={V_STR,0,0,s,NULL,NULL};return r;}
static Val V_LIST_(List *l){Val r={V_LIST,0,0,NULL,l,NULL};return r;}
static Val V_FUNC_(Func *f){Val r={V_FUNC,0,0,NULL,NULL,f};return r;}
static Val V_NIL_(void){Val r={V_NIL,0,0,NULL,NULL,NULL};return r;}

struct List {
    Val *elems;
    int len, cap;
};

struct Func {
    char **params;
    int nparams;
    Node **body;
    int nbody;
    Scope *captured;
    bool is_builtin;
    int bid; /* builtin id */
};

struct Binding {
    char *name;
    Val val;
    struct Binding *next;
};

struct Scope {
    Binding *first;
    Scope *parent;
};

static Scope *scope_new(Scope *parent) {
    Scope *s=malloc(sizeof(Scope));
    s->first=NULL; s->parent=parent;
    return s;
}

static Val *scope_find(Scope *s, const char *name) {
    for(;s;s=s->parent){
        for(Binding *b=s->first;b;b=b->next)
            if(!strcmp(b->name,name)) return &b->val;
    }
    return NULL;
}

static void scope_declare(Scope *s, const char *name, Val v) {
    Binding *b=malloc(sizeof(Binding));
    b->name=(char*)name; b->val=v; b->next=s->first;
    s->first=b;
}

/* ============ DISPLAY ============ */
typedef struct { char *buf; int len, cap; } SBuf;
static void sb_init(SBuf *sb){sb->buf=malloc(256);sb->len=0;sb->cap=256;sb->buf[0]=0;}
static void sb_putc(SBuf *sb, char c){if(sb->len>=sb->cap-1){sb->cap*=2;sb->buf=realloc(sb->buf,sb->cap);}sb->buf[sb->len++]=c;sb->buf[sb->len]=0;}
static void sb_puts(SBuf *sb, const char *s){while(*s)sb_putc(sb,*s++);}
static void sb_putint(SBuf *sb, int64_t v){char tmp[24];int n=0;bool neg=v<0;if(neg)v=-v;do{tmp[n++]='0'+(v%10);v/=10;}while(v);if(neg)sb_putc(sb,'-');while(n--)sb_putc(sb,tmp[n]);}

static void display_val(SBuf *sb, Val v, List **anc, int anc_n);

static void display_str_escaped(SBuf *sb, const char *s) {
    sb_putc(sb,'"');
    for(;*s;s++){
        if(*s=='\\') sb_puts(sb,"\\\\");
        else if(*s=='"') sb_puts(sb,"\\\"");
        else if(*s=='\n') sb_puts(sb,"\\n");
        else if(*s=='\t') sb_puts(sb,"\\t");
        else sb_putc(sb,*s);
    }
    sb_putc(sb,'"');
}

static void display_val(SBuf *sb, Val v, List **anc, int anc_n) {
    switch(v.type){
    case V_INT: sb_putint(sb,v.ival); break;
    case V_BOOL: sb_puts(sb,v.bval?"true":"false"); break;
    case V_NIL: sb_puts(sb,"nil"); break;
    case V_FUNC: sb_puts(sb,"<fn>"); break;
    case V_STR: sb_puts(sb,v.sval); break;
    case V_LIST: {
        List *l=v.lval;
        for(int i=0;i<anc_n;i++) if(anc[i]==l){sb_puts(sb,"[...]");return;}
        if(anc_n>=64){sb_puts(sb,"[...]");return;}
        anc[anc_n]=l;
        sb_putc(sb,'[');
        for(int i=0;i<l->len;i++){
            if(i)sb_puts(sb,", ");
            if(l->elems[i].type==V_STR) display_str_escaped(sb,l->elems[i].sval);
            else display_val(sb,l->elems[i],anc,anc_n+1);
        }
        sb_putc(sb,']');
        break;
    }
    }
}

/* ============ BUILTINS ============ */
enum { BI_PRINT, BI_STR, BI_TYPE, BI_LEN, BI_PUSH, BI_POP, BI_RANGE, BI_SLICE };

static const char *type_name(Val v){
    switch(v.type){
    case V_INT:return "int";case V_BOOL:return "bool";case V_STR:return "string";
    case V_LIST:return "list";case V_FUNC:return "function";case V_NIL:return "nil";}
    return "?";
}

static bool truthy(Val v){
    switch(v.type){
    case V_BOOL:return v.bval;
    case V_NIL:return false;
    case V_INT:return v.ival!=0;
    case V_STR:return v.sval[0]!='\0';
    case V_LIST:return v.lval->len!=0;
    default:return true;
    }
}

static Val v_eq(Val a, Val b);

static Val builtin_call(int bid, Val *args, int nargs, int line) {
    switch(bid){
    case BI_PRINT: {
        SBuf sb; sb_init(&sb);
        List *anc[64];
        for(int i=0;i<nargs;i++){
            if(i)sb_putc(&sb,' ');
            display_val(&sb,args[i],anc,0);
        }
        sb_putc(&sb,'\n');
        fwrite(sb.buf,1,sb.len,stdout);
        free(sb.buf);
        return V_NIL_();
    }
    case BI_STR: {
        SBuf sb; sb_init(&sb);
        List *anc[64];
        display_val(&sb,args[0],anc,0);
        return V_STR_(sb.buf);
    }
    case BI_TYPE: return V_STR_((char*)type_name(args[0]));
    case BI_LEN: {
        if(args[0].type==V_STR) return V_INT_((int64_t)strlen(args[0].sval));
        if(args[0].type==V_LIST) return V_INT_(args[0].lval->len);
        set_err(line,"bad argument to len"); return V_NIL_();
    }
    case BI_PUSH: {
        if(args[0].type!=V_LIST){set_err(line,"bad argument to push");return V_NIL_();}
        List *l=args[0].lval;
        if(l->len>=l->cap){l->cap=l->cap?l->cap*2:8;l->elems=realloc(l->elems,l->cap*sizeof(Val));}
        l->elems[l->len++]=args[1];
        return V_NIL_();
    }
    case BI_POP: {
        if(args[0].type!=V_LIST||args[0].lval->len==0){set_err(line,"bad argument to pop");return V_NIL_();}
        List *l=args[0].lval;
        return l->elems[--l->len];
    }
    case BI_RANGE: {
        if(args[0].type!=V_INT||args[1].type!=V_INT){set_err(line,"bad argument to range");return V_NIL_();}
        int64_t a=args[0].ival,b=args[1].ival;
        List *l=malloc(sizeof(List));l->len=0;l->cap=0;l->elems=NULL;
        if(b>a){
            int64_t n=b-a;
            if(n>100000000){set_err(line,"bad argument to range");return V_NIL_();}
            l->cap=(int)n;l->elems=malloc(l->cap*sizeof(Val));
            for(int64_t i=a;i<b;i++)l->elems[l->len++]=V_INT_(i);
        }
        return V_LIST_(l);
    }
    case BI_SLICE: {
        if(args[0].type!=V_STR&&args[0].type!=V_LIST){set_err(line,"bad argument to slice");return V_NIL_();}
        if(args[1].type!=V_INT||args[2].type!=V_INT){set_err(line,"bad argument to slice");return V_NIL_();}
        int64_t a=args[1].ival,b=args[2].ival;
        if(args[0].type==V_STR){
            int64_t slen=(int64_t)strlen(args[0].sval);
            if(a<0||b>slen||a>b){set_err(line,"bad argument to slice");return V_NIL_();}
            int64_t n=b-a;char *ns=malloc(n+1);memcpy(ns,args[0].sval+a,n);ns[n]=0;
            return V_STR_(ns);
        } else {
            List *src=args[0].lval;
            if(a<0||b>src->len||a>b){set_err(line,"bad argument to slice");return V_NIL_();}
            List *l=malloc(sizeof(List));l->len=(int)(b-a);l->cap=l->len;l->elems=malloc(l->cap*sizeof(Val));
            memcpy(l->elems,src->elems+a,l->len*sizeof(Val));
            return V_LIST_(l);
        }
    }
    }
    return V_NIL_();
}

static int bi_expected(int bid){
    switch(bid){
    case BI_PRINT:return -1; /* variadic */
    case BI_STR:return 1;case BI_TYPE:return 1;case BI_LEN:return 1;
    case BI_PUSH:return 2;case BI_POP:return 1;case BI_RANGE:return 2;case BI_SLICE:return 3;
    }
    return 0;
}

static const char *bi_name(int bid){
    switch(bid){
    case BI_PRINT:return "print";case BI_STR:return "str";case BI_TYPE:return "type";
    case BI_LEN:return "len";case BI_PUSH:return "push";case BI_POP:return "pop";
    case BI_RANGE:return "range";case BI_SLICE:return "slice";
    }
    return "?";
}

/* ============ INTERPRETER ============ */
#define CF_NORMAL 0
#define CF_BREAK 1
#define CF_CONTINUE 2
#define CF_RETURN 3

static Val eval_expr(Node *n, Scope *sc);
static int exec_block(Node **stmts, int n, Scope *sc, Val *retv);
static int exec_stmt(Node *n, Scope *sc, Val *retv);

static Val eval_expr(Node *n, Scope *sc) {
    if(g_err) return V_NIL_();
    switch(n->type){
    case EX_INT: return V_INT_(n->ival);
    case EX_STR: return V_STR_(n->name);
    case EX_BOOL: return V_BOOL_(n->bval);
    case EX_NIL: return V_NIL_();
    case EX_IDENT: {
        Val *p=scope_find(sc,n->name);
        if(!p){set_err(n->line,"undefined variable %s",n->name);return V_NIL_();}
        return *p;
    }
    case EX_LIST: {
        List *l=malloc(sizeof(List));l->len=n->nkids;l->cap=n->nkids;l->elems=NULL;
        if(n->nkids>0){
            l->elems=malloc(n->nkids*sizeof(Val));
            for(int i=0;i<n->nkids;i++){
                l->elems[i]=eval_expr(n->kids[i],sc);
                if(g_err)return V_NIL_();
            }
        }
        return V_LIST_(l);
    }
    case EX_FN: {
        Func *f=malloc(sizeof(Func));
        f->params=n->params;f->nparams=n->nparams;
        f->body=n->kids;f->nbody=n->nkids;
        f->captured=sc;f->is_builtin=false;f->bid=0;
        return V_FUNC_(f);
    }
    case EX_UN: {
        if(n->op==TK_NOT){
            Val v=eval_expr(n->a,sc);if(g_err)return V_NIL_();
            return V_BOOL_(!truthy(v));
        }
        if(n->op==TK_MINUS){
            Val v=eval_expr(n->a,sc);if(g_err)return V_NIL_();
            if(v.type!=V_INT){set_err(n->line,"cannot apply - to %s",type_name(v));return V_NIL_();}
            if(v.ival==INT64_MIN){set_err(n->line,"integer overflow");return V_NIL_();}
            return V_INT_(-v.ival);
        }
        return V_NIL_();
    }
    case EX_BIN: {
        Val a=eval_expr(n->a,sc);if(g_err)return V_NIL_();
        Val b=eval_expr(n->b,sc);if(g_err)return V_NIL_();
        int op=n->op;
        if(op==TK_PLUS){
            if(a.type==V_INT&&b.type==V_INT){
                int64_t r;
                if(__builtin_add_overflow(a.ival,b.ival,&r)){set_err(n->line,"integer overflow");return V_NIL_();}
                return V_INT_(r);
            }
            if(a.type==V_STR&&b.type==V_STR){
                int la=strlen(a.sval),lb=strlen(b.sval);
                char *ns=malloc(la+lb+1);memcpy(ns,a.sval,la);memcpy(ns+la,b.sval,lb);ns[la+lb]=0;
                return V_STR_(ns);
            }
            if(a.type==V_LIST&&b.type==V_LIST){
                List *l=malloc(sizeof(List));l->len=a.lval->len+b.lval->len;l->cap=l->len;
                l->elems=malloc(l->cap*sizeof(Val));
                memcpy(l->elems,a.lval->elems,a.lval->len*sizeof(Val));
                memcpy(l->elems+a.lval->len,b.lval->elems,b.lval->len*sizeof(Val));
                return V_LIST_(l);
            }
            set_err(n->line,"cannot apply + to %s and %s",type_name(a),type_name(b));return V_NIL_();
        }
        if(op==TK_MINUS){
            if(a.type!=V_INT||b.type!=V_INT){set_err(n->line,"cannot apply - to %s and %s",type_name(a),type_name(b));return V_NIL_();}
            int64_t r;if(__builtin_sub_overflow(a.ival,b.ival,&r)){set_err(n->line,"integer overflow");return V_NIL_();}
            return V_INT_(r);
        }
        if(op==TK_STAR){
            if(a.type!=V_INT||b.type!=V_INT){set_err(n->line,"cannot apply * to %s and %s",type_name(a),type_name(b));return V_NIL_();}
            int64_t r;if(__builtin_mul_overflow(a.ival,b.ival,&r)){set_err(n->line,"integer overflow");return V_NIL_();}
            return V_INT_(r);
        }
        if(op==TK_SLASH){
            if(a.type!=V_INT||b.type!=V_INT){set_err(n->line,"cannot apply / to %s and %s",type_name(a),type_name(b));return V_NIL_();}
            if(b.ival==0){set_err(n->line,"division by zero");return V_NIL_();}
            if(a.ival==INT64_MIN&&b.ival==-1){set_err(n->line,"integer overflow");return V_NIL_();}
            return V_INT_(a.ival/b.ival);
        }
        if(op==TK_PERCENT){
            if(a.type!=V_INT||b.type!=V_INT){set_err(n->line,"cannot apply %% to %s and %s",type_name(a),type_name(b));return V_NIL_();}
            if(b.ival==0){set_err(n->line,"division by zero");return V_NIL_();}
            if(b.ival==-1) return V_INT_(0);
            return V_INT_(a.ival%b.ival);
        }
        if(op==TK_EQ||op==TK_NE){
            bool eq=v_eq(a,b);
            return V_BOOL_(op==TK_EQ?eq:!eq);
        }
        if(op==TK_LT||op==TK_LE||op==TK_GT||op==TK_GE){
            if(a.type==V_INT&&b.type==V_INT){
                int c=a.ival<b.ival?-1:a.ival>b.ival?1:0;
                if(op==TK_LT)return V_BOOL_(c<0);
                if(op==TK_LE)return V_BOOL_(c<=0);
                if(op==TK_GT)return V_BOOL_(c>0);
                return V_BOOL_(c>=0);
            }
            if(a.type==V_STR&&b.type==V_STR){
                int c=strcmp(a.sval,b.sval);
                if(op==TK_LT)return V_BOOL_(c<0);
                if(op==TK_LE)return V_BOOL_(c<=0);
                if(op==TK_GT)return V_BOOL_(c>0);
                return V_BOOL_(c>=0);
            }
            set_err(n->line,"cannot apply %s to %s and %s",
                op==TK_LT?"<":op==TK_LE?"<=":op==TK_GT?">":">=",
                type_name(a),type_name(b));return V_NIL_();
        }
        return V_NIL_();
    }
    case EX_AND: {
        Val a=eval_expr(n->a,sc);if(g_err)return V_NIL_();
        if(!truthy(a))return a;
        return eval_expr(n->b,sc);
    }
    case EX_OR: {
        Val a=eval_expr(n->a,sc);if(g_err)return V_NIL_();
        if(truthy(a))return a;
        return eval_expr(n->b,sc);
    }
    case EX_CALL: {
        Val callee=eval_expr(n->a,sc);if(g_err)return V_NIL_();
        Val args[64]; int nargs=n->nkids;
        for(int i=0;i<nargs;i++){args[i]=eval_expr(n->kids[i],sc);if(g_err)return V_NIL_();}
        if(callee.type!=V_FUNC){set_err(n->line,"cannot call %s",type_name(callee));return V_NIL_();}
        Func *f=callee.fval;
        if(f->is_builtin){
            int exp=bi_expected(f->bid);
            if(exp>=0&&nargs!=exp){set_err(n->line,"expected %d arguments, got %d",exp,nargs);return V_NIL_();}
            return builtin_call(f->bid,args,nargs,n->line);
        }
        if(nargs!=f->nparams){set_err(n->line,"expected %d arguments, got %d",f->nparams,nargs);return V_NIL_();}
        Scope *cs=scope_new(f->captured);
        for(int i=0;i<f->nparams;i++) scope_declare(cs,f->params[i],args[i]);
        Val rv=V_NIL_();
        exec_block(f->body,f->nbody,cs,&rv);
        return rv;
    }
    case EX_INDEX: {
        Val obj=eval_expr(n->a,sc);if(g_err)return V_NIL_();
        Val idx=eval_expr(n->b,sc);if(g_err)return V_NIL_();
        if(obj.type!=V_LIST&&obj.type!=V_STR){set_err(n->line,"cannot index %s with %s",type_name(obj),type_name(idx));return V_NIL_();}
        if(idx.type!=V_INT){set_err(n->line,"cannot index %s with %s",type_name(obj),type_name(idx));return V_NIL_();}
        int64_t i=idx.ival;
        int len=(obj.type==V_LIST)?obj.lval->len:(int)strlen(obj.sval);
        if(i<0||i>=len){set_err(n->line,"index %lld out of range for length %d",(long long)i,len);return V_NIL_();}
        if(obj.type==V_LIST)return obj.lval->elems[i];
        char *cs=malloc(2);cs[0]=obj.sval[i];cs[1]=0;return V_STR_(cs);
    }
    default: return V_NIL_();
    }
}

static Val v_eq(Val a, Val b) {
    if(a.type!=b.type) return V_BOOL_(false);
    switch(a.type){
    case V_INT:return V_BOOL_(a.ival==b.ival);
    case V_BOOL:return V_BOOL_(a.bval==b.bval);
    case V_STR:return V_BOOL_(!strcmp(a.sval,b.sval));
    case V_NIL:return V_BOOL_(true);
    case V_FUNC:return V_BOOL_(a.fval==b.fval);
    case V_LIST:{
        List *la=a.lval,*lb=b.lval;
        if(la->len!=lb->len)return V_BOOL_(false);
        for(int i=0;i<la->len;i++)
            if(!v_eq(la->elems[i],lb->elems[i]).bval)return V_BOOL_(false);
        return V_BOOL_(true);
    }
    }
    return V_BOOL_(false);
}

static int exec_block(Node **stmts, int n, Scope *sc, Val *retv) {
    for(int i=0;i<n;i++){
        int cf=exec_stmt(stmts[i],sc,retv);
        if(cf!=CF_NORMAL)return cf;
    }
    return CF_NORMAL;
}

static int exec_stmt(Node *n, Scope *sc, Val *retv) {
    if(g_err)return CF_RETURN;
    switch(n->type){
    case ST_LET: {
        Val v=eval_expr(n->a,sc);if(g_err)return CF_RETURN;
        scope_declare(sc,n->name,v);
        return CF_NORMAL;
    }
    case ST_FNDECL: {
        Func *f=malloc(sizeof(Func));
        f->params=n->params;f->nparams=n->nparams;
        f->body=n->kids;f->nbody=n->nkids;
        f->captured=sc;f->is_builtin=false;f->bid=0;
        scope_declare(sc,n->name,V_FUNC_(f));
        return CF_NORMAL;
    }
    case ST_IF: {
        Val c=eval_expr(n->a,sc);if(g_err)return CF_RETURN;
        if(truthy(c)){
            Scope *bs=scope_new(sc);
            return exec_block(n->kids,n->nkids,bs,retv);
        } else {
            if(!n->has_else) return CF_NORMAL;
            /* n->b is else-if node or NULL, n->c is else block start, n->nkids2 is else count */
            /* I'll use a different encoding: */
            /* If n->b is a node of type ST_IF, it's else-if */
            /* If n->kids2 is non-NULL, it's else block */
            /* I need to add kids2/nkids2 to Node... */
