public class Main {
    static String lineEnd;
    static int lineEndLen;

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles((d, name) -> name.endsWith(".eml"));
        if (files == null) files = new File[0];
        Arrays.sort(files, (a, b) -> compareBytes(a.getName(), b.getName()));
        boolean first = true;
        for (File f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static int compareBytes(String a, String b) {
        int la = a.length(), lb = b.length();
        int min = Math.min(la, lb);
        for (int i = 0; i < min; i++) {
            int ca = a.charAt(i) & 0xFF, cb = b.charAt(i) & 0xFF;
            if (ca != cb) return Integer.compare(ca, cb);
        }
        return Integer.compare(la, lb);
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        if (containsCRLF(data)) { lineEnd = "\r\n"; lineEndLen = 2; }
        else { lineEnd = "\n"; lineEndLen = 1; }
        Entity msg = parseEntity(data);
        System.out.println("== " + f.getName());
        String from = msg.headers.get("from");
        String subject = msg.headers.get("subject");
        System.out.println("From: " + (from != null ? quoteString(decodeRFC2047(from)) : "-"));
        System.out.println("Subject: " + (subject != null ? quoteString(decodeRFC2047(subject)) : "-"));
        printTree(msg, 0);
    }

    static boolean containsCRLF(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == '\r' && data[i + 1] == '\n') return true;
        }
        return false;
    }

    static class Param {
        String name; // lowercased, may include * suffixes for RFC2231
        String value; // raw value (token or unquoted string)
        Param(String n, String v) { name = n; value = v; }
    }

    static class Entity {
        Map<String, String> headers = new LinkedHashMap<>();
        byte[] body;
        List<Entity> parts;
        String type, subtype, cte, charset;
        List<Param> ctParams, cdParams;
        String dispType; // "inline", "attachment", or null
        boolean isMultipart;
    }

    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();
