        String cd = e.headers.get("content-disposition");
        e.cdParams = new ArrayList<>();
        if (cd != null) {
            int[] p = {0};
            skipWS(cd, p);
            e.dispType = readToken(cd, p).toLowerCase();
            parseParams(cd, p, e.cdParams);
