        String cteVal = e.headers.get("content-transfer-encoding");
        e.cte = (cteVal != null) ? trimSp(cteVal).toLowerCase() : "7bit";

        // Charset
        e.charset = getParam(e.ctParams, "charset");
        if (e.charset != null) e.charset = e.charset.toLowerCase();
        if (e.type.equals("text") && e.charset == null) e.charset = "us-ascii";

        // Multipart?
        e.isMultipart = e.type.equals("multipart");
        if (e.isMultipart) {
            String boundary = getParam(e.ctParams, "boundary");
            e.parts = parseMultipartBody(e.body, boundary);
            e.body = null;
