    static void parseParams(String s, int[] p, List<Param> params) {
        while (p[0] < s.length()) {
            skipWS(s, p);
            if (p[0] >= s.length() || s.charAt(p[0]) != ';') break;
            p[0]++; // skip ;
            skipWS(s, p);
            if (p[0] >= s.length()) break;
            String name = readToken(s, p).toLowerCase();
            skipWS(s, p);
            if (p[0] >= s.length() || s.charAt(p[0]) != '=') {
                params.add(new Param(name, ""));
                continue;
            }
            p[0]++; // skip =
            skipWS(s, p);
            String value = readParamValue(s, p);
            params.add(new Param(name, value));
        }
    }

    static String readParamValue(String s, int[] p) {
        if (p[0] < s.length() && s.charAt(p[0]) == '"') {
            p[0]++;
