            while (p[0] < s.length() && s.charAt(p[0]) != '"') {
                if (s.charAt(p[0]) == '\\' && p[0] + 1 < s.length()) {
                    p[0]++;
                    sb.append(s.charAt(p[0]));
                } else {
                    sb.append(s.charAt(p[0]));
                }
                p[0]++;
            }
            if (p[0] < s.length()) p[0]++; // skip closing "
            return sb.toString();
        } else {
            return readToken(s, p);
        }
    }

    static String readToken(String s, int[] p) {
        int start = p[0];
        while (p[0] < s.length()) {
            char c = s.charAt(p[0]);
            if (c == ' ' || c == '\t' || c == ';' || c == '/' || c == '=') break;
            p[0]++;
        }
        return s.substring(start, p[0]);
    }

    static void skipWS(String s, int[] p) {
        while (p[0] < s.length() && (s.charAt(p[0]) == ' ' || s.charAt(p[0]) == '\t')) p[0]++;
    }

    static String getParam(List<Param> params, String name) {
        for (Param p : params) {
            if (p.name.equals(name)) return p.value;
        }
        return null;
    }

    static List<Entity> parseMultipartBody(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        if (boundary == null) return parts;
        String delimStr = "--" + boundary;
        String closeStr = "--" + boundary + "--";

        // Find delimiter line positions
        List<int[]> delims = new ArrayList<>(); // [lineStart, lineEnd(inclusive of lineEnd bytes), isClose]
        int pos = 0;
        while (pos <= body.length) {
            int lePos = findLineEnd(body, pos);
            int lineContentEnd = (lePos == -1) ? body.length : lePos;
            int nextPos = (lePos == -1) ? body.length + 1 : lePos + lineEndLen;

            boolean isDelim = isDelimLine(body, pos, lineContentEnd, delimStr, closeStr);
            if (isDelim) {
                boolean isClose = isCloseLine(body, pos, lineContentEnd, closeStr);
                delims.add(new int[]{pos, nextPos, isClose ? 1 : 0});
            }
            pos = nextPos;
            if (lePos == -1) break;
        }

        // Extract parts between consecutive delimiters
        for (int i = 0; i < delims.size() - 1; i++) {
            int start = delims.get(i)[1]; // after delimiter line (including its line break)
            int end = delims.get(i + 1)[0]; // start of next delimiter line
            // Strip trailing line break before the next delimiter
            if (end > start) {
