    static String decodeCP1252(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            int v = b & 0xFF;
            if (v >= 0x80 && v <= 0x9F) {
                sb.append((char) CP1252_MAP[v - 0x80]);
            } else {
                sb.append((char) v);
            }
        }
        return sb.toString();
