    // --- RFC 2047 ---
    static final Pattern EW_PATTERN = Pattern.compile("\\=\\?([^?\\s\\t]+)\\?([BbQq])\\?([^?\\s\\t]*)\\?\\=");

    static String normalizeCharset(String cs) {
        cs = cs.toLowerCase();
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs;
    }

    static String decodeRFC2047(String text) {
        Matcher m = EW_PATTERN.matcher(text);
        List<Object> tokens = new ArrayList<>();
        int lastEnd = 0;
        while (m.find()) {
            if (m.start() > lastEnd) {
                tokens.add(text.substring(lastEnd, m.start()));
            }
            String charset = m.group(1);
            String encoding = m.group(2).toUpperCase();
            String encText = m.group(3);
            byte[] bytes;
            if (encoding.equals("B")) {
                bytes = decodeEWBase64(encText);
            } else {
                bytes = decodeEWQ(encText);
            }
            tokens.add(new Object[]{charset, bytes});
            lastEnd = m.end();
        }
        if (lastEnd < text.length()) {
            tokens.add(text.substring(lastEnd));
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < tokens.size()) {
            Object tok = tokens.get(i);
            if (tok instanceof String) {
                result.append((String) tok);
                i++;
            } else {
                // Collect adjacent encoded words
                List<Object[]> group = new ArrayList<>();
                group.add((Object[]) tok);
                i++;
                while (i < tokens.size()) {
                    if (tokens.get(i) instanceof Object[]) {
                        group.add((Object[]) tokens.get(i));
                        i++;
                    } else if (tokens.get(i) instanceof String) {
                        String s = (String) tokens.get(i);
