                    ByteArrayOutputStream baos = new ByteArrayOutputStream();
                    for (int x = j; x < k; x++) {
                        baos.write((byte[]) group.get(x)[1], 0, ((byte[]) group.get(x)[1]).length);
                    }
                    result.append(decodeCharset(baos.toByteArray(), cs));
                    j = k;
                }
            }
        }
        return result.toString();
    }

    static boolean isAllWS(String s) {
