            char c = s.charAt(i);
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            } else if (c == '=') {
                break;
            }
        }
        String b64 = sb.toString();
        int rem = b64.length() % 4;
        if (rem == 2) b64 += "==";
        else if (rem == 3) b64 += "=";
        try {
            return Base64.getDecoder().decode(b64);
        } catch (Exception e) {
            return new byte[0];
        }
    }

    static byte[] decodeEWQ(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '_') {
                out.write(0x20);
                i++;
            } else if (c == '=' && i + 2 < s.length() && isHex(s.charAt(i + 1)) && isHex(s.charAt(i + 2))) {
