                i += 3;
            } else {
                out.write(c);
                i++;
            }
        }
        return out.toByteArray();
    }

    // --- RFC 2231 ---
    static String getFileName(Entity e) {
        // Priority: CD filename RFC2231, CD filename, CT name RFC2231, CT name
        String r = tryRFC2231(e.cdParams, "filename");
        if (r != null) return r;
        r = tryRegular(e.cdParams, "filename");
        if (r != null) return r;
        r = tryRFC2231(e.ctParams, "name");
        if (r != null) return r;
        r = tryRegular(e.ctParams, "name");
        if (r != null) return r;
        return null;
    }

    static String tryRFC2231(List<Param> params, String attr) {
        // Look for attr*, attr*N, attr*N*
        List<int[]> segments = new ArrayList<>(); // [index, isPercentEncoded, paramIndex]
        String charset = null;
        ByteArrayOutputStream allBytes = new ByteArrayOutputStream();

        // Collect segments
        TreeMap<Integer, Object[]> segMap = new TreeMap<>(); // index -> [isPercent, value]
        boolean hasAny = false;

        for (Param p : params) {
            String pn = p.name;
            // Check if pn starts with attr and has * suffix
            if (!pn.startsWith(attr)) continue;
            String suffix = pn.substring(attr.length());
            if (suffix.isEmpty()) continue; // plain attr, not RFC2231
            if (suffix.charAt(0) != '*') continue;

            hasAny = true;
            boolean percent;
            int index;
            String rest = suffix.substring(1); // after first *
            if (rest.isEmpty()) {
                // attr* -> single segment, percent-encoded, index 0
                percent = true;
                index = 0;
            } else if (rest.endsWith("*")) {
                // attr*N* -> percent-encoded
                percent = true;
                index = Integer.parseInt(rest.substring(0, rest.length() - 1));
            } else {
                // attr*N -> literal
                percent = false;
                index = Integer.parseInt(rest);
            }
            segMap.put(index, new Object[]{percent, p.value});
        }

        if (!hasAny) return null;

        // Process segments in order
        boolean anyPercent = false;
        for (Object[] seg : segMap.values()) {
            if ((Boolean) seg[0]) { anyPercent = true; break; }
        }

        for (Map.Entry<Integer, Object[]> entry : segMap.entrySet()) {
            boolean percent = (Boolean) entry.getValue()[0];
            String val = (String) entry.getValue()[1];
            if (percent) {
                // Decode percent-encoding
                ByteArrayOutputStream segBytes = new ByteArrayOutputStream();
                int idx = 0;
                // First segment: extract charset'language'
                if (charset == null) {
                    int q1 = val.indexOf('\'');
                    if (q1 >= 0) {
                        int q2 = val.indexOf('\'', q1 + 1);
                        if (q2 >= 0) {
                            charset = val.substring(0, q1);
                            idx = q2 + 1;
                        }
                    }
                }
                // Decode percent-encoded from idx
                while (idx < val.length()) {
                    char c = val.charAt(idx);
                    if (c == '%' && idx + 2 < val.length() && isHex(val.charAt(idx + 1)) && isHex(val.charAt(idx + 2))) {
                        segBytes.write((hexVal(val.charAt(idx + 1)) << 4) | hexVal(val.charAt(idx + 2)));
                        idx += 3;
                    } else {
                        segBytes.write(c);
                        idx++;
                    }
                }
                allBytes.write(segBytes.toByteArray(), 0, segBytes.size());
            } else {
                // Literal: bytes are the characters
                for (int i = 0; i < val.length(); i++) {
                    allBytes.write(val.charAt(i) & 0xFF);
                }
            }
        }

        String cs = (charset != null) ? charset.toLowerCase() : "us-ascii";
        return decodeCharset(allBytes.toByteArray(), cs);
    }

    static String tryRegular(List<Param> params, String attr) {
        String val = getParam(params, attr);
        if (val == null) return null;
        return decodeRFC2047(val);
    }

    // --- Output ---
    static void printTree(Entity e, int indent) {
        String pad = " ".repeat(indent);
        if (e.isMultipart) {
            System.out.println(pad + "multipart/" + e.subtype + " parts=" + (e.parts != null ? e.parts.size() : 0));
            if (e.parts != null) {
                for (Entity part : e.parts) {
                    printTree(part, indent + 2);
                }
            }
        } else if (e.type.equals("text") && !"attachment".equals(e.dispType)) {
            byte[] decoded = decodeCTE(e.body, e.cte);
            String text = decodeCharset(decoded, e.charset);
            // Replace CRLF and lone CR with LF
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(pad + "text/" + e.subtype + " charset=" + e.charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println(" ".repeat(indent + 2) + quoteString(text));
        } else {
            byte[] decoded = decodeCTE(e.body, e.cte);
            int size = decoded.length;
            CRC32 crc = new CRC32();
            crc.update(decoded);
            long crcVal = crc.getValue();
            String name = getFileName(e);
            String nameStr = (name != null) ? quoteString(name) : "-";
            String disp = (e.dispType != null) ? e.dispType : "-";
            System.out.println(pad + e.type + "/" + e.subtype + " cte=" + e.cte + " disposition=" + disp + " name=" + nameStr + " size=" + size + " crc32=" + String.format("%08x", crcVal));
        }
    }

    static String quoteString(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            i += Character.charCount(cp);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
        }
        sb.append('"');
        return sb.toString();
    }
