        return false;
    }

    static class Param {
        String name; // lowercased, may include * suffixes for RFC2231
        String value; // raw value (token or unquoted string)
        Param(String n, String v) { name = n; value = v; }
    }

    static class Entity {
        Map<String, String> headers = new LinkedHashMap<>();
        byte[] body;
        List<Entity> parts;
        String type, subtype, cte, charset;
        List<Param> ctParams, cdParams;
        String dispType; // "inline", "attachment", or null
        boolean isMultipart;
    }

    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();
        int pos = 0;
        // Check if starts with empty line (no headers)
        if (data.length >= lineEndLen && startsWith(data, 0, lineEnd)) {
            pos = lineEndLen;
        } else {
            // Read header lines until empty line
            List<String> physLines = new ArrayList<>();
            while (pos < data.length) {
                int lePos = findLineEnd(data, pos);
                int lineEndIdx = (lePos == -1) ? data.length : lePos;
                if (lineEndIdx == pos) {
                    // empty line
                    pos = pos + lineEndLen;
                    break;
                }
                physLines.add(new String(data, pos, lineEndIdx - pos, java.nio.charset.StandardCharsets.ISO_8859_1));
                pos = (lePos == -1) ? data.length : lePos + lineEndLen;
            }
            // Unfold
            List<String> logicalLines = new ArrayList<>();
            for (String line : physLines) {
                if (!logicalLines.isEmpty() && (line.startsWith(" ") || line.startsWith("\t"))) {
                    logicalLines.set(logicalLines.size() - 1, logicalLines.get(logicalLines.size() - 1) + line);
                } else {
                    logicalLines.add(line);
                }
            }
            // Parse headers
            for (String h : logicalLines) {
                int colon = h.indexOf(':');
                if (colon >= 0) {
                    String name = h.substring(0, colon).trim().toLowerCase();
                    String val = h.substring(colon + 1);
                    // trim leading/trailing spaces and tabs
                    val = trimSp(val);
                    e.headers.put(name, val);
                }
            }
        }
        e.body = Arrays.copyOfRange(data, pos, data.length);

        // Parse Content-Type
        String ct = e.headers.get("content-type");
        e.ctParams = new ArrayList<>();
        if (ct != null) {
            int[] p = {0};
            skipWS(ct, p);
            e.type = readToken(ct, p).toLowerCase();
            skipWS(ct, p);
            if (p[0] < ct.length() && ct.charAt(p[0]) == '/') {
                p[0]++;
                skipWS(ct, p);
                e.subtype = readToken(ct, p).toLowerCase();
            } else {
                e.subtype = "";
            }
            // Parse parameters
            parseParams(ct, p, e.ctParams);
        } else {
            e.type = "text"; e.subtype = "plain";
        }

        // Parse Content-Disposition
        String cd = e.headers.get("content-disposition");
        e.cdParams = new ArrayList<>();
        if (cd != null) {
            int[] p = {0};
            skipWS(cd, p);
            e.dispType = readToken(cd, p).toLowerCase();
            parseParams(cd, p, e.cdParams);
        }

        // CTE
        String cteVal = e.headers.get("content-transfer-encoding");
        e.cte = (cteVal != null) ? trimSp(cteVal).toLowerCase() : "7bit";

        // Charset
        e.charset = getParam(e.ctParams, "charset");
        if (e.charset != null) e.charset = e.charset.toLowerCase();
        if (e.type.equals("text") && e.charset == null) e.charset = "us-ascii";

        // Multipart?
        e.isMultipart = e.type.equals("multipart");
        if (e.isMultipart) {
            String boundary = getParam(e.ctParams, "boundary");
            e.parts = parseMultipartBody(e.body, boundary);
            e.body = null;
        }

        return e;
    }

    static void parseParams(String s, int[] p, List<Param> params) {
        while (p[0] < s.length()) {
            skipWS(s, p);
            if (p[0] >= s.length() || s.charAt(p[0]) != ';') break;
            p[0]++; // skip ;
            skipWS(s, p);
            if (p[0] >= s.length()) break;
            String name = readToken(s, p).toLowerCase();
            skipWS(s, p);
            if (p[0] >= s.length() || s.charAt(p[0]) != '=') {
                params.add(new Param(name, ""));
                continue;
            }
            p[0]++; // skip =
            skipWS(s, p);
            String value = readParamValue(s, p);
            params.add(new Param(name, value));
        }
    }

    static String readParamValue(String s, int[] p) {
        if (p[0] < s.length() && s.charAt(p[0]) == '"') {
            p[0]++;
            StringBuilder sb = new StringBuilder();
            while (p[0] < s.length() && s.charAt(p[0]) != '"') {
                if (s.charAt(p[0]) == '\\' && p[0] + 1 < s.length()) {
                    p[0]++;
                    sb.append(s.charAt(p[0]));
                } else {
                    sb.append(s.charAt(p[0]));
                }
                p[0]++;
            }
            if (p[0] < s.length()) p[0]++; // skip closing "
            return sb.toString();
        } else {
            return readToken(s, p);
        }
    }

    static String readToken(String s, int[] p) {
        int start = p[0];
        while (p[0] < s.length()) {
            char c = s.charAt(p[0]);
            if (c == ' ' || c == '\t' || c == ';' || c == '/' || c == '=') break;
            p[0]++;
        }
        return s.substring(start, p[0]);
    }

    static void skipWS(String s, int[] p) {
        while (p[0] < s.length() && (s.charAt(p[0]) == ' ' || s.charAt(p[0]) == '\t')) p[0]++;
    }

    static String getParam(List<Param> params, String name) {
        for (Param p : params) {
            if (p.name.equals(name)) return p.value;
        }
        return null;
    }

    static List<Entity> parseMultipartBody(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        if (boundary == null) return parts;
        String delimStr = "--" + boundary;
        String closeStr = "--" + boundary + "--";

        // Find delimiter line positions
        List<int[]> delims = new ArrayList<>(); // [lineStart, lineEnd(inclusive of lineEnd bytes), isClose]
        int pos = 0;
        while (pos <= body.length) {
            int lePos = findLineEnd(body, pos);
            int lineContentEnd = (lePos == -1) ? body.length : lePos;
            int nextPos = (lePos == -1) ? body.length + 1 : lePos + lineEndLen;

            boolean isDelim = isDelimLine(body, pos, lineContentEnd, delimStr, closeStr);
            if (isDelim) {
                boolean isClose = isCloseLine(body, pos, lineContentEnd, closeStr);
                delims.add(new int[]{pos, nextPos, isClose ? 1 : 0});
            }
            pos = nextPos;
            if (lePos == -1) break;
        }

        // Extract parts between consecutive delimiters
        for (int i = 0; i < delims.size() - 1; i++) {
            int start = delims.get(i)[1]; // after delimiter line (including its line break)
            int end = delims.get(i + 1)[0]; // start of next delimiter line
            // Strip trailing line break before the next delimiter
            if (end > start) {
                if (lineEndLen == 2 && end >= 2 && body[end - 2] == '\r' && body[end - 1] == '\n') {
                    end -= 2;
                } else if (lineEndLen == 1 && end >= 1 && body[end - 1] == '\n') {
                    end -= 1;
                }
            }
            if (start > end) start = end;
            byte[] partData = Arrays.copyOfRange(body, start, end);
            parts.add(parseEntity(partData));
        }
        return parts;
    }

    static boolean isDelimLine(byte[] data, int start, int end, String delimStr, String closeStr) {
        String line = new String(data, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
        if (line.startsWith(delimStr)) {
            String rest = line.substring(delimStr.length());
            for (int i = 0; i < rest.length(); i++) {
                char c = rest.charAt(i);
                if (c != ' ' && c != '\t') return false;
            }
            return true;
        }
        return false;
    }

    static boolean isCloseLine(byte[] data, int start, int end, String closeStr) {
        String line = new String(data, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
        if (line.startsWith(closeStr)) {
            String rest = line.substring(closeStr.length());
            for (int i = 0; i < rest.length(); i++) {
                char c = rest.charAt(i);
                if (c != ' ' && c != '\t') return false;
            }
            return true;
        }
        return false;
    }

    static int findLineEnd(byte[] data, int from) {
        for (int i = from; i < data.length; i++) {
            if (data[i] == '\r' && i + 1 < data.length && data[i + 1] == '\n') return i;
            if (data[i] == '\n') return i;
        }
        return -1;
    }

    static boolean startsWith(byte[] data, int pos, String s) {
        for (int i = 0; i < s.length(); i++) {
            if (pos + i >= data.length || data[pos + i] != (byte) s.charAt(i)) return false;
        }
        return true;
    }

    static String trimSp(String s) {
        int start = 0, end = s.length();
        while (start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t')) start++;
        while (end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t')) end--;
        return s.substring(start, end);
    }

    // --- Transfer Encoding ---
    static byte[] decodeCTE(byte[] data, String cte) {
        switch (cte) {
            case "base64": return decodeBase64(data);
            case "quoted-printable": return decodeQP(data);
            default: return data; // 7bit, 8bit, binary
        }
    }

    static byte[] decodeBase64(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            char c = (char) (b & 0xFF);
            if (c == '=') break;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            }
        }
        String b64 = sb.toString();
        // Pad if necessary
        int rem = b64.length() % 4;
        if (rem == 2) b64 += "==";
        else if (rem == 3) b64 += "=";
        else if (rem == 1) b64 += "==="; // shouldn't happen normally

        byte[] decoded = Base64.getDecoder().decode(b64);
        return decoded;
    }

    static byte[] decodeQP(byte[] data) {
        String text = new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
        // Split into lines
        List<String> lines = new ArrayList<>();
        int pos = 0;
        while (pos < text.length()) {
            int idx = text.indexOf(lineEnd, pos);
            if (idx == -1) {
                lines.add(text.substring(pos));
                pos = text.length();
            } else {
                lines.add(text.substring(pos, idx));
                pos = idx + lineEnd.length();
            }
        }

        // Remove trailing spaces/tabs, handle soft line breaks
        StringBuilder joined = new StringBuilder();
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            // Remove trailing spaces/tabs
            int lend = line.length();
            while (lend > 0 && (line.charAt(lend - 1) == ' ' || line.charAt(lend - 1) == '\t')) lend--;
            line = line.substring(0, lend);

            if (line.endsWith("=") && i < lines.size() - 1) {
                // Soft line break: remove the = and join with next
                joined.append(line, 0, line.length() - 1);
            } else {
                joined.append(line);
                if (i < lines.size() - 1) joined.append(lineEnd);
            }
        }

        // Decode =XY sequences
        String s = joined.toString();
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '=' && i + 2 < s.length()) {
                char h1 = s.charAt(i + 1), h2 = s.charAt(i + 2);
                if (isHex(h1) && isHex(h2)) {
                    int val = (hexVal(h1) << 4) | hexVal(h2);
                    out.write(val);
                    i += 3;
                } else {
                    out.write('=');
                    i++;
                }
            } else {
                out.write(c);
                i++;
            }
        }
        return out.toByteArray();
    }

    static boolean isHex(char c) {
        return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f');
    }

    static int hexVal(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return c - 'a' + 10;
    }

    // --- Charset Decoding ---
    static final int[] CP1252_MAP = new int[32]; // for bytes 0x80-0x9F

    static {
        int[] map = {
            0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
            0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
            0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
            0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
        };
        System.arraycopy(map, 0, CP1252_MAP, 0, 32);
    }

    static String decodeCharset(byte[] data, String charset) {
        if (charset == null) charset = "us-ascii";
        switch (charset) {
            case "us-ascii":
            case "utf-8":
            case "utf8":
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            case "iso-8859-1":
            case "latin1":
                return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
            case "windows-1252":
            case "cp1252":
                return decodeCP1252(data);
            default:
                // Try Java charset lookup
                try {
                    return new String(data, charset);
                } catch (Exception ex) {
                    return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
                }
        }
    }

    static String decodeCP1252(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            int v = b & 0xFF;
            if (v >= 0x80 && v <= 0x9F) {
                sb.append((char) CP1252_MAP[v - 0x80]);
            } else {
                sb.append((char) v);
            }
        }
        return sb.toString();
    }

    // --- RFC 2047 ---
    static final Pattern EW_PATTERN = Pattern.compile("\\=\\?([^?\\s\\t]+)\\?([BbQq])\\?([^?\\s\\t]*)\\?\\=");

    static String normalizeCharset(String cs) {
        cs = cs.toLowerCase();
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs;
    }

    static String decodeRFC2047(String text) {
        Matcher m = EW_PATTERN.matcher(text);
        List<Object> tokens = new ArrayList<>();
        int lastEnd = 0;
        while (m.find()) {
            if (m.start() > lastEnd) {
                tokens.add(text.substring(lastEnd, m.start()));
            }
            String charset = m.group(1);
            String encoding = m.group(2).toUpperCase();
            String encText = m.group(3);
            byte[] bytes;
            if (encoding.equals("B")) {
                bytes = decodeEWBase64(encText);
            } else {
                bytes = decodeEWQ(encText);
            }
            tokens.add(new Object[]{charset, bytes});
            lastEnd = m.end();
        }
        if (lastEnd < text.length()) {
            tokens.add(text.substring(lastEnd));
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < tokens.size()) {
            Object tok = tokens.get(i);
            if (tok instanceof String) {
                result.append((String) tok);
                i++;
            } else {
                // Collect adjacent encoded words
                List<Object[]> group = new ArrayList<>();
                group.add((Object[]) tok);
                i++;
                while (i < tokens.size()) {
                    if (tokens.get(i) instanceof Object[]) {
                        group.add((Object[]) tokens.get(i));
                        i++;
                    } else if (tokens.get(i) instanceof String) {
                        String s = (String) tokens.get(i);
                        if (isAllWS(s) && i + 1 < tokens.size() && tokens.get(i + 1) instanceof Object[]) {
                            i++; // skip whitespace between adjacent EWs
                        } else {
                            break;
                        }
                    } else {
                        break;
                    }
                }
                // Within group, find maximal same-charset runs
                int j = 0;
                while (j < group.size()) {
                    String cs = normalizeCharset((String) group.get(j)[0]);
                    int k = j + 1;
                    while (k < group.size() && normalizeCharset((String) group.get(k)[0]).equals(cs)) {
                        k++;
                    }
                    ByteArrayOutputStream baos = new ByteArrayOutputStream();
                    for (int x = j; x < k; x++) {
                        baos.write((byte[]) group.get(x)[1], 0, ((byte[]) group.get(x)[1]).length);
                    }
                    result.append(decodeCharset(baos.toByteArray(), cs));
                    j = k;
                }
            }
        }
        return result.toString();
    }

    static boolean isAllWS(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c != ' ' && c != '\t') return false;
        }
        return true;
    }

    static byte[] decodeEWBase64(String s) {
        // Filter to valid base64 chars
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            } else if (c == '=') {
                break;
            }
        }
        String b64 = sb.toString();
        int rem = b64.length() % 4;
        if (rem == 2) b64 += "==";
        else if (rem == 3) b64 += "=";
        try {
            return Base64.getDecoder().decode(b64);
        } catch (Exception e) {
            return new byte[0];
        }
    }

    static byte[] decodeEWQ(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '_') {
                out.write(0x20);
                i++;
            } else if (c == '=' && i + 2 < s.length() && isHex(s.charAt(i + 1)) && isHex(s.charAt(i + 2))) {
                out.write((hexVal(s.charAt(i + 1)) << 4) | hexVal(s.charAt(i + 2)));
                i += 3;
            } else {
                out.write(c);
                i++;
            }
        }
        return out.toByteArray();
    }

    // --- RFC 2231 ---
    static String getFileName(Entity e) {
        // Priority: CD filename RFC2231, CD filename, CT name RFC2231, CT name
        String r = tryRFC2231(e.cdParams, "filename");
        if (r != null) return r;
        r = tryRegular(e.cdParams, "filename");
        if (r != null) return r;
        r = tryRFC2231(e.ctParams, "name");
        if (r != null) return r;
        r = tryRegular(e.ctParams, "name");
        if (r != null) return r;
        return null;
    }

    static String tryRFC2231(List<Param> params, String attr) {
        // Look for attr*, attr*N, attr*N*
        List<int[]> segments = new ArrayList<>(); // [index, isPercentEncoded, paramIndex]
        String charset = null;
        ByteArrayOutputStream allBytes = new ByteArrayOutputStream();

        // Collect segments
        TreeMap<Integer, Object[]> segMap = new TreeMap<>(); // index -> [isPercent, value]
        boolean hasAny = false;

        for (Param p : params) {
            String pn = p.name;
            // Check if pn starts with attr and has * suffix
            if (!pn.startsWith(attr)) continue;
            String suffix = pn.substring(attr.length());
            if (suffix.isEmpty()) continue; // plain attr, not RFC2231
            if (suffix.charAt(0) != '*') continue;

            hasAny = true;
            boolean percent;
            int index;
            String rest = suffix.substring(1); // after first *
            if (rest.isEmpty()) {
                // attr* -> single segment, percent-encoded, index 0
                percent = true;
                index = 0;
            } else if (rest.endsWith("*")) {
                // attr*N* -> percent-encoded
                percent = true;
                index = Integer.parseInt(rest.substring(0, rest.length() - 1));
            } else {
                // attr*N -> literal
                percent = false;
                index = Integer.parseInt(rest);
            }
            segMap.put(index, new Object[]{percent, p.value});
        }

        if (!hasAny) return null;

        // Process segments in order
        boolean anyPercent = false;
        for (Object[] seg : segMap.values()) {
            if ((Boolean) seg[0]) { anyPercent = true; break; }
        }

        for (Map.Entry<Integer, Object[]> entry : segMap.entrySet()) {
            boolean percent = (Boolean) entry.getValue()[0];
            String val = (String) entry.getValue()[1];
            if (percent) {
                // Decode percent-encoding
                ByteArrayOutputStream segBytes = new ByteArrayOutputStream();
                int idx = 0;
                // First segment: extract charset'language'
                if (charset == null) {
                    int q1 = val.indexOf('\'');
                    if (q1 >= 0) {
                        int q2 = val.indexOf('\'', q1 + 1);
                        if (q2 >= 0) {
                            charset = val.substring(0, q1);
                            idx = q2 + 1;
                        }
                    }
                }
                // Decode percent-encoded from idx
                while (idx < val.length()) {
                    char c = val.charAt(idx);
                    if (c == '%' && idx + 2 < val.length() && isHex(val.charAt(idx + 1)) && isHex(val.charAt(idx + 2))) {
                        segBytes.write((hexVal(val.charAt(idx + 1)) << 4) | hexVal(val.charAt(idx + 2)));
                        idx += 3;
                    } else {
                        segBytes.write(c);
                        idx++;
                    }
                }
                allBytes.write(segBytes.toByteArray(), 0, segBytes.size());
            } else {
                // Literal: bytes are the characters
                for (int i = 0; i < val.length(); i++) {
                    allBytes.write(val.charAt(i) & 0xFF);
                }
            }
        }

        String cs = (charset != null) ? charset.toLowerCase() : "us-ascii";
        return decodeCharset(allBytes.toByteArray(), cs);
    }

    static String tryRegular(List<Param> params, String attr) {
        String val = getParam(params, attr);
        if (val == null) return null;
        return decodeRFC2047(val);
    }

    // --- Output ---
    static void printTree(Entity e, int indent) {
        String pad = " ".repeat(indent);
        if (e.isMultipart) {
            System.out.println(pad + "multipart/" + e.subtype + " parts=" + (e.parts != null ? e.parts.size() : 0));
            if (e.parts != null) {
                for (Entity part : e.parts) {
                    printTree(part, indent + 2);
                }
            }
        } else if (e.type.equals("text") && !"attachment".equals(e.dispType)) {
            byte[] decoded = decodeCTE(e.body, e.cte);
            String text = decodeCharset(decoded, e.charset);
            // Replace CRLF and lone CR with LF
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(pad + "text/" + e.subtype + " charset=" + e.charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println(" ".repeat(indent + 2) + quoteString(text));
        } else {
            byte[] decoded = decodeCTE(e.body, e.cte);
            int size = decoded.length;
            CRC32 crc = new CRC32();
            crc.update(decoded);
            long crcVal = crc.getValue();
            String name = getFileName(e);
            String nameStr = (name != null) ? quoteString(name) : "-";
            String disp = (e.dispType != null) ? e.dispType : "-";
            System.out.println(pad + e.type + "/" + e.subtype + " cte=" + e.cte + " disposition=" + disp + " name=" + nameStr + " size=" + size + " crc32=" + String.format("%08x", crcVal));
        }
    }

    static String quoteString(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            i += Character.charCount(cp);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
