/* ============ Dynamic byte buffer ============ */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void buf_init(Buf *b){ b->d=NULL; b->len=0; b->cap=0; }
static void buf_free(Buf *b){ free(b->d); }
static void buf_ensure(Buf *b, size_t n){
    if(b->len+n > b->cap){
        b->cap = (b->len+n)*2+64;
        b->d = realloc(b->d, b->cap);
    }
}
static void buf_append(Buf *b, unsigned char c){ buf_ensure(b,1); b->d[b->len++]=c; }
static void buf_append_bytes(Buf *b, const unsigned char *s, size_t n){
    buf_ensure(b,n); memcpy(b->d+b->len,s,n); b->len+=n;
}

