static void cp_free(CPBuf *b){ free(b->d); }
static void cp_ensure(CPBuf *b, size_t n){
    if(b->len+n > b->cap){ b->cap=(b->len+n)*2+64; b->d=realloc(b->d,b->cap*sizeof(uint32_t)); }
}
static void cp_append(CPBuf *b, uint32_t c){ cp_ensure(b,1); b->d[b->len++]=c; }
static void cp_append_cp(CPBuf *b, const uint32_t *s, size_t n){
    cp_ensure(b,n); memcpy(b->d+b->len,s,n*sizeof(uint32_t)); b->len+=n;
}

/* ============ CRC32 ============ */
static uint32_t crc_tab[256];
static int crc_ok=0;
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){
        uint32_t c=i;
        for(int j=0;j<8;j++) c = (c&1)?0xEDB88320^(c>>1):(c>>1);
        crc_tab[i]=c;
    }
    crc_ok=1;
}
static uint32_t crc32(const unsigned char *d, size_t n){
    if(!crc_ok) crc_init();
    uint32_t c=0xFFFFFFFF;
    for(size_t i=0;i<n;i++) c=crc_tab[(c^d[i])&0xFF]^(c>>8);
    return c^0xFFFFFFFF;
}

/* ============ Base64 decode ============ */
static int b64val(int c){
    if(c>='A'&&c<='Z') return c-'A';
    if(c>='a'&&c<='z') return c-'a'+26;
    if(c>='0'&&c<='9') return c-'0'+52;
    if(c=='+') return 62;
    if(c=='/') return 63;
    return -1;
}
static void base64_decode(const unsigned char *in, size_t inlen, Buf *out){
    int accum=0, bits=0;
    for(size_t i=0;i<inlen;i++){
        if(in[i]=='=') break;
        int v=b64val(in[i]);
        if(v<0) continue;
        accum=(accum<<6)|v; bits+=6;
        if(bits>=8){ bits-=8; buf_append(out,(accum>>bits)&0xFF); }
    }
}

/* ============ Quoted-printable decode ============ */
static int hexval(int c){
    if(c>='0'&&c<='9') return c-'0';
    if(c>='a'&&c<='f') return c-'a'+10;
    if(c>='A'&&c<='F') return c-'A'+10;
    return -1;
}
static void qp_decode(const unsigned char *in, size_t inlen, int le_len, Buf *out){
    size_t i=0;
    while(i<inlen){
        /* find end of current line */
        size_t line_end=i;
        while(line_end<inlen && !(in[line_end]=='\r'&&line_end+1<inlen&&in[line_end+1]=='\n') && in[line_end]!='\n')
            line_end++;
        size_t le_pos=line_end;
        size_t actual_le=0;
        if(le_pos<inlen){
            if(in[le_pos]=='\r'&&le_pos+1<inlen&&in[le_pos+1]=='\n') actual_le=2;
            else if(in[le_pos]=='\n') actual_le=1;
        }
        /* content of this line is in[i..line_end) */
        /* remove trailing spaces/tabs */
        size_t content_end=line_end;
        while(content_end>i && (in[content_end-1]==' '||in[content_end-1]=='\t')) content_end--;
        /* check soft line break */
        int soft=0;
        if(content_end>i && in[content_end-1]=='='){ content_end--; soft=1; }
        /* decode this line's content */
        for(size_t j=i;j<content_end;j++){
            if(in[j]=='=' && j+2<content_end){
                int h1=hexval(in[j+1]), h2=hexval(in[j+2]);
                if(h1>=0&&h2>=0){ buf_append(out,(h1<<4)|h2); j+=2; continue; }
            }
            buf_append(out,in[j]);
        }
        if(!soft && actual_le>0){
            /* keep the line break */
            buf_append_bytes(out, in+le_pos, actual_le);
        }
        i = le_pos + actual_le;
    }
}

/* ============ Charset decode ============ */
static void decode_charset(const unsigned char *bytes, size_t len, const char *cs, CPBuf *out){
    /* normalize cs to lowercase */
    char lc[64]; strncpy(lc,cs,63); lc[63]=0;
    for(int i=0;lc[i];i++) lc[i]=tolower((unsigned char)lc[i]);

    if(strcmp(lc,"us-ascii")==0 || strcmp(lc,"utf-8")==0 || strcmp(lc,"ascii")==0){
        if(strcmp(lc,"utf-8")==0){
            /* UTF-8 decode */
            size_t i=0;
            while(i<len){
                uint32_t cp=0;
                unsigned char c=bytes[i];
                if(c<0x80){ cp=c; i+=1; }
                else if((c&0xE0)==0xC0){ cp=c&0x1F; if(i+1<len) cp=(cp<<6)|(bytes[i+1]&0x3F); i+=2; }
                else if((c&0xF0)==0xE0){ cp=c&0x0F; if(i+1<len) cp=(cp<<6)|(bytes[i+1]&0x3F); if(i+2<len) cp=(cp<<6)|(bytes[i+2]&0x3F); i+=3; }
                else if((c&0xF8)==0xF0){ cp=c&0x07; if(i+1<len) cp=(cp<<6)|(bytes[i+1]&0x3F); if(i+2<len) cp=(cp<<6)|(bytes[i+2]&0x3F); if(i+3<len) cp=(cp<<6)|(bytes[i+3]&0x3F); i+=4; }
                else { cp=c; i+=1; }
                cp_append(out,cp);
            }
        } else {
            /* us-ascii: each byte is its own code point */
            for(size_t i=0;i<len;i++) cp_append(out,bytes[i]);
        }
    } else if(strcmp(lc,"iso-8859-1")==0){
        for(size_t i=0;i<len;i++) cp_append(out,bytes[i]);
    } else if(strcmp(lc,"windows-1252")==0){
        static const uint32_t cp1252[32]={
            0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
            0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
            0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
            0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178
        };
        for(size_t i=0;i<len;i++){
            unsigned char b=bytes[i];
            if(b>=0x80&&b<=0x9F) cp_append(out,cp1252[b-0x80]);
            else cp_append(out,b);
        }
    } else {
        /* fallback: treat as latin-1 */
        for(size_t i=0;i<len;i++) cp_append(out,bytes[i]);
    }
}

/* ============ UTF-8 encode one code point ============ */
static void utf8_encode(uint32_t cp, Buf *out){
    if(cp<0x80) buf_append(out,cp);
    else if(cp<0x800){ buf_append(out,0xC0|(cp>>6)); buf_append(out,0x80|(cp&0x3F)); }
    else if(cp<0x10000){ buf_append(out,0xE0|(cp>>12)); buf_append(out,0x80|((cp>>6)&0x3F)); buf_append(out,0x80|(cp&0x3F)); }
    else { buf_append(out,0xF0|(cp>>18)); buf_append(out,0x80|((cp>>12)&0x3F)); buf_append(out,0x80|((cp>>6)&0x3F)); buf_append(out,0x80|(cp&0x3F)); }
}

/* ============ Quoted string output ============ */
static void print_quoted(FILE *f, const uint32_t *cp, size_t n){
    fputc('"',f);
    for(size_t i=0;i<n;i++){
        uint32_t c=cp[i];
        if(c=='\\') fprintf(f,"\\\\");
        else if(c=='"') fprintf(f,"\\\"");
        else if(c=='\n') fprintf(f,"\\n");
        else if(c=='\t') fprintf(f,"\\t");
        else if(c<0x20 || (c>=0x7F&&c<=0x9F)) fprintf(f,"\\u%04x",c);
        else { Buf tmp; buf_init(&tmp); utf8_encode(c,&tmp); fwrite(tmp.d,1,tmp.len,f); buf_free(&tmp); }
    }
    fputc('"',f);
}

/* ============ RFC 2047 encoded-word decoding ============ */
/* Try to match encoded word at position pos in data. Returns end position or 0 if no match. */
static size_t try_match_ew(const unsigned char *data, size_t len, size_t pos,
                          char *charset_out, size_t cs_max, char *enc_out,
                          size_t *text_start, size_t *text_end){
    if(pos+1>=len) return 0;
    if(data[pos]!='=' || data[pos+1]!='?') return 0;
    size_t p=pos+2;
    /* charset: 1+ chars not ?, space, tab */
    size_t cs_start=p;
    while(p<len && data[p]!='?' && data[p]!=' ' && data[p]!='\t') p++;
    if(p>=len || p==cs_start) return 0;
    size_t cs_len=p-cs_start;
    if(cs_len>=cs_max) cs_len=cs_max-1;
    memcpy(charset_out,data+cs_start,cs_len); charset_out[cs_len]=0;
    p++; /* skip ? */
    /* encoding: B/b/Q/q */
    if(p>=len) return 0;
    char enc=data[p];
    if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q') return 0;
    *enc_out=enc;
    p++;
    if(p>=len||data[p]!='?') return 0;
    p++;
    /* encoded text: 0+ chars not ?, space, tab */
    *text_start=p;
    while(p<len && data[p]!='?' && data[p]!=' ' && data[p]!='\t') p++;
    *text_end=p;
    /* must be followed by ?= */
    if(p+1>=len||data[p]!='?'||data[p+1]!='=') return 0;
    return p+2; /* end of encoded word */
}

static void strip_lang(char *cs){
    char *star=strchr(cs,'*');
    if(star) *star=0;
}
static void lower_str(char *s){ for(;*s;s++) *s=tolower((unsigned char)*s); }

typedef struct { size_t start, end; char charset[64]; char enc; size_t ts, te; } EW;

static void rfc2047_decode(const unsigned char *val, size_t vlen, CPBuf *out){
    /* Find all encoded words */
    EW words[256]; int nw=0;
    size_t pos=0;
    while(pos<vlen){
        char cs[64]; char enc; size_t ts,te;
        size_t end = try_match_ew(val,vlen,pos,cs,sizeof(cs),&enc,&ts,&te);
        if(end>0){
            words[nw].start=pos; words[nw].end=end;
            strncpy(words[nw].charset,cs,63); words[nw].charset[63]=0;
            words[nw].enc=enc; words[nw].ts=ts; words[nw].te=te;
            nw++;
            pos=end;
        } else {
            pos++;
        }
    }
    if(nw==0){
        /* all literal */
        for(size_t i=0;i<vlen;i++) cp_append(out,val[i]);
        return;
    }
    /* Build segments: literal text and encoded words */
    /* We'll process words and check adjacency */
    /* First, identify runs of adjacent same-charset encoded words */
    /* Two words are adjacent if between word[i].end and word[i+1].start there's only spaces/tabs */

    /* Build list of segments */
    typedef struct { int is_ew; size_t wi_start, wi_end; /* for literal: byte range */ size_t bs, be; } Seg;
    Seg segs[512]; int nseg=0;
    size_t prev_end=0;
    for(int i=0;i<nw;i++){
        if(words[i].start > prev_end){
            segs[nseg].is_ew=0; segs[nseg].bs=prev_end; segs[nseg].be=words[i].start; nseg++;
        }
        segs[nseg].is_ew=1; segs[nseg].wi_start=i; segs[nseg].wi_end=i; nseg++;
        prev_end=words[i].end;
    }
    if(prev_end<vlen){
        segs[nseg].is_ew=0; segs[nseg].bs=prev_end; segs[nseg].be=vlen; nseg++;
    }

    /* Merge adjacent encoded words with same charset (ignoring *lang) */
    /* Adjacent means: between two EW segments, only spaces/tabs */
    /* Actually, adjacency is between consecutive encoded words in the original text */
    /* Let me re-approach: merge consecutive EW words that are adjacent (only ws between) and same charset */

    /* Rebuild: mark which words are in the same run */
    int run_id[256]; for(int i=0;i<nw;i++) run_id[i]=i;
    for(int i=0;i+1<nw;i++){
        /* check if word i and word i+1 are adjacent */
        size_t gap_start=words[i].end, gap_end=words[i+1].start;
        int adj=1;
        for(size_t g=gap_start;g<gap_end;g++){
            if(val[g]!=' '&&val[g]!='\t'){adj=0;break;}
        }
        if(!adj) continue;
        /* check same charset */
        char cs1[64],cs2[64];
        strncpy(cs1,words[i].charset,63); cs1[63]=0; strip_lang(cs1); lower_str(cs1);
        strncpy(cs2,words[i+1].charset,63); cs2[63]=0; strip_lang(cs2); lower_str(cs2);
        if(strcmp(cs1,cs2)==0){
            /* merge runs */
            int r1=run_id[i], r2=run_id[i+1];
            for(int k=0;k<nw;k++) if(run_id[k]==r2) run_id[k]=r1;
        }
    }

    /* Now decode each run */
    /* Process segments in order, but handle runs specially */
    int processed[256]; memset(processed,0,sizeof(processed));
    for(int i=0;i<nw;i++){
        if(processed[i]) continue;
        /* collect all words in this run */
        int r=run_id[i];
        Buf raw; buf_init(&raw);
        char cs[64]; strncpy(cs,words[i].charset,63); cs[63]=0; strip_lang(cs); lower_str(cs);
        for(int j=i;j<nw;j++){
            if(run_id[j]!=r) continue;
            processed[j]=1;
            /* decode this word's encoded text */
            Buf tmp; buf_init(&tmp);
            if(words[j].enc=='B'||words[j].enc=='b'){
                base64_decode(val+words[j].ts, words[j].te-words[j].ts, &tmp);
            } else {
                /* Q encoding */
                for(size_t k=words[j].ts;k<words[j].te;k++){
                    if(val[k]=='_') buf_append(&tmp,0x20);
                    else if(val[k]=='='&&k+2<words[j].te){
                        int h1=hexval(val[k+1]),h2=hexval(val[k+2]);
                        if(h1>=0&&h2>=0){ buf_append(&tmp,(h1<<4)|h2); k+=2; continue; }
                        buf_append(&tmp,'=');
                    } else buf_append(&tmp,val[k]);
                }
            }
            buf_append_bytes(&raw,tmp.d,tmp.len);
            buf_free(&tmp);
        }
        /* decode raw bytes with charset */
        CPBuf decoded; cp_init(&decoded);
        decode_charset(raw.d,raw.len,cs,&decoded);
        cp_append_cp(out,decoded.d,decoded.len);
        cp_free(&decoded);
        buf_free(&raw);
    }

    /* Now output literal segments and encoded word segments in order */
    /* But we already output encoded words above. We need to interleave. */
    /* Let me redo this properly. */
    /* Actually, let me redo the whole function more carefully. */
    cp_free(out); cp_init(out);

    /* Rebuild: create a list of items (literal or decoded-ew-run) in order */
    memset(processed,0,sizeof(processed));
    /* For each word, determine its run's output */
    /* First pass: decode each run */
    Buf run_raw[256]; CPBuf run_dec[256]; int run_valid[256];
    for(int i=0;i<256;i++){ buf_init(&run_raw[i]); cp_init(&run_dec[i]); run_valid[i]=0; }

    for(int i=0;i<nw;i++){
        if(run_valid[run_id[i]]) continue;
        int r=run_id[i];
        char cs[64]; strncpy(cs,words[i].charset,63); cs[63]=0; strip_lang(cs); lower_str(cs);
        Buf raw; buf_init(&raw);
        for(int j=i;j<nw;j++){
            if(run_id[j]!=r) continue;
            if(words[j].enc=='B'||words[j].enc=='b'){
                base64_decode(val+words[j].ts,words[j].te-words[j].ts,&raw);
            } else {
                for(size_t k=words[j].ts;k<words[j].te;k++){
                    if(val[k]=='_') buf_append(&raw,0x20);
                    else if(val[k]=='='&&k+2<words[j].te){
                        int h1=hexval(val[k+1]),h2=hexval(val[k+2]);
                        if(h1>=0&&h2>=0){ buf_append(&raw,(h1<<4)|h2); k+=2; continue; }
                        buf_append(&raw,'=');
                    } else buf_append(&raw,val[k]);
                }
            }
        }
        decode_charset(raw.d,raw.len,cs,&run_dec[r]);
        run_valid[r]=1;
        buf_free(&raw);
    }

    /* Second pass: output in order */
    size_t out_pos=0;
    for(int i=0;i<nw;i++){
        /* literal text before this word */
        if(words[i].start>out_pos){
            /* check if this literal is just whitespace between adjacent words */
            int is_ws_between=0;
            if(i>0){
                /* check if previous word is adjacent to this one */
                size_t gap_s=words[i-1].end, gap_e=words[i].start;
                is_ws_between=1;
                for(size_t g=gap_s;g<gap_e;g++) if(val[g]!=' '&&val[g]!='\t'){is_ws_between=0;break;}
                if(is_ws_between && run_id[i-1]==run_id[i]) is_ws_between=1; /* same run, ws removed */
                else if(is_ws_between) is_ws_between=1; /* different runs, ws still removed */
                else is_ws_between=0;
            }
            if(!is_ws_between){
                for(size_t k=out_pos;k<words[i].start;k++) cp_append(out,val[k]);
            }
        }
        /* output this word's run (only once) */
        int r=run_id[i];
        if(i==0 || run_id[i]!=run_id[i-1]){
            cp_append_cp(out,run_dec[r].d,run_dec[r].len);
        }
        out_pos=words[i].end;
    }
    /* trailing literal */
    if(out_pos<vlen){
        for(size_t k=out_pos;k<vlen;k++) cp_append(out,val[k]);
    }

    for(int i=0;i<256;i++){ buf_free(&run_raw[i]); cp_free(&run_dec[i]); }
}

/* ============ Parameter parsing ============ */
typedef struct { char name[128]; unsigned char *val; size_t vlen; } Param;

static int is_token_char(int c){
    return !isspace(c) && c!=';' && c!='=' && c!='\"' && c!='(' && c!=')' && c!='<' && c!='>' &&
           c!='@' && c!=',' && c!=':' && c!='\\' && c!='/' && c!='[' && c!=']' && c!='?' && c!='=';
}

static void skip_ws(const unsigned char *s, size_t len, size_t *p){
    while(*p<len && (s[*p]==' '||s[*p]=='\t')) (*p)++;
}

static void parse_params(const unsigned char *s, size_t len, Param *params, int *np, int maxp){
    *np=0;
    size_t p=0;
    while(p<len && *np<maxp){
        skip_ws(s,len,&p);
        if(p>=len) break;
        /* read param name */
        size_t ns=p;
        while(p<len && is_token_char(s[p])) p++;
        if(p==ns) { p++; continue; } /* skip unexpected char */
        Param *par=&params[*np];
        size_t nlen=p-ns;
        if(nlen>=sizeof(par->name)) nlen=sizeof(par->name)-1;
        memcpy(par->name,s+ns,nlen); par->name[nlen]=0;
        lower_str(par->name);
        skip_ws(s,len,&p);
        if(p<len && s[p]=='='){ p++; skip_ws(s,len,&p); }
        else { par->val=(unsigned char*)""; par->vlen=0; (*np)++; continue; }
        /* read value */
        if(p<len && s[p]=='\"'){
            /* quoted string */
            p++;
            size_t vs=p;
            Buf vb; buf_init(&vb);
            while(p<len && s[p]!='\"'){
                if(s[p]=='\\'&&p+1<len){ p++; buf_append(&vb,s[p]); }
                else buf_append(&vb,s[p]);
                p++;
            }
            if(p<len) p++; /* skip closing " */
            par->val=vb.d; par->vlen=vb.len;
        } else {
            /* token */
            size_t vs=p;
            while(p<len && s[p]!=';' && s[p]!=' ' && s[p]!='\t') p++;
            par->val=(unsigned char*)(s+vs); par->vlen=p-vs;
        }
        (*np)++;
        skip_ws(s,len,&p);
        if(p<len && s[p]==';') p++;
    }
}

/* ============ Entity ============ */
typedef struct Entity {
    char type[64], subtype[64];
    char charset[64];
    char cte[32];
    char disp[32]; /* "inline","attachment","" */
    uint32_t *name; size_t name_len; /* decoded name or NULL */
    char boundary[256];
    struct Entity **parts; size_t nparts;
    unsigned char *body; size_t body_len;
    uint32_t *text; size_t text_len;
    int is_multipart, is_text;
} Entity;

static int le_len_global = 2; /* 1 or 2 */

/* Check if line at position pos (in body bytes) is a delimiter or close delimiter */
static int check_delim(const unsigned char *body, size_t blen, size_t pos, const char *bnd, int *is_close){
    /* line starts at pos, ends at next linebreak or end of body */
    size_t line_end=pos;
    while(line_end<blen && !(body[line_end]=='\r'&&line_end+1<blen&&body[line_end+1]=='\n') && body[line_end]!='\n')
        line_end++;
    size_t ll=line_end-pos;
    /* must start with -- */
    if(ll<2 || body[pos]!='-'||body[pos+1]!='-') return 0;
    size_t bnd_len=strlen(bnd);
    if(ll<2+bnd_len) return 0;
    if(memcmp(body+pos+2,bnd,bnd_len)!=0) return 0;
    /* after boundary: only spaces/tabs */
    size_t after=pos+2+bnd_len;
    /* check for close delimiter: --B-- */
    if(after<blen && body[after]=='-'){
        after++;
        *is_close=1;
    } else {
        *is_close=0;
    }
    for(size_t k=after;k<line_end;k++){
        if(body[k]!=' '&&body[k]!='\t') return 0;
    }
    return 1;
}

/* Find line start positions */
static size_t next_line_start(const unsigned char *body, size_t blen, size_t pos){
    while(pos<blen){
        if(body[pos]=='\r'&&pos+1<blen&&body[pos+1]=='\n') return pos+2;
        if(body[pos]=='\n') return pos+1;
        pos++;
    }
    return pos;
}

/* ============ RFC 2231 name decoding ============ */
static void percent_decode(const unsigned char *s, size_t len, Buf *out){
    for(size_t i=0;i<len;i++){
        if(s[i]=='%'&&i+2<len){
            int h1=hexval(s[i+1]),h2=hexval(s[i+2]);
            if(h1>=0&&h2>=0){ buf_append(out,(h1<<4)|h2); i+=2; continue; }
        }
        buf_append(out,s[i]);
    }
}

static void rfc2231_decode(Param *params, int np, const char *attr, CPBuf *out){
    /* Look for RFC 2231 form: attr*, or attr*N, or attr*N* */
    char prefix[128];
    snprintf(prefix,sizeof(prefix),"%s*",attr); /* attr* or attr*0, attr*1, etc. */

    /* Check for single form: attr* */
    int found_single=0;
    Param *single=NULL;
    for(int i=0;i<np;i++){
        if(strcmp(params[i].name,prefix)==0){ found_single=1; single=&params[i]; break; }
    }

    /* Check for continuation: attr*N or attr*N* */
    int found_cont=0;
    int max_seg=-1;
    int seg_pct[64]; memset(seg_pct,0,sizeof(seg_pct));
    Param *segs[64]; memset(segs,0,sizeof(segs));
    for(int i=0;i<np;i++){
        if(strncmp(params[i].name,prefix,strlen(prefix))==0){
            const char *rest=params[i].name+strlen(prefix);
            /* rest should be digits, optionally followed by * */
            int idx=0; int has_digit=0;
            while(*rest>='0'&&*rest<='9'){ idx=idx*10+(*rest-'0'); rest++; has_digit=1; }
            if(has_digit && (*rest==0 || *rest=='*')){
                found_cont=1;
                if(idx<64){ segs[idx]=&params[i]; seg_pct[idx]=(*rest=='*'); }
