    if(!found_single && !found_cont) return; /* not RFC 2231 form */

    Buf raw; buf_init(&raw);
    char cs[64]="us-ascii";

    if(found_single && !found_cont){
        /* attr*=charset'lang'percent_encoded */
        /* value is charset'lang'percent_encoded */
        unsigned char *v=single->val; size_t vl=single->vlen;
