            } else {
                percent_decode(v,vl,&raw);
            }
        } else {
            percent_decode(v,vl,&raw);
        }
    } else {
        /* continuation */
        int any_pct=0;
        for(int i=0;i<=max_seg;i++) if(segs[i]&&seg_pct[i]) any_pct=1;

        for(int i=0;i<=max_seg;i++){
            if(!segs[i]) continue;
            if(seg_pct[i]){
                if(i==0){
                    /* first percent-encoded segment starts with charset'lang' */
                    unsigned char *v=segs[i]->val; size_t vl=segs[i]->vlen;
                    size_t q1=0; while(q1<vl&&v[q1]!='\'') q1++;
                    if(q1<vl){
                        size_t q2=q1+1; while(q2<vl&&v[q2]!='\'') q2++;
                        if(q2<vl){
                            size_t csl=q1; if(csl>=sizeof(cs)) csl=sizeof(cs)-1;
