    /* RFC 2231 filename in CD */
    CPBuf out; cp_init(&out);
    int found=0;

    /* Check CD filename RFC2231 */
    rfc2231_decode(cd_params,ncd,"filename",&out);
    if(out.len>0){ found=1; goto done; }

    /* Check CD filename regular */
    for(int i=0;i<ncd;i++){
