            rfc2047_decode(ct_params[i].val,ct_params[i].vlen,&out);
            found=1; goto done;
        }
    }

done:
    if(found && out.len>0){
        e->name=malloc(out.len*sizeof(uint32_t));
        memcpy(e->name,out.d,out.len*sizeof(uint32_t));
        e->name_len=out.len;
    } else {
        e->name=NULL; e->name_len=0;
    }
    cp_free(&out);
}

