import sys

INT_MIN = -(2**63)
INT_MAX = 2**63 - 1

# Token types
T_INT, T_STR, T_IDENT, T_KW, T_OP, T_EOF = range(6)
KEYWORDS = frozenset(['let','fn','if','else','while','for','in','return','break','continue','and','or','not','true','false','nil'])

class Token:
    __slots__ = ('type','value','line')
    def __init__(self, type, value, line):
        self.type = type; self.value = value; self.line = line

def lex(src):
    tokens = []
    i = 0; line = 1; n = len(src)
    while i < n:
        c = src[i]
        if c in ' \t\r\n':
            if c == '\n': line += 1
            i += 1; continue
        if c == '#':
            while i < n and src[i] != '\n': i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and src[j].isdigit(): j += 1
            tokens.append(Token(T_INT, int(src[i:j]), line)); i = j; continue
        if c == '"':
            j = i + 1; parts = []
            while j < n and src[j] != '"':
                if src[j] == '\\':
                    j += 1; ec = src[j]
                    if ec == 'n': parts.append('\n')
                    elif ec == 't': parts.append('\t')
                    elif ec == '"': parts.append('"')
                    else: parts.append('\\')
                    j += 1
                else:
                    parts.append(src[j]); j += 1
            j += 1
            tokens.append(Token(T_STR, ''.join(parts), line)); i = j; continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'): j += 1
            word = src[i:j]
            tokens.append(Token(T_KW if word in KEYWORDS else T_IDENT, word, line))
            i = j; continue
        if i + 1 < n:
            two = src[i:i+2]
            if two in ('==','!=','<=','>='):
                tokens.append(Token(T_OP, two, line)); i += 2; continue
        if c in '+-*/%<>()[]{},;=':
            tokens.append(Token(T_OP, c, line)); i += 1; continue
        i += 1
    tokens.append(Token(T_EOF, None, line))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.toks = tokens; self.pos = 0
    def peek(self): return self.toks[self.pos]
    def next(self):
        t = self.toks[self.pos]; self.pos += 1; return t
    def at(self, tp, val=None):
        t = self.toks[self.pos]; return t.type == tp and (val is None or t.value == val)
    def expect(self, tp, val=None):
        t = self.toks[self.pos]; self.pos += 1; return t

    def parse_program(self):
        stmts = []
        while not self.at(T_EOF): stmts.append(self.parse_stmt())
        return stmts

    def parse_block(self):
        self.expect(T_OP, '{'); stmts = []
        while not self.at(T_OP, '}'): stmts.append(self.parse_stmt())
        self.expect(T_OP, '}'); return stmts

    def parse_params(self):
        params = []
        if self.at(T_IDENT):
            params.append(self.next().value)
            while self.at(T_OP, ','): self.next(); params.append(self.next().value)
        return params

    def parse_stmt(self):
        t = self.peek()
        if t.type == T_KW:
            kw = t.value
            if kw == 'let':
                self.next(); name = self.next().value; self.expect(T_OP, '=')
                val = self.parse_expr(); self.expect(T_OP, ';')
                return ('let', name, val, t.line)
            if kw == 'fn':
                self.next(); name = self.next().value; self.expect(T_OP, '(')
                params = self.parse_params(); self.expect(T_OP, ')')
                body = self.parse_block()
                return ('fn_decl', name, params, body, t.line)
            if kw == 'if': return self.parse_if()
            if kw == 'while':
                self.next(); cond = self.parse_expr(); body = self.parse_block()
                return ('while', cond, body, t.line)
            if kw == 'for':
                self.next(); var = self.next().value; self.expect(T_KW, 'in')
                iter_e = self.parse_expr(); body = self.parse_block()
                return ('for', var, iter_e, body, t.line)
            if kw == 'return':
                self.next()
                if self.at(T_OP, ';'): self.next(); return ('return', None, t.line)
                val = self.parse_expr(); self.expect(T_OP, ';')
                return ('return', val, t.line)
            if kw == 'break': self.next(); self.expect(T_OP, ';'); return ('break', t.line)
            if kw == 'continue': self.next(); self.expect(T_OP, ';'); return ('continue', t.line)
        if t.type == T_IDENT and self.toks[self.pos+1].type == T_OP and self.toks[self.pos+1].value == '=':
            self.next(); self.next(); val = self.parse_expr(); self.expect(T_OP, ';')
            return ('assign', t.value, val, t.line)
        expr = self.parse_expr()
        if self.at(T_OP, '='):
            self.next(); val = self.parse_expr(); self.expect(T_OP, ';')
            return ('index_assign', expr[1], expr[2], val, expr[3])
        self.expect(T_OP, ';')
        return ('expr', expr, t.line)

    def parse_if(self):
        t = self.next(); cond = self.parse_expr(); then_body = self.parse_block()
        else_body = None; else_is_block = False
        if self.at(T_KW, 'else'):
            self.next()
            if self.at(T_KW, 'if'):
                else_body = self.parse_if(); else_is_block = False
            else:
                else_body = self.parse_block(); else_is_block = True
        return ('if', cond, then_body, else_body, else_is_block, t.line)

    def parse_expr(self): return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.at(T_KW, 'or'):
            t = self.next(); right = self.parse_and()
            left = ('binop', 'or', left, right, t.line)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.at(T_KW, 'and'):
            t = self.next(); right = self.parse_not()
            left = ('binop', 'and', left, right, t.line)
        return left

    def parse_not(self):
        if self.at(T_KW, 'not'):
            t = self.next(); operand = self.parse_not()
            return ('unop', 'not', operand, t.line)
        return self.parse_comp()

    def parse_comp(self):
        left = self.parse_add()
        while self.peek().type == T_OP and self.peek().value in ('==','!=','<','<=','>','>='):
            t = self.next(); right = self.parse_add()
            left = ('binop', t.value, left, right, t.line)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.peek().type == T_OP and self.peek().value in ('+','-'):
            t = self.next(); right = self.parse_mul()
            left = ('binop', t.value, left, right, t.line)
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.peek().type == T_OP and self.peek().value in ('*','/','%'):
            t = self.next(); right = self.parse_unary()
            left = ('binop', t.value, left, right, t.line)
        return left

    def parse_unary(self):
        if self.peek().type == T_OP and self.peek().value == '-':
            t = self.next(); operand = self.parse_unary()
            return ('unop', '-', operand, t.line)
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
