                self.expect(T_OP, ')')
                expr = ('call', expr, args, t.line)
            elif self.at(T_OP, '['):
                t = self.next(); idx = self.parse_expr(); self.expect(T_OP, ']')
                expr = ('index', expr, idx, t.line)
            else: break
        return expr

    def parse_primary(self):
        t = self.peek()
        if t.type == T_INT: self.next(); return ('int', t.value, t.line)
        if t.type == T_STR: self.next(); return ('str', t.value, t.line)
        if t.type == T_IDENT: self.next(); return ('ident', t.value, t.line)
        if t.type == T_KW:
            if t.value == 'true': self.next(); return ('bool', True, t.line)
            if t.value == 'false': self.next(); return ('bool', False, t.line)
            if t.value == 'nil': self.next(); return ('nil', t.line)
            if t.value == 'fn':
