            self.next(); expr = self.parse_expr(); self.expect(T_OP, ')'); return expr
        if t.type == T_OP and t.value == '[':
            self.next(); elems = []
            if not self.at(T_OP, ']'):
                elems.append(self.parse_expr())
                while self.at(T_OP, ','): self.next(); elems.append(self.parse_expr())
            self.expect(T_OP, ']')
            return ('list_lit', elems, t.line)
