            b'!' if i+1<b.len()&&b[i+1]==b'=' => {i+=1;Tok::Neq}
            b'<' if i+1<b.len()&&b[i+1]==b'=' => {i+=1;Tok::Lte}
            b'>' if i+1<b.len()&&b[i+1]==b'=' => {i+=1;Tok::Gte}
            b'<' => Tok::Lt, b'>' => Tok::Gt, b'=' => Tok::Assign,
            b'+' => Tok::Plus, b'-' => Tok::Minus, b'*' => Tok::Star,
            b'/' => Tok::Slash, b'%' => Tok::Percent,
            b'(' => Tok::LParen, b')' => Tok::RParen,
            b'[' => Tok::LBracket, b']' => Tok::RBracket,
            b'{' => Tok::LBrace, b'}' => Tok::RBrace,
            b',' => Tok::Comma, b';' => Tok::Semicolon,
            _ => {i+=1; continue;}
        };
        toks.push(Token{kind:k, line}); i += 1;
    }
    toks.push(Token{kind:Tok::Eof, line});
    toks
}

// ===== AST =====
#[derive(Clone)]
enum Expr {
    IntLit(i64), StrLit(Rc<String>), BoolLit(bool), Nil,
    Ident(String, usize),
    Binary(String, Box<Expr>, Box<Expr>, usize),
    Unary(String, Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>),
    FnLit(Vec<String>, Vec<Stmt>),
}

#[derive(Clone)]
enum Stmt {
    Let(String, Expr, usize),
    FnDecl(String, Vec<String>, Vec<Stmt>, usize),
    If(Expr, Vec<Stmt>, Option<ElseBr>),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>, usize),
    Return(Option<Expr>, usize),
    Break, Continue,
    Assign(String, Expr, usize),
    IndexAssign(Box<Expr>, Box<Expr>, Expr, usize),
    ExprStmt(Expr),
}

#[derive(Clone)]
enum ElseBr { Block(Vec<Stmt>), If(Stmt) }

// ===== Values =====
#[derive(Clone)]
enum Value {
    Int(i64), Bool(bool), Str(Rc<String>),
    List(Rc<RefCell<Vec<Value>>>),
    Func(Rc<Function>),
    Nil,
}

enum Function {
    User{params:Vec<String>, body:Vec<Stmt>, cap:Rc<RefCell<Scope>>},
    Builtin(BuiltinId),
}

#[derive(Clone,Copy,PartialEq)]
enum BuiltinId { Print, Str, Type_, Len, Push, Pop, Range, Slice }

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

#[derive(PartialEq)]
enum CF { Normal, Break, Continue, Return(Value) }

struct RtError { line: usize, msg: String }

fn type_name(v: &Value) -> &'static str {
    match v { Value::Int(_)=>"int", Value::Bool(_)=>"bool", Value::Str(_)=>"string",
              Value::List(_)=>"list", Value::Func(_)=>"function", Value::Nil=>"nil" }
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Nil => false,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Func(_) => true,
    }
}

fn display(v: &Value, seen: &mut HashSet<usize>) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(b) => if *b {"true".to_string()} else {"false".to_string()},
        Value::Str(s) => s.as_str().to_string(),
        Value::Nil => "nil".to_string(),
        Value::Func(_) => "<fn>".to_string(),
        Value::List(l) => {
            let p = Rc::as_ptr(l) as usize;
            if seen.contains(&p) { return "[...]".to_string(); }
            seen.insert(p);
            let inner: Vec<String> = l.borrow().iter().map(|e| display_in_list(e, seen)).collect();
            seen.remove(&p);
            format!("[{}]", inner.join(", "))
        }
    }
}

fn display_in_list(v: &Value, seen: &mut HashSet<usize>) -> String {
    match v {
        Value::Str(s) => {
            let mut r = String::with_capacity(s.len()+2);
            r.push('"');
            for ch in s.chars() {
                match ch { '\\'=>r.push_str("\\\\"), '"'=>r.push_str("\\\""),
                          '\n'=>r.push_str("\\n"), '\t'=>r.push_str("\\t"),
                          _=>r.push(ch), }
            }
            r.push('"'); r
        }
        _ => display(v, seen),
    }
}

fn val_eq(a: &Value, b: &Value) -> bool {
    match (a,b) {
        (Value::Int(x),Value::Int(y)) => x==y,
        (Value::Bool(x),Value::Bool(y)) => x==y,
        (Value::Str(x),Value::Str(y)) => x==y,
        (Value::Nil,Value::Nil) => true,
        (Value::Func(x),Value::Func(y)) => Rc::ptr_eq(x,y),
        (Value::List(x),Value::List(y)) => {
            if Rc::ptr_eq(x,y) { return true; }
            let xa = x.borrow(); let ya = y.borrow();
            if xa.len() != ya.len() { return false; }
            for (i,j) in xa.iter().zip(ya.iter()) { if !val_eq(i,j) { return false; } }
            true
        }
        _ => false,
    }
}

// ===== Parser =====
struct Parser { toks: Vec<Token>, pos: usize }

impl Parser {
    fn new(toks: Vec<Token>) -> Self { Parser{toks, pos:0} }
    fn peek(&self) -> &Tok { &self.toks[self.pos].kind }
    fn peek_line(&self) -> usize { self.toks[self.pos].line }
    fn advance(&mut self) -> &Token { let t = &self.toks[self.pos]; self.pos += 1; t }
    fn expect(&mut self, k: &Tok) { if self.peek() != k { self.pos += 1; } }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut s = Vec::new();
        while *self.peek() != Tok::Eof { s.push(self.parse_stmt()); }
        s
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().clone() {
            Tok::Let => { self.advance(); let name = match self.advance().kind {Tok::Ident(n)=>n,_=>unreachable()}; let ln = self.toks[self.pos-1].line; self.expect(&Tok::Assign); let e = self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::Let(name, e, ln) }
            Tok::Fn => { self.advance(); let name = match self.advance().kind {Tok::Ident(n)=>n,_=>unreachable()}; let ln = self.toks[self.pos-1].line; self.expect(&Tok::LParen); let params = self.parse_params(); self.expect(&Tok::RParen); let body = self.parse_block(); Stmt::FnDecl(name, params, body, ln) }
            Tok::If => self.parse_if(),
            Tok::While => { self.advance(); let c = self.parse_expr(); let body = self.parse_block(); Stmt::While(c, body) }
            Tok::For => { let ln = self.peek_line(); self.advance(); let var = match self.advance().kind {Tok::Ident(n)=>n,_=>unreachable()}; self.expect(&Tok::In); let iter = self.parse_expr(); let body = self.parse_block(); Stmt::For(var, iter, body, ln) }
            Tok::Return => { self.advance(); if *self.peek()==Tok::Semicolon { self.advance(); Stmt::Return(None, self.toks[self.pos-1].line) } else { let e = self.parse_expr(); self.expect(&Tok::Semicolon); Stmt::Return(Some(e), self.toks[self.pos-1].line) } }
            Tok::Break => { self.advance(); self.expect(&Tok::Semicolon); Stmt::Break }
            Tok::Continue => { self.advance(); self.expect(&Tok::Semicolon); Stmt::Continue }
            _ => {
                let e = self.parse_expr();
                if *self.peek() == Tok::Assign {
                    self.advance();
                    let v = self.parse_expr();
                    self.expect(&Tok::Semicolon);
                    match e {
                        Expr::Ident(n, ln) => Stmt::Assign(n, v, ln),
                        Expr::Index(obj, idx, ln) => Stmt::IndexAssign(obj, idx, v, ln),
                        _ => Stmt::ExprStmt(e), // shouldn't happen
                    }
                } else {
                    self.expect(&Tok::Semicolon);
                    Stmt::ExprStmt(e)
                }
            }
        }
    }

    fn parse_if(&mut self) -> Stmt {
        self.advance();
        let cond = self.parse_expr();
        let body = self.parse_block();
        let els = if *self.peek() == Tok::Else {
            self.advance();
            if *self.peek() == Tok::If { Some(ElseBr::If(self.parse_if())) }
            else { Some(ElseBr::Block(self.parse_block())) }
        } else { None };
        Stmt::If(cond, body, els)
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(&Tok::LBrace);
        let mut s = Vec::new();
        while *self.peek() != Tok::RBrace && *self.peek() != Tok::Eof { s.push(self.parse_stmt()); }
        self.expect(&Tok::RBrace);
        s
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut p = Vec::new();
        if *self.peek() != Tok::RParen {
            loop {
                p.push(match self.advance().kind {Tok::Ident(n)=>n,_=>unreachable()});
                if *self.peek() != Tok::Comma { break; }
                self.advance();
            }
        }
        p
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut l = self.parse_and();
        while *self.peek() == Tok::Or { let ln = self.peek_line(); self.advance(); let r = self.parse_and(); l = Expr::Binary("or".into(), Box::new(l), Box::new(r), ln); }
        l
    }
    fn parse_and(&mut self) -> Expr {
        let mut l = self.parse_not();
        while *self.peek() == Tok::And { let ln = self.peek_line(); self.advance(); let r = self.parse_not(); l = Expr::Binary("and".into(), Box::new(l), Box::new(r), ln); }
        l
    }
    fn parse_not(&mut self) -> Expr {
        if *self.peek() == Tok::Not { let ln = self.peek_line(); self.advance(); let e = self.parse_not(); Expr::Unary("not".into(), Box::new(e), ln) }
        else { self.parse_cmp() }
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut l = self.parse_add();
        loop {
            let op = match self.peek() {
                Tok::Eq=>"==", Tok::Neq=>"!=", Tok::Lt=>"<", Tok::Lte=>"<=", Tok::Gt=>">", Tok::Gte=>">=", _=>break,
            };
            let ln = self.peek_line(); self.advance();
            let r = self.parse_add();
            l = Expr::Binary(op.into(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_add(&mut self) -> Expr {
        let mut l = self.parse_mul();
        loop {
            let op = match self.peek() { Tok::Plus=>"+", Tok::Minus=>"-", _=>break };
            let ln = self.peek_line(); self.advance();
            let r = self.parse_mul();
            l = Expr::Binary(op.into(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_mul(&mut self) -> Expr {
        let mut l = self.parse_unary();
        loop {
            let op = match self.peek() { Tok::Star=>"*", Tok::Slash=>"/", Tok::Percent=>"%", _=>break };
            let ln = self.peek_line(); self.advance();
            let r = self.parse_unary();
            l = Expr::Binary(op.into(), Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_unary(&mut self) -> Expr {
        if *self.peek() == Tok::Minus { let ln = self.peek_line(); self.advance(); let e = self.parse_unary(); Expr::Unary("-".into(), Box::new(e), ln) }
        else { self.parse_postfix() }
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek() {
                Tok::LParen => { let ln = self.peek_line(); self.advance(); let args = self.parse_args(); self.expect(&Tok::RParen); e = Expr::Call(Box::new(e), args, ln); }
                Tok::LBracket => { let ln = self.peek_line(); self.advance(); let idx = self.parse_expr(); self.expect(&Tok::RBracket); e = Expr::Index(Box::new(e), Box::new(idx), ln); }
                _ => break,
            }
        }
        e
    }
    fn parse_args(&mut self) -> Vec<Expr> {
        let mut a = Vec::new();
        if *self.peek() != Tok::RParen {
            loop { a.push(self.parse_expr()); if *self.peek()!=Tok::Comma {break;} self.advance(); }
        }
        a
    }
    fn parse_primary(&mut self) -> Expr {
        match self.advance().kind.clone() {
            Tok::IntLit(n) => Expr::IntLit(n),
            Tok::StrLit(s) => Expr::StrLit(Rc::new(s)),
            Tok::True => Expr::BoolLit(true),
            Tok::False => Expr::BoolLit(false),
            Tok::Nil => Expr::Nil,
            Tok::Ident(n) => { let ln = self.toks[self.pos-1].line; Expr::Ident(n, ln) }
            Tok::LParen => { let e = self.parse_expr(); self.expect(&Tok::RParen); e }
            Tok::LBracket => {
                let mut elems = Vec::new();
                if *self.peek() != Tok::RBracket {
                    loop { elems.push(self.parse_expr()); if *self.peek()!=Tok::Comma {break;} self.advance(); }
                }
                self.expect(&Tok::RBracket);
                Expr::ListLit(elems)
            }
            Tok::Fn => { self.expect(&Tok::LParen); let params = self.parse_params(); self.expect(&Tok::RParen); let body = self.parse_block(); Expr::FnLit(params, body) }
            _ => Expr::Nil,
        }
    }
}

// ===== Interpreter =====
struct Interp { out: String }

impl Interp {
    fn new() -> Self { Interp{out:String::new()} }

    fn lookup(&self, name: &str, scope: &Rc<RefCell<Scope>>) -> Option<Value> {
        let mut cur = Some(scope.clone());
        while let Some(s) = cur {
            if let Some(v) = s.borrow().vars.get(name) { return Some(v.clone()); }
            let p = s.borrow().parent.clone();
            cur = p;
        }
        None
    }

    fn assign_existing(&self, name: &str, val: Value, scope: &Rc<RefCell<Scope>>) -> bool {
        let mut cur = Some(scope.clone());
        while let Some(s) = cur {
            if s.borrow().vars.contains_key(name) { s.borrow_mut().vars.insert(name.to_string(), val); return true; }
            let p = s.borrow().parent.clone();
            cur = p;
        }
        false
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<CF, RtError> {
        for s in stmts {
            let cf = self.exec_stmt(s, scope)?;
            if cf != CF::Normal { return Ok(cf); }
        }
        Ok(CF::Normal)
    }

    fn exec_stmt(&mut self, s: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<CF, RtError> {
        match s {
            Stmt::Let(name, expr, ln) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), v);
                let _ = ln;
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, ln) => {
                let f = Rc::new(Function::User{params:params.clone(), body:body.clone(), cap:scope.clone()});
                scope.borrow_mut().vars.insert(name.clone(), Value::Func(f));
                let _ = ln;
                Ok(CF::Normal)
            }
            Stmt::If(cond, body, els) => {
                let c = self.eval(cond, scope)?;
                if truthy(&c) {
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    self.exec_block(body, &inner)
                } else {
                    match els {
                        Some(ElseBr::Block(b)) => { let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())})); self.exec_block(b, &inner) }
                        Some(ElseBr::If(s)) => self.exec_stmt(s, scope),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let c = self.eval(cond, scope)?;
                    if !truthy(&c) { break; }
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    match self.exec_block(body, &inner)? {
                        CF::Break => break,
                        CF::Continue => {},
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => {},
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, iter_expr, body, ln) => {
                let list_val = self.eval(iter_expr, scope)?;
                let list = match &list_val {
                    Value::List(l) => l.clone(),
                    _ => return Err(RtError{line:*ln, msg:format!("cannot iterate {}", type_name(&list_val))}),
                };
                let mut i: i64 = 0;
                loop {
                    let len = list.borrow().len() as i64;
                    if i >= len { break; }
                    let elem = list.borrow()[i as usize].clone();
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    inner.borrow_mut().vars.insert(var.clone(), elem);
                    match self.exec_block(body, &inner)? {
                        CF::Break => break,
                        CF::Continue => { i += 1; }
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => { i += 1; }
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::Return(expr, _) => {
                let v = match expr { Some(e)=>self.eval(e, scope)?, None=>Value::Nil };
                Ok(CF::Return(v))
            }
            Stmt::Break => Ok(CF::Break),
            Stmt::Continue => Ok(CF::Continue),
            Stmt::Assign(name, expr, ln) => {
                let v = self.eval(expr, scope)?;
                if !self.assign_existing(name, v, scope) {
                    return Err(RtError{line:*ln, msg:format!("undefined variable {}", name)});
                }
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(obj_expr, idx_expr, val_expr, ln) => {
                let obj = self.eval(obj_expr, scope)?;
                let idx = self.eval(idx_expr, scope)?;
                let val = self.eval(val_expr, scope)?;
                // checks
                let list = match &obj {
                    Value::List(l) => l.clone(),
                    other => return Err(RtError{line:*ln, msg:format!("cannot assign into {}", type_name(other))}),
                };
                let i = match &idx {
                    Value::Int(n) => *n,
                    other => return Err(RtError{line:*ln, msg:format!("cannot index list with {}", type_name(other))}),
                };
                let len = list.borrow().len() as i64;
                if i < 0 || i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                list.borrow_mut()[i as usize] = val;
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(e) => { self.eval(e, scope)?; Ok(CF::Normal) }
        }
    }

    fn eval(&mut self, e: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value, RtError> {
        match e {
            Expr::IntLit(n) => Ok(Value::Int(*n)),
            Expr::StrLit(s) => Ok(Value::Str(s.clone())),
            Expr::BoolLit(b) => Ok(Value::Bool(*b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Ident(name, ln) => {
                match self.lookup(name, scope) {
                    Some(v) => Ok(v),
                    None => Err(RtError{line:*ln, msg:format!("undefined variable {}", name)}),
                }
            }
            Expr::Binary(op, l, r, ln) => {
                match op.as_str() {
                    "and" => { let lv = self.eval(l, scope)?; if !truthy(&lv) { Ok(lv) } else { self.eval(r, scope) } }
                    "or" => { let lv = self.eval(l, scope)?; if truthy(&lv) { Ok(lv) } else { self.eval(r, scope) } }
                    "==" => { let lv = self.eval(l, scope)?; let rv = self.eval(r, scope)?; Ok(Value::Bool(val_eq(&lv, &rv))) }
                    "!=" => { let lv = self.eval(l, scope)?; let rv = self.eval(r, scope)?; Ok(Value::Bool(!val_eq(&lv, &rv))) }
                    _ => {
                        let lv = self.eval(l, scope)?;
                        let rv = self.eval(r, scope)?;
                        self.binop(op, lv, rv, *ln)
                    }
                }
            }
            Expr::Unary(op, inner, ln) => {
                let v = self.eval(inner, scope)?;
                match op.as_str() {
                    "not" => Ok(Value::Bool(!truthy(&v))),
                    "-" => {
                        match v {
                            Value::Int(n) => n.checked_neg().map(Value::Int).ok_or(RtError{line:*ln, msg:"integer overflow".into()}),
                            other => Err(RtError{line:*ln, msg:format!("cannot apply - to {}", type_name(&other))}),
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call(callee, args, ln) => {
                let cv = self.eval(callee, scope)?;
                let mut vals = Vec::with_capacity(args.len());
                for a in args { vals.push(self.eval(a, scope)?); }
                self.call(&cv, vals, *ln)
            }
            Expr::Index(obj, idx, ln) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                match (&ov, &iv) {
                    (Value::List(l), Value::Int(i)) => {
                        let len = l.borrow().len() as i64;
                        if *i < 0 || *i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                        Ok(l.borrow()[*i as usize].clone())
                    }
                    (Value::Str(s), Value::Int(i)) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                        Ok(Value::Str(Rc::new(s[*i as usize..*i as usize+1].to_string())))
                    }
                    (Value::List(_), _) => Err(RtError{line:*ln, msg:format!("cannot index list with {}", type_name(&iv))}),
                    (Value::Str(_), _) => Err(RtError{line:*ln, msg:format!("cannot index string with {}", type_name(&iv))}),
                    (other, _) => Err(RtError{line:*ln, msg:format!("cannot index {} with {}", type_name(other), type_name(&iv))}),
                }
            }
            Expr::ListLit(elems) => {
                let mut v = Vec::with_capacity(elems.len());
                for el in elems { v.push(self.eval(el, scope)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body) => {
                Ok(Value::Func(Rc::new(Function::User{params:params.clone(), body:body.clone(), cap:scope.clone()})))
            }
        }
    }

    fn binop(&mut self, op: &str, lv: Value, rv: Value, ln: usize) -> Result<Value, RtError> {
        match op {
            "+" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or(RtError{line:ln, msg:"integer overflow".into()}),
                (Value::Str(a), Value::Str(b)) => Ok(Value::Str(Rc::new(format!("{}{}", a, b)))),
                (Value::List(a), Value::List(b)) => {
                    let mut v = a.borrow().clone(); v.extend(b.borrow().iter().cloned());
                    Ok(Value::List(Rc::new(RefCell::new(v))))
                }
                _ => Err(RtError{line:ln, msg:format!("cannot apply + to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "-" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or(RtError{line:ln, msg:"integer overflow".into()}),
                _ => Err(RtError{line:ln, msg:format!("cannot apply - to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "*" => match (&lv, &rv) {
