                Tok::LParen => { let ln = self.peek_line(); self.advance(); let args = self.parse_args(); self.expect(&Tok::RParen); e = Expr::Call(Box::new(e), args, ln); }
                Tok::LBracket => { let ln = self.peek_line(); self.advance(); let idx = self.parse_expr(); self.expect(&Tok::RBracket); e = Expr::Index(Box::new(e), Box::new(idx), ln); }
                _ => break,
            }
        }
        e
    }
    fn parse_args(&mut self) -> Vec<Expr> {
        let mut a = Vec::new();
        if *self.peek() != Tok::RParen {
            loop { a.push(self.parse_expr()); if *self.peek()!=Tok::Comma {break;} self.advance(); }
        }
        a
    }
    fn parse_primary(&mut self) -> Expr {
        match self.advance().kind.clone() {
            Tok::IntLit(n) => Expr::IntLit(n),
            Tok::StrLit(s) => Expr::StrLit(Rc::new(s)),
            Tok::True => Expr::BoolLit(true),
            Tok::False => Expr::BoolLit(false),
            Tok::Nil => Expr::Nil,
            Tok::Ident(n) => { let ln = self.toks[self.pos-1].line; Expr::Ident(n, ln) }
            Tok::LParen => { let e = self.parse_expr(); self.expect(&Tok::RParen); e }
            Tok::LBracket => {
                let mut elems = Vec::new();
                if *self.peek() != Tok::RBracket {
                    loop { elems.push(self.parse_expr()); if *self.peek()!=Tok::Comma {break;} self.advance(); }
                }
                self.expect(&Tok::RBracket);
                Expr::ListLit(elems)
            }
            Tok::Fn => { self.expect(&Tok::LParen); let params = self.parse_params(); self.expect(&Tok::RParen); let body = self.parse_block(); Expr::FnLit(params, body) }
            _ => Expr::Nil,
        }
    }
}

// ===== Interpreter =====
struct Interp { out: String }

impl Interp {
    fn new() -> Self { Interp{out:String::new()} }

    fn lookup(&self, name: &str, scope: &Rc<RefCell<Scope>>) -> Option<Value> {
        let mut cur = Some(scope.clone());
        while let Some(s) = cur {
            if let Some(v) = s.borrow().vars.get(name) { return Some(v.clone()); }
            let p = s.borrow().parent.clone();
            cur = p;
        }
        None
    }

    fn assign_existing(&self, name: &str, val: Value, scope: &Rc<RefCell<Scope>>) -> bool {
        let mut cur = Some(scope.clone());
        while let Some(s) = cur {
            if s.borrow().vars.contains_key(name) { s.borrow_mut().vars.insert(name.to_string(), val); return true; }
            let p = s.borrow().parent.clone();
            cur = p;
        }
        false
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<CF, RtError> {
        for s in stmts {
            let cf = self.exec_stmt(s, scope)?;
            if cf != CF::Normal { return Ok(cf); }
        }
        Ok(CF::Normal)
    }

    fn exec_stmt(&mut self, s: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<CF, RtError> {
        match s {
            Stmt::Let(name, expr, ln) => {
                let v = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), v);
                let _ = ln;
                Ok(CF::Normal)
            }
            Stmt::FnDecl(name, params, body, ln) => {
                let f = Rc::new(Function::User{params:params.clone(), body:body.clone(), cap:scope.clone()});
                scope.borrow_mut().vars.insert(name.clone(), Value::Func(f));
                let _ = ln;
                Ok(CF::Normal)
            }
            Stmt::If(cond, body, els) => {
                let c = self.eval(cond, scope)?;
                if truthy(&c) {
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    self.exec_block(body, &inner)
                } else {
                    match els {
                        Some(ElseBr::Block(b)) => { let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())})); self.exec_block(b, &inner) }
                        Some(ElseBr::If(s)) => self.exec_stmt(s, scope),
                        None => Ok(CF::Normal),
                    }
                }
            }
            Stmt::While(cond, body) => {
                loop {
                    let c = self.eval(cond, scope)?;
                    if !truthy(&c) { break; }
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    match self.exec_block(body, &inner)? {
                        CF::Break => break,
                        CF::Continue => {},
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => {},
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::For(var, iter_expr, body, ln) => {
                let list_val = self.eval(iter_expr, scope)?;
                let list = match &list_val {
                    Value::List(l) => l.clone(),
                    _ => return Err(RtError{line:*ln, msg:format!("cannot iterate {}", type_name(&list_val))}),
                };
                let mut i: i64 = 0;
                loop {
                    let len = list.borrow().len() as i64;
                    if i >= len { break; }
                    let elem = list.borrow()[i as usize].clone();
                    let inner = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(scope.clone())}));
                    inner.borrow_mut().vars.insert(var.clone(), elem);
                    match self.exec_block(body, &inner)? {
                        CF::Break => break,
                        CF::Continue => { i += 1; }
                        CF::Return(v) => return Ok(CF::Return(v)),
                        CF::Normal => { i += 1; }
                    }
                }
                Ok(CF::Normal)
            }
            Stmt::Return(expr, _) => {
                let v = match expr { Some(e)=>self.eval(e, scope)?, None=>Value::Nil };
                Ok(CF::Return(v))
            }
            Stmt::Break => Ok(CF::Break),
            Stmt::Continue => Ok(CF::Continue),
            Stmt::Assign(name, expr, ln) => {
                let v = self.eval(expr, scope)?;
                if !self.assign_existing(name, v, scope) {
                    return Err(RtError{line:*ln, msg:format!("undefined variable {}", name)});
                }
                Ok(CF::Normal)
            }
            Stmt::IndexAssign(obj_expr, idx_expr, val_expr, ln) => {
                let obj = self.eval(obj_expr, scope)?;
                let idx = self.eval(idx_expr, scope)?;
                let val = self.eval(val_expr, scope)?;
                // checks
                let list = match &obj {
                    Value::List(l) => l.clone(),
                    other => return Err(RtError{line:*ln, msg:format!("cannot assign into {}", type_name(other))}),
                };
                let i = match &idx {
                    Value::Int(n) => *n,
                    other => return Err(RtError{line:*ln, msg:format!("cannot index list with {}", type_name(other))}),
                };
                let len = list.borrow().len() as i64;
                if i < 0 || i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                list.borrow_mut()[i as usize] = val;
                Ok(CF::Normal)
            }
            Stmt::ExprStmt(e) => { self.eval(e, scope)?; Ok(CF::Normal) }
        }
    }

    fn eval(&mut self, e: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value, RtError> {
        match e {
            Expr::IntLit(n) => Ok(Value::Int(*n)),
            Expr::StrLit(s) => Ok(Value::Str(s.clone())),
            Expr::BoolLit(b) => Ok(Value::Bool(*b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Ident(name, ln) => {
                match self.lookup(name, scope) {
                    Some(v) => Ok(v),
                    None => Err(RtError{line:*ln, msg:format!("undefined variable {}", name)}),
                }
            }
            Expr::Binary(op, l, r, ln) => {
                match op.as_str() {
                    "and" => { let lv = self.eval(l, scope)?; if !truthy(&lv) { Ok(lv) } else { self.eval(r, scope) } }
                    "or" => { let lv = self.eval(l, scope)?; if truthy(&lv) { Ok(lv) } else { self.eval(r, scope) } }
                    "==" => { let lv = self.eval(l, scope)?; let rv = self.eval(r, scope)?; Ok(Value::Bool(val_eq(&lv, &rv))) }
                    "!=" => { let lv = self.eval(l, scope)?; let rv = self.eval(r, scope)?; Ok(Value::Bool(!val_eq(&lv, &rv))) }
                    _ => {
                        let lv = self.eval(l, scope)?;
                        let rv = self.eval(r, scope)?;
                        self.binop(op, lv, rv, *ln)
                    }
                }
            }
            Expr::Unary(op, inner, ln) => {
                let v = self.eval(inner, scope)?;
                match op.as_str() {
                    "not" => Ok(Value::Bool(!truthy(&v))),
                    "-" => {
                        match v {
                            Value::Int(n) => n.checked_neg().map(Value::Int).ok_or(RtError{line:*ln, msg:"integer overflow".into()}),
                            other => Err(RtError{line:*ln, msg:format!("cannot apply - to {}", type_name(&other))}),
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call(callee, args, ln) => {
                let cv = self.eval(callee, scope)?;
                let mut vals = Vec::with_capacity(args.len());
                for a in args { vals.push(self.eval(a, scope)?); }
                self.call(&cv, vals, *ln)
            }
            Expr::Index(obj, idx, ln) => {
                let ov = self.eval(obj, scope)?;
                let iv = self.eval(idx, scope)?;
                match (&ov, &iv) {
                    (Value::List(l), Value::Int(i)) => {
                        let len = l.borrow().len() as i64;
                        if *i < 0 || *i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                        Ok(l.borrow()[*i as usize].clone())
                    }
                    (Value::Str(s), Value::Int(i)) => {
                        let len = s.len() as i64;
                        if *i < 0 || *i >= len { return Err(RtError{line:*ln, msg:format!("index {} out of range for length {}", i, len)}); }
                        Ok(Value::Str(Rc::new(s[*i as usize..*i as usize+1].to_string())))
                    }
                    (Value::List(_), _) => Err(RtError{line:*ln, msg:format!("cannot index list with {}", type_name(&iv))}),
                    (Value::Str(_), _) => Err(RtError{line:*ln, msg:format!("cannot index string with {}", type_name(&iv))}),
                    (other, _) => Err(RtError{line:*ln, msg:format!("cannot index {} with {}", type_name(other), type_name(&iv))}),
                }
            }
            Expr::ListLit(elems) => {
                let mut v = Vec::with_capacity(elems.len());
                for el in elems { v.push(self.eval(el, scope)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Expr::FnLit(params, body) => {
                Ok(Value::Func(Rc::new(Function::User{params:params.clone(), body:body.clone(), cap:scope.clone()})))
            }
        }
    }

    fn binop(&mut self, op: &str, lv: Value, rv: Value, ln: usize) -> Result<Value, RtError> {
        match op {
            "+" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or(RtError{line:ln, msg:"integer overflow".into()}),
                (Value::Str(a), Value::Str(b)) => Ok(Value::Str(Rc::new(format!("{}{}", a, b)))),
                (Value::List(a), Value::List(b)) => {
                    let mut v = a.borrow().clone(); v.extend(b.borrow().iter().cloned());
                    Ok(Value::List(Rc::new(RefCell::new(v))))
                }
                _ => Err(RtError{line:ln, msg:format!("cannot apply + to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "-" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or(RtError{line:ln, msg:"integer overflow".into()}),
                _ => Err(RtError{line:ln, msg:format!("cannot apply - to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "*" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => a.checked_mul(*b).map(Value::Int).ok_or(RtError{line:ln, msg:"integer overflow".into()}),
                _ => Err(RtError{line:ln, msg:format!("cannot apply * to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "/" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => {
                    if *b == 0 { return Err(RtError{line:ln, msg:"division by zero".into()}); }
                    if *a == i64::MIN && *b == -1 { return Err(RtError{line:ln, msg:"integer overflow".into()}); }
                    Ok(Value::Int(a / b))
                }
                _ => Err(RtError{line:ln, msg:format!("cannot apply / to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "%" => match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => {
                    if *b == 0 { return Err(RtError{line:ln, msg:"division by zero".into()}); }
                    if *b == -1 { return Ok(Value::Int(0)); }
                    Ok(Value::Int(a % b))
                }
                _ => Err(RtError{line:ln, msg:format!("cannot apply % to {} and {}", type_name(&lv), type_name(&rv))}),
            },
            "<" | "<=" | ">" | ">=" => {
                match (&lv, &rv) {
                    (Value::Int(a), Value::Int(b)) => Ok(Value::Bool(match op {"<"=>a<*b,"<=" =>a<=*b,">"=>a>*b,">="=>a>=*b,_=>false})),
                    (Value::Str(a), Value::Str(b)) => Ok(Value::Bool(match op {"<"=>a.as_str()<b.as_str(),"<="=>a.as_str()<=b.as_str(),">"=>a.as_str()>b.as_str(),">="=>a.as_str()>=b.as_str(),_=>false})),
                    _ => Err(RtError{line:ln, msg:format!("cannot apply {} to {} and {}", op, type_name(&lv), type_name(&rv))}),
                }
            }
            _ => unreachable!(),
        }
    }

    fn call(&mut self, f: &Value, args: Vec<Value>, ln: usize) -> Result<Value, RtError> {
        match f {
            Value::Func(func) => match &**func {
                Function::User{params, body, cap} => {
                    if args.len() != params.len() { return Err(RtError{line:ln, msg:format!("expected {} arguments, got {}", params.len(), args.len())}); }
                    let call_scope = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(cap.clone())}));
                    for (p,v) in params.iter().zip(args.into_iter()) { call_scope.borrow_mut().vars.insert(p.clone(), v); }
                    match self.exec_block(body, &call_scope)? {
                        CF::Return(v) => Ok(v),
                        _ => Ok(Value::Nil),
                    }
                }
                Function::Builtin(bid) => self.call_builtin(*bid, args, ln),
            },
            other => Err(RtError{line:ln, msg:format!("cannot call {}", type_name(other))}),
        }
    }

    fn call_builtin(&mut self, bid: BuiltinId, args: Vec<Value>, ln: usize) -> Result<Value, RtError> {
        match bid {
            BuiltinId::Print => {
                let mut seen = HashSet::new();
                let strs: Vec<String> = args.iter().map(|v| display(v, &mut seen)).collect();
                self.out.push_str(&strs.join(" "));
                self.out.push('\n');
                Ok(Value::Nil)
            }
            BuiltinId::Str => {
                if args.len() != 1 { return Err(RtError{line:ln, msg:format!("expected 1 arguments, got {}", args.len())}); }
                let mut seen = HashSet::new();
                Ok(Value::Str(Rc::new(display(&args[0], &mut seen))))
            }
            BuiltinId::Type_ => {
                if args.len() != 1 { return Err(RtError{line:ln, msg:format!("expected 1 arguments, got {}", args.len())}); }
                Ok(Value::Str(Rc::new(type_name(&args[0]).to_string())))
            }
            BuiltinId::Len => {
                if args.len() != 1 { return Err(RtError{line:ln, msg:format!("expected 1 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.len() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(RtError{line:ln, msg:"bad argument to len".into()}),
                }
            }
            BuiltinId::Push => {
                if args.len() != 2 { return Err(RtError{line:ln, msg:format!("expected 2 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(RtError{line:ln, msg:"bad argument to push".into()}),
                }
            }
            BuiltinId::Pop => {
                if args.len() != 1 { return Err(RtError{line:ln, msg:format!("expected 1 arguments, got {}", args.len())}); }
                match &args[0] {
                    Value::List(l) => {
                        let mut v = l.borrow_mut();
                        if v.is_empty() { return Err(RtError{line:ln, msg:"bad argument to pop".into()}); }
                        Ok(v.pop().unwrap())
                    }
                    _ => Err(RtError{line:ln, msg:"bad argument to pop".into()}),
                }
            }
            BuiltinId::Range => {
                if args.len() != 2 { return Err(RtError{line:ln, msg:format!("expected 2 arguments, got {}", args.len())}); }
                match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => {
                        let mut v = Vec::new();
                        let mut i = *a;
                        while i < *b { v.push(Value::Int(i)); i += 1; }
                        Ok(Value::List(Rc::new(RefCell::new(v))))
                    }
                    _ => Err(RtError{line:ln, msg:"bad argument to range".into()}),
                }
            }
            BuiltinId::Slice => {
                if args.len() != 3 { return Err(RtError{line:ln, msg:format!("expected 3 arguments, got {}", args.len())}); }
                let a = match &args[1] { Value::Int(n)=>*n, _=>return Err(RtError{line:ln, msg:"bad argument to slice".into()}) };
                let b = match &args[2] { Value::Int(n)=>*n, _=>return Err(RtError{line:ln, msg:"bad argument to slice".into()}) };
                match &args[0] {
                    Value::Str(s) => {
                        let len = s.len() as i64;
                        if a < 0 || b > len || a > b { return Err(RtError{line:ln, msg:"bad argument to slice".into()}); }
                        Ok(Value::Str(Rc::new(s[a as usize..b as usize].to_string())))
                    }
                    Value::List(l) => {
                        let len = l.borrow().len() as i64;
                        if a < 0 || b > len || a > b { return Err(RtError{line:ln, msg:"bad argument to slice".into()}); }
                        Ok(Value::List(Rc::new(RefCell::new(l.borrow()[a as usize..b as usize].to_vec()))))
                    }
                    _ => Err(RtError{line:ln, msg:"bad argument to slice".into()}),
                }
            }
        }
    }

    fn run(&mut self, program: &[Stmt]) {
        let builtins = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:None}));
        {
            let b = builtins.borrow_mut();
            b.vars.insert("print".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Print))));
            b.vars.insert("str".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Str))));
            b.vars.insert("type".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Type_))));
            b.vars.insert("len".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Len))));
            b.vars.insert("push".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Push))));
            b.vars.insert("pop".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Pop))));
            b.vars.insert("range".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Range))));
            b.vars.insert("slice".into(), Value::Func(Rc::new(Function::Builtin(BuiltinId::Slice))));
        }
        let global = Rc::new(RefCell::new(Scope{vars:HashMap::new(), parent:Some(builtins)}));
        match self.exec_block(program, &global) {
            Ok(_) => {},
            Err(e) => {
                self.out.push_str(&format!("error at line {}: {}\n", e.line, e.msg));
            }
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = fs::read_to_string(&path).unwrap();
    let toks = lex(&src);
    let mut parser = Parser::new(toks);
    let program = parser.parse_program();
    let mut interp = Interp::new();
    interp.run(&program);
    let stdout = std::io::stdout();
    let mut w = stdout.lock();
    w.write_all(interp.out.as_bytes()).unwrap();
    w.flush().unwrap();
    process::exit(0);
}
