import Foundation

// CRC-32 lookup table (PNG standard)
let crc32Table: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) } else { c = c >> 1 }
        }
        table[i] = c
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc = crc32Table[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var s1: UInt32 = 1
    var s2: UInt32 = 0
    for byte in data {
        s1 = (s1 + UInt32(byte)) % 65521
        s2 = (s2 + s1) % 65521
    }
    return (s2 << 16) | s1
}

func writeBE32(_ val: UInt32) -> [UInt8] {
    return [UInt8((val >> 24) & 0xFF), UInt8((val >> 16) & 0xFF), UInt8((val >> 8) & 0xFF), UInt8(val & 0xFF)]
}

func writeLE16(_ val: UInt16) -> [UInt8] {
    return [UInt8(val & 0xFF), UInt8((val >> 8) & 0xFF)]
}

func makeChunk(_ type: String, _ data: [UInt8]) -> [UInt8] {
    var chunk: [UInt8] = []
    chunk += writeBE32(UInt32(data.count))
    let typeBytes = Array(type.utf8)
    chunk += typeBytes
    chunk += data
    var crcInput = typeBytes
    crcInput += data
    chunk += writeBE32(crc32(crcInput))
    return chunk
