        elif sym == 18:
            all_lengths.extend([0] * (11 + reader.read_bits(7)))
    lit_lengths = all_lengths[:hlit]
    dist_lengths = all_lengths[hlit:hlit + hdist]
    lit_tree = build_tree(lit_lengths)
    if any(l > 0 for l in dist_lengths):
        dist_tree = build_tree(dist_lengths)
    else:
        # No distance codes used; create dummy tree
        dist_tree = {0: {'s': 0}, 1: {'s': 0}}
    while True:
        sym = decode_sym(reader, lit_tree)
        if sym == 256:
            break
        if sym >= 257:
