func buildTree(_ lens: [Int]) -> HN {
    let root = HN()
    let maxL = lens.max() ?? 0
    if maxL == 0 { return root }
    var bl = [Int](repeating: 0, count: maxL + 1)
    for l in lens { if l > 0 { bl[l] += 1 } }
    var nc = [Int](repeating: 0, count: maxL + 1)
    var code = 0
    for l in 1...maxL { nc[l] = code; code = (code + bl[l]) << 1 }
    for (sym, l) in lens.enumerated() {
        if l == 0 { continue }
        var c = nc[l]; nc[l] += 1
        var nd = root
        for i in stride(from: l - 1, through: 0, by: -1) {
            if (c >> i) & 1 == 0 {
                if nd.l == nil { nd.l = HN() }
                nd = nd.l!
            } else {
                if nd.r == nil { nd.r = HN() }
                nd = nd.r!
            }
        }
        nd.sym = sym
    }
    return root
}

