}

func unfilter(_ data: [UInt8], width: Int, height: Int, channels: Int, bitDepth: Int) -> ([[UInt8]], [Int]) {
    let bpp = max(1, channels * bitDepth / 8)
    let rowBytes = (width * channels * bitDepth + 7) / 8
    var rows = [[UInt8]](repeating: [UInt8](repeating: 0, count: rowBytes), count: height)
    var fc = [Int](repeating: 0, count: 5)
    for y in 0..<height {
        let ft = Int(data[y * (rowBytes + 1)])
        fc[ft] += 1
        let off = y * (rowBytes + 1) + 1
        for x in 0..<rowBytes {
            let raw = Int(data[off + x])
            let a = x >= bpp ? Int(rows[y][x - bpp]) : 0
            let b = y > 0 ? Int(rows[y - 1][x]) : 0
            let c = (y > 0 && x >= bpp) ? Int(rows[y - 1][x - bpp]) : 0
            let v: Int
            switch ft {
            case 0: v = raw
            case 1: v = raw + a
            case 2: v = raw + b
            case 3: v = raw + (a + b) / 2
            case 4: v = raw + paeth(a, b, c)
            default: v = raw
