struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,
    bit_pos: u8,
}

impl<'a> BitReader<'a> {
    fn new(data: &'a [u8]) -> Self { BitReader { data, pos: 0, bit_pos: 0 } }
    fn read_bit(&mut self) -> u32 {
        let b = (self.data[self.pos] >> self.bit_pos) & 1;
        self.bit_pos += 1;
        if self.bit_pos == 8 { self.bit_pos = 0; self.pos += 1; }
        b as u32
    }
    fn read_bits(&mut self, n: u32) -> u32 {
        let mut val = 0u32;
        for i in 0..n { val |= self.read_bit() << i; }
        val
    }
    fn align(&mut self) {
        if self.bit_pos != 0 { self.bit_pos = 0; self.pos += 1; }
    }
}

fn build_tree(lengths: &[u8]) -> Vec<[i32; 2]> {
    let max_bits = 15;
    let mut bl_count = vec![0u32; max_bits + 1];
    for &l in lengths { if l > 0 { bl_count[l as usize] += 1; } }
    let mut next_code = vec![0u32; max_bits + 1];
    let mut code = 0u32;
    for bits in 1..=max_bits {
        code = (code + bl_count[bits - 1]) << 1;
        next_code[bits] = code;
    }
    let mut codes = vec![0u32; lengths.len()];
    for (i, &l) in lengths.iter().enumerate() {
        if l > 0 { codes[i] = next_code[l as usize]; next_code[l as usize] += 1; }
    }
    let mut tree: Vec<[i32; 2]> = vec![[-1, -1]];
    for (sym, &l) in lengths.iter().enumerate() {
        if l == 0 { continue; }
        let mut node = 0usize;
        for bit in (0..l).rev() {
            let b = ((codes[sym] >> bit) & 1) as usize;
            if tree[node][b] == -1 {
                tree.push([-1, -1]);
                tree[node][b] = (tree.len() - 1) as i32;
            }
            node = tree[node][b] as usize;
        }
        tree[node] = [-(sym as i32) - 1, 0];
    }
    // Handle single-symbol tree
    if tree.len() == 2 && tree[0][0] != -1 && tree[0][1] == -1 {
        tree[0][1] = tree[0][0];
    } else if tree.len() == 2 && tree[0][1] != -1 && tree[0][0] == -1 {
        tree[0][0] = tree[0][1];
    }
    tree
}

fn decode_sym(tree: &[[i32; 2]], br: &mut BitReader) -> u16 {
    let mut node = 0usize;
    loop {
        let bit = br.read_bit() as usize;
        let next = tree[node][bit];
        if next < 0 { return (-(next + 1)) as u16; }
        node = next as usize;
    }
}

