                let dist_lengths = vec![5u8; 32];
                let dist_tree = build_tree(&dist_lengths);
                loop {
                    let sym = decode_sym(&lit_tree, &mut br);
                    if sym < 256 {
                        output.push(sym as u8);
                    } else if sym == 256 {
                        break;
                    } else {
                        let idx = (sym - 257) as usize;
                        let length = LENGTH_BASE[idx] + br.read_bits(LENGTH_EXTRA[idx]) as u16;
                        let dsym = decode_sym(&dist_tree, &mut br) as usize;
                        let dist = DIST_BASE[dsym] + br.read_bits(DIST_EXTRA[dsym]) as u16;
                        let start = output.len() - dist as usize;
                        for i in 0..length as usize {
                            let b = output[start + i];
                            output.push(b);
                        }
                    }
                }
            }
            2 => {
                let hlit = br.read_bits(5) as usize + 257;
                let hdist = br.read_bits(5) as usize + 1;
                let hclen = br.read_bits(4) as usize + 4;
                let mut clen_lengths = [0u8; 19];
                for i in 0..hclen { clen_lengths[CLEN_ORDER[i]] = br.read_bits(3) as u8; }
                let clen_tree = build_tree(&clen_lengths);
