                while i < total {
                    let sym = decode_sym(&clen_tree, &mut br) as usize;
                    if sym < 16 { all_lengths[i] = sym as u8; i += 1; }
                    else if sym == 16 {
                        let prev = all_lengths[i - 1];
                        let rep = 3 + br.read_bits(2) as usize;
                        for _ in 0..rep { all_lengths[i] = prev; i += 1; }
                    } else if sym == 17 {
                        let rep = 3 + br.read_bits(3) as usize;
                        for _ in 0..rep { all_lengths[i] = 0; i += 1; }
                    } else {
                        let rep = 11 + br.read_bits(7) as usize;
                        for _ in 0..rep { all_lengths[i] = 0; i += 1; }
                    }
                }
                let lit_tree = build_tree(&all_lengths[..hlit]);
                let dist_tree = build_tree(&all_lengths[hlit..]);
                loop {
                    let sym = decode_sym(&lit_tree, &mut br);
                    if sym < 256 { output.push(sym as u8); }
                    else if sym == 256 { break; }
                    else {
                        let idx = (sym - 257) as usize;
                        let length = LENGTH_BASE[idx] + br.read_bits(LENGTH_EXTRA[idx]) as u16;
                        let dsym = decode_sym(&dist_tree, &mut br) as usize;
                        let dist = DIST_BASE[dsym] + br.read_bits(DIST_EXTRA[dsym]) as u16;
                        let start = output.len() - dist as usize;
                        for j in 0..length as usize { let b = output[start + j]; output.push(b); }
                    }
                }
            }
            _ => unreachable!(),
        }
        if final_block == 1 { break; }
    }
    output
}

fn paeth_predictor(a: i32, b: i32, c: i32) -> u8 {
    let p = a + b - c;
    let pa = (p - a).abs();
    let pb = (p - b).abs();
    let pc = (p - c).abs();
    if pa <= pb && pa <= pc { a as u8 }
    else if pb <= pc { b as u8 }
    else { c as u8 }
}

fn extract_sample(data: &[u8], y: usize, x: usize, ch: usize, channels: usize, row_bytes: usize, bit_depth: usize) -> u32 {
    let bit_offset = (x * channels + ch) * bit_depth;
    let byte_idx = bit_offset / 8;
    let bit_idx = bit_offset % 8;
    if bit_depth >= 8 {
        // Multi-byte sample, big-endian
        let mut val: u32 = 0;
        let n_bytes = bit_depth / 8;
        for i in 0..n_bytes {
            val = (val << 8) | data[y * row_bytes + byte_idx + i] as u32;
        }
        val
    } else {
        // Sub-byte sample, MSB first
        let byte = data[y * row_bytes + byte_idx];
        let shift = 8 - bit_idx - bit_depth;
        ((byte >> shift) & ((1u8 << bit_depth) - 1)) as u32
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let path = Path::new(dir);
    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(path).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.ends_with(".png") { files.push(name); }
    }
    files.sort();

    let mut first = true;
    for fname in &files {
        if !first { print!("\n"); }
        first = false;
        let fpath = path.join(fname);
        let data = fs::read(&fpath).unwrap();
        process_file(fname, &data);
    }
}

fn process_file(fname: &str, data: &[u8]) {
    println!("== {}", fname);

    let sig: [u8; 8] = [137, 80, 78, 71, 13, 10, 26, 10];
    if data.len() < 8 || data[..8] != sig {
        println!("error: invalid PNG");
        return;
    }

    let mut offset = 8usize;
    let mut chunk_types: Vec<String> = Vec::new();
    let mut chunk_index = 0usize;
    let mut crc_error_chunk: Option<(usize, String)> = None;

    let mut ihdr_data: Vec<u8> = Vec::new();
    let mut idat_data: Vec<u8> = Vec::new();
    let mut plte_data: Vec<u8> = Vec::new();
    let mut trns_data: Vec<u8> = Vec::new();

    while offset + 8 <= data.len() {
        let length = u32::from_be_bytes([data[offset], data[offset+1], data[offset+2], data[offset+3]]) as usize;
        let ctype = String::from_utf8_lossy(&data[offset+4..offset+8]).to_string();
        chunk_index += 1;
        let data_start = offset + 8;
        let crc_start = data_start + length;
        if crc_start + 4 > data.len() { break; }
        let stored_crc = u32::from_be_bytes([data[crc_start], data[crc_start+1], data[crc_start+2], data[crc_start+3]]);
        let computed_crc = crc32(&data[offset+4..crc_start]);
        if stored_crc != computed_crc && crc_error_chunk.is_none() {
            crc_error_chunk = Some((chunk_index, ctype.clone()));
        }
        chunk_types.push(ctype.clone());
        let chunk_payload = &data[data_start..data_start+length];
        match ctype.as_str() {
            "IHDR" => ihdr_data = chunk_payload.to_vec(),
            "IDAT" => idat_data.extend_from_slice(chunk_payload),
            "PLTE" => plte_data.extend_from_slice(chunk_payload),
            "tRNS" => trns_data.extend_from_slice(chunk_payload),
            _ => {}
        }
        offset = crc_start + 4;
        if ctype == "IEND" { break; }
    }

    if let Some((n, ref t)) = crc_error_chunk {
        println!("error: CRC mismatch in chunk {} {}", n, t);
        return;
    }

    let width = u32::from_be_bytes([ihdr_data[0], ihdr_data[1], ihdr_data[2], ihdr_data[3]]) as usize;
    let height = u32::from_be_bytes([ihdr_data[4], ihdr_data[5], ihdr_data[6], ihdr_data[7]]) as usize;
    let bit_depth = ihdr_data[8] as usize;
    let color_type = ihdr_data[9] as usize;

    let channels = match color_type {
        0 => 1, 2 => 3, 3 => 1, 4 => 2, 6 => 4, _ => 1,
    };
    let bpp = (channels * bit_depth + 7) / 8;
    let row_bytes = (width * channels * bit_depth + 7) / 8;

    if idat_data.len() < 6 {
        println!("error: invalid zlib");
        return;
    }
    let deflate_data = &idat_data[2..idat_data.len()-4];
    let stored_adler = u32::from_be_bytes([
        idat_data[idat_data.len()-4], idat_data[idat_data.len()-3],
        idat_data[idat_data.len()-2], idat_data[idat_data.len()-1]
    ]);

    let mut block_counts = [0u32; 3];
    let decompressed = inflate(deflate_data, &mut block_counts);

    if adler32(&decompressed) != stored_adler {
        println!("error: Adler-32 mismatch");
        return;
    }

    // Apply filters
    let mut filtered: Vec<u8> = Vec::with_capacity(height * row_bytes);
    let mut filter_counts = [0u32; 5];
    let mut prev_row = vec![0u8; row_bytes];
    let mut cur_row = vec![0u8; row_bytes];
    let mut di = 0usize;
    for _y in 0..height {
        let ftype = decompressed[di] as usize;
        di += 1;
        filter_counts[ftype] += 1;
        for x in 0..row_bytes {
            let raw = decompressed[di + x] as i32;
            let a: i32 = if x >= bpp { cur_row[x - bpp] as i32 } else { 0 };
            let b: i32 = prev_row[x] as i32;
            let c: i32 = if x >= bpp { prev_row[x - bpp] as i32 } else { 0 };
            cur_row[x] = match ftype {
                0 => raw as u8,
                1 => ((raw + a) & 0xFF) as u8,
                2 => ((raw + b) & 0xFF) as u8,
                3 => ((raw + (a + b) / 2) & 0xFF) as u8,
                4 => ((raw + paeth_predictor(a, b, c) as i32) & 0xFF) as u8,
                _ => 0,
            };
        }
        di += row_bytes;
        filtered.extend_from_slice(&cur_row);
        prev_row.copy_from_slice(&cur_row);
    }

    // Convert to RGBA
    let total_pixels = width * height;
    let mut rgba: Vec<u8> = Vec::with_capacity(total_pixels * 4);

    let trns_gray: Option<u32> = if color_type == 0 && trns_data.len() >= 2 {
        Some(u16::from_be_bytes([trns_data[0], trns_data[1]]) as u32)
    } else { None };
    let trns_rgb: Option<(u32, u32, u32)> = if color_type == 2 && trns_data.len() >= 6 {
        Some((
            u16::from_be_bytes([trns_data[0], trns_data[1]]) as u32,
            u16::from_be_bytes([trns_data[2], trns_data[3]]) as u32,
            u16::from_be_bytes([trns_data[4], trns_data[5]]) as u32,
        ))
    } else { None };

    let gray_scale = (1u32 << bit_depth) - 1;

    for y in 0..height {
        for x in 0..width {
            let mut r: u8 = 0; let mut g: u8 = 0; let mut b: u8 = 0; let mut a: u8 = 255;
            match color_type {
                0 => {
                    let val = extract_sample(&filtered, y, x, 0, channels, row_bytes, bit_depth);
                    let gray8 = if bit_depth < 8 { (val * 255 / gray_scale) as u8 }
                                else if bit_depth == 8 { val as u8 }
                                else { (val >> 8) as u8 };
                    r = gray8; g = gray8; b = gray8;
                    if let Some(tv) = trns_gray { if val == tv { a = 0; } }
                }
                2 => {
                    let rv = extract_sample(&filtered, y, x, 0, channels, row_bytes, bit_depth);
                    let gv = extract_sample(&filtered, y, x, 1, channels, row_bytes, bit_depth);
                    let bv = extract_sample(&filtered, y, x, 2, channels, row_bytes, bit_depth);
                    r = if bit_depth == 16 { (rv >> 8) as u8 } else { rv as u8 };
                    g = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    b = if bit_depth == 16 { (bv >> 8) as u8 } else { bv as u8 };
                    if let Some((tr, tg, tb)) = trns_rgb {
                        if rv == tr && gv == tg && bv == tb { a = 0; }
                    }
                }
                3 => {
                    let idx = extract_sample(&filtered, y, x, 0, channels, row_bytes, bit_depth) as usize;
                    r = plte_data[idx * 3];
                    g = plte_data[idx * 3 + 1];
                    b = plte_data[idx * 3 + 2];
                    if idx < trns_data.len() { a = trns_data[idx]; }
                }
                4 => {
                    let gv = extract_sample(&filtered, y, x, 0, channels, row_bytes, bit_depth);
                    let av = extract_sample(&filtered, y, x, 1, channels, row_bytes, bit_depth);
                    let gray8 = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    r = gray8; g = gray8; b = gray8;
                    a = if bit_depth == 16 { (av >> 8) as u8 } else { av as u8 };
                }
                6 => {
                    let rv = extract_sample(&filtered, y, x, 0, channels, row_bytes, bit_depth);
                    let gv = extract_sample(&filtered, y, x, 1, channels, row_bytes, bit_depth);
                    let bv = extract_sample(&filtered, y, x, 2, channels, row_bytes, bit_depth);
                    let av = extract_sample(&filtered, y, x, 3, channels, row_bytes, bit_depth);
                    r = if bit_depth == 16 { (rv >> 8) as u8 } else { rv as u8 };
                    g = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    b = if bit_depth == 16 { (bv >> 8) as u8 } else { bv as u8 };
                    a = if bit_depth == 16 { (av >> 8) as u8 } else { av as u8 };
                }
                _ => {}
            }
            rgba.push(r); rgba.push(g); rgba.push(b); rgba.push(a);
        }
    }

    let mut sums = [0u64; 4];
    for i in 0..total_pixels {
        sums[0] += rgba[i*4] as u64;
        sums[1] += rgba[i*4+1] as u64;
        sums[2] += rgba[i*4+2] as u64;
        sums[3] += rgba[i*4+3] as u64;
    }
    let rgba_crc = crc32(&rgba);

    println!("IHDR {}x{} depth={} color={}", width, height, bit_depth, color_type);
    print!("chunks");
    let mut i = 0;
    while i < chunk_types.len() {
        let mut j = i + 1;
        while j < chunk_types.len() && chunk_types[j] == chunk_types[i] { j += 1; }
        let run = j - i;
        if run > 1 { print!(" {}*{}", chunk_types[i], run); }
        else { print!(" {}", chunk_types[i]); }
        i = j;
    }
    println!();
    println!("deflate stored={} fixed={} dynamic={}", block_counts[0], block_counts[1], block_counts[2]);
    println!("filters none={} sub={} up={} average={} paeth={}",
        filter_counts[0], filter_counts[1], filter_counts[2], filter_counts[3], filter_counts[4]);
    println!("rgba sum={},{},{},{} crc32={:08x}", sums[0], sums[1], sums[2], sums[3], rgba_crc);
}
