    } else { None };
    let trns_rgb: Option<(u32, u32, u32)> = if color_type == 2 && trns_data.len() >= 6 {
        Some((
            u16::from_be_bytes([trns_data[0], trns_data[1]]) as u32,
            u16::from_be_bytes([trns_data[2], trns_data[3]]) as u32,
            u16::from_be_bytes([trns_data[4], trns_data[5]]) as u32,
        ))
    } else { None };

    let gray_scale = (1u32 << bit_depth) - 1;

    for y in 0..height {
        let row_start = y * row_bytes;
        for x in 0..width {
            let mut r: u8 = 0;
            let mut g: u8 = 0;
            let mut b: u8 = 0;
            let mut a: u8 = 255;
            match color_type {
                0 => {
                    let val = extract_sample(&filtered, row_start, x, 0, num_channels, bit_depth);
                    let gray8 = if bit_depth < 8 {
                        (val * 255 / gray_scale) as u8
                    } else if bit_depth == 8 {
                        val as u8
                    } else {
                        (val >> 8) as u8
                    };
                    r = gray8; g = gray8; b = gray8;
                    if let Some(tv) = trns_gray {
                        if val == tv { a = 0; }
                    }
                }
                2 => {
                    let rv = extract_sample(&filtered, row_start, x, 0, num_channels, bit_depth);
                    let gv = extract_sample(&filtered, row_start, x, 1, num_channels, bit_depth);
                    let bv = extract_sample(&filtered, row_start, x, 2, num_channels, bit_depth);
                    r = if bit_depth == 16 { (rv >> 8) as u8 } else { rv as u8 };
                    g = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    b = if bit_depth == 16 { (bv >> 8) as u8 } else { bv as u8 };
                    if let Some((tr, tg, tb)) = trns_rgb {
                        if rv == tr && gv == tg && bv == tb { a = 0; }
                    }
                }
                3 => {
                    let idx = extract_sample(&filtered, row_start, x, 0, num_channels, bit_depth) as usize;
                    r = plte_data[idx * 3];
                    g = plte_data[idx * 3 + 1];
                    b = plte_data[idx * 3 + 2];
                    if idx < trns_data.len() { a = trns_data[idx]; }
                }
                4 => {
                    let gv = extract_sample(&filtered, row_start, x, 0, num_channels, bit_depth);
                    let av = extract_sample(&filtered, row_start, x, 1, num_channels, bit_depth);
                    let gray8 = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    r = gray8; g = gray8; b = gray8;
                    a = if bit_depth == 16 { (av >> 8) as u8 } else { av as u8 };
                }
                6 => {
                    let rv = extract_sample(&filtered, row_start, x, 0, num_channels, bit_depth);
                    let gv = extract_sample(&filtered, row_start, x, 1, num_channels, bit_depth);
                    let bv = extract_sample(&filtered, row_start, x, 2, num_channels, bit_depth);
                    let av = extract_sample(&filtered, row_start, x, 3, num_channels, bit_depth);
                    r = if bit_depth == 16 { (rv >> 8) as u8 } else { rv as u8 };
                    g = if bit_depth == 16 { (gv >> 8) as u8 } else { gv as u8 };
                    b = if bit_depth == 16 { (bv >> 8) as u8 } else { bv as u8 };
                    a = if bit_depth == 16 { (av >> 8) as u8 } else { av as u8 };
                }
                _ => {}
            }
            rgba.push(r); rgba.push(g); rgba.push(b); rgba.push(a);
        }
    }

    // Compute sums
    let mut sums = [0u64; 4];
    for i in 0..total_pixels {
        sums[0] += rgba[i*4] as u64;
        sums[1] += rgba[i*4+1] as u64;
        sums[2] += rgba[i*4+2] as u64;
        sums[3] += rgba[i*4+3] as u64;
    }
    let rgba_crc = crc32(&rgba);

    // Output
    println!("IHDR {}x{} depth={} color={}", width, height, bit_depth, color_type);
    print!("chunks");
    let mut i = 0;
    while i < chunk_types.len() {
        let mut j = i + 1;
        while j < chunk_types.len() && chunk_types[j] == chunk_types[i] { j += 1; }
        let run = j - i;
        if run > 1 {
            print!(" {}*{}", chunk_types[i], run);
        } else {
            print!(" {}", chunk_types[i]);
        }
        i = j;
    }
    println!();
    println!("deflate stored={} fixed={} dynamic={}", block_counts[0], block_counts[1], block_counts[2]);
    println!("filters none={} sub={} up={} average={} paeth={}",
        filter_counts[0], filter_counts[1], filter_counts[2], filter_counts[3], filter_counts[4]);
    println!("rgba sum={},{},{},{} crc32={:08x}", sums[0], sums[1], sums[2], sums[3], rgba_crc);
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let path = Path::new(dir);
    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(path).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.ends_with(".png") { files.push(name); }
    }
    files.sort();

    let mut first = true;
    for fname in &files {
        if !first { print!("\n"); }
        first = false;
        let fpath = path.join(fname);
        let data = fs::read(&fpath).unwrap();
        process_file(fname, &data);
    }
}

