fn covers(shape: &Shape, x: i64, y: i64) -> bool {
    match shape {
        Shape::Rect { x: rx, y: ry, w, h, .. } => {
            *rx <= x && x < *rx + *w && *ry <= y && y < *ry + *h
        }
        Shape::Circle { cx, cy, r, .. } => {
            let dx = x - *cx;
            let dy = y - *cy;
            dx * dx + dy * dy <= *r * *r
        }
        Shape::Triangle { points, .. } => {
            let (x0, y0) = points[0];
            let (x1, y1) = points[1];
            let (x2, y2) = points[2];
            let e0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0);
            let e1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1);
            let e2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2);
            (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
        }
        Shape::Line { x1, y1, x2, y2, r, .. } => {
            let dx = *x2 - *x1;
            let dy = *y2 - *y1;
            let l = dx * dx + dy * dy;
            let t = (x - *x1) * dx + (y - *y1) * dy;
            let r2 = *r * *r;
            if t <= 0 {
                let ddx = x - *x1;
                let ddy = y - *y1;
                ddx * ddx + ddy * ddy <= r2
            } else if t >= l {
                let ddx = x - *x2;
                let ddy = y - *y2;
                ddx * ddx + ddy * ddy <= r2
            } else {
                let c = (x - *x1) * dy - (y - *y1) * dx;
                c * c <= r2 * l
            }
        }
    }
}

fn blend(dst: &mut [u8], idx: usize, color: &[i64; 4]) {
    let a = color[3];
    if a == 0 { return; }
    let inv_a = 255 - a;
    for ch in 0..3 {
        let s = color[ch];
        let d = dst[idx + ch] as i64;
        dst[idx + ch] = ((s * a + d * inv_a + 127) / 255) as u8;
    }
}

