fn write_png(path: &str, width: usize, height: usize, pixels: &[u8]) {
    let row_size = 1 + width * 3;
    let raw_size = height * row_size;
    let mut raw = Vec::with_capacity(raw_size);
    for y in 0..height {
        raw.push(0u8); // filter None
        let row_start = y * width * 3;
        raw.extend_from_slice(&pixels[row_start..row_start + width * 3]);
    }

    // zlib stream
    let mut zlib = Vec::new();
    zlib.push(0x78u8); // CMF
    zlib.push(0x01u8); // FLG

    // stored deflate blocks
    let mut offset = 0usize;
    while offset < raw.len() {
        let remaining = raw.len() - offset;
        let block_size = if remaining > 65535 { 65535 } else { remaining };
        let is_last = (offset + block_size) >= raw.len();

        zlib.push(if is_last { 1u8 } else { 0u8 });
        zlib.push((block_size & 0xFF) as u8);
        zlib.push(((block_size >> 8) & 0xFF) as u8);
        let nlen = !(block_size as u16);
        zlib.push((nlen & 0xFF) as u8);
        zlib.push(((nlen >> 8) & 0xFF) as u8);
        zlib.extend_from_slice(&raw[offset..offset + block_size]);
        offset += block_size;
    }

    let adler = adler32(&raw);
    zlib.push((adler >> 24) as u8);
    zlib.push((adler >> 16) as u8);
    zlib.push((adler >> 8) as u8);
    zlib.push(adler as u8);

    let mut file = fs::File::create(path).unwrap();
    file.write_all(b"\x89PNG\r\n\x1a\n").unwrap();

    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&(width as u32).to_be_bytes());
    ihdr.extend_from_slice(&(height as u32).to_be_bytes());
    ihdr.push(8);  // bit depth
    ihdr.push(2);  // color type RGB
    ihdr.push(0);  // compression
    ihdr.push(0);  // filter
    ihdr.push(0);  // interlace
    write_chunk(&mut file, b"IHDR", &ihdr);

    write_chunk(&mut file, b"IDAT", &zlib);
    write_chunk(&mut file, b"IEND", &[]);
}

