function crc32(data: Buffer, start: number, len: number): number {
  let crc = 0xFFFFFFFF;
  for (let i = start; i < start + len; i++) {
    crc = CRC_TABLE[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function adler32(data: Buffer): number {
