function applyFilters(data: Buffer, width: number, height: number, bitDepth: number, channels: number): Buffer {
  const bitsPerPixel = bitDepth * channels;
  const scanlineBytes = Math.ceil(width * bitsPerPixel / 8);
  const bpp = Math.max(1, Math.ceil(bitsPerPixel / 8));

  const result = Buffer.alloc(height * scanlineBytes);

  for (let row = 0; row < height; row++) {
    const srcOffset = row * (scanlineBytes + 1);
    const filterType = data[srcOffset];
    const dstOffset = row * scanlineBytes;

    for (let x = 0; x < scanlineBytes; x++) {
      const filtVal = data[srcOffset + 1 + x];
      let rawVal = filtVal;

      const left = x >= bpp ? result[dstOffset + x - bpp] : 0;
      const up = row > 0 ? result[dstOffset - scanlineBytes + x] : 0;
      const upperLeft = (x >= bpp && row > 0) ? result[dstOffset - scanlineBytes + x - bpp] : 0;

      switch (filterType) {
        case 0: rawVal = filtVal; break;
        case 1: rawVal = (filtVal + left) & 0xFF; break;
        case 2: rawVal = (filtVal + up) & 0xFF; break;
        case 3: rawVal = (filtVal + Math.floor((left + up) / 2)) & 0xFF; break;
        case 4: rawVal = (filtVal + paethPredictor(left, up, upperLeft)) & 0xFF; break;
