        clLens[clOrder[i]] = br.readBits(3);
      }

      const clTree = buildHuffmanTree(clLens);

      const allLens = new Array(hlit + hdist).fill(0);
      let idx = 0;
      while (idx < hlit + hdist) {
        const sym = decodeSymbol(br, clTree);
        if (sym <= 15) {
          allLens[idx++] = sym;
        } else if (sym === 16) {
          const prev = allLens[idx - 1];
          const rep = br.readBits(2) + 3;
          for (let i = 0; i < rep; i++) allLens[idx++] = prev;
        } else if (sym === 17) {
          const rep = br.readBits(3) + 3;
          for (let i = 0; i < rep; i++) allLens[idx++] = 0;
        } else if (sym === 18) {
          const rep = br.readBits(7) + 11;
          for (let i = 0; i < rep; i++) allLens[idx++] = 0;
        }
      }

      const litLens = allLens.slice(0, hlit);
      const distLens = allLens.slice(hlit, hlit + hdist);

      const litTree = buildHuffmanTree(litLens);
      const distTree = buildHuffmanTree(distLens);
      decodeBlock(br, output, litTree, distTree);
    } else {
      // BTYPE 11 - reserved, shouldn't happen per problem statement
      break;
    }
  }

  return { output: Buffer.from(output), blockCounts };
}

function decodeBlock(br: BitReader, output: number[], litTree: HNode, distTree: HNode): void {
  while (true) {
    const sym = decodeSymbol(br, litTree);
    if (sym < 256) {
      output.push(sym);
    } else if (sym === 256) {
      break;
    } else {
      const li = sym - 257;
      let len = LENGTH_BASE[li];
      if (LENGTH_EXTRA[li] > 0) len += br.readBits(LENGTH_EXTRA[li]);

      const distSym = decodeSymbol(br, distTree);
      let d = DIST_BASE[distSym];
      if (DIST_EXTRA[distSym] > 0) d += br.readBits(DIST_EXTRA[distSym]);

      const start = output.length - d;
      for (let i = 0; i < len; i++) {
        output.push(output[start + i]);
      }
    }
  }
}

// Paeth predictor
function paethPredictor(a: number, b: number, c: number): number {
  const p = a + b - c;
  const pa = Math.abs(p - a);
  const pb = Math.abs(p - b);
  const pc = Math.abs(p - c);
  if (pa <= pb && pa <= pc) return a;
  if (pb <= pc) return b;
  return c;
}

// Apply PNG filters
function applyFilters(data: Buffer, width: number, height: number, bitDepth: number, channels: number): Buffer {
  const bitsPerPixel = bitDepth * channels;
  const scanlineBytes = Math.ceil(width * bitsPerPixel / 8);
  const bpp = Math.max(1, Math.ceil(bitsPerPixel / 8));

  const result = Buffer.alloc(height * scanlineBytes);

  for (let row = 0; row < height; row++) {
    const srcOffset = row * (scanlineBytes + 1);
    const filterType = data[srcOffset];
    const dstOffset = row * scanlineBytes;

    for (let x = 0; x < scanlineBytes; x++) {
      const filtVal = data[srcOffset + 1 + x];
      let rawVal = filtVal;

      const left = x >= bpp ? result[dstOffset + x - bpp] : 0;
      const up = row > 0 ? result[dstOffset - scanlineBytes + x] : 0;
      const upperLeft = (x >= bpp && row > 0) ? result[dstOffset - scanlineBytes + x - bpp] : 0;

      switch (filterType) {
        case 0: rawVal = filtVal; break;
        case 1: rawVal = (filtVal + left) & 0xFF; break;
        case 2: rawVal = (filtVal + up) & 0xFF; break;
        case 3: rawVal = (filtVal + Math.floor((left + up) / 2)) & 0xFF; break;
        case 4: rawVal = (filtVal + paethPredictor(left, up, upperLeft)) & 0xFF; break;
      }

      result[dstOffset + x] = rawVal;
    }
  }

  return result;
}

// Convert sample to 8-bit
function convertSample(v: number, bitDepth: number): number {
  if (bitDepth === 16) return v >> 8;
  if (bitDepth === 8) return v;
  // bitDepth 1, 2, 4
  return (v * 255) / ((1 << bitDepth) - 1);
}

// Extract pixel samples from filtered data
function extractSamples(data: Buffer, width: number, height: number, bitDepth: number, channels: number): number[][] {
  const bitsPerPixel = bitDepth * channels;
  const scanlineBytes = Math.ceil(width * bitsPerPixel / 8);
  const pixels: number[][] = [];

  for (let row = 0; row < height; row++) {
    const rowOffset = row * scanlineBytes;
    for (let col = 0; col < width; col++) {
      const samples: number[] = [];
      for (let ch = 0; ch < channels; ch++) {
        const bitPos = col * bitsPerPixel + ch * bitDepth;
        const bytePos = rowOffset + Math.floor(bitPos / 8);
        const bitOffset = bitPos % 8;

        let value: number;
        if (bitDepth === 16) {
          value = (data[bytePos] << 8) | data[bytePos + 1];
        } else {
          value = (data[bytePos] >> (8 - bitOffset - bitDepth)) & ((1 << bitDepth) - 1);
        }
        samples.push(value);
      }
      pixels.push(samples);
    }
  }

  return pixels;
}

// Convert pixel samples to RGBA
function toRGBA(samples: number[], colorType: number, bitDepth: number, plte: Buffer | null, trns: Buffer | null): [number, number, number, number] {
  let r = 0, g = 0, b = 0, a = 255;

  if (colorType === 0) {
    // Grayscale
    const gray = convertSample(samples[0], bitDepth);
    r = g = b = gray;
    if (trns && trns.length >= 2) {
      const trnsGray16 = (trns[0] << 8) | trns[1];
      const trnsGray = bitDepth < 16 ? (trnsGray16 >> (16 - bitDepth)) : trnsGray16;
      a = (samples[0] === trnsGray) ? 0 : 255;
    }
  } else if (colorType === 2) {
    // RGB
    r = convertSample(samples[0], bitDepth);
    g = convertSample(samples[1], bitDepth);
    b = convertSample(samples[2], bitDepth);
    if (trns && trns.length >= 6) {
      const trnsR16 = (trns[0] << 8) | trns[1];
      const trnsG16 = (trns[2] << 8) | trns[3];
      const trnsB16 = (trns[4] << 8) | trns[5];
      const trnsR = bitDepth < 16 ? (trnsR16 >> (16 - bitDepth)) : trnsR16;
      const trnsG = bitDepth < 16 ? (trnsG16 >> (16 - bitDepth)) : trnsG16;
      const trnsB = bitDepth < 16 ? (trnsB16 >> (16 - bitDepth)) : trnsB16;
      a = (samples[0] === trnsR && samples[1] === trnsG && samples[2] === trnsB) ? 0 : 255;
    }
  } else if (colorType === 3) {
    // Palette
    const idx = samples[0];
    if (plte) {
      r = plte[idx * 3];
      g = plte[idx * 3 + 1];
      b = plte[idx * 3 + 2];
    }
    if (trns && idx < trns.length) {
      a = trns[idx];
    } else {
      a = 255;
    }
  } else if (colorType === 4) {
    // Grayscale + Alpha
    const gray = convertSample(samples[0], bitDepth);
    r = g = b = gray;
    a = convertSample(samples[1], bitDepth);
  } else if (colorType === 6) {
    // RGBA
    r = convertSample(samples[0], bitDepth);
    g = convertSample(samples[1], bitDepth);
    b = convertSample(samples[2], bitDepth);
    a = convertSample(samples[3], bitDepth);
  }

  return [r, g, b, a];
}

function getChannels(colorType: number): number {
  switch (colorType) {
    case 0: return 1;
    case 2: return 3;
    case 3: return 1;
    case 4: return 2;
    case 6: return 4;
    default: return 1;
  }
}

function formatChunks(types: string[]): string {
  const parts: string[] = [];
  let i = 0;
  while (i < types.length) {
    let j = i;
    while (j < types.length && types[j] === types[i]) j++;
    const count = j - i;
    if (count > 1) {
      parts.push(`${types[i]}*${count}`);
    } else {
      parts.push(types[i]);
    }
    i = j;
  }
  return parts.join(' ');
}

function processFile(filePath: string, fileName: string): void {
  const fileData = fs.readFileSync(filePath);

  // Check PNG signature
  const sig = [137, 80, 78, 71, 13, 10, 26, 10];
  for (let i = 0; i < 8; i++) {
    if (fileData[i] !== sig[i]) {
      console.log(`== ${fileName}`);
      console.log(`error: invalid signature`);
      return;
    }
  }

  // Parse chunks
  let offset = 8;
  const chunkTypes: string[] = [];
  let width = 0, height = 0, bitDepth = 0, colorType = 0;
  let plteData: Buffer | null = null;
  let trnsData: Buffer | null = null;
  const idatChunks: Buffer[] = [];
  let crcError: { chunkNum: number; chunkType: string } | null = null;

  let chunkNum = 0;
  while (offset + 12 <= fileData.length) {
    const dataLen = fileData.readUInt32BE(offset);
    const chunkType = fileData.toString('ascii', offset + 4, offset + 8);
    const dataStart = offset + 8;
    const crcStored = fileData.readUInt32BE(offset + 8 + dataLen);

    // CRC over type + data
    const crcComputed = crc32(fileData, offset + 4, 4 + dataLen);

    chunkNum++;

    if (crcError === null && crcStored !== crcComputed) {
      crcError = { chunkNum, chunkType };
    }

    chunkTypes.push(chunkType);

    if (chunkType === 'IHDR') {
      width = fileData.readUInt32BE(dataStart);
      height = fileData.readUInt32BE(dataStart + 4);
      bitDepth = fileData[dataStart + 8];
      colorType = fileData[dataStart + 9];
    } else if (chunkType === 'PLTE') {
      plteData = fileData.slice(dataStart, dataStart + dataLen);
    } else if (chunkType === 'tRNS') {
      trnsData = fileData.slice(dataStart, dataStart + dataLen);
    } else if (chunkType === 'IDAT') {
      if (dataLen > 0) {
        idatChunks.push(fileData.slice(dataStart, dataStart + dataLen));
      }
    }

    offset += 12 + dataLen;

    if (chunkType === 'IEND') break;
  }

  // Output header
  console.log(`== ${fileName}`);

  // Check CRC error
  if (crcError !== null) {
    console.log(`error: CRC mismatch in chunk ${crcError.chunkNum} ${crcError.chunkType}`);
    return;
  }

  // Output IHDR
  console.log(`IHDR ${width}x${height} depth=${bitDepth} color=${colorType}`);

  // Output chunks
  console.log(`chunks ${formatChunks(chunkTypes)}`);

  // Decompress IDAT data
  const idatData = Buffer.concat(idatChunks);

  // zlib: 2-byte header + DEFLATE + 4-byte Adler-32
  if (idatData.length < 6) {
    console.log(`error: Adler-32 mismatch`);
    return;
  }

  const deflateData = idatData.slice(2, idatData.length - 4);
  const adlerStored = idatData.readUInt32BE(idatData.length - 4);

  const { output: decompressed, blockCounts } = inflate(deflateData);

  // Check Adler-32
  if (adler32(decompressed) !== adlerStored) {
    console.log(`error: Adler-32 mismatch`);
    return;
  }

  // Output deflate block counts
  console.log(`deflate stored=${blockCounts[0]} fixed=${blockCounts[1]} dynamic=${blockCounts[2]}`);

  // Apply filters
  const channels = getChannels(colorType);
  const bitsPerPixel = bitDepth * channels;
  const scanlineBytes = Math.ceil(width * bitsPerPixel / 8);
  const filteredData = applyFilters(decompressed, width, height, bitDepth, channels);

  // Count filter types
  const filterCounts = [0, 0, 0, 0, 0];
  for (let row = 0; row < height; row++) {
    const ft = decompressed[row * (scanlineBytes + 1)];
    filterCounts[ft]++;
  }
  console.log(`filters none=${filterCounts[0]} sub=${filterCounts[1]} up=${filterCounts[2]} average=${filterCounts[3]} paeth=${filterCounts[4]}`);

  // Extract pixels and convert to RGBA
  const pixels = extractSamples(filteredData, width, height, bitDepth, channels);

  const rgbaBuf = Buffer.alloc(width * height * 4);
  let sumR = 0, sumG = 0, sumB = 0, sumA = 0;

  for (let i = 0; i < pixels.length; i++) {
    const [r, g, b, a] = toRGBA(pixels[i], colorType, bitDepth, plteData, trnsData);
    rgbaBuf[i * 4] = r;
    rgbaBuf[i * 4 + 1] = g;
    rgbaBuf[i * 4 + 2] = b;
    rgbaBuf[i * 4 + 3] = a;
    sumR += r;
    sumG += g;
    sumB += b;
    sumA += a;
  }

  const rgbaCrc = crc32(rgbaBuf, 0, rgbaBuf.length);
  console.log(`rgba sum=${sumR},${sumG},${sumB},${sumA} crc32=${rgbaCrc.toString(16).padStart(8, '0')}`);
}

