            chunk = sock.recv(65536)
            if not chunk:
                break
            resp_body += chunk

    sock.close()
    return status_code, resp_headers, resp_body


def get_token(host, port, path_prefix, client_id, client_secret, scope):
    encoded_id = form_urlencode(client_id)
    encoded_secret = form_urlencode(client_secret)
    credentials = f"{encoded_id}:{encoded_secret}"
    auth_b64 = base64.b64encode(credentials.encode('utf-8')).decode('ascii')

    path = f"{path_prefix}/oauth/token"
    headers = {
        "Content-Type": "application/x-www-form-urlencoded",
        "Authorization": f"Basic {auth_b64}",
    }
    body = f"grant_type=client_credentials&scope={form_urlencode(scope)}"

    status, resp_headers, resp_body = http_request('POST', host, port, path, headers, body)

    if status != 200:
        return None, f"ERROR {status} {resp_body.decode('utf-8')}"

    data = json.loads(resp_body.decode('utf-8'))
    return data['access_token'], None


def parse_amount_to_cents(amount_str):
    negative = False
    if amount_str.startswith('-'):
        negative = True
        amount_str = amount_str[1:]

    if '.' in amount_str:
        int_part, dec_part = amount_str.split('.')
    else:
        int_part = amount_str
        dec_part = ''

    if len(dec_part) == 1:
        cents = int(dec_part) * 10
    elif len(dec_part) == 2:
        cents = int(dec_part)
    else:
        cents = 0

    total = int(int_part) * 100 + cents
    if negative:
        total = -total
    return total


def format_cents(cents):
    if cents < 0:
        return '-' + format_cents(-cents)
    integer_part = cents // 100
    frac_part = cents % 100
    return f"{integer_part}.{frac_part:02d}"


