import Foundation

// MARK: - Utility: form-urlencoded encoding (RFC 6749 §2.3.1 style)
func formEncode(_ s: String) -> String {
    var result = ""
    for b in s.utf8 {
        if (b >= 0x41 && b <= 0x5A) || (b >= 0x61 && b <= 0x7A) || (b >= 0x30 && b <= 0x39)
            || b == 0x2D || b == 0x2E || b == 0x5F || b == 0x2A {
            result.append(Character(UnicodeScalar(b)))
        } else if b == 0x20 {
            result.append("+")
        } else {
            result.append(String(format: "%%%02X", b))
        }
    }
    return result
}

// MARK: - Utility: percent-encode for URL query (unreserved = A-Za-z0-9-._~)
func percentEncode(_ s: String) -> String {
    var result = ""
    for b in s.utf8 {
        if (b >= 0x41 && b <= 0x5A) || (b >= 0x61 && b <= 0x7A) || (b >= 0x30 && b <= 0x39)
            || b == 0x2D || b == 0x2E || b == 0x5F || b == 0x7E {
            result.append(Character(UnicodeScalar(b)))
        } else {
            result.append(String(format: "%%%02X", b))
        }
    }
    return result
}

// MARK: - Utility: parse decimal amount string to cents (Int64)
func parseCents(_ s: String) -> Int64 {
    var negative = false
    var str = s
    if str.hasPrefix("-") {
        negative = true
        str = String(str.dropFirst())
    }
    var cents: Int64 = 0
    if let dotIdx = str.firstIndex(of: ".") {
        let intStr = String(str[str.startIndex..<dotIdx])
        let fracStr = String(str[str.index(after: dotIdx)...])
        let ip = Int64(intStr) ?? 0
        cents = ip * 100
        if fracStr.count == 1 {
            cents += (Int64(fracStr) ?? 0) * 10
        } else {
            cents += Int64(fracStr) ?? 0
        }
    } else {
        cents = (Int64(str) ?? 0) * 100
    }
    return negative ? -cents : cents
}

// MARK: - Utility: format cents to string
func formatCents(_ cents: Int64) -> String {
    let negative = cents < 0
    let absC = negative ? -cents : cents
    let intPart = absC / 100
    let fracPart = absC % 100
    let sign = negative ? "-" : ""
    return String(format: "%@%lld.%02lld", sign, intPart, fracPart)
}

// MARK: - Utility: UTF-8 byte-order comparison
func utf8Less(_ a: String, _ b: String) -> Bool {
    let ab = Array(a.utf8)
    let bb = Array(b.utf8)
    return ab.lexicographicallyPrecedes(bb)
