      'Host': hostname + (port !== 80 ? ':' + port : ''),
      'Connection': 'close',
      ...headers,
    };
    const req = http.request({
      hostname, port, path: reqPath, method, headers: allHeaders,
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        resolve({
          status: res.statusCode || 0,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

async function getToken(hostname: string, port: number, basePath: string, clientId: string, clientSecret: string, scope: string): Promise<string> {
  const credentials = formUrlEncode(clientId) + ':' + formUrlEncode(clientSecret);
  const b64 = Buffer.from(credentials, 'utf-8').toString('base64');
  const body = 'grant_type=client_credentials&scope=' + formUrlEncode(scope);

  const res = await httpReq('POST', hostname, port, basePath + '/oauth/token', {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Authorization': 'Basic ' + b64,
  }, body);

  if (res.status !== 200) {
    console.log(`ERROR ${res.status} ${res.body}`);
    process.exit(0);
  }

  const json = JSON.parse(res.body);
  return json.access_token;
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const client = JSON.parse(fs.readFileSync(path.join(dataDir, 'client.json'), 'utf-8'));
  const clientId: string = client.client_id;
  const clientSecret: string = client.client_secret;
  const scope: string = client.scope;
  const pageSize: number = client.page_size;

  const url = new URL(baseUrl);
  const hostname = url.hostname;
  const port = parseInt(url.port) || 80;
  const basePath = url.pathname;

  let accessToken = await getToken(hostname, port, basePath, clientId, clientSecret, scope);
  let tokenFresh = true;

  let cursor: string | null = null;
  const allOrders: any[] = [];
  let pages = 0;
  let retries = 0;
  let reauth = 0;

  while (true) {
    let reqPath = basePath + '/orders?limit=' + pageSize;
    if (cursor !== null) {
      reqPath += '&cursor=' + percentEncode(cursor);
    }

    const res = await httpReq('GET', hostname, port, reqPath, {
      'Authorization': 'Bearer ' + accessToken,
    });

    if (res.status === 429) {
      retries++;
      const retryAfter = parseInt(res.headers['retry-after'] as string);
      await sleep(retryAfter * 1000);
      continue;
    }

    if (res.status === 503) {
      retries++;
      await sleep(1000);
      continue;
    }

    if (res.status === 401) {
      if (tokenFresh) {
        console.log(`ERROR ${res.status} ${res.body}`);
        process.exit(0);
      }
      reauth++;
      accessToken = await getToken(hostname, port, basePath, clientId, clientSecret, scope);
      tokenFresh = true;
      continue;
    }

    if (res.status !== 200) {
      console.log(`ERROR ${res.status} ${res.body}`);
      process.exit(0);
    }

    tokenFresh = false;
    pages++;
    const json = JSON.parse(res.body);
    if (json.data && Array.isArray(json.data)) {
      for (const o of json.data) allOrders.push(o);
    }
    const nc = json.next_cursor;
    if (nc === null || nc === undefined) break;
    cursor = nc;
  }

  const totals = new Map<string, bigint>();
  const statusCounts = new Map<string, number>();

  for (const order of allOrders) {
    const status: string = order.status;
    statusCounts.set(status, (statusCounts.get(status) || 0) + 1);

    if (status !== 'cancelled') {
      const name: string = order.customer.name;
      const currency: string = order.currency;
      const cents = parseCents(order.amount);
      const key = currency + '\x00' + name;
      totals.set(key, (totals.get(key) || 0n) + cents);
    }
  }

  const totalEntries: { currency: string; name: string; cents: bigint }[] = [];
  for (const [key, cents] of totals) {
    const sep = key.indexOf('\x00');
    const currency = key.slice(0, sep);
    const name = key.slice(sep + 1);
    totalEntries.push({ currency, name, cents });
  }
  totalEntries.sort((a, b) => {
    const cmp = compareUtf8(a.name, b.name);
    if (cmp !== 0) return cmp;
    return a.currency < b.currency ? -1 : a.currency > b.currency ? 1 : 0;
  });

