    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  );

  for (const { currency, name, cents } of totalEntries) {
    console.log(`total ${currency} ${formatCents(cents)} ${name}`);
  }
  for (const [status, count] of statusEntries) {
    console.log(`status ${status} ${count}`);
  }
  console.log(`orders ${allOrders.length} pages ${pages} retries ${retries} reauth ${reauth}`);
}

