public class Main {

    static class FieldInfo {
        int number;
        String name, jsonName, type;
        boolean repeated, optional, isMap;
        String oneofName;
        String mapKeyType, mapValueType;
    }

    static class MessageInfo {
        String name;
        List<FieldInfo> fields = new ArrayList<>();
        Map<Integer, FieldInfo> byNum = new HashMap<>();
    }

    static class EnumInfo {
        String name;
        Map<Integer, String> byNum = new HashMap<>();
    }

    static Map<String, MessageInfo> msgs = new LinkedHashMap<>();
    static Map<String, EnumInfo> enms = new LinkedHashMap<>();
    static MessageInfo root;

    // ===== Proto Parser =====
    static class PP {
        String s; int p;
        PP(String s){this.s=s;p=0;}
        void ws(){
            while(p<s.length()){
                char c=s.charAt(p);
                if(c==' '||c=='\t'||c=='\n'||c=='\r'){p++;}
                else if(c=='/'&&p+1<s.length()){
                    if(s.charAt(p+1)=='/'){p+=2;while(p<s.length()&&s.charAt(p)!='\n')p++;}
                    else if(s.charAt(p+1)=='*'){p+=2;while(p+1<s.length()&&!(s.charAt(p)=='*'&&s.charAt(p+1)=='/'))p++;p+=2;}
                    else break;
                }else break;
            }
        }
        boolean more(){ws();return p<s.length();}
        char pk(){ws();return p<s.length()?s.charAt(p):'\0';}
        String id(){ws();int a=p;while(p<s.length()&&(Character.isLetterOrDigit(s.charAt(p))||s.charAt(p)=='_'||s.charAt(p)=='.'))p++;return s.substring(a,p);}
        void ex(char c){ws();if(p<s.length()&&s.charAt(p)==c)p++;}
        String str(){ws();ex('"');int a=p;while(p<s.length()&&s.charAt(p)!='"')p++;String r=s.substring(a,p);p++;return r;}
        long num(){ws();int a=p;if(p<s.length()&&(s.charAt(p)=='-'||s.charAt(p)=='+'))p++;while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;return Long.parseLong(s.substring(a,p));}
        void skipSemi(){while(p<s.length()){char c=s.charAt(p);if(c==';'){p++;return;}if(c=='"'){p++;while(p<s.length()&&s.charAt(p)!='"')p++;p++;}else p++;}}
        void skipOpt(){id();skipSemi();}
        void skipRes(){id();skipSemi();}
        void skipFOpt(){ws();if(p<s.length()&&s.charAt(p)=='['){p++;while(p<s.length()){ws();if(s.charAt(p)==']'){p++;return;}id();ws();if(p<s.length()&&s.charAt(p)=='=')p++;ws();if(p<s.length()&&s.charAt(p)=='"')str();else if(p<s.length()&&(s.charAt(p)=='-'||s.charAt(p)=='+'||Character.isDigit(s.charAt(p))))num();else id();ws();if(p<s.length()&&s.charAt(p)==',')p++;}}}
        String pkId(){ws();int a=p;while(p<s.length()&&(Character.isLetterOrDigit(s.charAt(p))||s.charAt(p)=='_'||s.charAt(p)=='.'))p++;String r=s.substring(a,p);p=a;return r;}
        void parseFile(){
            while(more()){
                String w=pkId();
                if(w.equals("syntax")||w.equals("package")||w.equals("option")||w.equals("import")){id();skipSemi();}
                else if(w.equals("message")){MessageInfo m=parseMsg();msgs.put(m.name,m);if(root==null)root=m;}
                else if(w.equals("enum")){parseEnum();}
                else p++;
            }
        }
        MessageInfo parseMsg(){
            id();String name=id();ex('{');
            MessageInfo m=new MessageInfo();m.name=name;
            while(more()){
                char c=pk();if(c=='}'){p++;break;}
                String w=pkId();
                if(w.equals("option"))skipOpt();
                else if(w.equals("reserved"))skipRes();
                else if(w.equals("message"))parseMsg();
                else if(w.equals("enum"))parseEnum();
                else if(w.equals("oneof"))parseOneof(m);
                else if(w.equals("map"))parseMap(m);
                else if(w.equals("repeated")||w.equals("optional")){String lb=id();FieldInfo f=parseFD();if(lb.equals("repeated"))f.repeated=true;else f.optional=true;m.fields.add(f);}
                else{FieldInfo f=parseFD();m.fields.add(f);}
            }
            m.fields.sort(Comparator.comparingInt(f->f.number));
            for(FieldInfo f:m.fields)m.byNum.put(f.number,f);
            return m;
        }
        void parseOneof(MessageInfo m){
            id();String on=id();ex('{');
            while(more()){char c=pk();if(c=='}'){p++;break;}FieldInfo f=parseFD();f.oneofName=on;m.fields.add(f);}
        }
        void parseMap(MessageInfo m){
            id();ex('<');String kt=id();ex(',');String vt=id();ex('>');
            String nm=id();ex('=');int n=(int)num();skipFOpt();ex(';');
            FieldInfo f=new FieldInfo();f.number=n;f.name=nm;f.jsonName=toCC(nm);f.isMap=true;f.mapKeyType=kt;f.mapValueType=vt;
            m.fields.add(f);
        }
        FieldInfo parseFD(){
            FieldInfo f=new FieldInfo();f.type=id();f.name=id();ex('=');f.number=(int)num();skipFOpt();ex(';');f.jsonName=toCC(f.name);return f;
        }
        void parseEnum(){
            id();String name=id();ex('{');
            EnumInfo e=new EnumInfo();e.name=name;
            while(more()){char c=pk();if(c=='}'){p++;break;}String w=pkId();
                if(w.equals("option"))skipOpt();else if(w.equals("reserved"))skipRes();
                else{String vn=id();ex('=');int v=(int)num();skipFOpt();ex(';');e.byNum.put(v,vn);}
            }
            enms.put(name,e);
        }
    }

    static String toCC(String n){
        StringBuilder sb=new StringBuilder();boolean up=false;
        for(int i=0;i<n.length();i++){char c=n.charAt(i);if(c=='_'){up=true;}else{if(up&&c>='a'&&c<='z')sb.append((char)(c-32));else sb.append(c);up=false;}}
        return sb.toString();
    }

    // ===== Binary Reader =====
    static class BR{
        byte[] d;int p;
        BR(byte[] d){this.d=d;p=0;}
        boolean more(){return p<d.length;}
        long rv(){long r=0;int s=0;while(p<d.length){byte b=d[p++];r|=((long)(b&0x7F))<<s;if((b&0x80)==0)break;s+=7;}return r;}
        int rf32(){int v=(d[p]&0xFF)|((d[p+1]&0xFF)<<8)|((d[p+2]&0xFF)<<16)|((d[p+3]&0xFF)<<24);p+=4;return v;}
        long rf64(){long v=0;for(int i=0;i<8;i++)v|=((long)(d[p+i]&0xFF))<<(i*8);p+=8;return v;}
        byte[] rb(int n){byte[] r=Arrays.copyOfRange(d,p,p+n);p+=n;return r;}
    }

    // ===== Decoded Message =====
    static class DM{
        Map<Integer,Object> vals=new LinkedHashMap<>();
        Set<Integer> occ=new HashSet<>();
        Map<String,Integer> oneofAct=new HashMap<>();
    }

    static boolean packable(String t){
        switch(t){case"int32":case"int64":case"uint32":case"uint64":case"sint32":case"sint64":case"bool":case"fixed32":case"fixed64":case"sfixed32":case"sfixed64":return true;}
        return enms.containsKey(t);
    }
    static boolean isMsg(String t){return msgs.containsKey(t);}
    static boolean isEnum(String t){return enms.containsKey(t);}

    static long zz32(long n){return(n>>>1)^-(n&1);}
    static long zz64(long n){return(n>>>1)^-(n&1);}

    static Object decVal(BR r,int wt,String t){
        long vi=0;int f3=0;long f6=0;byte[] bl=null;
        switch(wt){case 0:vi=r.rv();break;case 1:f6=r.rf64();break;case 2:bl=r.rb((int)r.rv());break;case 5:f3=r.rf32();break;}
        switch(t){
            case"int32":return(int)vi;
            case"int64":return vi;
            case"uint32":return vi&0xFFFFFFFFL;
            case"uint64":return vi;
            case"sint32":return(int)zz32(vi);
            case"sint64":return zz64(vi);
            case"bool":return vi!=0;
            case"fixed32":return Integer.toUnsignedLong(f3);
            case"sfixed32":return(long)f3;
            case"fixed64":return f6;
            case"sfixed64":return f6;
            case"string":return new String(bl,java.nio.charset.StandardCharsets.UTF_8);
            case"bytes":return bl;
            default:return(int)vi; // enum
        }
    }

    static Object decPackedElem(BR r,String t){
        switch(t){
            case"int32":return(int)r.rv();
            case"int64":return r.rv();
            case"uint32":return r.rv()&0xFFFFFFFFL;
            case"uint64":return r.rv();
            case"sint32":return(int)zz32(r.rv());
            case"sint64":return zz64(r.rv());
            case"bool":return r.rv()!=0;
            case"fixed32":return Integer.toUnsignedLong(r.rf32());
            case"sfixed32":return(long)r.rf32();
            case"fixed64":return r.rf64();
            case"sfixed64":return r.rf64();
            default:return(int)r.rv(); // enum
        }
    }

    static void skipUnk(BR r,int wt,int fn){
        switch(wt){
            case 0:r.rv();break;
            case 1:r.p+=8;break;
            case 2:{int l=(int)r.rv();r.p+=l;break;}
            case 5:r.p+=4;break;
            case 3:{// start group
                while(r.more()){long k=r.rv();int f2=(int)(k>>>3);int w2=(int)(k&7);if(w2==4&&f2==fn)return;skipUnk(r,w2,f2);}
                break;
            }
            case 4:break;
        }
    }

    @SuppressWarnings("unchecked")
    static List<Object> getList(DM m,int n){
        Object o=m.vals.get(n);
        if(o==null){o=new ArrayList<>();m.vals.put(n,o);}
        return(List<Object>)o;
    }

    @SuppressWarnings("unchecked")
    static LinkedHashMap<Object,Object> getMap(DM m,int n){
        Object o=m.vals.get(n);
        if(o==null){o=new LinkedHashMap<>();m.vals.put(n,o);}
        return(LinkedHashMap<Object,Object>)o;
    }

    static void mergeDM(DM tgt,DM src,MessageInfo sch){
        for(Map.Entry<Integer,Object> e:src.vals.entrySet()){
            int n=e.getKey();Object v=e.getValue();
            FieldInfo fi=sch.byNum.get(n);if(fi==null)continue;
            tgt.occ.add(n);
            if(fi.repeated){
                List<Object> tl=getList(tgt,n);
                List<Object> sl=(List<Object>)v;
                tl.addAll(sl);
            }else if(fi.isMap){
                LinkedHashMap<Object,Object> tm=getMap(tgt,n);
                LinkedHashMap<Object,Object> sm=(LinkedHashMap<Object,Object>)v;
                tm.putAll(sm);
            }else if(fi.oneofName!=null){
                Integer act=tgt.oneofAct.get(fi.oneofName);
                if(act!=null&&act==n){
                    if(isMsg(fi.type)){
                        DM ex=(DM)tgt.vals.get(n);
                        MessageInfo sub=msgs.get(fi.type);
                        if(ex!=null&&sub!=null)mergeDM(ex,(DM)v,sub);
                    }else tgt.vals.put(n,v);
                }else{
                    if(act!=null){tgt.vals.remove(act);tgt.occ.remove(act);}
                    tgt.oneofAct.put(fi.oneofName,n);
                    tgt.vals.put(n,v);
                }
            }else if(isMsg(fi.type)){
                if(tgt.vals.containsKey(n)){
                    DM ex=(DM)tgt.vals.get(n);
                    MessageInfo sub=msgs.get(fi.type);
                    if(ex!=null&&sub!=null)mergeDM(ex,(DM)v,sub);
                }else tgt.vals.put(n,v);
            }else{
                tgt.vals.put(n,v);
            }
        }
    }

    @SuppressWarnings("unchecked")
    static void decMapEntry(DM m,FieldInfo fi,byte[] data){
        BR r=new BR(data);
        Object key=null,val=null;
        while(r.more()){
            long k=r.rv();int fn=(int)(k>>>3);int wt=(int)(k&7);
            if(fn==1){key=decVal(r,wt,fi.mapKeyType);}
            else if(fn==2){val=decVal(r,wt,fi.mapValueType);}
            else skipUnk(r,wt,fn);
        }
        if(key==null)key=fi.mapKeyType.equals("string")?"":0;
        if(val==null){
            if(isMsg(fi.mapValueType))val=new DM();
            else if(isEnum(fi.mapValueType))val=0;
            else val=defaultScalar(fi.mapValueType);
        }
        LinkedHashMap<Object,Object> mp=getMap(m,fi.number);
        mp.put(key,val);
        m.occ.add(fi.number);
    }

    static Object defaultScalar(String t){
        switch(t){
            case"int32":case"sint32":case"sfixed32":return 0;
            case"uint32":case"fixed32":return 0L;
            case"int64":case"sint64":case"sfixed64":return 0L;
            case"uint64":case"fixed64":return 0L;
            case"bool":return false;
            case"string":return "";
            case"bytes":return new byte[0];
            default:return 0;// enum
        }
    }

    static DM decodeMsg(byte[] data,MessageInfo sch){
        DM m=new DM();BR r=new BR(data);
        while(r.more()){
            long key=r.rv();int fn=(int)(key>>>3);int wt=(int)(key&7);
            FieldInfo fi=sch.byNum.get(fn);
            if(fi==null){skipUnk(r,wt,fn);continue;}
            if(fi.isMap){
                byte[] ed=r.rb((int)r.rv());
                decMapEntry(m,fi,ed);
            }else if(fi.repeated&&packable(fi.type)&&wt==2){
                byte[] pd=r.rb((int)r.rv());BR pr=new BR(pd);
                List<Object> lst=getList(m,fn);
                while(pr.more())lst.add(decPackedElem(pr,fi.type));
                m.occ.add(fn);
            }else if(fi.repeated){
                Object v=decVal(r,wt,fi.type);
                getList(m,fn).add(v);
                m.occ.add(fn);
            }else if(fi.oneofName!=null){
                Object v;
                if(isMsg(fi.type)){byte[] sd=r.rb((int)r.rv());v=decodeMsg(sd,msgs.get(fi.type));}
                else v=decVal(r,wt,fi.type);
                Integer act=m.oneofAct.get(fi.oneofName);
                if(act!=null&&act==fn){
                    if(isMsg(fi.type)){DM ex=(DM)m.vals.get(fn);MessageInfo sub=msgs.get(fi.type);if(ex!=null&&sub!=null)mergeDM(ex,(DM)v,sub);}
                    else m.vals.put(fn,v);
                }else{
                    if(act!=null){m.vals.remove(act);m.occ.remove(act);}
                    m.oneofAct.put(fi.oneofName,fn);
                    m.vals.put(fn,v);
                }
                m.occ.add(fn);
            }else if(isMsg(fi.type)){
                byte[] sd=r.rb((int)r.rv());
                DM sub=decodeMsg(sd,msgs.get(fi.type));
                if(m.occ.contains(fn)){DM ex=(DM)m.vals.get(fn);if(ex!=null)mergeDM(ex,sub,msgs.get(fi.type));}
                else m.vals.put(fn,sub);
                m.occ.add(fn);
            }else{
                Object v=decVal(r,wt,fi.type);
                m.vals.put(fn,v);
                m.occ.add(fn);
            }
        }
        return m;
    }

    // ===== JSON Output =====
    static boolean isDefault(Object v,String type){
        if(v==null)return true;
        switch(type){
            case"int32":case"sint32":case"sfixed32":return((Integer)v)==0;
            case"uint32":case"fixed32":return((Long)v)==0L;
            case"int64":case"sint64":case"sfixed64":return((Long)v)==0L;
            case"uint64":case"fixed64":return((Long)v)==0L;
            case"bool":return!((Boolean)v);
            case"string":return((String)v).isEmpty();
            case"bytes":return((byte[])v).length==0;
            default:return((Integer)v)==0;// enum
        }
    }

    static void escStr(StringBuilder sb,String s){
        sb.append('"');
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(c=='"')sb.append("\\\"");
            else if(c=='\\')sb.append("\\\\");
            else if(c=='\b')sb.append("\\b");
            else if(c=='\t')sb.append("\\t");
            else if(c=='\n')sb.append("\\n");
            else if(c=='\f')sb.append("\\f");
            else if(c=='\r')sb.append("\\r");
            else if(c<0x20)sb.append(String.format("\\u%04x",(int)c));
            else sb.append(c);
        }
        sb.append('"');
    }

    static void emitVal(StringBuilder sb,Object v,String type){
        if(v==null){sb.append("null");return;}
        switch(type){
            case"int32":case"sint32":case"sfixed32":sb.append(((Integer)v).intValue());break;
            case"uint32":case"fixed32":sb.append(((Long)v).longValue());break;
            case"int64":case"sint64":case"sfixed64":sb.append('"').append(((Long)v).longValue()).append('"');break;
            case"uint64":case"fixed64":sb.append('"').append(Long.toUnsignedString(((Long)v).longValue())).append('"');break;
            case"bool":sb.append(((Boolean)v)?"true":"false");break;
            case"string":escStr(sb,(String)v);break;
            case"bytes":sb.append('"').append(java.util.Base64.getEncoder().encodeToString((byte[])v)).append('"');break;
            default:
                if(isMsg(type)){emitMsg(sb,(DM)v,msgs.get(type));}
                else if(isEnum(type)){
                    EnumInfo ei=enms.get(type);int iv=((Integer)v).intValue();
                    String nm=ei.byNum.get(iv);
                    if(nm!=null)escStr(sb,nm);else sb.append(iv);
                }else sb.append("null");
        }
    }

    @SuppressWarnings("unchecked")
    static void emitMsg(StringBuilder sb,DM m,MessageInfo sch){
        sb.append('{');boolean first=true;
        for(FieldInfo fi:sch.fields){
            boolean emit=false;
            if(fi.isMap){
                LinkedHashMap<Object,Object> mp=(LinkedHashMap<Object,Object>)m.vals.get(fi.number);
                if(mp!=null&&!mp.isEmpty())emit=true;
            }else if(fi.repeated){
                List<Object> lst=(List<Object>)m.vals.get(fi.number);
                if(lst!=null&&!lst.isEmpty())emit=true;
            }else if(fi.oneofName!=null){
                Integer act=m.oneofAct.get(fi.oneofName);
                if(act!=null&&act==fi.number)emit=true;
            }else if(isMsg(fi.type)){
                if(m.occ.contains(fi.number))emit=true;
            }else{
                if(m.occ.contains(fi.number)){
                    Object v=m.vals.get(fi.number);
                    if(fi.optional||!isDefault(v,fi.type))emit=true;
                }
            }
            if(!emit)continue;
            if(!first)sb.append(',');first=false;
            escStr(sb,fi.jsonName);sb.append(':');
            Object v=m.vals.get(fi.number);
            if(fi.isMap){
                LinkedHashMap<Object,Object> mp=(LinkedHashMap<Object,Object>)v;
                emitMap(sb,mp,fi);
            }else if(fi.repeated){
                List<Object> lst=(List<Object>)v;
                sb.append('[');
                for(int i=0;i<lst.size();i++){if(i>0)sb.append(',');emitVal(sb,lst.get(i),fi.type);}
                sb.append(']');
            }else{
                emitVal(sb,v,fi.type);
            }
        }
        sb.append('}');
    }

    @SuppressWarnings("unchecked")
    static void emitMap(StringBuilder sb,LinkedHashMap<Object,Object> mp,FieldInfo fi){
        sb.append('{');
        List<Map.Entry<Object,Object>> entries=new ArrayList<>(mp.entrySet());
        if(fi.mapKeyType.equals("string")){
            entries.sort((a,b)->{
                byte[] ba=((String)a.getKey()).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                byte[] bb=((String)b.getKey()).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                int len=Math.min(ba.length,bb.length);
                for(int i=0;i<len;i++){int d=(ba[i]&0xFF)-(bb[i]&0xFF);if(d!=0)return d;}
                return ba.length-bb.length;
            });
        }else{
            entries.sort((a,b)->Long.compare(((Number)a.getKey()).longValue(),((Number)b.getKey()).longValue()));
        }
        boolean first=true;
        for(Map.Entry<Object,Object> e:entries){
            if(!first)sb.append(',');first=false;
            if(fi.mapKeyType.equals("string"))escStr(sb,(String)e.getKey());
            else sb.append('"').append(((Number)e.getKey()).longValue()).append('"');
            sb.append(':');
            emitVal(sb,e.getValue(),fi.mapValueType);
        }
        sb.append('}');
    }

    // ===== Main =====
    public static void main(String[] args)throws Exception{
        String dir=args[0];
        String proto=new String(Files.readAllBytes(Paths.get(dir,"schema.proto")),java.nio.charset.StandardCharsets.UTF_8);
        byte[] bin=Files.readAllBytes(Paths.get(dir,"messages.bin"));
        PP pp=new PP(proto);pp.parseFile();
        BR br=new BR(bin);
        StringBuilder out=new StringBuilder();
        while(br.more()){
            int len=(int)br.rv();
            byte[] md=Arrays.copyOfRange(br.d,br.p,br.p+len);br.p+=len;
            DM dm=decodeMsg(md,root);
            emitMsg(out,dm,root);out.append('\n');
        }
        System.out.print(out.toString());
    }
}
