// ==================== TOKENIZER ====================

interface Token {
  type: 'ident' | 'number' | 'string' | 'punct';
  value: string;
}

function tokenize(text: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') { i++; continue; }
    if (c === '/' && i + 1 < text.length && text[i + 1] === '/') {
      i += 2;
      while (i < text.length && text[i] !== '\n') i++;
      continue;
    }
    if (c === '/' && i + 1 < text.length && text[i + 1] === '*') {
      i += 2;
      while (i + 1 < text.length && !(text[i] === '*' && text[i + 1] === '/')) i++;
      i += 2;
      continue;
    }
    if (c === '"') {
      i++;
      let s = '';
      while (i < text.length && text[i] !== '"') { s += text[i]; i++; }
      if (i < text.length) i++;
      tokens.push({ type: 'string', value: s });
      continue;
    }
    if (/[a-zA-Z_]/.test(c)) {
      let s = '';
      while (i < text.length && /[a-zA-Z0-9_]/.test(text[i])) { s += text[i]; i++; }
      tokens.push({ type: 'ident', value: s });
      continue;
    }
    if (/[0-9]/.test(c) || (c === '-' && i + 1 < text.length && /[0-9]/.test(text[i + 1]))) {
      let s = '';
      if (c === '-') { s += '-'; i++; }
      while (i < text.length && /[0-9]/.test(text[i])) { s += text[i]; i++; }
      tokens.push({ type: 'number', value: s });
      continue;
    }
    tokens.push({ type: 'punct', value: c });
    i++;
  }
  return tokens;
}

