class ProtoParser {
  tokens: Token[];
  pos: number;
  messages: Map<string, MessageDef> = new Map();
  enums: Map<string, EnumDef> = new Map();
  rootMessage: string = '';

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  peek(): Token | null {
    return this.pos < this.tokens.length ? this.tokens[this.pos] : null;
  }

  peekAt(n: number): Token | null {
    return this.pos + n < this.tokens.length ? this.tokens[this.pos + n] : null;
  }

  next(): Token {
    return this.tokens[this.pos++];
  }

  expect(value: string): void {
    const t = this.next();
    if (!t || t.value !== value) throw new Error(`Expected '${value}', got '${t?.value}' at ${this.pos}`);
  }

  skipToSemicolon(): void {
    while (this.pos < this.tokens.length && this.tokens[this.pos].value !== ';') this.pos++;
    if (this.pos < this.tokens.length) this.pos++;
  }

  skipFieldOptions(): void {
    if (this.peek()?.value === '[') {
      let depth = 1;
      this.pos++;
      while (this.pos < this.tokens.length && depth > 0) {
        if (this.tokens[this.pos].value === '[') depth++;
        else if (this.tokens[this.pos].value === ']') depth--;
        this.pos++;
