    while (this.pos < this.tokens.length) {
      const t = this.peek();
      if (!t) break;
      if (t.value === 'syntax') { this.skipToSemicolon(); }
      else if (t.value === 'package') { this.skipToSemicolon(); }
      else if (t.value === 'option') { this.skipToSemicolon(); }
      else if (t.value === 'message') { this.parseMessage(); }
      else if (t.value === 'enum') { this.parseEnum(); }
      else { this.pos++; }
    }
  }

  parseMessage(): void {
    this.expect('message');
    const name = this.next().value;
    if (!this.rootMessage) this.rootMessage = name;
    const msg: MessageDef = { name, fields: new Map() };
    this.messages.set(name, msg);
    this.expect('{');
