class Reader {
  buf: Buffer; pos: number;
  constructor(buf: Buffer) { this.buf = buf; this.pos = 0; }
  eof(): boolean { return this.pos >= this.buf.length; }
  readVarint(): bigint {
    let result = 0n; let shift = 0n;
    for (let i = 0; i < 10; i++) {
      const b = this.buf[this.pos++];
      result |= BigInt(b & 0x7F) << shift;
      if ((b & 0x80) === 0) return result;
      shift += 7n;
    }
    return result;
  }
  readVarintBytes(): bigint {
    let result = 0n; let shift = 0n;
    for (let i = 0; i < 10; i++) {
      const b = this.buf[this.pos++];
      result |= BigInt(b & 0x7F) << shift;
      if ((b & 0x80) === 0) return result;
      shift += 7n;
    }
    return result;
  }
  readFixed32(): number { const v = this.buf.readUInt32LE(this.pos); this.pos += 4; return v; }
  readFixed64(): bigint { const v = this.buf.readBigUInt64LE(this.pos); this.pos += 8; return v; }
  readLengthDelimited(): Buffer {
    const len = Number(this.readVarint());
    const v = this.buf.subarray(this.pos, this.pos + len);
    this.pos += len;
    return v;
  }
  skipField(wireType: number) {
    if (wireType === 0) { this.readVarint(); }
    else if (wireType === 1) { this.pos += 8; }
    else if (wireType === 2) { const len = Number(this.readVarint()); this.pos += len; }
    else if (wireType === 5) { this.pos += 4; }
    else if (wireType === 3 || wireType === 4) { /* handled externally */ }
  }
  skipGroup(fnum: number) {
    while (!this.eof()) {
      const key = Number(this.readVarint());
      const fn = key >>> 3; const wt = key & 7;
      if (fn === fnum && wt === 4) return;
      if (wt === 3) { this.skipGroup(fn); }
      else { this.skipField(wt); }
    }
  }
}

function decodeScalar(reader: Reader, wireType: number, type: string, enums: Map<string, EnumDef>): any {
