}

function isDefaultScalar(type: string, value: any, enums: Map<string, EnumDef>): boolean {
  if (type === 'string') return value === '';
  if (type === 'bytes') return (value as Buffer).length === 0;
  if (type === 'bool') return value === false;
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return value === '0';
  if (enums.has(type)) return value === 0;
  return value === 0;
