function serializeValue(value: any, type: string, messages: Map<string, MessageDef>, enums: Map<string, EnumDef>): string {
  if (type === 'string') return '"' + escapeJsonString(value) + '"';
  if (type === 'bytes') return '"' + (value as Buffer).toString('base64') + '"';
  if (type === 'bool') return value ? 'true' : 'false';
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return '"' + value + '"';
  if (type === 'int32' || type === 'uint32' || type === 'sint32' || type === 'fixed32' || type === 'sfixed32') return String(value);
