    const en = enums.get(type)!;
    const name = en.values.get(value);
    if (name !== undefined) return '"' + escapeJsonString(name) + '"';
    return String(value);
  }
  // message type
  return serializeMessage(value as DecodedMsg, messages.get(type)!, messages, enums);
}

function serializeMessage(msg: DecodedMsg, msgDef: MessageDef, messages: Map<string, MessageDef>, enums: Map<string, EnumDef>): string {
  const parts: string[] = [];
