        const bb = Buffer.from(b[0] as string, 'utf8');
        const minLen = Math.min(ba.length, bb.length);
        for (let i = 0; i < minLen; i++) { if (ba[i] !== bb[i]) return ba[i] - bb[i]; }
        return ba.length - bb.length;
      });
