}

enum TypeRef {
    case scalar(ScalarType)
    case named(String)
    case map(key: ScalarType, value: TypeRef)
}

enum FieldLabel { case singular, repeated, optional }

struct FieldDef {
    let name: String
    let number: Int
    let type: TypeRef
    let label: FieldLabel
    let oneofName: String?
}

struct MessageDef {
    let name: String
    var fields: [FieldDef] = []
    var oneofs: [String: [Int]] = [:]
}

struct EnumDef {
    let name: String
    var values: [Int: String] = [:]
}

var messages: [String: MessageDef] = [:]
var enums: [String: EnumDef] = [:]
var rootTypeName: String = ""

// MARK: - Proto Parser

func removeComments(_ src: [Character]) -> [Character] {
    var out: [Character] = []
    var i = 0
    while i < src.count {
        if i + 1 < src.count && src[i] == "/" && src[i+1] == "/" {
            while i < src.count && src[i] != "\n" { i += 1 }
        } else if i + 1 < src.count && src[i] == "/" && src[i+1] == "*" {
            i += 2
            while i + 1 < src.count && !(src[i] == "*" && src[i+1] == "/") { i += 1 }
            if i + 1 < src.count { i += 2 }
        } else {
            out.append(src[i])
            i += 1
        }
    }
    return out
}

enum Tok: Equatable {
    case ident(String)
    case int(Int)
    case str(String)
    case punct(Character)
    case eof
}

func tokenize(_ src: [Character]) -> [Tok] {
    var toks: [Tok] = []
    var i = 0
    while i < src.count {
        let c = src[i]
        if c == " " || c == "\t" || c == "\n" || c == "\r" {
            i += 1
        } else if c == "\"" {
            i += 1
            var s = ""
            while i < src.count && src[i] != "\"" {
                if src[i] == "\\" {
                    i += 1
                    if i < src.count {
                        let e = src[i]
                        switch e {
                        case "n": s.append("\n")
                        case "t": s.append("\t")
                        case "r": s.append("\r")
                        case "\\": s.append("\\")
                        case "\"": s.append("\"")
                        default: s.append(e)
                        }
                        i += 1
                    }
                } else {
                    s.append(src[i])
                    i += 1
                }
            }
            if i < src.count { i += 1 }
            toks.append(.str(s))
        } else if c.isLetter || c == "_" {
            var s = ""
            while i < src.count && (src[i].isLetter || src[i].isNumber || src[i] == "_") {
                s.append(src[i]); i += 1
            }
            toks.append(.ident(s))
        } else if c.isNumber {
            var s = ""
            while i < src.count && src[i].isNumber {
                s.append(src[i]); i += 1
            }
            toks.append(.int(Int(s) ?? 0))
        } else {
            toks.append(.punct(c)); i += 1
        }
    }
    toks.append(.eof)
    return toks
}

struct ProtoParser {
    let toks: [Tok]
    var pos: Int = 0
    var topLevelMessages: [String] = []

    func peek() -> Tok { toks[pos] }
    func advance() -> Tok { let t = toks[pos]; pos += 1; return t }
    func expect(_ t: Tok) { if peek() != t { fatalError("Expected \(t) got \(peek())") }; pos += 1 }
    func match(_ t: Tok) -> Bool { if peek() == t { pos += 1; return true }; return false }

    func parseFile() {
        while peek() != .eof {
            if case .ident(let kw) = peek() {
                switch kw {
                case "syntax": skipToSemi()
                case "package": skipToSemi()
                case "import": skipToSemi()
                case "option": skipToSemi()
                case "message": parseMessage(topLevel: true)
                case "enum": parseEnum()
                default: pos += 1
                }
            } else { pos += 1 }
        }
    }

    func skipToSemi() {
        while pos < toks.count && peek() != .punct(";") && peek() != .eof { pos += 1 }
        if peek() == .punct(";") { pos += 1 }
    }

    func skipBrackets() {
        // skip [...] options
        if peek() == .punct("[") {
            var depth = 1; pos += 1
            while depth > 0 && peek() != .eof {
                if peek() == .punct("[") { depth += 1 }
                else if peek() == .punct("]") { depth -= 1 }
                pos += 1
            }
        }
    }

    func parseMessage(topLevel: Bool) {
        expect(.ident("message"))
        guard case .ident(let name) = advance() else { fatalError("msg name") }
        var def = MessageDef(name: name)
        expect(.punct("{"))
        while peek() != .punct("}") && peek() != .eof {
            if case .ident(let kw) = peek() {
                switch kw {
                case "message": parseMessage(topLevel: false)
                case "enum": parseEnum()
                case "oneof": parseOneof(into: &def)
                case "reserved": skipToSemi()
                case "option": skipToSemi()
                default: parseField(into: &def, oneofName: nil, label: .singular)
                }
            } else if peek() == .punct(";") { pos += 1 }
            else { pos += 1 }
        }
        if peek() == .punct("}") { pos += 1 }
        messages[name] = def
        if topLevel { topLevelMessages.append(name) }
    }

    func parseOneof(into def: inout MessageDef) {
        expect(.ident("oneof"))
        guard case .ident(let oName) = advance() else { fatalError("oneof name") }
        expect(.punct("{"))
        var fieldNums: [Int] = []
        while peek() != .punct("}") && peek() != .eof {
            if case .ident(let kw) = peek(), kw == "option" { skipToSemi(); continue }
            let f = parseFieldRaw(oneofName: oName, label: .singular)
            def.fields.append(f)
            fieldNums.append(f.number)
        }
        if peek() == .punct("}") { pos += 1 }
        def.oneofs[oName] = fieldNums
    }

    func parseFieldRaw(oneofName: String?, label: FieldLabel) -> FieldDef {
        let type = parseType()
        guard case .ident(let fname) = advance() else { fatalError("field name") }
        expect(.punct("="))
        var num = 0
        if peek() == .punct("-") { pos += 1; if case .int(let n) = advance() { num = -n } }
        else if case .int(let n) = advance() { num = n }
        skipBrackets()
        if peek() == .punct(";") { pos += 1 }
        return FieldDef(name: fname, number: num, type: type, label: label, oneofName: oneofName)
    }

    func parseField(into def: inout MessageDef, oneofName: String?, label: FieldLabel) {
        var lbl = label
        if case .ident(let kw) = peek() {
            if kw == "repeated" { lbl = .repeated; pos += 1 }
            else if kw == "optional" { lbl = .optional; pos += 1 }
        }
        let f = parseFieldRaw(oneofName: oneofName, label: lbl)
        def.fields.append(f)
    }

    func parseType() -> TypeRef {
        if case .ident(let id) = peek() {
            switch id {
            case "int32": pos += 1; return .scalar(.int32)
            case "int64": pos += 1; return .scalar(.int64)
            case "uint32": pos += 1; return .scalar(.uint32)
            case "uint64": pos += 1; return .scalar(.uint64)
            case "sint32": pos += 1; return .scalar(.sint32)
            case "sint64": pos += 1; return .scalar(.sint64)
            case "bool": pos += 1; return .scalar(.bool)
            case "string": pos += 1; return .scalar(.string)
            case "bytes": pos += 1; return .scalar(.bytes)
            case "fixed32": pos += 1; return .scalar(.fixed32)
            case "fixed64": pos += 1; return .scalar(.fixed64)
            case "sfixed32": pos += 1; return .scalar(.sfixed32)
            case "sfixed64": pos += 1; return .scalar(.sfixed64)
            case "map":
                pos += 1
                expect(.punct("<"))
                let kt = parseType()
                expect(.punct(","))
                let vt = parseType()
                expect(.punct(">"))
                let kScalar: ScalarType
                if case .scalar(let s) = kt { kScalar = s } else { kScalar = .string }
                return .map(key: kScalar, value: vt)
            default:
                pos += 1
                return .named(id)
            }
        }
        pos += 1
        return .scalar(.string)
    }

    func parseEnum() {
        expect(.ident("enum"))
        guard case .ident(let name) = advance() else { fatalError("enum name") }
        var def = EnumDef(name: name)
        expect(.punct("{"))
        while peek() != .punct("}") && peek() != .eof {
            if case .ident(let kw) = peek(), kw == "option" { skipToSemi(); continue }
            if case .ident(let vname) = peek() {
                pos += 1
                expect(.punct("="))
                var v = 0
                if peek() == .punct("-") { pos += 1; if case .int(let n) = advance() { v = -n } }
                else if case .int(let n) = advance() { v = n }
                skipBrackets()
                def.values[v] = vname
            } else { pos += 1 }
            if peek() == .punct(";") { pos += 1 }
        }
        if peek() == .punct("}") { pos += 1 }
        enums[name] = def
    }
}

// MARK: - Wire Format

func readVarint(_ data: Data, _ off: inout Int) -> UInt64 {
    var result: UInt64 = 0
    var shift: UInt64 = 0
    for _ in 0..<10 {
        if off >= data.count { break }
        let b = data[data.startIndex + off]
        off += 1
        result |= UInt64(b & 0x7F) << shift
        if b & 0x80 == 0 { break }
        shift += 7
    }
    return result
}

func readFixed32(_ data: Data, _ off: inout Int) -> UInt32 {
    var v: UInt32 = 0
    for i in 0..<4 {
        if off < data.count { v |= UInt32(data[data.startIndex + off]) << (8 * i); off += 1 }
    }
    return v
}

func readFixed64(_ data: Data, _ off: inout Int) -> UInt64 {
    var v: UInt64 = 0
    for i in 0..<8 {
        if off < data.count { v |= UInt64(data[data.startIndex + off]) << (8 * i); off += 1 }
    }
    return v
}

enum DecodedVal {
    case varint(UInt64)
    case fixed64(UInt64)
    case fixed32(UInt32)
    case bytes(Data)
    case msg(DecodedMsg)
}

class DecodedMsg {
    var fields: [Int: [DecodedVal]] = [:]
    var present: Set<Int> = []
    var oneofSet: [String: Int] = [:]
}

func skipField(_ data: Data, _ off: inout Int, end: Int, wt: Int) {
    switch wt {
    case 0: _ = readVarint(data, &off)
    case 1: off += 8
    case 2:
        let len = Int(readVarint(data, &off))
        off += len
    case 3:
        // group start - skip until matching end group
        // We don't know the field number here; caller handles it
        break
    case 5: off += 4
    default: break
    }
}

func skipGroup(_ data: Data, _ off: inout Int, end: Int, startFN: Int) {
    while off < end {
        let key = readVarint(data, &off)
        let fn = Int(key >> 3)
        let wt = Int(key & 7)
        switch wt {
        case 3: skipGroup(data, &off, end: end, startFN: fn)
        case 4: if fn == startFN { return }
        case 0: _ = readVarint(data, &off)
        case 1: off += 8
        case 2: let len = Int(readVarint(data, &off)); off += len
        case 5: off += 4
        default: break
        }
    }
}

func isNumericOrBoolOrEnum(_ tr: TypeRef) -> Bool {
    switch tr {
    case .scalar(let s):
        switch s {
        case .int32,.int64,.uint32,.uint64,.sint32,.sint64,.bool,.fixed32,.fixed64,.sfixed32,.sfixed64:
            return true
        default: return false
        }
    case .named(let n):
        return enums[n] != nil
    default: return false
    }
}

func normalWireType(_ tr: TypeRef) -> Int {
    switch tr {
    case .scalar(let s):
        switch s {
        case .int32,.int64,.uint32,.uint64,.sint32,.sint64,.bool: return 0
        case .fixed64,.sfixed64: return 1
        case .fixed32,.sfixed32: return 5
        default: return 2 // string, bytes
        }
    case .named(let n):
        if enums[n] != nil { return 0 }
        return 2 // message
    default: return 2
    }
}

func decodeMessage(data: Data, start: Int, end: Int, msgName: String) -> DecodedMsg {
    let msg = DecodedMsg()
    guard let def = messages[msgName] else { return msg }
    var off = start

    while off < end {
        let key = readVarint(data, &off)
        let fn = Int(key >> 3)
        let wt = Int(key & 7)

        guard let fd = def.fields.first(where: { $0.number == fn }) else {
            // Unknown field
            switch wt {
            case 0: _ = readVarint(data, &off)
            case 1: off += 8
            case 2: let len = Int(readVarint(data, &off)); off += len
            case 3: skipGroup(data, &off, end: end, startFN: fn)
            case 5: off += 4
            default: break
            }
            continue
        }

        // Handle oneof clearing
        if let oName = fd.oneofName {
            if let prev = msg.oneofSet[oName], prev != fn {
                msg.fields.removeValue(forKey: prev)
                msg.present.remove(prev)
            }
            msg.oneofSet[oName] = fn
        }

        let isRepeated = (fd.label == .repeated)
        let isMap: Bool
        if case .map = fd.type { isMap = true } else { isMap = false }

        // Decode value(s)
        if isRepeated && wt == 2 && isNumericOrBoolOrEnum(fd.type) {
            // Packed
            let len = Int(readVarint(data, &off))
            let pEnd = min(off + len, end)
            var vals: [DecodedVal] = []
            while off < pEnd {
                let nwt = normalWireType(fd.type)
                switch nwt {
                case 0: vals.append(.varint(readVarint(data, &off)))
                case 1: vals.append(.fixed64(readFixed64(data, &off)))
                case 5: vals.append(.fixed32(readFixed32(data, &off)))
                default: break
                }
            }
            msg.fields[fn, default: []].append(contentsOf: vals)
            msg.present.insert(fn)
        } else if isMap && wt == 2 {
            // Map entry
            let len = Int(readVarint(data, &off))
            let eEnd = min(off + len, end)
            let entry = decodeMapEntry(data: data, start: off, end: eEnd, fd: fd)
            msg.fields[fn, default: []].append(.msg(entry))
            msg.present.insert(fn)
            off = eEnd
        } else {
            let expectedWT = normalWireType(fd.type)
            var val: DecodedVal
            if wt == 2 && expectedWT == 2 {
                let len = Int(readVarint(data, &off))
                let vEnd = min(off + len, end)
                if case .named(let tn) = fd.type, messages[tn] != nil {
                    val = .msg(decodeMessage(data: data, start: off, end: vEnd, msgName: tn))
                } else {
                    let sub = data.subdata(in: (data.startIndex + off)..<(data.startIndex + vEnd))
                    val = .bytes(sub)
                }
                off = vEnd
            } else if wt == 0 && expectedWT == 0 {
                val = .varint(readVarint(data, &off))
            } else if wt == 1 && expectedWT == 1 {
                val = .fixed64(readFixed64(data, &off))
            } else if wt == 5 && expectedWT == 5 {
                val = .fixed32(readFixed32(data, &off))
            } else if wt == 2 && isRepeated && isNumericOrBoolOrEnum(fd.type) {
                // packed (shouldn't reach here due to earlier check, but handle)
                let len = Int(readVarint(data, &off))
                off += len
                continue
            } else {
                // Wire type mismatch - skip
                switch wt {
                case 0: _ = readVarint(data, &off)
                case 1: off += 8
                case 2: let l = Int(readVarint(data, &off)); off += l
                case 3: skipGroup(data, &off, end: end, startFN: fn)
                case 5: off += 4
                default: break
                }
                continue
            }

            if isRepeated {
                msg.fields[fn, default: []].append(val)
            } else {
                // Singular
                if case .msg(let newMsg) = val, case .named(let tn) = fd.type, messages[tn] != nil {
                    // Singular message: merge if already present
                    if let existing = msg.fields[fn], case .msg(let em) = existing.first {
                        mergeMsg(em, newMsg, msgName: tn)
                    } else {
                        msg.fields[fn] = [val]
                    }
                } else {
                    msg.fields[fn] = [val]
                }
            }
            msg.present.insert(fn)
        }
    }
    return msg
}

func decodeMapEntry(data: Data, start: Int, end: Int, fd: FieldDef) -> DecodedMsg {
    let entry = DecodedMsg()
    var off = start
    guard case .map(let kt, let vt) = fd.type else { return entry }
    while off < end {
        let key = readVarint(data, &off)
        let fn = Int(key >> 3)
        let wt = Int(key & 7)
        if fn == 1 {
            // key
            let kwt = normalWireType(.scalar(kt))
            if wt == kwt {
                if kwt == 0 { entry.fields[1] = [.varint(readVarint(data, &off))] }
                else if kwt == 5 { entry.fields[1] = [.fixed32(readFixed32(data, &off))] }
                else { let len = Int(readVarint(data, &off)); let vEnd = min(off+len, end); let sub = data.subdata(in: (data.startIndex+off)..<(data.startIndex+vEnd)); entry.fields[1] = [.bytes(sub)]; off = vEnd }
            } else {
                switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 5: off+=4; default: break }
            }
            entry.present.insert(1)
        } else if fn == 2 {
            // value
            let vwt = normalWireType(vt)
            if wt == vwt {
                if vwt == 0 { entry.fields[2] = [.varint(readVarint(data, &off))] }
                else if vwt == 5 { entry.fields[2] = [.fixed32(readFixed32(data, &off))] }
                else if vwt == 1 { entry.fields[2] = [.fixed64(readFixed64(data, &off))] }
                else {
                    let len = Int(readVarint(data, &off))
                    let vEnd = min(off+len, end)
                    if case .named(let tn) = vt, messages[tn] != nil {
                        entry.fields[2] = [.msg(decodeMessage(data: data, start: off, end: vEnd, msgName: tn))]
                    } else {
                        let sub = data.subdata(in: (data.startIndex+off)..<(data.startIndex+vEnd))
                        entry.fields[2] = [.bytes(sub)]
                    }
                    off = vEnd
                }
            } else {
                switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 5: off+=4; default: break }
            }
            entry.present.insert(2)
        } else {
            switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 3: skipGroup(data,&off,end:end,startFN:fn); case 5: off+=4; default: break }
        }
    }
    return entry
}

func mergeMsg(_ target: DecodedMsg, _ source: DecodedMsg, msgName: String) {
    guard let def = messages[msgName] else { return }
    for (fn, vals) in source.fields {
        guard let fd = def.fields.first(where: { $0.number == fn }) else { continue }
        if fd.label == .repeated {
            target.fields[fn, default: []].append(contentsOf: vals)
        } else if case .named(let tn) = fd.type, messages[tn] != nil {
            if let existing = target.fields[fn], case .msg(let em) = existing.first,
               let newVal = vals.first, case .msg(let nm) = newVal {
                mergeMsg(em, nm, msgName: tn)
            } else {
                target.fields[fn] = vals
            }
        } else {
            target.fields[fn] = vals
        }
        target.present.insert(fn)
    }
    for (oName, fn) in source.oneofSet {
        if let prev = target.oneofSet[oName], prev != fn {
            target.fields.removeValue(forKey: prev)
            target.present.remove(prev)
        }
        target.oneofSet[oName] = fn
    }
}

// MARK: - JSON Output

func toCamelCase(_ name: String) -> String {
    var result = ""
    var chars = Array(name)
    var i = 0
    while i < chars.count {
        if chars[i] == "_" {
            i += 1
            if i < chars.count && chars[i] >= "a" && chars[i] <= "z" {
                result.append(chars[i].uppercased())
                i += 1
            }
        } else {
            result.append(chars[i])
            i += 1
        }
    }
    return result
}

func escapeJSON(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\t": r += "\\t"
        case "\n": r += "\\n"
        case "\u{0C}": r += "\\f"
        case "\r": r += "\\r"
        default:
            if scalar.value < 0x20 {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

func base64Encode(_ data: Data) -> String {
    return data.base64EncodedString()
}

func zigzagDecode32(_ n: UInt32) -> Int32 {
    let x = (n >> 1) ^ (n & 1 == 1 ? 0xFFFFFFFF : 0)
    return Int32(bitPattern: x)
}

func zigzagDecode64(_ n: UInt64) -> Int64 {
    let x = (n >> 1) ^ (n & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
    return Int64(bitPattern: x)
}

func isDefault(_ fd: FieldDef, _ msg: DecodedMsg) -> Bool {
    guard let vals = msg.fields[fd.number], let v = vals.first else { return true }
    switch fd.type {
    case .scalar(let s):
        switch s {
        case .int32,.int64,.uint32,.uint64,.sint32,.sint64,.fixed32,.fixed64,.sfixed32,.sfixed64:
            if case .varint(let n) = v { return n == 0 }
            if case .fixed32(let n) = v { return n == 0 }
            if case .fixed64(let n) = v { return n == 0 }
            return true
        case .bool:
            if case .varint(let n) = v { return n == 0 }
            return true
        case .string:
            if case .bytes(let d) = v { return d.isEmpty }
            return true
        case .bytes:
            if case .bytes(let d) = v { return d.isEmpty }
            return true
        }
    case .named(let n):
        if enums[n] != nil {
            if case .varint(let raw) = v {
                let iv = Int(Int32(truncatingIfNeeded: raw))
                return iv == 0
            }
            return true
        }
        return false // message
    case .map:
        return msg.fields[fd.number]?.isEmpty ?? true
    }
}

func scalarToJSON(_ tr: TypeRef, _ val: DecodedVal) -> String {
    switch tr {
    case .scalar(let s):
        switch s {
        case .int32:
            if case .varint(let n) = val { return String(Int32(truncatingIfNeeded: n)) }
            return "0"
        case .int64:
            if case .varint(let n) = val { return "\"\(Int64(bitPattern: n))\"" }
            return "\"0\""
        case .uint32:
            if case .varint(let n) = val { return String(UInt32(truncatingIfNeeded: n)) }
            return "0"
        case .uint64:
            if case .varint(let n) = val { return "\"\(n)\"" }
            return "\"0\""
        case .sint32:
            if case .varint(let n) = val { return String(zigzagDecode32(UInt32(truncatingIfNeeded: n))) }
            return "0"
        case .sint64:
            if case .varint(let n) = val { return "\"\(zigzagDecode64(n))\"" }
            return "\"0\""
        case .bool:
            if case .varint(let n) = val { return n != 0 ? "true" : "false" }
            return "false"
        case .string:
            if case .bytes(let d) = val {
                let s = String(data: d, encoding: .utf8) ?? ""
                return escapeJSON(s)
            }
            return "\"\""
        case .bytes:
            if case .bytes(let d) = val { return "\"\(base64Encode(d))\"" }
            return "\"\""
        case .fixed32:
            if case .fixed32(let n) = val { return String(n) }
            return "0"
        case .fixed64:
            if case .fixed64(let n) = val { return "\"\(n)\"" }
            return "\"0\""
        case .sfixed32:
            if case .fixed32(let n) = val { return String(Int32(bitPattern: n)) }
