}

func messageToJSON(_ msg: DecodedMsg, msgName: String) -> String {
    guard let def = messages[msgName] else { return "{}" }
    var parts: [String] = []
    let sortedFields = def.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        let shouldPrint: Bool
        if case .map = fd.type {
            shouldPrint = msg.fields[fd.number]?.isEmpty == false
        } else if fd.label == .repeated {
            shouldPrint = msg.fields[fd.number]?.isEmpty == false
        } else if fd.label == .optional {
            shouldPrint = msg.present.contains(fd.number)
        } else if fd.oneofName != nil {
            shouldPrint = msg.oneofSet[fd.oneofName!] == fd.number
        } else if case .named(let tn) = fd.type, messages[tn] != nil {
            shouldPrint = msg.present.contains(fd.number)
        } else {
            shouldPrint = !isDefault(fd, msg)
        }

        guard shouldPrint else { continue }
        let jsonKey = escapeJSON(toCamelCase(fd.name))
        let jsonVal: String

        if case .map(let kt, let vt) = fd.type {
            jsonVal = mapToJSON(msg.fields[fd.number] ?? [], keyType: kt, valType: vt)
        } else if fd.label == .repeated {
            let vals = msg.fields[fd.number] ?? []
            jsonVal = "[" + vals.map { scalarToJSON(fd.type, $0) }.joined(separator: ",") + "]"
        } else {
            if let vals = msg.fields[fd.number], let v = vals.first {
                jsonVal = scalarToJSON(fd.type, v)
            } else {
                jsonVal = "null"
            }
        }
        parts.append("\(jsonKey):\(jsonVal)")
    }
    return "{" + parts.joined(separator: ",") + "}"
}

func mapToJSON(_ entries: [DecodedVal], keyType: ScalarType, valType: TypeRef) -> String {
    var pairs: [(String, String, Int)] = [] // (key_json, val_json, sort_key_int)
    var strPairs: [(String, String, [UInt8])] = [] // for string keys

    for entry in entries {
        guard case .msg(let em) = entry else { continue }
        let keyVal = em.fields[1]?.first
        let valVal = em.fields[2]?.first

        let keyStr: String
        if case .scalar(.string) = keyType {
