        }

        if case .scalar(.string) = keyType {
            let rawKey: String
            if case .bytes(let d) = keyVal { rawKey = String(data: d, encoding: .utf8) ?? "" } else { rawKey = "" }
            strPairs.append((keyStr, valStr, Array(rawKey.utf8)))
        } else {
            let rawKey: Int
            if case .varint(let n) = keyVal { rawKey = Int(Int32(truncatingIfNeeded: n)) } else { rawKey = 0 }
            pairs.append((keyStr, valStr, rawKey))
        }
    }

    if case .scalar(.string) = keyType {
        strPairs.sort { $0.2 < $1.2 }
        // Deduplicate by key (later wins)
        var seen: [String: Int] = [:]
        var ordered: [String] = []
        for i in 0..<strPairs.count {
            let k = strPairs[i].0
            if seen[k] != nil {
                ordered[seen[k]!] = "\(i)" // mark for replacement
            }
            seen[k] = ordered.count
            ordered.append(k)
