            let ab = Array(a.dropFirst().dropLast().utf8) // remove quotes
            let bb = Array(b.dropFirst().dropLast().utf8)
            return ab < bb
        }
        return "{" + keyOrder.map { "\($0):\(map[$0]!)" }.joined(separator: ",") + "}"
    } else {
