            let kwt = normalWireType(.scalar(kt))
            if wt == kwt {
                if kwt == 0 { entry.fields[1] = [.varint(readVarint(data, &off))] }
                else if kwt == 5 { entry.fields[1] = [.fixed32(readFixed32(data, &off))] }
                else { let len = Int(readVarint(data, &off)); let vEnd = min(off+len, end); let sub = data.subdata(in: (data.startIndex+off)..<(data.startIndex+vEnd)); entry.fields[1] = [.bytes(sub)]; off = vEnd }
            } else {
                switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 5: off+=4; default: break }
            }
            entry.present.insert(1)
        } else if fn == 2 {
            // value
            let vwt = normalWireType(vt)
            if wt == vwt {
                if vwt == 0 { entry.fields[2] = [.varint(readVarint(data, &off))] }
                else if vwt == 5 { entry.fields[2] = [.fixed32(readFixed32(data, &off))] }
                else if vwt == 1 { entry.fields[2] = [.fixed64(readFixed64(data, &off))] }
                else {
                    let len = Int(readVarint(data, &off))
                    let vEnd = min(off+len, end)
                    if case .named(let tn) = vt, messages[tn] != nil {
                        entry.fields[2] = [.msg(decodeMessage(data: data, start: off, end: vEnd, msgName: tn))]
                    } else {
                        let sub = data.subdata(in: (data.startIndex+off)..<(data.startIndex+vEnd))
                        entry.fields[2] = [.bytes(sub)]
                    }
                    off = vEnd
                }
            } else {
                switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 5: off+=4; default: break }
            }
            entry.present.insert(2)
        } else {
            switch wt { case 0: _ = readVarint(data,&off); case 1: off+=8; case 2: let l=Int(readVarint(data,&off)); off+=l; case 3: skipGroup(data,&off,end:end,startFN:fn); case 5: off+=4; default: break }
        }
    }
    return entry
}

func mergeMsg(_ target: DecodedMsg, _ source: DecodedMsg, msgName: String) {
    guard let def = messages[msgName] else { return }
    for (fn, vals) in source.fields {
        guard let fd = def.fields.first(where: { $0.number == fn }) else { continue }
        if fd.label == .repeated {
            target.fields[fn, default: []].append(contentsOf: vals)
        } else if case .named(let tn) = fd.type, messages[tn] != nil {
            if let existing = target.fields[fn], case .msg(let em) = existing.first,
               let newVal = vals.first, case .msg(let nm) = newVal {
                mergeMsg(em, nm, msgName: tn)
            } else {
                target.fields[fn] = vals
            }
        } else {
            target.fields[fn] = vals
        }
        target.present.insert(fn)
    }
    for (oName, fn) in source.oneofSet {
        if let prev = target.oneofSet[oName], prev != fn {
            target.fields.removeValue(forKey: prev)
            target.present.remove(prev)
        }
        target.oneofSet[oName] = fn
    }
}

// MARK: - JSON Output

func toCamelCase(_ name: String) -> String {
    var result = ""
    var chars = Array(name)
    var i = 0
    while i < chars.count {
        if chars[i] == "_" {
            i += 1
            if i < chars.count && chars[i] >= "a" && chars[i] <= "z" {
                result.append(chars[i].uppercased())
                i += 1
            }
        } else {
            result.append(chars[i])
            i += 1
        }
    }
    return result
}

func escapeJSON(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\u{08}": r += "\\b"
        case "\t": r += "\\t"
        case "\n": r += "\\n"
        case "\u{0C}": r += "\\f"
        case "\r": r += "\\r"
        default:
            if scalar.value < 0x20 {
                r += String(format: "\\u%04x", scalar.value)
            } else {
                r.unicodeScalars.append(scalar)
            }
        }
    }
    r += "\""
    return r
}

func base64Encode(_ data: Data) -> String {
    return data.base64EncodedString()
}

func zigzagDecode32(_ n: UInt32) -> Int32 {
    let x = (n >> 1) ^ (n & 1 == 1 ? 0xFFFFFFFF : 0)
    return Int32(bitPattern: x)
}

func zigzagDecode64(_ n: UInt64) -> Int64 {
    let x = (n >> 1) ^ (n & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
    return Int64(bitPattern: x)
}

func isDefault(_ fd: FieldDef, _ msg: DecodedMsg) -> Bool {
    guard let vals = msg.fields[fd.number], let v = vals.first else { return true }
    switch fd.type {
    case .scalar(let s):
        switch s {
        case .int32,.int64,.uint32,.uint64,.sint32,.sint64,.fixed32,.fixed64,.sfixed32,.sfixed64:
            if case .varint(let n) = v { return n == 0 }
            if case .fixed32(let n) = v { return n == 0 }
            if case .fixed64(let n) = v { return n == 0 }
            return true
        case .bool:
            if case .varint(let n) = v { return n == 0 }
            return true
        case .string:
            if case .bytes(let d) = v { return d.isEmpty }
            return true
        case .bytes:
            if case .bytes(let d) = v { return d.isEmpty }
            return true
        }
    case .named(let n):
        if enums[n] != nil {
            if case .varint(let raw) = v {
                let iv = Int(Int32(truncatingIfNeeded: raw))
                return iv == 0
            }
            return true
        }
        return false // message
    case .map:
        return msg.fields[fd.number]?.isEmpty ?? true
    }
}

func scalarToJSON(_ tr: TypeRef, _ val: DecodedVal) -> String {
    switch tr {
    case .scalar(let s):
        switch s {
        case .int32:
            if case .varint(let n) = val { return String(Int32(truncatingIfNeeded: n)) }
            return "0"
        case .int64:
            if case .varint(let n) = val { return "\"\(Int64(bitPattern: n))\"" }
            return "\"0\""
        case .uint32:
            if case .varint(let n) = val { return String(UInt32(truncatingIfNeeded: n)) }
            return "0"
        case .uint64:
            if case .varint(let n) = val { return "\"\(n)\"" }
            return "\"0\""
        case .sint32:
            if case .varint(let n) = val { return String(zigzagDecode32(UInt32(truncatingIfNeeded: n))) }
            return "0"
        case .sint64:
            if case .varint(let n) = val { return "\"\(zigzagDecode64(n))\"" }
            return "\"0\""
        case .bool:
            if case .varint(let n) = val { return n != 0 ? "true" : "false" }
            return "false"
        case .string:
            if case .bytes(let d) = val {
                let s = String(data: d, encoding: .utf8) ?? ""
                return escapeJSON(s)
            }
            return "\"\""
        case .bytes:
            if case .bytes(let d) = val { return "\"\(base64Encode(d))\"" }
            return "\"\""
        case .fixed32:
            if case .fixed32(let n) = val { return String(n) }
            return "0"
        case .fixed64:
            if case .fixed64(let n) = val { return "\"\(n)\"" }
            return "\"0\""
        case .sfixed32:
            if case .fixed32(let n) = val { return String(Int32(bitPattern: n)) }
            return "0"
        case .sfixed64:
            if case .fixed64(let n) = val { return "\"\(Int64(bitPattern: n))\"" }
            return "\"0\""
        }
    case .named(let n):
        if let ed = enums[n] {
            if case .varint(let raw) = val {
                let iv = Int(Int32(truncatingIfNeeded: raw))
                if let name = ed.values[iv] { return "\"\(name)\"" }
                return String(iv)
            }
            return "0"
        }
        // message
        if case .msg(let m) = val { return messageToJSON(m, msgName: n) }
        return "{}"
    case .map:
        return "{}"
    }
}

func messageToJSON(_ msg: DecodedMsg, msgName: String) -> String {
    guard let def = messages[msgName] else { return "{}" }
    var parts: [String] = []
    let sortedFields = def.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        let shouldPrint: Bool
        if case .map = fd.type {
            shouldPrint = msg.fields[fd.number]?.isEmpty == false
        } else if fd.label == .repeated {
            shouldPrint = msg.fields[fd.number]?.isEmpty == false
        } else if fd.label == .optional {
            shouldPrint = msg.present.contains(fd.number)
        } else if fd.oneofName != nil {
            shouldPrint = msg.oneofSet[fd.oneofName!] == fd.number
        } else if case .named(let tn) = fd.type, messages[tn] != nil {
            shouldPrint = msg.present.contains(fd.number)
        } else {
            shouldPrint = !isDefault(fd, msg)
        }

        guard shouldPrint else { continue }
        let jsonKey = escapeJSON(toCamelCase(fd.name))
        let jsonVal: String

        if case .map(let kt, let vt) = fd.type {
            jsonVal = mapToJSON(msg.fields[fd.number] ?? [], keyType: kt, valType: vt)
        } else if fd.label == .repeated {
            let vals = msg.fields[fd.number] ?? []
            jsonVal = "[" + vals.map { scalarToJSON(fd.type, $0) }.joined(separator: ",") + "]"
        } else {
            if let vals = msg.fields[fd.number], let v = vals.first {
                jsonVal = scalarToJSON(fd.type, v)
            } else {
                jsonVal = "null"
            }
        }
        parts.append("\(jsonKey):\(jsonVal)")
    }
    return "{" + parts.joined(separator: ",") + "}"
}

func mapToJSON(_ entries: [DecodedVal], keyType: ScalarType, valType: TypeRef) -> String {
    var pairs: [(String, String, Int)] = [] // (key_json, val_json, sort_key_int)
    var strPairs: [(String, String, [UInt8])] = [] // for string keys

    for entry in entries {
        guard case .msg(let em) = entry else { continue }
        let keyVal = em.fields[1]?.first
        let valVal = em.fields[2]?.first

        let keyStr: String
        if case .scalar(.string) = keyType {
            if case .bytes(let d) = keyVal {
                keyStr = escapeJSON(String(data: d, encoding: .utf8) ?? "")
            } else {
                keyStr = "\"\""
            }
        } else {
            // int32 key
            if case .varint(let n) = keyVal {
                keyStr = escapeJSON(String(Int32(truncatingIfNeeded: n)))
            } else {
                keyStr = "\"0\""
            }
        }

        let valStr: String
        if let vv = valVal {
            valStr = scalarToJSON(valType, vv)
        } else {
            valStr = scalarToJSON(valType, defaultVal(valType))
        }

        if case .scalar(.string) = keyType {
            let rawKey: String
            if case .bytes(let d) = keyVal { rawKey = String(data: d, encoding: .utf8) ?? "" } else { rawKey = "" }
            strPairs.append((keyStr, valStr, Array(rawKey.utf8)))
        } else {
            let rawKey: Int
            if case .varint(let n) = keyVal { rawKey = Int(Int32(truncatingIfNeeded: n)) } else { rawKey = 0 }
            pairs.append((keyStr, valStr, rawKey))
        }
    }

    if case .scalar(.string) = keyType {
        strPairs.sort { $0.2 < $1.2 }
        // Deduplicate by key (later wins)
        var seen: [String: Int] = [:]
        var ordered: [String] = []
        for i in 0..<strPairs.count {
            let k = strPairs[i].0
            if seen[k] != nil {
                ordered[seen[k]!] = "\(i)" // mark for replacement
            }
            seen[k] = ordered.count
            ordered.append(k)
        }
        // Actually, let me redo this properly
        var map: [String: String] = [:]
        var keyOrder: [String] = []
        for (ks, vs, _) in strPairs {
            if map[ks] == nil { keyOrder.append(ks) }
            map[ks] = vs
        }
        // Sort by UTF-8 bytes
        keyOrder.sort { a, b in
            let ab = Array(a.dropFirst().dropLast().utf8) // remove quotes
            let bb = Array(b.dropFirst().dropLast().utf8)
            return ab < bb
        }
        return "{" + keyOrder.map { "\($0):\(map[$0]!)" }.joined(separator: ",") + "}"
    } else {
        pairs.sort { $0.2 < $1.2 }
        var map: [String: String] = [:]
        var keyOrder: [String] = []
        for (ks, vs, _) in pairs {
            if map[ks] == nil { keyOrder.append(ks) }
            map[ks] = vs
        }
        keyOrder.sort { a, b in
            let ai = Int(a.dropFirst().dropLast()) ?? 0
            let bi = Int(b.dropFirst().dropLast()) ?? 0
            return ai < bi
        }
        return "{" + keyOrder.map { "\($0):\(map[$0]!)" }.joined(separator: ",") + "}"
    }
}

func defaultVal(_ tr: TypeRef) -> DecodedVal {
    switch tr {
    case .scalar(let s):
        switch s {
        case .fixed32,.sfixed32: return .fixed32(0)
        case .fixed64,.sfixed64: return .fixed64(0)
        default: return .varint(0)
        }
    case .named(let n):
        if messages[n] != nil { return .msg(DecodedMsg()) }
        return .varint(0)
    case .map: return .varint(0)
    }
}

