// ===== Tokenizer =====
fn tokenize(input: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let bytes = input.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i].is_ascii_whitespace() { i += 1; continue; }
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'/' {
            i += 2;
            while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
            continue;
        }
        if i + 1 < bytes.len() && bytes[i] == b'/' && bytes[i + 1] == b'*' {
            i += 2;
            while i + 1 < bytes.len() && !(bytes[i] == b'*' && bytes[i + 1] == b'/') { i += 1; }
            i += 2;
            continue;
        }
        if bytes[i] == b'"' {
            i += 1;
            let start = i;
            while i < bytes.len() && bytes[i] != b'"' { i += 1; }
            tokens.push(Token::StrLit(String::from_utf8_lossy(&bytes[start..i]).into_owned()));
            if i < bytes.len() { i += 1; }
            continue;
        }
        if bytes[i].is_ascii_alphabetic() || bytes[i] == b'_' {
            let start = i;
            while i < bytes.len() && (bytes[i].is_ascii_alphanumeric() || bytes[i] == b'_') { i += 1; }
            tokens.push(Token::Ident(String::from_utf8_lossy(&bytes[start..i]).into_owned()));
            continue;
        }
        if bytes[i].is_ascii_digit() {
            let start = i;
            while i < bytes.len() && bytes[i].is_ascii_digit() { i += 1; }
            tokens.push(Token::Num(String::from_utf8_lossy(&bytes[start..i]).into_owned()));
            continue;
        }
        match bytes[i] {
            b'{' => tokens.push(Token::LBrace),
            b'}' => tokens.push(Token::RBrace),
            b'[' => tokens.push(Token::LBracket),
            b']' => tokens.push(Token::RBracket),
            b'<' => tokens.push(Token::Lt),
            b'>' => tokens.push(Token::Gt),
            b';' => tokens.push(Token::Semi),
            b',' => tokens.push(Token::Comma),
            b'=' => tokens.push(Token::Eq),
            b'.' => tokens.push(Token::Dot),
            b'-' => tokens.push(Token::Minus),
            _ => {}
        }
        i += 1;
    }
    tokens.push(Token::Eof);
    tokens
}

