    fn new(tokens: Vec<Token>) -> Self { Parser { tokens, pos: 0 } }
    fn peek(&self) -> &Token { &self.tokens[self.pos] }
    fn advance(&mut self) -> Token { let t = self.tokens[self.pos].clone(); self.pos += 1; t }
    fn at(&self, tok: &Token) -> bool { self.tokens[self.pos] == *tok }
    fn expect_ident(&mut self) -> String {
        match self.advance() { Token::Ident(s) => s, _ => panic!("expected ident") }
    }
    fn expect_num(&mut self) -> u32 {
        match self.advance() { Token::Num(s) => s.parse().unwrap(), _ => panic!("expected num") }
    }
    fn expect(&mut self, t: &Token) { assert_eq!(self.advance(), *t); }
    fn skip_to_semi(&mut self) {
        while !self.at(&Token::Semi) && !self.at(&Token::Eof) { self.advance(); }
        if self.at(&Token::Semi) { self.advance(); }
    }
    fn skip_bracket(&mut self) {
        // skip [ ... ]
        self.expect(&Token::LBracket);
        let mut depth = 1;
        while depth > 0 && !self.at(&Token::Eof) {
            match self.advance() {
                Token::LBracket => depth += 1,
                Token::RBracket => depth -= 1,
                _ => {}
            }
        }
    }

