use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::io::Read;

// ============ Schema Types ============

#[derive(Clone, Debug)]
enum FieldType {
    Scalar(String),
    Msg(String),
    Enum(String),
    Map(String, Box<FieldType>),
}

#[derive(Clone, Debug, PartialEq)]
enum Label {
    Singular,
    Optional,
    Repeated,
    Oneof,
}

#[derive(Clone, Debug)]
struct FieldDef {
    number: u32,
    name: String,
    field_type: FieldType,
    label: Label,
    oneof_name: Option<String>,
}

#[derive(Clone, Debug)]
struct MessageDef {
    fields: Vec<FieldDef>,
}

#[derive(Clone, Debug)]
struct EnumDef {
    values: Vec<(String, i64)>,
}

struct Schema {
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root: String,
}

// ============ Raw Wire ============

#[derive(Clone, Debug)]
enum RawVal {
    Varint(u64),
    Fixed32(u32),
    Fixed64(u64),
    Bytes(Vec<u8>),
}

type WireEntry = (u32, u8, RawVal);

// ============ Proto Parser ============

struct ProtoParser {
    chars: Vec<char>,
    pos: usize,
}

impl ProtoParser {
    fn new(input: &str) -> Self {
        ProtoParser { chars: input.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '/' {
                while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                    self.pos += 1;
                }
            } else if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '*' {
                self.pos += 2;
                while self.pos + 1 < self.chars.len() {
                    if self.chars[self.pos] == '*' && self.chars[self.pos + 1] == '/' {
                        self.pos += 2;
                        break;
                    }
                    self.pos += 1;
                }
            } else {
                break;
            }
        }
    }

    fn peek(&mut self) -> Option<char> {
        self.skip_ws();
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn read_ident(&mut self) -> String {
        self.skip_ws();
        let mut s = String::new();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.') {
            s.push(self.chars[self.pos]);
            self.pos += 1;
        }
        s
    }

    fn read_number_str(&mut self) -> String {
        self.skip_ws();
        let mut s = String::new();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_ascii_digit() || self.chars[self.pos] == '-' || self.chars[self.pos] == '.' || self.chars[self.pos] == 'e' || self.chars[self.pos] == 'E' || self.chars[self.pos] == '+') {
            s.push(self.chars[self.pos]);
            self.pos += 1;
        }
        s
    }

    fn read_string_lit(&mut self) -> String {
        self.pos += 1; // skip opening "
        let mut s = String::new();
        while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
            s.push(self.chars[self.pos]);
            self.pos += 1;
        }
        if self.pos < self.chars.len() { self.pos += 1; }
        s
    }

    fn expect_char(&mut self, c: char) {
        self.skip_ws();
        if self.pos < self.chars.len() && self.chars[self.pos] == c {
            self.pos += 1;
        }
    }

    fn skip_to_semi(&mut self) {
        while self.pos < self.chars.len() {
            if self.chars[self.pos] == '"' {
                self.pos += 1;
                while self.pos < self.chars.len() && self.chars[self.pos] != '"' { self.pos += 1; }
                if self.pos < self.chars.len() { self.pos += 1; }
            } else if self.chars[self.pos] == '{' {
                let mut d = 1; self.pos += 1;
                while self.pos < self.chars.len() && d > 0 {
                    if self.chars[self.pos] == '{' { d += 1; }
                    else if self.chars[self.pos] == '}' { d -= 1; }
                    else if self.chars[self.pos] == '"' {
                        self.pos += 1;
                        while self.pos < self.chars.len() && self.chars[self.pos] != '"' { self.pos += 1; }
                    }
                    self.pos += 1;
                }
            } else if self.chars[self.pos] == ';' {
                self.pos += 1; return;
            } else {
                self.pos += 1;
            }
        }
    }

    fn skip_bracket_options(&mut self) {
        self.skip_ws();
        if self.pos < self.chars.len() && self.chars[self.pos] == '[' {
            let mut d = 1; self.pos += 1;
            while self.pos < self.chars.len() && d > 0 {
                if self.chars[self.pos] == '[' { d += 1; }
                else if self.chars[self.pos] == ']' { d -= 1; }
                else if self.chars[self.pos] == '"' {
                    self.pos += 1;
                    while self.pos < self.chars.len() && self.chars[self.pos] != '"' { self.pos += 1; }
                }
                self.pos += 1;
            }
        }
    }

    fn parse_schema(&mut self) -> Schema {
        let mut messages: HashMap<String, MessageDef> = HashMap::new();
        let mut enums: HashMap<String, EnumDef> = HashMap::new();
        let mut root = String::new();
        let mut root_set = false;

        loop {
            let ident = self.read_ident();
            if ident.is_empty() { break; }
            match ident.as_str() {
                "syntax" | "package" => { self.skip_to_semi(); }
                "option" => { self.skip_to_semi(); }
                "message" => {
                    let name = self.read_ident();
                    let def = self.parse_message_body(&mut messages, &mut enums);
                    if !root_set { root = name.clone(); root_set = true; }
                    messages.insert(name, def);
                }
                "enum" => {
                    let name = self.read_ident();
                    let def = self.parse_enum_body();
                    enums.insert(name, def);
                }
                _ => { self.skip_to_semi(); }
            }
        }
        Schema { messages, enums, root }
    }

    fn parse_message_body(&mut self, messages: &mut HashMap<String, MessageDef>, enums: &mut HashMap<String, EnumDef>) -> MessageDef {
        self.expect_char('{');
        let mut fields: Vec<FieldDef> = Vec::new();

        loop {
            let ident = self.read_ident();
            if ident.is_empty() { break; }
            match ident.as_str() {
                "}" => break,
                "message" => {
                    let name = self.read_ident();
                    let def = self.parse_message_body(messages, enums);
                    messages.insert(name, def);
                }
                "enum" => {
                    let name = self.read_ident();
                    let def = self.parse_enum_body();
                    enums.insert(name, def);
                }
                "oneof" => {
                    let oneof_name = self.read_ident();
                    self.expect_char('{');
                    loop {
                        let fi = self.read_ident();
                        if fi.is_empty() || fi == "}" { break; }
                        if fi == "option" { self.skip_to_semi(); continue; }
                        if fi == "reserved" { self.skip_to_semi(); continue; }
                        // parse field (no label)
                        let ft = self.parse_type(fi);
                        let fname = self.read_ident();
                        self.expect_char('=');
                        let num: u32 = self.read_number_str().parse().unwrap_or(0);
                        self.skip_bracket_options();
                        self.expect_char(';');
                        fields.push(FieldDef { number: num, name: fname, field_type: ft, label: Label::Oneof, oneof_name: Some(oneof_name.clone()) });
                    }
                }
                "reserved" => { self.skip_to_semi(); }
                "option" => { self.skip_to_semi(); }
                "map" => {
                    self.expect_char('<');
                    let key_type = self.read_ident();
                    self.expect_char(',');
                    let val_type_str = self.read_ident();
                    let val_type = self.classify_type(val_type_str, messages, enums);
                    self.expect_char('>');
                    let fname = self.read_ident();
                    self.expect_char('=');
                    let num: u32 = self.read_number_str().parse().unwrap_or(0);
                    self.skip_bracket_options();
                    self.expect_char(';');
                    fields.push(FieldDef { number: num, name: fname, field_type: FieldType::Map(key_type, Box::new(val_type)), label: Label::Repeated, oneof_name: None });
                }
                _ => {
                    let (label, type_ident) = if ident == "repeated" {
                        (Label::Repeated, self.read_ident())
                    } else if ident == "optional" {
                        (Label::Optional, self.read_ident())
                    } else {
                        (Label::Singular, ident)
                    };
                    let ft = self.classify_type(type_ident, messages, enums);
                    let fname = self.read_ident();
                    self.expect_char('=');
                    let num: u32 = self.read_number_str().parse().unwrap_or(0);
                    self.skip_bracket_options();
                    self.expect_char(';');
                    fields.push(FieldDef { number: num, name: fname, field_type: ft, label, oneof_name: None });
                }
            }
        }
        MessageDef { fields }
    }

    fn parse_type(&mut self, first_ident: String) -> FieldType {
        // first_ident is already read; check if it's "map"
        // Actually this is used inside oneof where we already read the type ident
        // For simplicity, just classify as scalar/message/enum
        // map inside oneof shouldn't happen per spec
        let s = first_ident;
        if is_scalar_type(&s) { FieldType::Scalar(s) }
        else { FieldType::Msg(s) } // will be resolved later
    }

    fn classify_type(&mut self, name: String, messages: &HashMap<String, MessageDef>, enums: &HashMap<String, EnumDef>) -> FieldType {
        if name == "map" {
            self.expect_char('<');
            let key_type = self.read_ident();
            self.expect_char(',');
            let val_type_str = self.read_ident();
            let val_type = self.classify_type(val_type_str, messages, enums);
            self.expect_char('>');
            return FieldType::Map(key_type, Box::new(val_type));
        }
        if is_scalar_type(&name) { return FieldType::Scalar(name); }
        if enums.contains_key(&name) { return FieldType::Enum(name); }
        FieldType::Msg(name)
    }

    fn parse_enum_body(&mut self) -> EnumDef {
        self.expect_char('{');
        let mut values: Vec<(String, i64)> = Vec::new();
        loop {
            let ident = self.read_ident();
            if ident.is_empty() || ident == "}" { break; }
            if ident == "option" || ident == "reserved" { self.skip_to_semi(); continue; }
            self.expect_char('=');
            let num_str = self.read_number_str();
            let num: i64 = num_str.parse().unwrap_or(0);
            self.skip_bracket_options();
            self.expect_char(';');
            values.push((ident, num));
        }
        EnumDef { values }
    }
}

fn is_scalar_type(s: &str) -> bool {
    matches!(s, "int32"|"int64"|"uint32"|"uint64"|"sint32"|"sint64"|"bool"|"string"|"bytes"|"fixed32"|"fixed64"|"sfixed32"|"sfixed64")
}

// ============ Wire Decoder ============

fn read_varint(data: &[u8], pos: &mut usize) -> u64 {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        if *pos >= data.len() { break; }
        let byte = data[*pos];
        *pos += 1;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 == 0 { break; }
        shift += 7;
        if shift >= 64 { break; }
    }
    result
}

fn parse_wire_entries(data: &[u8]) -> Vec<WireEntry> {
    let mut entries: Vec<WireEntry> = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let key = read_varint(data, &mut pos);
        let field_num = (key >> 3) as u32;
        let wire_type = (key & 7) as u8;
        match wire_type {
            0 => { let v = read_varint(data, &mut pos); entries.push((field_num, 0, RawVal::Varint(v))); }
            1 => { if pos + 8 <= data.len() { let v = u64::from_le_bytes(data[pos..pos+8].try_into().unwrap()); pos += 8; entries.push((field_num, 1, RawVal::Fixed64(v))); } else { break; } }
            2 => { let len = read_varint(data, &mut pos) as usize; if pos + len <= data.len() { let v = data[pos..pos+len].to_vec(); pos += len; entries.push((field_num, 2, RawVal::Bytes(v))); } else { break; } }
            5 => { if pos + 4 <= data.len() { let v = u32::from_le_bytes(data[pos..pos+4].try_into().unwrap()); pos += 4; entries.push((field_num, 5, RawVal::Fixed32(v))); } else { break; } }
            3 => { // start group - skip
                let mut depth = 1u32;
                while depth > 0 && pos < data.len() {
                    let k = read_varint(data, &mut pos);
                    let wt = (k & 7) as u8;
                    match wt {
                        0 => { read_varint(data, &mut pos); }
                        1 => { pos += 8; }
                        2 => { let l = read_varint(data, &mut pos) as usize; pos += l; }
                        3 => { depth += 1; }
                        4 => { depth -= 1; }
                        5 => { pos += 4; }
                        _ => {}
                    }
                }
            }
            4 => { // end group at top level - skip
            }
            _ => { break; }
        }
    }
    entries
}

// ============ JSON Generation ============

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    let mut i = 0;
    while i < data.len() {
        let b0 = data[i] as u32;
        let b1 = if i + 1 < data.len() { data[i + 1] as u32 } else { 0 };
        let b2 = if i + 2 < data.len() { data[i + 2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if i + 1 < data.len() { result.push(CHARS[((n >> 6) & 63) as usize] as char); } else { result.push('='); }
        if i + 2 < data.len() { result.push(CHARS[(n & 63) as usize] as char); } else { result.push('='); }
        i += 3;
    }
    result
}

fn json_escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\t' => result.push_str("\\t"),
            '\n' => result.push_str("\\n"),
            '\u{000C}' => result.push_str("\\f"),
            '\r' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => { result.push_str(&format!("\\u{:04x}", c as u32)); }
            c => result.push(c),
        }
    }
    result
}

fn to_camel(name: &str) -> String {
    let mut result = String::new();
    let mut upper_next = false;
    for c in name.chars() {
        if c == '_' {
            upper_next = true;
        } else {
            if upper_next {
                if c.is_ascii_lowercase() { result.push(c.to_ascii_uppercase()); }
                else { result.push(c); }
                upper_next = false;
            } else {
                result.push(c);
            }
        }
    }
    result
}

fn scalar_default(scalar_type: &str) -> bool {
    match scalar_type {
        "int32"|"int64"|"uint32"|"uint64"|"sint32"|"sint64"|"fixed32"|"fixed64"|"sfixed32"|"sfixed64" => true, // 0
        "bool" => true, // false
        "string"|"bytes" => true, // empty
        _ => false,
    }
}

fn is_numeric_scalar(s: &str) -> bool {
    matches!(s, "int32"|"int64"|"uint32"|"uint64"|"sint32"|"sint64"|"bool"|"fixed32"|"fixed64"|"sfixed32"|"sfixed64")
}

fn varint_wire_type(s: &str) -> u8 {
    match s {
        "int32"|"int64"|"uint32"|"uint64"|"sint32"|"sint64"|"bool" => 0,
        "fixed32"|"sfixed32" => 5,
        "fixed64"|"sfixed64" => 1,
        _ => 2, // string, bytes
    }
}

fn decode_scalar_val(s: &str, raw: &RawVal) -> i64 {
    match s {
        "int32" => { let v = match raw { RawVal::Varint(x) => *x, _ => 0 }; (v as u32) as i32 as i64; (v as u32) as i32 as i64 }
        _ => 0
    }
}

fn raw_to_i32(raw: &RawVal) -> i32 {
    match raw {
        RawVal::Varint(v) => (*v as u32) as i32,
        RawVal::Fixed32(v) => *v as i32,
        RawVal::Fixed64(v) => (*v as u32) as i32,
        _ => 0,
    }
}

fn raw_to_i64(raw: &RawVal) -> i64 {
    match raw {
        RawVal::Varint(v) => *v as i64,
        RawVal::Fixed64(v) => *v as i64,
        _ => 0,
    }
}

fn raw_to_u32(raw: &RawVal) -> u32 {
    match raw {
        RawVal::Varint(v) => *v as u32,
        RawVal::Fixed32(v) => *v,
        RawVal::Fixed64(v) => *v as u32,
        _ => 0,
    }
}

fn raw_to_u64(raw: &RawVal) -> u64 {
    match raw {
        RawVal::Varint(v) => *v,
        RawVal::Fixed64(v) => *v,
        _ => 0,
    }
}

fn raw_to_sint32(raw: &RawVal) -> i32 {
    let v = match raw { RawVal::Varint(x) => *x, _ => 0 };
    let v32 = v as u32;
    ((v32 >> 1) as i32) ^ ((v32 & 1) as i32).wrapping_neg()
}

fn raw_to_sint64(raw: &RawVal) -> i64 {
    let v = match raw { RawVal::Varint(x) => *x, _ => 0 };
    ((v >> 1) as i64) ^ ((v & 1) as i64).wrapping_neg()
}

fn raw_to_bool(raw: &RawVal) -> bool {
    match raw { RawVal::Varint(v) => *v != 0, _ => false }
}

fn raw_to_bytes(raw: &RawVal) -> &Vec<u8> {
    match raw { RawVal::Bytes(b) => b, _ => &vec![] }
}

fn decode_packed_numeric(s: &str, data: &[u8]) -> Vec<RawVal> {
    let mut result = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        match s {
            "int32"|"int64"|"uint32"|"uint64"|"sint32"|"sint64"|"bool" => {
                result.push(RawVal::Varint(read_varint(data, &mut pos)));
            }
            "fixed32"|"sfixed32" => {
                if pos + 4 <= data.len() {
                    result.push(RawVal::Fixed32(u32::from_le_bytes(data[pos..pos+4].try_into().unwrap())));
                    pos += 4;
                } else { break; }
            }
            "fixed64"|"sfixed64" => {
                if pos + 8 <= data.len() {
                    result.push(RawVal::Fixed64(u64::from_le_bytes(data[pos..pos+8].try_into().unwrap())));
                    pos += 8;
                } else { break; }
            }
            _ => break,
        }
    }
    result
}

fn scalar_to_json_str(s: &str, raw: &RawVal, schema: &Schema) -> String {
    match s {
        "int32" => format!("{}", raw_to_i32(raw)),
        "int64" => format!("\"{}\"", raw_to_i64(raw)),
        "uint32" => format!("{}", raw_to_u32(raw)),
        "uint64" => format!("\"{}\"", raw_to_u64(raw)),
        "sint32" => format!("{}", raw_to_sint32(raw)),
        "sint64" => format!("\"{}\"", raw_to_sint64(raw)),
        "fixed32" => format!("{}", raw_to_u32(raw)),
        "fixed64" => format!("\"{}\"", raw_to_u64(raw)),
        "sfixed32" => format!("{}", raw_to_i32(raw)),
        "sfixed64" => format!("\"{}\"", raw_to_i64(raw)),
        "bool" => if raw_to_bool(raw) { "true".to_string() } else { "false".to_string() },
        "string" => format!("\"{}\"", json_escape(std::str::from_utf8(raw_to_bytes(raw)).unwrap_or(""))),
        "bytes" => format!("\"{}\"", base64_encode(raw_to_bytes(raw))),
        _ => "null".to_string(),
    }
}

fn enum_to_json_str(enum_name: &str, raw: &RawVal, schema: &Schema) -> String {
    let val = raw_to_i32(raw);
    if let Some(ed) = schema.enums.get(enum_name) {
        for (name, num) in &ed.values {
            if *num == val as i64 {
                return format!("\"{}\"", name);
            }
        }
    }
    format!("{}", val)
}

fn is_scalar_default(s: &str, raw: &RawVal) -> bool {
    match s {
        "int32"|"uint32"|"sint32"|"fixed32"|"sfixed32" => raw_to_i32(raw) == 0,
        "int64"|"uint64"|"sint64"|"fixed64"|"sfixed64" => raw_to_i64(raw) == 0,
        "bool" => !raw_to_bool(raw),
        "string" => raw_to_bytes(raw).is_empty(),
        "bytes" => raw_to_bytes(raw).is_empty(),
        _ => true,
    }
}

fn resolve_field_type(ft: &FieldType, schema: &Schema) -> FieldType {
    match ft {
        FieldType::Msg(name) => {
            if schema.enums.contains_key(name) { FieldType::Enum(name.clone()) }
            else { FieldType::Msg(name.clone()) }
        }
        FieldType::Map(k, v) => FieldType::Map(k.clone(), Box::new(resolve_field_type(v, schema))),
        _ => ft.clone(),
    }
}

fn value_to_json(ft: &FieldType, raw: &RawVal, schema: &Schema) -> String {
    match ft {
        FieldType::Scalar(s) => scalar_to_json_str(s, raw, schema),
        FieldType::Enum(name) => enum_to_json_str(name, raw, schema),
        FieldType::Msg(name) => {
            let sub_data = raw_to_bytes(raw);
            msg_to_json(sub_data, schema, name)
        }
        FieldType::Map(_, _) => "null".to_string(), // shouldn't be called directly
    }
}

fn msg_to_json(data: &[u8], schema: &Schema, msg_name: &str) -> String {
    let entries = parse_wire_entries(data);
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return "{}".to_string(),
    };

    // Resolve field types
    let resolved_fields: Vec<FieldDef> = msg_def.fields.iter().map(|f| {
        FieldDef {
            number: f.number,
            name: f.name.clone(),
            field_type: resolve_field_type(&f.field_type, schema),
            label: f.label.clone(),
            oneof_name: f.oneof_name.clone(),
        }
    }).collect();

    // Group entries by field number
    let mut field_entries: HashMap<u32, Vec<(u8, &RawVal)>> = HashMap::new();
    for (fn_, wt, val) in &entries {
        field_entries.entry(*fn_).or_default().push((*wt, val));
    }

    // Determine oneof state: process entries in wire order
    let mut oneof_set: HashMap<String, u32> = HashMap::new(); // oneof_name -> field_num
    let mut field_to_oneof: HashMap<u32, String> = HashMap::new();
    for f in &resolved_fields {
        if let Some(ref on) = f.oneof_name {
            field_to_oneof.insert(f.number, on.clone());
        }
    }
    for (fn_, _, _) in &entries {
        if let Some(on) = field_to_oneof.get(fn_) {
            oneof_set.insert(on.clone(), *fn_);
        }
    }

    // Sort fields by number
    let mut sorted_fields: Vec<&FieldDef> = resolved_fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    let mut parts: Vec<String> = Vec::new();

    for f in &sorted_fields {
        let fentries = match field_entries.get(&f.number) {
            Some(e) => e,
            None => continue,
        };

        match &f.field_type {
            FieldType::Map(key_type, val_type) => {
                // Process map entries
                let mut map_entries: Vec<(String, String)> = Vec::new(); // json_key, json_val
                let mut seen_keys: HashMap<String, usize> = HashMap::new();
                for (_, raw) in fentries {
                    let entry_data = raw_to_bytes(raw);
                    let sub_entries = parse_wire_entries(entry_data);
                    let mut key_raw: Option<&RawVal> = None;
                    let mut val_raw: Option<&RawVal> = None;
                    for (sf, _, sv) in &sub_entries {
                        if *sf == 1 { key_raw = Some(sv); }
                        if *sf == 2 { val_raw = Some(sv); }
                    }
                    let json_key = match key_type.as_str() {
                        "string" => {
                            let k = key_raw.map(|r| std::str::from_utf8(raw_to_bytes(r)).unwrap_or("").to_string()).unwrap_or_default();
                            json_escape(&k)
                        }
                        "int32" => {
                            let k = key_raw.map(|r| raw_to_i32(r)).unwrap_or(0);
                            format!("{}", k)
                        }
                        _ => "\"\"".to_string(),
