                        let mut vals: Vec<String> = Vec::new();
                        for (wt, raw) in fentries {
                            if *wt == 2 && is_numeric_scalar(s) {
                                // packed
                                let packed = decode_packed_numeric(s, raw_to_bytes(raw));
                                for pr in &packed {
                                    vals.push(scalar_to_json_str(s, pr, schema));
                                }
                            } else {
