                        let on = f.oneof_name.as_ref().unwrap();
                        if oneof_set.get(on) != Some(&f.number) { continue; }
                        let raw = fentries.last().unwrap().1;
                        parts.push(format!("\"{}\":{}", to_camel(&f.name), enum_to_json_str(name, raw, schema)));
                    }
                    Label::Optional => {
                        let raw = fentries.last().unwrap().1;
                        parts.push(format!("\"{}\":{}", to_camel(&f.name), enum_to_json_str(name, raw, schema)));
                    }
                    Label::Singular => {
                        let raw = fentries.last().unwrap().1;
                        let val = raw_to_i32(raw);
                        if val == 0 { continue; }
                        parts.push(format!("\"{}\":{}", to_camel(&f.name), enum_to_json_str(name, raw, schema)));
                    }
                }
            }
            FieldType::Msg(name) => {
                match &f.label {
                    Label::Repeated => {
                        let mut vals: Vec<String> = Vec::new();
                        for (_, raw) in fentries {
                            vals.push(msg_to_json(raw_to_bytes(raw), schema, name));
                        }
                        if vals.is_empty() { continue; }
                        parts.push(format!("\"{}\":[{}]", to_camel(&f.name), vals.join(",")));
                    }
                    Label::Oneof => {
                        let on = f.oneof_name.as_ref().unwrap();
                        if oneof_set.get(on) != Some(&f.number) { continue; }
                        // Merge occurrences if same member still set
                        let merged = merge_msg_entries(fentries, &resolved_fields, schema, name);
                        parts.push(format!("\"{}\":{}", to_camel(&f.name), msg_to_json(&merged, schema, name)));
