                    Label::Optional | Label::Singular => {
                        let merged = merge_msg_entries(fentries, &resolved_fields, schema, name);
                        parts.push(format!("\"{}\":{}", to_camel(&f.name), msg_to_json(&merged, schema, name)));
                    }
                }
            }
        }
    }

    format!("{{{}}}", parts.join(","))
}

fn merge_msg_entries(fentries: &[(u8, &RawVal)], _fields: &[FieldDef], schema: &Schema, msg_name: &str) -> Vec<u8> {
    // Merge multiple occurrences of a singular message field
    // For simplicity, we re-encode merged entries
    // Actually, we can just concatenate the wire bytes and let msg_to_json handle it
    // But that's not correct for merging semantics (scalars: last wins; repeated: append)
    // The simplest correct approach: concatenate all sub-entry bytes
    // Because msg_to_json processes entries in order, and:
    // - singular scalar: last occurrence wins (we take .last())
    // - repeated: all occurrences append
    // - singular message: we merge recursively
    // So concatenating the raw bytes of all occurrences gives correct semantics!
    let mut result = Vec::new();
    for (_, raw) in fentries {
        result.extend_from_slice(raw_to_bytes(raw));
    }
    result
}

fn default_value_json(ft: &FieldType, schema: &Schema) -> String {
    match ft {
        FieldType::Scalar(s) => match s.as_str() {
            "int32"|"uint32"|"sint32"|"fixed32"|"sfixed32" => "0".to_string(),
            "int64"|"uint64"|"sint64"|"fixed64"|"sfixed64" => "\"0\"".to_string(),
            "bool" => "false".to_string(),
            "string" => "\"\"".to_string(),
            "bytes" => "\"\"".to_string(),
            _ => "0".to_string(),
        },
        FieldType::Enum(name) => {
            if let Some(ed) = schema.enums.get(name) {
                for (n, v) in &ed.values {
                    if *v == 0 { return format!("\"{}\"", n); }
                }
            }
            "0".to_string()
        }
        FieldType::Msg(_) => "{}".to_string(),
        FieldType::Map(_, _) => "{}".to_string(),
    }
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_path = format!("{}/schema.proto", dir);
    let schema_str = fs::read_to_string(&schema_path).unwrap();
