                    self.pos += 1;
                }
            } else {
                break;
            }
        }
    }

    fn peek(&mut self) -> Option<char> {
        self.skip_ws();
        if self.pos < self.chars.len() { Some(self.chars[self.pos]) } else { None }
    }

    fn read_ident(&mut self) -> String {
        self.skip_ws();
        let mut s = String::new();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_' || self.chars[self.pos] == '.') {
            s.push(self.chars[self.pos]);
            self.pos += 1;
        }
        s
    }

    fn read_number_str(&mut self) -> String {
        self.skip_ws();
        let mut s = String::new();
        while self.pos < self.chars.len() && (self.chars[self.pos].is_ascii_digit() || self.chars[self.pos] == '-' || self.chars[self.pos] == '.' || self.chars[self.pos] == 'e' || self.chars[self.pos] == 'E' || self.chars[self.pos] == '+') {
            s.push(self.chars[self.pos]);
            self.pos += 1;
        }
        s
    }

    fn read_string_lit(&mut self) -> String {
        self.pos += 1; // skip opening "
        let mut s = String::new();
        while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
            s.push(self.chars[self.pos]);
            self.pos += 1;
