    fn parse_schema(&mut self) -> Schema {
        let mut messages: HashMap<String, MessageDef> = HashMap::new();
        let mut enums: HashMap<String, EnumDef> = HashMap::new();
        let mut root = String::new();
        let mut root_set = false;

