    for (k, v) in hdrs {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("Connection: close\r\n\r\n");
    if let Some(b) = body { req.push_str(b); }
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();
    let he = find_crlfcrlf(&raw);
    let hdr_str = std::str::from_utf8(&raw[..he]).unwrap();
    let body_raw = &raw[he+4..];
    let first_line = hdr_str.split("\r\n").next().unwrap();
    let status: u16 = first_line.split_whitespace().nth(1).unwrap().parse().unwrap();
    let mut headers = Vec::new();
    for line in hdr_str.split("\r\n").skip(1) {
        if let Some(i) = line.find(':') {
            headers.push((line[..i].trim().to_lowercase(), line[i+1..].trim().to_string()));
        }
    }
    let is_chunked = headers.iter().any(|(k,v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));
    let body_bytes = if is_chunked { decode_chunked(body_raw) } else { body_raw.to_vec() };
    HttpResp { status, headers, body: String::from_utf8_lossy(&body_bytes).to_string() }
}

fn parse_amount(s: &str) -> i64 {
    let neg = s.starts_with('-');
    let s2 = if neg { &s[1..] } else { s };
    let (int_part, frac_part) = match s2.find('.') {
        Some(i) => (&s2[..i], &s2[i+1..]),
        None => (s2, ""),
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 { format!("{}0", frac_part) } else { frac_part.to_string() };
        cents += f.parse::<i64>().unwrap();
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(c: i64) -> String {
    let neg = c < 0;
    let a = if neg { -(c as i128) as i64 } else { c };
    let int_part = a / 100;
    let frac_part = a % 100;
    if neg {
        format!("-{}.{:02}", int_part, frac_part)
    } else {
        format!("{}.{:02}", int_part, frac_part)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    // Read client.json
    let cj_path = format!("{}/client.json", data_dir);
    let cj_str = std::fs::read_to_string(&cj_path).unwrap();
    let cj = json_parse(&cj_str.trim());
    let client_id = cj.get("client_id").unwrap().as_str().to_string();
    let client_secret = cj.get("client_secret").unwrap().as_str().to_string();
    let scope = cj.get("scope").unwrap().as_str().to_string();
    let page_size = match cj.get("page_size") {
        Some(JsonValue::Num(n)) => *n as usize,
        _ => 10,
    };

    // Parse URL
    let rest = base_url.strip_prefix("http://").unwrap();
    let (authority, base_path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, ""),
    };
    let (host, port) = match authority.rfind(':') {
        Some(i) => (&authority[..i], authority[i+1..].parse::<u16>().unwrap()),
        None => (authority, 80u16),
    };

    // Get token
    fn get_token(host: &str, port: u16, base_path: &str, client_id: &str, client_secret: &str, scope: &str) -> String {
        let enc_id = form_enc(client_id);
        let enc_secret = form_enc(client_secret);
        let joined = format!("{}:{}", enc_id, enc_secret);
        let b64 = base64_encode(joined.as_bytes());
        let body = format!("grant_type=client_credentials&scope={}", form_enc(scope));
        let hdrs = vec![
            ("Content-Type", "application/x-www-form-urlencoded".to_string()),
            ("Authorization", format!("Basic {}", b64)),
        ];
        let resp = http_req(host, port, "POST", &format!("{}/oauth/token", base_path), &hdrs, Some(&body));
        if resp.status != 200 {
            println!("ERROR {} {}", resp.status, resp.body);
            std::process::exit(0);
        }
        let j = json_parse(resp.body.trim());
        j.get("access_token").unwrap().as_str().to_string()
    }

    let mut token = get_token(host, port, base_path, &client_id, &client_secret, &scope);
    let mut reauth_count: usize = 0;
    let mut retry_count: usize = 0;
    let mut pages_count: usize = 0;
    let mut orders_count: usize = 0;

    let mut totals: HashMap<(String, String), i64> = HashMap::new();
    let mut status_counts: HashMap<String, usize> = HashMap::new();

    let mut cursor: Option<String> = None;
    let mut token_used_ok = false;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}/orders?limit={}&cursor={}", base_path, page_size, pct_enc(c))
        } else {
            format!("{}/orders?limit={}", base_path, page_size)
        };
        let hdrs = vec![("Authorization", format!("Bearer {}", token))];
        let resp = http_req(host, port, "GET", &path, &hdrs, None);

        match resp.status {
            200 => {
                pages_count += 1;
                token_used_ok = true;
                let j = json_parse(resp.body.trim());
                let data = j.get("data").unwrap();
                if let JsonValue::Arr(ref orders) = data {
                    for order in orders {
                        orders_count += 1;
                        let status = order.get("status").map(|v| v.as_str().to_string()).unwrap_or_default();
                        *status_counts.entry(status.clone()).or_insert(0) += 1;
                        if status != "cancelled" {
                            let currency = order.get("currency").map(|v| v.as_str().to_string()).unwrap_or_default();
                            let amount_str = order.get("amount").map(|v| v.as_str().to_string()).unwrap_or_else(|| "0".to_string());
                            let cents = parse_amount(&amount_str);
                            let name = order.get("customer")
                                .and_then(|c| c.get("name"))
                                .map(|v| v.as_str().to_string())
                                .unwrap_or_default();
                            *totals.entry((name, currency)).or_insert(0) += cents;
                        }
                    }
                }
                let nc = j.get("next_cursor");
                match nc {
                    Some(JsonValue::Null) | None => break,
                    Some(JsonValue::Str(s)) => { cursor = Some(s.clone()); }
                    _ => break,
                }
            }
            429 => {
                retry_count += 1;
                let ra = resp.headers.iter().find(|(k,_)| k == "retry-after").map(|(_,v)| v.parse::<u64>().unwrap_or(1)).unwrap_or(1);
                sleep(Duration::from_secs(ra));
            }
            503 => {
                retry_count += 1;
                sleep(Duration::from_millis(500));
            }
            401 => {
                if !token_used_ok {
                    println!("ERROR {} {}", resp.status, resp.body);
                    std::process::exit(0);
                }
                reauth_count += 1;
                token = get_token(host, port, base_path, &client_id, &client_secret, &scope);
                token_used_ok = false;
            }
            _ => {
                println!("ERROR {} {}", resp.status, resp.body);
                std::process::exit(0);
            }
        }
    }

    // Output totals
    let mut total_lines: Vec<(String, String, i64, String)> = totals.into_iter()
        .map(|((name, currency), cents)| (name, currency, cents, String::new()))
        .collect();
    total_lines.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));
    for (name, currency, cents, _) in &total_lines {
        println!("total {} {} {}", currency, fmt_cents(*cents), name);
    }

    // Output statuses
    let mut status_lines: Vec<(String, usize)> = status_counts.into_iter().collect();
    status_lines.sort_by(|a, b| a.0.cmp(&b.0));
    for (s, c) in &status_lines {
        println!("status {} {}", s, c);
    }

    // Final line
    println!("orders {} pages {} retries {} reauth {}", orders_count, pages_count, retry_count, reauth_count);
}
