#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* ============ Schema Structures ============ */
typedef enum {
    FT_INT32, FT_INT64, FT_UINT32, FT_UINT64, FT_SINT32, FT_SINT64,
    FT_BOOL, FT_STRING, FT_BYTES, FT_FIXED32, FT_FIXED64, FT_SFIXED32, FT_SFIXED64,
    FT_MESSAGE, FT_ENUM, FT_MAP
} FieldType;

#define MAXF 512
#define MAXO 64
#define MAXM 1024
#define MAXE 1024
#define MAXEV 512

typedef struct {
    char name[256];
    int field_num;
    FieldType type;
    int is_repeated;
    int is_optional;
    int oneof_idx;
    char type_name[256];
    FieldType map_key_type;
    FieldType map_val_type;
    char map_val_type_name[256];
} FieldDef;

typedef struct {
    char name[256];
    FieldDef fields[MAXF];
    int num_fields;
    char oneof_names[MAXO][64];
    int num_oneofs;
} MessageDef;

typedef struct {
    char name[256];
    struct { char name[64]; int value; } values[MAXEV];
    int num_values;
} EnumDef;

static MessageDef g_msgs[MAXM];
static int g_num_msgs;
static EnumDef g_enums[MAXE];
static int g_num_enums;

/* ============ Schema Parser ============ */
static const char *g_src;
static int g_src_len;
static int g_pos;

static void skip_ws(void) {
    while (g_pos < g_src_len) {
        char c = g_src[g_pos];
        if (c==' '||c=='\t'||c=='\n'||c=='\r') { g_pos++; }
        else if (c=='/' && g_pos+1<g_src_len && g_src[g_pos+1]=='/') {
            g_pos+=2; while(g_pos<g_src_len && g_src[g_pos]!='\n') g_pos++;
        } else if (c=='/' && g_pos+1<g_src_len && g_src[g_pos+1]=='*') {
            g_pos+=2;
            while(g_pos+1<g_src_len && !(g_src[g_pos]=='*'&&g_src[g_pos+1]=='/')) g_pos++;
            g_pos+=2;
        } else break;
    }
}

static int peek_ch(void) { skip_ws(); return g_pos<g_src_len ? (unsigned char)g_src[g_pos] : -1; }

static int is_id_start(int c){ return isalpha(c)||c=='_'; }
static int is_id_char(int c){ return isalnum(c)||c=='_'; }

static void read_ident(char *buf) {
    skip_ws();
    int i=0;
    while(g_pos<g_src_len && is_id_char((unsigned char)g_src[g_pos]))
        buf[i++]=g_src[g_pos++];
    buf[i]='\0';
}

static long long read_number(void) {
    skip_ws();
    int neg=0;
    if(g_pos<g_src_len && g_src[g_pos]=='-'){neg=1;g_pos++;}
    long long v=0;
    while(g_pos<g_src_len && isdigit((unsigned char)g_src[g_pos]))
        v=v*10+(g_src[g_pos++]-'0');
    return neg?-v:v;
}

static void read_str_lit(char *buf) {
    skip_ws();
    if(g_pos<g_src_len && g_src[g_pos]=='"') g_pos++;
    int i=0;
    while(g_pos<g_src_len && g_src[g_pos]!='"') buf[i++]=g_src[g_pos++];
    buf[i]='\0';
    if(g_pos<g_src_len) g_pos++;
}

static void skip_to_semi(void) {
    while(g_pos<g_src_len) {
        if(g_src[g_pos]=='"'){g_pos++;while(g_pos<g_src_len&&g_src[g_pos]!='"')g_pos++;if(g_pos<g_src_len)g_pos++;}
        else if(g_src[g_pos]==';'){g_pos++;return;}
        else g_pos++;
    }
}

static void skip_options(void) {
    skip_ws();
    if(g_pos>=g_src_len||g_src[g_pos]!='[') return;
    g_pos++;
    while(g_pos<g_src_len){
        if(g_src[g_pos]=='"'){g_pos++;while(g_pos<g_src_len&&g_src[g_pos]!='"')g_pos++;if(g_pos<g_src_len)g_pos++;}
        else if(g_src[g_pos]==']'){g_pos++;return;}
        else g_pos++;
    }
}

static int match_kw(const char *kw) {
    skip_ws();
    int len=strlen(kw);
    if(g_pos+len<=g_src_len && strncmp(g_src+g_pos,kw,len)==0 &&
       (g_pos+len>=g_src_len || !is_id_char((unsigned char)g_src[g_pos+len]))) {
        g_pos+=len; return 1;
    }
    return 0;
}

static void expect_ch(char c) { skip_ws(); if(g_pos<g_src_len&&g_src[g_pos]==c) g_pos++; }

static void parse_field(MessageDef *md, int oneof_idx) {
    FieldDef *fd = &md->fields[md->num_fields];
    memset(fd,0,sizeof(*fd));
    fd->oneof_idx = oneof_idx;
    fd->map_key_type = FT_INT32;
    fd->map_val_type = FT_INT32;

    skip_ws();
    char tok[256];
    /* check for label */
    int saved=g_pos;
    read_ident(tok);
    if(strcmp(tok,"repeated")==0){fd->is_repeated=1; read_ident(tok);}
    else if(strcmp(tok,"optional")==0){fd->is_optional=1; read_ident(tok);}
    else g_pos=saved;

    /* check for map */
    skip_ws();
    if(g_pos<g_src_len && g_src[g_pos]=='m') {
        saved=g_pos;
        read_ident(tok);
        if(strcmp(tok,"map")==0){
            fd->type=FT_MAP;
            expect_ch('<');
            char kt[64]; read_ident(kt);
            expect_ch(',');
            char vt[256]; read_ident(vt);
            expect_ch('>');
            if(strcmp(kt,"string")==0) fd->map_key_type=FT_STRING;
            else fd->map_key_type=FT_INT32;
            /* determine value type */
            if(strcmp(vt,"int32")==0)fd->map_val_type=FT_INT32;
            else if(strcmp(vt,"int64")==0)fd->map_val_type=FT_INT64;
            else if(strcmp(vt,"uint32")==0)fd->map_val_type=FT_UINT32;
            else if(strcmp(vt,"uint64")==0)fd->map_val_type=FT_UINT64;
            else if(strcmp(vt,"sint32")==0)fd->map_val_type=FT_SINT32;
            else if(strcmp(vt,"sint64")==0)fd->map_val_type=FT_SINT64;
            else if(strcmp(vt,"bool")==0)fd->map_val_type=FT_BOOL;
            else if(strcmp(vt,"string")==0)fd->map_val_type=FT_STRING;
            else if(strcmp(vt,"bytes")==0)fd->map_val_type=FT_BYTES;
            else if(strcmp(vt,"fixed32")==0)fd->map_val_type=FT_FIXED32;
            else if(strcmp(vt,"fixed64")==0)fd->map_val_type=FT_FIXED64;
            else if(strcmp(vt,"sfixed32")==0)fd->map_val_type=FT_SFIXED32;
            else if(strcmp(vt,"sfixed64")==0)fd->map_val_type=FT_SFIXED64;
            else { fd->map_val_type=FT_MESSAGE; strcpy(fd->map_val_type_name,vt); }
            read_ident(fd->name);
            expect_ch('=');
            fd->field_num=(int)read_number();
            skip_options();
            expect_ch(';');
            md->num_fields++;
            return;
        } else {
            g_pos=saved;
        }
    }

    /* regular field type */
    read_ident(tok);
    if(strcmp(tok,"int32")==0)fd->type=FT_INT32;
    else if(strcmp(tok,"int64")==0)fd->type=FT_INT64;
    else if(strcmp(tok,"uint32")==0)fd->type=FT_UINT32;
    else if(strcmp(tok,"uint64")==0)fd->type=FT_UINT64;
    else if(strcmp(tok,"sint32")==0)fd->type=FT_SINT32;
    else if(strcmp(tok,"sint64")==0)fd->type=FT_SINT64;
    else if(strcmp(tok,"bool")==0)fd->type=FT_BOOL;
    else if(strcmp(tok,"string")==0)fd->type=FT_STRING;
    else if(strcmp(tok,"bytes")==0)fd->type=FT_BYTES;
    else if(strcmp(tok,"fixed32")==0)fd->type=FT_FIXED32;
    else if(strcmp(tok,"fixed64")==0)fd->type=FT_FIXED64;
    else if(strcmp(tok,"sfixed32")==0)fd->type=FT_SFIXED32;
    else if(strcmp(tok,"sfixed64")==0)fd->type=FT_SFIXED64;
    else { /* message or enum - determine later */
        fd->type=FT_MESSAGE; /* placeholder, resolved at decode time */
        strcpy(fd->type_name,tok);
    }
    read_ident(fd->name);
    expect_ch('=');
    fd->field_num=(int)read_number();
    skip_options();
    expect_ch(';');
    md->num_fields++;
}

static void parse_enum(void) {
    char name[256]; read_ident(name);
    EnumDef *ed=&g_enums[g_num_enums++];
    memset(ed,0,sizeof(*ed));
    strcpy(ed->name,name);
    expect_ch('{');
    while(1){
        skip_ws();
        if(g_pos<g_src_len&&g_src[g_pos]=='}'){g_pos++;break;}
        if(match_kw("option")){skip_to_semi();continue;}
        char vn[64]; read_ident(vn);
        expect_ch('=');
        int v=(int)read_number();
        skip_options();
        expect_ch(';');
        if(ed->num_values<MAXEV){
            strcpy(ed->values[ed->num_values].name,vn);
            ed->values[ed->num_values].value=v;
            ed->num_values++;
        }
    }
}

static void parse_message(void) {
    char name[256]; read_ident(name);
    MessageDef *md=&g_msgs[g_num_msgs++];
    memset(md,0,sizeof(*md));
    strcpy(md->name,name);
    expect_ch('{');
    while(1){
        skip_ws();
        if(g_pos>=g_src_len) break;
        if(g_src[g_pos]=='}'){g_pos++;break;}
        int saved=g_pos;
        char tok[256]; read_ident(tok);
        if(strcmp(tok,"option")==0){skip_to_semi();}
        else if(strcmp(tok,"reserved")==0){skip_to_semi();}
        else if(strcmp(tok,"message")==0){parse_message();}
        else if(strcmp(tok,"enum")==0){parse_enum();}
        else if(strcmp(tok,"oneof")==0){
            char oname[64]; read_ident(oname);
            int oi=md->num_oneofs;
            if(oi<MAXO) strcpy(md->oneof_names[oi],oname);
            md->num_oneofs++;
            expect_ch('{');
            while(1){
                skip_ws();
                if(g_pos<g_src_len&&g_src[g_pos]=='}'){g_pos++;break;}
                parse_field(md,oi);
            }
        } else {
            g_pos=saved;
            parse_field(md,-1);
        }
    }
}

static void parse_file(void) {
    g_pos=0;
    while(1){
        skip_ws();
        if(g_pos>=g_src_len) break;
        int saved=g_pos;
        char tok[256]; read_ident(tok);
        if(strcmp(tok,"syntax")==0||strcmp(tok,"package")==0||strcmp(tok,"option")==0){
            skip_to_semi();
        } else if(strcmp(tok,"message")==0){
            parse_message();
        } else if(strcmp(tok,"enum")==0){
            parse_enum();
        } else {
            g_pos=saved;
            break;
        }
    }
}

/* ============ Lookup ============ */
static MessageDef *find_msg(const char *name){
    for(int i=0;i<g_num_msgs;i++) if(strcmp(g_msgs[i].name,name)==0) return &g_msgs[i];
    return NULL;
}
static EnumDef *find_enum(const char *name){
    for(int i=0;i<g_num_enums;i++) if(strcmp(g_enums[i].name,name)==0) return &g_enums[i];
    return NULL;
}

/* ============ Decoded Structures ============ */
typedef struct DecodedMsg DecodedMsg;
typedef struct {
    FieldType type;
    uint64_t bits;
    char *str;
    int str_len;
    DecodedMsg *msg;
} Val;

typedef struct { Val key; Val val; } MapEnt;

typedef struct {
    int wire_present;
    Val val;
    Val *elems; int ecount; int ecap;
    MapEnt *entries; int mcount; int mcap;
} FData;

struct DecodedMsg {
    MessageDef *schema;
    FData fields[MAXF];
    int num_fields;
    int oneof_set[MAXO];
};

static DecodedMsg *new_msg(MessageDef *schema){
    DecodedMsg *m=calloc(1,sizeof(DecodedMsg));
    m->schema=schema;
    m->num_fields=schema->num_fields;
    for(int i=0;i<MAXO;i++) m->oneof_set[i]=-1;
    return m;
}

static void reset_fd(FData *f){
    memset(f,0,sizeof(*f));
}

/* ============ Binary Helpers ============ */
static uint64_t read_vi(const uint8_t *d,int *p,int len){
    uint64_t r=0;int sh=0;
    for(int i=0;i<10&&*p<len;i++){
        uint8_t b=d[(*p)++];
        r|=(uint64_t)(b&0x7F)<<sh;
        if(!(b&0x80))break;
        sh+=7;
    }
    return r;
}
static uint32_t rd_f32(const uint8_t *d,int *p){uint32_t v;memcpy(&v,d+*p,4);*p+=4;return v;}
static uint64_t rd_f64(const uint8_t *d,int *p){uint64_t v;memcpy(&v,d+*p,8);*p+=8;return v;}

static void skip_unknown(const uint8_t *d,int *p,int len,int wt,int fn){
    switch(wt){
        case 0: read_vi(d,p,len);break;
        case 1: *p+=8;break;
        case 2:{int l=(int)read_vi(d,p,len);*p+=l;break;}
        case 3:{
            while(*p<len){
                int64_t k=(int64_t)read_vi(d,p,len);
                int f2=(int)(k>>3),w2=(int)(k&7);
                if(w2==4&&f2==fn)break;
                skip_unknown(d,p,len,w2,f2);
            }
            break;
        }
        case 4:break;
        case 5:*p+=4;break;
    }
}

/* ============ Resolve field type ============ */
static FieldType resolve_ft(FieldDef *fd){
    if(fd->type==FT_MESSAGE){
        if(find_enum(fd->type_name)) return FT_ENUM;
        return FT_MESSAGE;
    }
    return fd->type;
}
static FieldType resolve_map_vft(FieldDef *fd){
    if(fd->map_val_type==FT_MESSAGE){
        if(find_enum(fd->map_val_type_name)) return FT_ENUM;
    }
    return fd->map_val_type;
}

/* ============ Decode a single scalar value from wire ============ */
static void decode_scalar(const uint8_t *d,int *p,int len,FieldType ft,Val *v){
    v->type=ft; v->str=NULL; v->str_len=0; v->msg=NULL;
    switch(ft){
        case FT_INT32: v->bits=read_vi(d,p,len); break;
        case FT_INT64: v->bits=read_vi(d,p,len); break;
