/* ============ Decode packed repeated ============ */
static void decode_packed(const uint8_t *d,int *p,int len,FieldType ft,FData *f){
    int l=(int)read_vi(d,p,len);
    int end=*p+l;
    while(*p<end){
        if(f->ecount>=f->ecap){
            f->ecap=f->ecap?f->ecap*2:16;
            f->elems=realloc(f->elems,f->ecap*sizeof(Val));
        }
        decode_scalar(d,p,end,ft,&f->elems[f->ecount++]);
    }
}

