/* ============ Merge decoded messages ============ */
static void merge_into(DecodedMsg *dst, DecodedMsg *src){
    MessageDef *sch=dst->schema;
    for(int i=0;i<sch->num_fields;i++){
        FieldDef *fd=&sch->fields[i];
        FData *sf=&src->fields[i];
        FData *df=&dst->fields[i];
        if(!sf->wire_present) continue;
        FieldType ft=resolve_ft(fd);
        if(fd->is_repeated){
            if(sf->ecount>0){
                if(df->ecount+sf->ecount>df->ecap){
                    df->ecap=(df->ecount+sf->ecount)*2;
                    df->elems=realloc(df->elems,df->ecap*sizeof(Val));
                }
                memcpy(df->elems+df->ecount,sf->elems,sf->ecount*sizeof(Val));
                df->ecount+=sf->ecount;
            }
            df->wire_present=1;
        } else if(ft==FT_MAP){
            for(int j=0;j<sf->mcount;j++){
                int found=0;
                for(int k=0;k<df->mcount;k++){
                    int cmp;
                    if(fd->map_key_type==FT_STRING)
                        cmp=(df->entries[k].key.str_len==sf->entries[j].key.str_len&&
                             memcmp(df->entries[k].key.str,sf->entries[j].key.str,sf->entries[j].key.str_len)==0)?0:1;
                    else
                        cmp=(df->entries[k].key.bits==sf->entries[j].key.bits)?0:1;
                    if(cmp==0){df->entries[k].val=sf->entries[j].val;found=1;break;}
                }
                if(!found){
                    if(df->mcount>=df->mcap){df->mcap=df->mcap?df->mcap*2:8;df->entries=realloc(df->entries,df->mcap*sizeof(MapEnt));}
                    df->entries[df->mcount++]=sf->entries[j];
                }
            }
            df->wire_present=1;
        } else if(ft==FT_MESSAGE){
            if(fd->oneof_idx>=0){
                int oi=fd->oneof_idx;
                if(src->oneof_set[oi]==i){
                    if(dst->oneof_set[oi]==i && df->val.msg){
                        merge_into(df->val.msg,sf->val.msg);
                    } else {
                        if(dst->oneof_set[oi]>=0 && dst->oneof_set[oi]!=i) reset_fd(&dst->fields[dst->oneof_set[oi]]);
                        df->val=sf->val;
                        dst->oneof_set[oi]=i;
                    }
                    df->wire_present=1;
                }
            } else {
                if(df->wire_present && df->val.msg && sf->val.msg){
                    merge_into(df->val.msg,sf->val.msg);
                } else {
                    df->val=sf->val;
                }
                df->wire_present=1;
            }
        } else {
            /* singular scalar */
            if(fd->oneof_idx>=0){
                int oi=fd->oneof_idx;
                if(src->oneof_set[oi]==i){
                    if(dst->oneof_set[oi]>=0 && dst->oneof_set[oi]!=i) reset_fd(&dst->fields[dst->oneof_set[oi]]);
                    df->val=sf->val;
                    dst->oneof_set[oi]=i;
                    df->wire_present=1;
                }
            } else {
                df->val=sf->val;
                df->wire_present=1;
            }
        }
    }
    /* copy oneof_set for oneofs not handled above */
    for(int oi=0;oi<sch->num_oneofs;oi++){
        if(src->oneof_set[oi]>=0 && dst->oneof_set[oi]<0){
            dst->oneof_set[oi]=src->oneof_set[oi];
        }
    }
}

/* ============ Decode message from bytes ============ */
static DecodedMsg *decode_msg_bytes(const uint8_t *d,int *p,int len,MessageDef *schema){
    DecodedMsg *m=new_msg(schema);
    while(*p<len){
        uint64_t key=read_vi(d,p,len);
        int fn=(int)(key>>3);
        int wt=(int)(key&7);
        /* find field in schema */
        int fi=-1;
        for(int i=0;i<schema->num_fields;i++){
            if(schema->fields[i].field_num==fn){fi=i;break;}
        }
        if(fi<0){skip_unknown(d,p,len,wt,fn);continue;}
        FieldDef *fd=&schema->fields[fi];
        FieldType ft=resolve_ft(fd);
        FData *f=&m->fields[fi];

        if(fd->is_repeated){
            f->wire_present=1;
            if(ft==FT_STRING||ft==FT_BYTES){
                if(f->ecount>=f->ecap){f->ecap=f->ecap?f->ecap*2:16;f->elems=realloc(f->elems,f->ecap*sizeof(Val));}
                decode_scalar(d,p,len,ft,&f->elems[f->ecount++]);
            } else if(ft==FT_MESSAGE){
                if(f->ecount>=f->ecap){f->ecap=f->ecap?f->ecap*2:16;f->elems=realloc(f->elems,f->ecap*sizeof(Val));}
                int sl=(int)read_vi(d,p,len);
                int sp=*p; *p+=sl;
                MessageDef *sub=find_msg(fd->type_name);
                Val *ev=&f->elems[f->ecount++];
                memset(ev,0,sizeof(*ev));ev->type=FT_MESSAGE;
                ev->msg=decode_msg_bytes(d,&sp,sl,sub);
            } else {
                /* numeric/bool/enum: packed or unpacked */
                if(wt==2){
                    decode_packed(d,p,len,ft,f);
                } else {
                    if(f->ecount>=f->ecap){f->ecap=f->ecap?f->ecap*2:16;f->elems=realloc(f->elems,f->ecap*sizeof(Val));}
                    decode_scalar(d,p,len,ft,&f->elems[f->ecount++]);
                }
            }
        } else if(ft==FT_MAP){
            f->wire_present=1;
            int sl=(int)read_vi(d,p,len);
            int sp=*p; *p+=sl;
            /* decode entry: field1=key, field2=value */
            Val kv,vv;
            memset(&kv,0,sizeof(kv));memset(&vv,0,sizeof(vv));
            kv.type=fd->map_key_type;
            FieldType vft=resolve_map_vft(fd);
            vv.type=vft;
            int kend=sp+sl;
            while(sp<kend){
                uint64_t ek=read_vi(d,&sp,kend);
                int efn=(int)(ek>>3);
                int ewt=(int)(ek&7);
                if(efn==1){
                    if(fd->map_key_type==FT_STRING){
                        int kl=(int)read_vi(d,&sp,kend);
                        kv.str=(char*)(d+sp);kv.str_len=kl;sp+=kl;
                    } else {
                        kv.bits=read_vi(d,&sp,kend);
                    }
                } else if(efn==2){
                    if(vft==FT_MESSAGE){
                        int ml=(int)read_vi(d,&sp,kend);
                        int mp=sp;sp+=ml;
                        MessageDef *sub=find_msg(fd->map_val_type_name);
                        vv.msg=decode_msg_bytes(d,&mp,ml,sub);
                    } else if(vft==FT_STRING||vft==FT_BYTES){
                        int vl=(int)read_vi(d,&sp,kend);
                        vv.str=(char*)(d+sp);vv.str_len=vl;sp+=vl;
                    } else {
                        decode_scalar(d,&sp,kend,vft,&vv);
                    }
                } else {
                    skip_unknown(d,&sp,kend,ewt,efn);
                }
            }
            /* upsert */
            int found=0;
            for(int j=0;j<f->mcount;j++){
                int cmp;
                if(fd->map_key_type==FT_STRING)
                    cmp=(f->entries[j].key.str_len==kv.str_len&&memcmp(f->entries[j].key.str,kv.str,kv.str_len)==0)?0:1;
                else
                    cmp=(f->entries[j].key.bits==kv.bits)?0:1;
                if(cmp==0){f->entries[j].val=vv;found=1;break;}
            }
            if(!found){
                if(f->mcount>=f->mcap){f->mcap=f->mcap?f->mcap*2:8;f->entries=realloc(f->entries,f->mcap*sizeof(MapEnt));}
                f->entries[f->mcount].key=kv;
                f->entries[f->mcount].val=vv;
                f->mcount++;
            }
        } else if(ft==FT_MESSAGE){
            int sl=(int)read_vi(d,p,len);
            int sp=*p; *p+=sl;
            MessageDef *sub=find_msg(fd->type_name);
            DecodedMsg *nm=decode_msg_bytes(d,&sp,sl,sub);
            if(fd->oneof_idx>=0){
                int oi=fd->oneof_idx;
                if(m->oneof_set[oi]==fi && f->wire_present && f->val.msg){
                    merge_into(f->val.msg,nm);
                } else {
                    if(m->oneof_set[oi]>=0 && m->oneof_set[oi]!=fi) reset_fd(&m->fields[m->oneof_set[oi]]);
                    f->val.type=FT_MESSAGE; f->val.msg=nm;
                    m->oneof_set[oi]=fi;
                }
                f->wire_present=1;
            } else {
                if(f->wire_present && f->val.msg){
                    merge_into(f->val.msg,nm);
                } else {
                    f->val.type=FT_MESSAGE; f->val.msg=nm;
                }
                f->wire_present=1;
            }
        } else {
            /* singular scalar */
            Val tmp;
            memset(&tmp,0,sizeof(tmp));
            decode_scalar(d,p,len,ft,&tmp);
            if(fd->oneof_idx>=0){
                int oi=fd->oneof_idx;
                if(m->oneof_set[oi]>=0 && m->oneof_set[oi]!=fi) reset_fd(&m->fields[m->oneof_set[oi]]);
                f->val=tmp;
                m->oneof_set[oi]=fi;
            } else {
                f->val=tmp;
            }
            f->wire_present=1;
        }
    }
    return m;
}

/* ============ JSON Output ============ */
static void to_camel(const char *name,char *out){
    int j=0;
    for(int i=0;name[i];i++){
        if(name[i]=='_'){
            /* skip, handled by next iteration */
        } else {
            if(i>0&&name[i-1]=='_'&&name[i]>='a'&&name[i]<='z')
                out[j++]=name[i]-32;
            else
                out[j++]=name[i];
        }
    }
    out[j]='\0';
}

static void print_jstr(const char *s,int len){
    putchar('"');
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"')printf("\\\"");
        else if(c=='\\')printf("\\\\");
        else if(c=='\b')printf("\\b");
        else if(c=='\t')printf("\\t");
        else if(c=='\n')printf("\\n");
        else if(c=='\f')printf("\\f");
        else if(c=='\r')printf("\\r");
        else if(c<0x20)printf("\\u%04x",c);
        else putchar(c);
    }
    putchar('"');
}

static const char b64c[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void print_b64(const char *d,int len){
    putchar('"');
    int i=0;
    while(i<len){
        int n=0;int bits=0;int chars=0;
        for(int j=0;j<3;j++){
            n<<=8;
            if(i+j<len){n|=(unsigned char)d[i+j];chars++;}
        }
        for(int j=0;j<4;j++){
            if(j<=chars) putchar(b64c[(n>>(18-6*j))&0x3F]);
            else putchar('=');
        }
        i+=3;
    }
    putchar('"');
}

