def parse_sse(data_bytes):
    text = data_bytes.decode('utf-8')
    lines = []
    current = []
    i = 0
    while i < len(text):
        if text[i] == '\r':
            if i + 1 < len(text) and text[i + 1] == '\n':
                lines.append(''.join(current))
                current = []
                i += 2
            else:
                lines.append(''.join(current))
                current = []
                i += 1
        elif text[i] == '\n':
