  outputLines.push(`stop_reason ${sr1.stopReason}`);

  // Execute tools
  const toolBlocks = sr1.blocks.filter(b => b.type === 'tool_use');
  const toolResults: { id: string; content: string; isError: boolean }[] = [];
  for (const tb of toolBlocks) {
