            } else {
                cur.append(c);
            }
            i++;
        }
        if (cur.length() > 0) lines.add(cur.toString());

        String eventName = "";
        List<String> dataLines = new ArrayList<>();
        boolean hasData = false;

        for (String line : lines) {
            if (line.isEmpty()) {
                // dispatch event
                if (hasData) {
                    String data = String.join("\n", dataLines);
                    processEvent(eventName, data, pr);
                }
                eventName = "";
                dataLines.clear();
                hasData = false;
            } else if (line.startsWith(":")) {
                // comment, ignore
            } else if (line.startsWith("event:")) {
                String val = line.substring(6);
                if (val.startsWith(" ")) val = val.substring(1);
                eventName = val;
            } else if (line.startsWith("data:")) {
                String val = line.substring(5);
                if (val.startsWith(" ")) val = val.substring(1);
                dataLines.add(val);
                hasData = true;
            }
        }
        // dispatch last event if any
        if (hasData) {
            String data = String.join("\n", dataLines);
            processEvent(eventName, data, pr);
        }
    }

    static void processEvent(String eventName, String data, ParsedResponse pr) {
        if (eventName.equals("ping")) return;
        @SuppressWarnings("unchecked")
        Map<String, Object> obj = (Map<String, Object>) parseJson(data);
        String type = (String) obj.get("type");

        switch (type) {
            case "message_start": {
                @SuppressWarnings("unchecked")
                Map<String, Object> msg = (Map<String, Object>) obj.get("message");
                @SuppressWarnings("unchecked")
                Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
                if (usage != null) {
                    if (usage.get("input_tokens") != null) pr.inputTokens += ((Number) usage.get("input_tokens")).longValue();
                    if (usage.get("cache_read_input_tokens") != null) pr.cacheReadInputTokens += ((Number) usage.get("cache_read_input_tokens")).longValue();
                }
                break;
            }
            case "content_block_start": {
                int index = ((Number) obj.get("index")).intValue();
                @SuppressWarnings("unchecked")
                Map<String, Object> cb = (Map<String, Object>) obj.get("content_block");
                String btype = (String) cb.get("type");
                ContentBlock block = new ContentBlock();
                block.type = btype;
                if (btype.equals("thinking")) {
                    block.thinkingText = "";
                    block.signature = "";
                } else if (btype.equals("text")) {
                    block.text = "";
                } else if (btype.equals("tool_use")) {
                    block.id = (String) cb.get("id");
                    block.name = (String) cb.get("name");
                    block.partialJson = new StringBuilder();
                }
                while (pr.blocks.size() <= index) pr.blocks.add(null);
                pr.blocks.set(index, block);
                break;
            }
            case "content_block_delta": {
                int index = ((Number) obj.get("index")).intValue();
                @SuppressWarnings("unchecked")
                Map<String, Object> delta = (Map<String, Object>) obj.get("delta");
                String dtype = (String) delta.get("type");
                ContentBlock block = pr.blocks.get(index);
                if (dtype.equals("thinking_delta")) {
                    block.thinkingText += (String) delta.get("thinking");
                } else if (dtype.equals("signature_delta")) {
                    block.signature += (String) delta.get("signature");
                } else if (dtype.equals("text_delta")) {
                    block.text += (String) delta.get("text");
                } else if (dtype.equals("input_json_delta")) {
                    block.partialJson.append((String) delta.get("partial_json"));
                }
                break;
            }
            case "content_block_stop": {
                int index = ((Number) obj.get("index")).intValue();
                ContentBlock block = pr.blocks.get(index);
                if (block != null && block.type.equals("tool_use")) {
                    String raw = block.partialJson.toString();
                    block.inputJsonRaw = raw;
                    @SuppressWarnings("unchecked")
                    Map<String, Object> parsed = (Map<String, Object>) parseJson(raw);
                    block.inputParsed = parsed;
                }
                break;
            }
            case "message_delta": {
                @SuppressWarnings("unchecked")
                Map<String, Object> delta = (Map<String, Object>) obj.get("delta");
                if (delta != null && delta.get("stop_reason") != null) {
                    pr.stopReason = (String) delta.get("stop_reason");
                }
                @SuppressWarnings("unchecked")
                Map<String, Object> usage = (Map<String, Object>) obj.get("usage");
                if (usage != null && usage.get("output_tokens") != null) {
                    pr.outputTokens += ((Number) usage.get("output_tokens")).longValue();
                }
                break;
            }
            case "message_stop":
                break;
            default:
                break;
        }
    }

    static void printBlocks(List<ContentBlock> blocks) {
        for (ContentBlock cb : blocks) {
            if (cb == null) continue;
            if (cb.type.equals("thinking")) {
                out.println("thinking " + escape(cb.thinkingText));
                out.println("signature " + escape(cb.signature));
            } else if (cb.type.equals("text")) {
                out.println("text " + escape(cb.text));
            } else if (cb.type.equals("tool_use")) {
                out.println("tool_use " + cb.id + " " + cb.name + " " + escape(cb.inputJsonRaw));
            }
        }
    }

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c); break;
            }
        }
        return sb.toString();
    }

    static String executeTool(String name, Map<String, Object> input) {
        if (name.equals("measure")) {
            String text = (String) input.get("text");
            String unit = (String) input.get("unit");
            switch (unit) {
                case "code_points":
                    return String.valueOf(text.codePointCount(0, text.length()));
                case "utf8_bytes":
                    return String.valueOf(text.getBytes(StandardCharsets.UTF_8).length);
                case "utf16_units":
                    return String.valueOf(text.length());
                default:
                    throw new RuntimeException("unsupported unit: " + unit);
            }
        } else if (name.equals("reverse")) {
            String text = (String) input.get("text");
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return sb.toString();
        } else {
            throw new RuntimeException("unknown tool: " + name);
        }
    }

