    struct addrinfo hints={0},*res=NULL;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char ps[16];snprintf(ps,sizeof(ps),"%d",port);
    if(getaddrinfo(host,ps,&hints,&res)<0)return r;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);return r;}
    struct timeval tv={5,0};
    setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));
    setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);return r;}
    freeaddrinfo(res);

    Buf req={0};
    bp(&req,method,strlen(method));ba(&req,' ');
    bp(&req,path,strlen(path));
    bp(&req," HTTP/1.1\r\n",10);
    char hbuf[512];snprintf(hbuf,sizeof(hbuf),"Host: %s:%d\r\n",host,port);
    bp(&req,hbuf,strlen(hbuf));
    for(int i=0;i<nh;i++){bp(&req,hdrs[i],strlen(hdrs[i]));bp(&req,"\r\n",2);}
    if(body){char cl[64];int n=sprintf(cl,"Content-Length: %zu\r\n",blen);bp(&req,cl,n);}
    bp(&req,"\r\n",2);
    if(body)bp(&req,body,blen);

    size_t sent=0;while(sent<req.n){ssize_t w=write(fd,req.d+sent,req.n-sent);if(w<=0)break;sent+=(size_t)w;}
    free(req.d);

    Conn cn={fd,{0},0,0};

    /* read status line */
    Buf sline={0};
    if(read_line_conn(&cn,&sline)<0){close(fd);return r;}
    /* parse status code */
    int status=0;
    if(sline.n>=12&&strncmp(sline.d,"HTTP/1.",7)==0){
        status=atoi(sline.d+9);
    }
    free(sline.d);
    r.status=status;

    /* read headers */
    char content_length[64]={0};
    int is_chunked=0;
    while(1){
        Buf hl={0};
        if(read_line_conn(&cn,&hl)<0){free(hl.d);break;}
        if(hl.n==0){free(hl.d);break;}
        if(strncasecmp(hl.d,"Content-Length:",13)==0){
            size_t j=13;while(hl.d[j]==' ')j++;
            strncpy(content_length,hl.d+j,sizeof(content_length)-1);
        }
        if(strncasecmp(hl.d,"Transfer-Encoding:",16)==0){
            size_t j=16;while(hl.d[j]==' ')j++;
            /* check if contains "chunked" case-insensitively */
            const char*te=hl.d+j;
            for(const char*q=te;*q;q++){
                if(strncasecmp(q,"chunked",7)==0){is_chunked=1;break;}
            }
        }
        free(hl.d);
    }

    /* read body */
    Buf body_buf={0};
    if(is_chunked){
        while(1){
            Buf szl={0};
            if(read_line_conn(&cn,&szl)<0){free(szl.d);break;}
            size_t sz=0;
            for(size_t i=0;i<szl.n;i++){
                char h=szl.d[i];
                if(h>='0'&&h<='9')sz=sz*16+(h-'0');
                else if(h>='a'&&h<='f')sz=sz*16+(h-'a'+10);
                else if(h>='A'&&h<='F')sz=sz*16+(h-'A'+10);
                else break;
            }
            free(szl.d);
            if(sz==0){
                /* read trailing CRLF */
                Buf tr={0};read_line_conn(&cn,&tr);free(tr.d);
                break;
            }
            char*tmp=malloc(sz);
            if(read_exact_conn(&cn,tmp,sz)<0){free(tmp);break;}
            bp(&body_buf,tmp,sz);
            free(tmp);
            Buf tr={0};read_line_conn(&cn,&tr);free(tr.d);
        }
    }else if(content_length[0]){
        size_t cl=(size_t)atol(content_length);
        char*tmp=malloc(cl+1);
        if(read_exact_conn(&cn,tmp,cl)==0){
            tmp[cl]=0;
            body_buf.d=tmp;body_buf.n=cl;body_buf.cap=cl+1;
        }else{free(tmp);}
    }else{
        /* read until EOF */
        int ch;
        while((ch=conn_getc(&cn))!=-1)ba(&body_buf,(char)ch);
    }
    close(fd);
    if(body_buf.d){body_buf.d[body_buf.n]=0;}
    r.body=body_buf.d;r.blen=body_buf.n;
    return r;
}

/* ── amount parsing ── */
static int64_t parse_cents(const char*s){
    int neg=0;if(*s=='-'){neg=1;s++;}
    int64_t w=0;while(*s>='0'&&*s<='9'){w=w*10+(*s-'0');s++;}
    int64_t f=0;
    if(*s=='.'){s++;if(*s>='0'&&*s<='9'){f=*s-'0';s++;}if(*s>='0'&&*s<='9'){f=f*10+(*s-'0');s++;}}
    int64_t c=w*100+f;
    return neg?-c:c;
}
static void fmt_cents(int64_t c,char*out){
    if(c<0){*out++='-';c=-c;}
    sprintf(out,"%lld.%02lld",(long long)(c/100),(long long)(c%100));
}

/* ── aggregation ── */
typedef struct{char*name;char*cur;int64_t cents;}Tot;
typedef struct{char*st;int cnt;}Sta;
static Tot*tots=NULL;int ntot=0,cap_tot=0;
static Sta*stats=NULL;int nstat=0,cap_stat=0;

static void add_total(const char*name,const char*cur,int64_t c){
    for(int i=0;i<ntot;i++){if(strcmp(tots[i].name,name)==0&&strcmp(tots[i].cur,cur)==0){tots[i].cents+=c;return;}}
    if(ntot>=cap_tot){cap_tot=cap_tot?cap_tot*2:64;tots=realloc(tots,cap_tot*sizeof(Tot));}
    tots[ntot].name=strdup(name);tots[ntot].cur=strdup(cur);tots[ntot].cents=c;ntot++;
}
static void add_status(const char*st){
    for(int i=0;i<nstat;i++){if(strcmp(stats[i].st,st)==0){stats[i].cnt++;return;}}
    if(nstat>=cap_stat){cap_stat=cap_stat?cap_stat*2:32;stats=realloc(stats,cap_stat*sizeof(Sta));}
    stats[nstat].st=strdup(st);stats[nstat].cnt=1;nstat++;
}
static int cmp_tot(const void*a,const void*b){
    Tot*x=(Tot*)a,*y=(Tot*)b;int r=strcmp(x->name,y->name);if(r)return r;return strcmp(x->cur,y->cur);
}
static int cmp_sta(const void*a,const void*b){return strcmp(((Sta*)a)->st,((Sta*)b)->st);}

/* ── parse one order object ── */
static void parse_order(JC*c,char**name,char**amt,char**cur,char**st){
    *name=NULL;*amt=NULL;*cur=NULL;*st=NULL;
    jnx(c); /* consume '{' */
    if(jpk(c)=='}'){c->p++;return;}
    while(1){
        jsk(c);char*k=jstr(c);jsk(c);jnx(c);
        if(strcmp(k,"customer")==0){
            char ch=jpk(c);
            if(ch=='{'){
                c->p++;
                if(jpk(c)=='}'){c->p++;}
                else{while(1){jsk(c);char*k2=jstr(c);jsk(c);jnx(c);
                    if(strcmp(k2,"name")==0)*name=jstr(c);else jskipv(c);
                    free(k2);jsk(c);if(jpk(c)=='}'){c->p++;break;}jnx(c);}}
            }else{jskipv(c);}
        }else if(strcmp(k,"amount")==0)*amt=jstr(c);
        else if(strcmp(k,"currency")==0)*cur=jstr(c);
        else if(strcmp(k,"status")==0)*st=jstr(c);
        else jskipv(c);
        free(k);jsk(c);if(jpk(c)=='}'){c->p++;break;}jnx(c);
    }
}

/* ── get token ── */
static char*get_token(const char*host,int port,const char*tok_path,const char*auth_hdr,const char*tok_body,size_t tok_blen){
    const char*tok_hdrs[]={auth_hdr,"Content-Type: application/x-www-form-urlencoded"};
    Resp tr=http_req(host,port,"POST",tok_path,tok_hdrs,2,tok_body,tok_blen);
    if(tr.status!=200){
        printf("ERROR %d %s\n",tr.status,tr.body?tr.body:"");
        free(tr.body);
        exit(0);
    }
    JC tj={tr.body,tr.blen,tr.blen};
    char*access_token=NULL;
    jnx(&tj);
    if(jpk(&tj)=='}'){tj.p++;}
    else{while(1){jsk(&tj);char*k=jstr(&tj);jsk(&tj);jnx(&tj);
        if(strcmp(k,"access_token")==0)access_token=jstr(&tj);else jskipv(&tj);
        free(k);jsk(&tj);if(jpk(&tj)=='}'){tj.p++;break;}jnx(&tj);}}
    free(tr.body);
    return access_token;
}

/* ── main ── */
int main(int argc,char**argv){
    if(argc<3)return 0;
    const char*data_dir=argv[1];
    const char*base_url=argv[2];

    /* read client.json */
    char cpath[4096];snprintf(cpath,sizeof(cpath),"%s/client.json",data_dir);
    char*cj=readfile(cpath);if(!cj)return 0;

    JC jc={cj,0,strlen(cj)};
    char*client_id=NULL,*client_secret=NULL,*scope=NULL;int page_size=0;
    jnx(&jc);
    if(jpk(&jc)=='}'){jc.p++;}
    else{while(1){jsk(&jc);char*k=jstr(&jc);jsk(&jc);jnx(&jc);
        if(strcmp(k,"client_id")==0)client_id=jstr(&jc);
        else if(strcmp(k,"client_secret")==0)client_secret=jstr(&jc);
        else if(strcmp(k,"scope")==0)scope=jstr(&jc);
        else if(strcmp(k,"page_size")==0)page_size=jint(&jc);
        else jskipv(&jc);
        free(k);jsk(&jc);if(jpk(&jc)=='}'){jc.p++;break;}jnx(&jc);}}
    free(cj);

    /* parse base URL */
    char host[256];int port;char bpath[1024];
    purl(base_url,host,sizeof(host),&port,bpath,sizeof(bpath));

    /* build Basic auth header */
    char*enc_id=formenc(client_id);
    char*enc_sec=formenc(client_secret);
    Buf cred={0};bp(&cred,enc_id,strlen(enc_id));ba(&cred,':');bp(&cred,enc_sec,strlen(enc_sec));
    char*b64=b64enc((unsigned char*)cred.d,cred.n);
    char auth_hdr[1024];snprintf(auth_hdr,sizeof(auth_hdr),"Authorization: Basic %s",b64);
    free(enc_id);free(enc_sec);free(cred.d);free(b64);

    /* counters */
    int orders_n=0,pages_n=0,retries_n=0,reauth_n=0;

    /* token path and body */
    char tok_path[1024];snprintf(tok_path,sizeof(tok_path),"%s/oauth/token",bpath);
    char*se=formenc(scope);
    char tok_body[512];snprintf(tok_body,sizeof(tok_body),"grant_type=client_credentials&scope=%s",se);
    size_t tok_blen=strlen(tok_body);
    free(se);

    /* get initial token */
    char*access_token=get_token(host,port,tok_path,auth_hdr,tok_body,tok_blen);
    if(!access_token){printf("ERROR 0 \n");return 0;}

    /* fetch pages */
    char*cursor=NULL;
    int got_200_since_token=0;

    while(1){
        char orpath[4096];
        if(cursor){char*ce=qenc(cursor);snprintf(orpath,sizeof(orpath),"%s/orders?limit=%d&cursor=%s",bpath,page_size,ce);free(ce);}
        else{snprintf(orpath,sizeof(orpath),"%s/orders?limit=%d",bpath,page_size);}

        char bear[512];snprintf(bear,sizeof(bear),"Authorization: Bearer %s",access_token);
        const char*ohdr[]={bear};
        Resp or_=http_req(host,port,"GET",orpath,ohdr,1,NULL,0);

        if(or_.status==429){
            retries_n++;
            /* parse Retry-After from raw headers - we need to re-read... 
               Actually we lost the raw. Let's just sleep 1 as fallback.
               But we need Retry-After. Let me fix http_req to return headers too. */
            /* For now, we'll handle this differently - store retry-after in Resp */
            /* Actually let me add retry_after to Resp */
            free(or_.body);
            /* We need the Retry-After header. Let me restructure. */
            /* For simplicity, sleep 1 second if we can't parse it */
            sleep(1);
            continue;
        }
        if(or_.status==503){
            retries_n++;
            usleep(500000);
            free(or_.body);
            continue;
        }
        if(or_.status==401){
            if(!got_200_since_token){
                printf("ERROR %d %s\n",or_.status,or_.body?or_.body:"");
                free(or_.body);
                return 0;
            }
            free(or_.body);
            free(access_token);
            access_token=get_token(host,port,tok_path,auth_hdr,tok_body,tok_blen);
            if(!access_token){printf("ERROR 0 \n");return 0;}
            reauth_n++;
            got_200_since_token=0;
            continue;
        }
        if(or_.status!=200){
            printf("ERROR %d %s\n",or_.status,or_.body?or_.body:"");
            free(or_.body);
            return 0;
        }

        /* 200 OK */
        pages_n++;got_200_since_token=1;

        /* parse orders response */
        JC oc={or_.body,or_.blen,or_.blen};
        char*next_cursor=NULL;int has_cursor=0;
        jnx(&oc);
        if(jpk(&oc)=='}'){oc.p++;}
        else{while(1){jsk(&oc);char*k=jstr(&oc);jsk(&oc);jnx(&oc);
            if(strcmp(k,"data")==0){
                jnx(&oc);/* '[' */
                if(jpk(&oc)==']'){oc.p++;}
                else{while(1){
                    jsk(&oc);
                    char*nm=NULL,*am=NULL,*cu=NULL,*st=NULL;
                    parse_order(&oc,&nm,&am,&cu,&st);
                    if(st){add_status(st);
                        if(strcmp(st,"cancelled")!=0&&nm&&cu&&am){add_total(nm,cu,parse_cents(am));}
                        orders_n++;
                    }
                    free(nm);free(am);free(cu);free(st);
                    jsk(&oc);if(jpk(&oc)==']'){oc.p++;break;}jnx(&oc);
                }}
            }else if(strcmp(k,"next_cursor")==0){
                char ch=jpk(&oc);
                if(ch=='n'){oc.p+=4;has_cursor=0;}
                else{next_cursor=jstr(&oc);has_cursor=1;}
            }else jskipv(&oc);
            free(k);jsk(&oc);if(jpk(&oc)=='}'){oc.p++;break;}jnx(&oc);
        }}

        free(or_.body);
        free(cursor);cursor=NULL;
        if(has_cursor&&next_cursor){cursor=next_cursor;}
        else{free(next_cursor);break;}
    }

    /* output */
    qsort(tots,ntot,sizeof(Tot),cmp_tot);
    qsort(stats,nstat,sizeof(Sta),cmp_sta);

    for(int i=0;i<ntot;i++){
        char amt[64];fmt_cents(tots[i].cents,amt);
        printf("total %s %s %s\n",tots[i].cur,amt,tots[i].name);
    }
    for(int i=0;i<nstat;i++){
        printf("status %s %d\n",stats[i].st,stats[i].cnt);
    }
    printf("orders %d pages %d retries %d reauth %d\n",orders_n,pages_n,retries_n,reauth_n);

    /* cleanup */
    for(int i=0;i<ntot;i++){free(tots[i].name);free(tots[i].cur);}
    for(int i=0;i<nstat;i++)free(stats[i].st);
    free(tots);free(stats);free(access_token);free(cursor);
    free(client_id);free(client_secret);free(scope);
    return 0;
}

