Looking at the timeout issue, the main problem is the HTTP response reading loop reads until EOF (`read()` returns 0), which can block for the full socket timeout (30s) even though the response is complete. The fix is to read headers first, then read exactly the body based on `Content-Length` or `Transfer-Encoding: chunked`. I also replaced `strcasestr` (not reliably available with `-std=c17` on macOS) and tightened the socket timeout.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>
#include <errno.h>
#include <ctype.h>

/* ── dynamic buffer ── */
typedef struct{char*d;size_t n,cap;}Buf;
static void bi(Buf*b){b->d=NULL;b->n=0;b->cap=0;}
static void bg(Buf*b,size_t x){if(b->n+x>b->cap){b->cap=(b->n+x)*2+256;b->d=realloc(b->d,b->cap);}}
static void ba(Buf*b,char c){bg(b,1);b->d[b->n++]=c;}
static void bp(Buf*b,const void*s,size_t n){bg(b,n);memcpy(b->d+b->n,s,n);b->n+=n;}

/* ── base64 ── */
static const char B64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char*b64enc(const unsigned char*d,size_t n){
    size_t o=4*((n+2)/3);char*r=malloc(o+1);size_t j=0;
    for(size_t i=0;i<n;i+=3){
        uint32_t v=((uint32_t)d[i])<<16;
        if(i+1<n)v|=((uint32_t)d[i+1])<<8;
        if(i+2<n)v|=(uint32_t)d[i+2];
        r[j++]=B64[(v>>18)&63];r[j++]=B64[(v>>12)&63];
        r[j++]=(i+1<n)?B64[(v>>6)&63]:'=';
        r[j++]=(i+2<n)?B64[v&63]:'=';
    }
    r[j]=0;return r;
}

/* ── form-urlencoded (RFC 6749 §2.3.1) ── */
static char*formenc(const char*s){
    Buf b={0};
    for(const char*p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='*')ba(&b,c);
        else if(c==' ')ba(&b,'+');
        else{ba(&b,'%');ba(&b,"0123456789ABCDEF"[c>>4]);ba(&b,"0123456789ABCDEF"[c&15]);}
    }
    ba(&b,0);return b.d;
}

/* ── percent-encode for query ── */
static char*qenc(const char*s){
    Buf b={0};
    for(const char*p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='~')ba(&b,c);
        else{ba(&b,'%');ba(&b,"0123456789ABCDEF"[c>>4]);ba(&b,"0123456789ABCDEF"[c&15]);}
    }
    ba(&b,0);return b.d;
}

/* ── JSON parser ── */
typedef struct{const char*s;size_t p,len;}JC;
static void jsk(JC*c){while(c->p<c->len&&isspace((unsigned char)c->s[c->p]))c->p++;}
static char jpk(JC*c){jsk(c);return c->p<c->len?c->s[c->p]:0;}
static char jnx(JC*c){jsk(c);return c->p<c->len?c->s[c->p++]:0;}
static uint32_t hx4(JC*c){uint32_t v=0;for(int i=0;i<4;i++){char h=c->s[c->p++];v<<=4;if(h<='9')v|=h-'0';else if(h<='f')v|=h-'a'+10;else v|=h-'A'+10;}return v;}
static void u8(Buf*b,uint32_t cp){
    if(cp<0x80)ba(b,(char)cp);
    else if(cp<0x800){ba(b,(char)(0xC0|(cp>>6)));ba(b,(char)(0x80|(cp&0x3F)));}
    else if(cp<0x10000){ba(b,(char)(0xE0|(cp>>12)));ba(b,(char)(0x80|((cp>>6)&0x3F)));ba(b,(char)(0x80|(cp&0x3F)));}
    else{ba(b,(char)(0xF0|(cp>>18)));ba(b,(char)(0x80|((cp>>12)&0x3F)));ba(b,(char)(0x80|((cp>>6)&0x3F)));ba(b,(char)(0x80|(cp&0x3F)));}
}
static char*jstr(JC*c){
    Buf b={0};c->p++;
    while(c->p<c->len&&c->s[c->p]!='"'){
        if(c->s[c->p]=='\\'){
            c->p++;
            char e=c->s[c->p];
            switch(e){
                case'"':ba(&b,'"');c->p++;break;
                case'\\':ba(&b,'\\');c->p++;break;
                case'/':ba(&b,'/');c->p++;break;
                case'b':ba(&b,'\b');c->p++;break;
                case'f':ba(&b,'\f');c->p++;break;
                case'n':ba(&b,'\n');c->p++;break;
                case'r':ba(&b,'\r');c->p++;break;
                case't':ba(&b,'\t');c->p++;break;
                case'u':{c->p++;uint32_t cp=hx4(c);
                    if(cp>=0xD800&&cp<=0xDBFF&&c->p+1<c->len&&c->s[c->p]=='\\'&&c->s[c->p+1]=='u'){
                        c->p+=2;uint32_t lo=hx4(c);cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    u8(&b,cp);break;}
                default:ba(&b,e);c->p++;break;
            }
        }else{ba(&b,c->s[c->p]);c->p++;}
    }
    if(c->p<c->len)c->p++;
    ba(&b,0);return b.d;
}
static void jskipv(JC*c){
    char ch=jpk(c);
    if(ch=='"'){c->p++;while(c->p<c->len){if(c->s[c->p]=='\\')c->p+=2;else if(c->s[c->p]=='"'){c->p++;break;}else c->p++;}}
    else if(ch=='{'||ch=='['){int d=1;c->p++;while(c->p<c->len&&d>0){if(c->s[c->p]=='"'){c->p++;while(c->p<c->len){if(c->s[c->p]=='\\')c->p+=2;else if(c->s[c->p]=='"'){c->p++;break;}else c->p++;}}else if(c->s[c->p]=='{'||c->s[c->p]=='[')d++;else if(c->s[c->p]=='}'||c->s[c->p]==']')d--;else c->p++;}}
    else{while(c->p<c->len&&c->s[c->p]!=','&&c->s[c->p]!='}'&&c->s[c->p]!=']'&&!isspace((unsigned char)c->s[c->p]))c->p++;}
}
static int jint(JC*c){jsk(c);int v=0,neg=0;if(c->p<c->len&&c->s[c->p]=='-'){neg=1;c->p++;}while(c->p<c->len&&isdigit((unsigned char)c->s[c->p])){v=v*10+(c->s[c->p]-'0');c->p++;}return neg?-v:v;}

/* ── file I/O ── */
static char*readfile(const char*path){
    FILE*f=fopen(path,"rb");if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*b=malloc(sz+1);fread(b,1,sz,f);b[sz]=0;fclose(f);return b;
}

/* ── URL parse ── */
static void purl(const char*url,char*host,size_t hsz,int*port,char*path,size_t psz){
    const char*p=strstr(url,"://");if(p)p+=3;else p=url;
    const char*sl=strchr(p,'/');const char*co=strchr(p,':');
    if(co&&(!sl||co<sl)){size_t hl=(size_t)(co-p);if(hl>=hsz)hl=hsz-1;memcpy(host,p,hl);host[hl]=0;*port=atoi(co+1);}
    else{size_t hl=sl?(size_t)(sl-p):strlen(p);if(hl>=hsz)hl=hsz-1;memcpy(host,p,hl);host[hl]=0;*port=80;}
    if(sl){size_t pl=strlen(sl);if(pl>=psz)pl=psz-1;memcpy(path,sl,pl);path[pl]=0;}
    else{path[0]='/';path[1]=0;}
}

/* ── buffered connection reader ── */
typedef struct{int fd;char buf[8192];size_t pos,len;}Conn;
static int conn_getc(Conn*c){
    if(c->pos>=c->len){
        ssize_t n=read(c->fd,c->buf,sizeof(c->buf));
        if(n<=0)return -1;
        c->pos=0;c->len=(size_t)n;
    }
    return (unsigned char)c->buf[c->pos++];
}
static int read_line_conn(Conn*c,Buf*out){
    int ch;
    while((ch=conn_getc(c))!=-1){
        if(ch=='\n')return 0;
        if(ch!='\r')ba(out,ch);
    }
    return -1;
}
static int read_exact_conn(Conn*c,char*dst,size_t n){
    size_t got=0;
    while(got<n){
        int ch=conn_getc(c);
        if(ch==-1)return -1;
        dst[got++]=(char)ch;
    }
    return 0;
}

/* ── HTTP response ── */
typedef struct{int status;char*body;size_t blen;}Resp;

static int hdr_get_line(const char*line,const char*name,char*val,size_t vsz){
    size_t nl=strlen(name);
    if(strncasecmp(line,name,nl)!=0)return 0;
    if(line[nl]!=':')return 0;
    size_t j=nl+1;while(line[j]==' ')j++;
    size_t vl=strlen(line+j);
    if(vl>=vsz)vl=vsz-1;
    memcpy(val,line+j,vl);val[vl]=0;
    return 1;
}

static Resp http_req(const char*host,int port,const char*method,const char*path,const char*hdrs[],int nh,const char*body,size_t blen){
    Resp r={0,NULL,0};
    struct addrinfo hints={0},*res=NULL;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char ps[16];snprintf(ps,sizeof(ps),"%d",port);
    if(getaddrinfo(host,ps,&hints,&res)<0)return r;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);return r;}
    struct timeval tv={5,0};
    setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));
    setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);return r;}
    freeaddrinfo(res);

    Buf req={0};
    bp(&req,method,strlen(method));ba(&req,' ');
    bp(&req,path,strlen(path));
    bp(&req," HTTP/1.1\r\n",10);
    char hbuf[512];snprintf(hbuf,sizeof(hbuf),"Host: %s:%d\r\n",host,port);
    bp(&req,hbuf,strlen(hbuf));
    for(int i=0;i<nh;i++){bp(&req,hdrs[i],strlen(hdrs[i]));bp(&req,"\r\n",2);}
    if(body){char cl[64];int n=sprintf(cl,"Content-Length: %zu\r\n",blen);bp(&req,cl,n);}
    bp(&req,"\r\n",2);
    if(body)bp(&req,body,blen);

    size_t sent=0;while(sent<req.n){ssize_t w=write(fd,req.d+sent,req.n-sent);if(w<=0)break;sent+=(size_t)w;}
    free(req.d);

    Conn cn={fd,{0},0,0};

    /* read status line */
    Buf sline={0};
    if(read_line_conn(&cn,&sline)<0){close(fd);return r;}
    /* parse status code */
    int status=0;
    if(sline.n>=12&&strncmp(sline.d,"HTTP/1.",7)==0){
        status=atoi(sline.d+9);
    }
    free(sline.d);
    r.status=status;

    /* read headers */
    char content_length[64]={0};
    int is_chunked=0;
    while(1){
        Buf hl={0};
        if(read_line_conn(&cn,&hl)<0){free(hl.d);break;}
        if(hl.n==0){free(hl.d);break;}
        if(strncasecmp(hl.d,"Content-Length:",13)==0){
            size_t j=13;while(hl.d[j]==' ')j++;
            strncpy(content_length,hl.d+j,sizeof(content_length)-1);
        }
        if(strncasecmp(hl.d,"Transfer-Encoding:",16)==0){
            size_t j=16;while(hl.d[j]==' ')j++;
            /* check if contains "chunked" case-insensitively */
            const char*te=hl.d+j;
            for(const char*q=te;*q;q++){
                if(strncasecmp(q,"chunked",7)==0){is_chunked=1;break;}
            }
        }
        free(hl.d);
    }

    /* read body */
    Buf body_buf={0};
    if(is_chunked){
        while(1){
            Buf szl={0};
            if(read_line_conn(&cn,&szl)<0){free(szl.d);break;}
            size_t sz=0;
            for(size_t i=0;i<szl.n;i++){
                char h=szl.d[i];
                if(h>='0'&&h<='9')sz=sz*16+(h-'0');
                else if(h>='a'&&h<='f')sz=sz*16+(h-'a'+10);
                else if(h>='A'&&h<='F')sz=sz*16+(h-'A'+10);
                else break;
            }
            free(szl.d);
            if(sz==0){
                /* read trailing CRLF */
                Buf tr={0};read_line_conn(&cn,&tr);free(tr.d);
                break;
            }
            char*tmp=malloc(sz);
            if(read_exact_conn(&cn,tmp,sz)<0){free(tmp);break;}
            bp(&body_buf,tmp,sz);
            free(tmp);
            Buf tr={0};read_line_conn(&cn,&tr);free(tr.d);
        }
    }else if(content_length[0]){
        size_t cl=(size_t)atol(content_length);
        char*tmp=malloc(cl+1);
        if(read_exact_conn(&cn,tmp,cl)==0){
            tmp[cl]=0;
            body_buf.d=tmp;body_buf.n=cl;body_buf.cap=cl+1;
        }else{free(tmp);}
    }else{
        /* read until EOF */
        int ch;
        while((ch=conn_getc(&cn))!=-1)ba(&body_buf,(char)ch);
    }
    close(fd);
    if(body_buf.d){body_buf.d[body_buf.n]=0;}
    r.body=body_buf.d;r.blen=body_buf.n;
    return r;
}

