    var result = [(Int, [UInt8])]()
    for st in serialTypes {
        var d = [UInt8]()
        switch st {
        case 0: break
        case 1: if pos+1 <= payload.count { d = Array(payload[pos..<pos+1]) }; pos += 1
        case 2: if pos+2 <= payload.count { d = Array(payload[pos..<pos+2]) }; pos += 2
        case 3: if pos+3 <= payload.count { d = Array(payload[pos..<pos+3]) }; pos += 3
        case 4: if pos+4 <= payload.count { d = Array(payload[pos..<pos+4]) }; pos += 4
        case 5: if pos+6 <= payload.count { d = Array(payload[pos..<pos+6]) }; pos += 6
        case 6: if pos+8 <= payload.count { d = Array(payload[pos..<pos+8]) }; pos += 8
        case 7: if pos+8 <= payload.count { d = Array(payload[pos..<pos+8]) }; pos += 8
        case 8, 9: break
        default:
            if st >= 12 {
                let len = (st - 12) / 2
                if pos + len <= payload.count { d = Array(payload[pos..<pos+len]) }
                pos += len
            }
        }
        result.append((st, d))
