// MARK: - TEXT escaping

func escapeText(_ raw: [UInt8]) -> String {
    var result = "\""
    var i = 0
    while i < raw.count {
        let b = raw[i]
        switch b {
        case 0x5C: result += "\\\\"; i += 1
        case 0x22: result += "\\\""; i += 1
        case 0x0A: result += "\\n"; i += 1
        case 0x0D: result += "\\r"; i += 1
        case 0x09: result += "\\t"; i += 1
        default:
            if b < 0x20 || b == 0x7F {
                result += String(format: "\\x%02X", b); i += 1
            } else if b < 0x80 {
                result.append(Character(UnicodeScalar(b))); i += 1
            } else {
                var seqLen = 1
                if b >= 0xF0 { seqLen = 4 }
                else if b >= 0xE0 { seqLen = 3 }
                else if b >= 0xC0 { seqLen = 2 }
                let end = min(i + seqLen, raw.count)
                if let s = String(bytes: raw[i..<end], encoding: .utf8) { result += s }
                i = end
            }
        }
    }
    result += "\""
    return result
}

// MARK: - Format a single value

func formatValue(_ st: Int, _ d: [UInt8], _ rowid: Int64, _ isRowidAlias: Bool) -> String {
    if isRowidAlias {
        return String(rowid)
    }
    switch st {
    case 0: return "NULL"
    case 1,2,3,4,5,6,8,9: return String(extractInt(st, d))
    case 7: return formatReal(d)
    default:
        let isText = (st % 2 == 1)
        let len = d.count
        if len <= 100 {
            if isText { return escapeText(d) }
            else {
                var s = "X'"
                for b in d { s += String(format: "%02X", b) }
                s += "'"
                return s
            }
        } else {
            let c = crc32(d)
            let kind = isText ? "TEXT" : "BLOB"
            return "<\(kind) len=\(len) crc32=\(String(format: "%08x", c))>"
        }
    }
}

// MARK: - CREATE TABLE parsing

func parseColumnDefs(_ sql: String) -> [(name: String, isRowidAlias: Bool)] {
    let s = Array(sql)
    // Find first '(' not inside double quotes
    var inQuote = false
    var openParen = -1
    for i in 0..<s.count {
        if s[i] == "\"" { inQuote.toggle() }
        else if s[i] == "(" && !inQuote { openParen = i; break }
    }
    guard openParen >= 0 else { return [] }

    // Find matching ')'
    var depth = 0
    var closeParen = -1
    inQuote = false
    for i in openParen..<s.count {
        if s[i] == "\"" { inQuote.toggle() }
        else if !inQuote {
            if s[i] == "(" { depth += 1 }
            else if s[i] == ")" { depth -= 1; if depth == 0 { closeParen = i; break } }
        }
    }
    guard closeParen > openParen else { return [] }

    let inner = String(s[(openParen+1)..<closeParen])
    let innerArr = Array(inner)

    // Split by top-level commas
    var defs = [String]()
    var cur = ""
    var d2 = 0
    inQuote = false
    for c in innerArr {
        if c == "\"" { inQuote.toggle(); cur.append(c) }
        else if inQuote { cur.append(c) }
        else if c == "(" { d2 += 1; cur.append(c) }
        else if c == ")" { d2 -= 1; cur.append(c) }
        else if c == "," && d2 == 0 { defs.append(cur); cur = "" }
        else { cur.append(c) }
    }
    if !cur.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { defs.append(cur) }

    var cols = [(name: String, isRowidAlias: Bool)]()
    for def in defs {
        let trimmed = def.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { continue }
        let ta = Array(trimmed)
        var idx = 0
        var colName = ""

        // Read column name
        if ta[idx] == "\"" {
            idx += 1
            while idx < ta.count && ta[idx] != "\"" { colName.append(ta[idx]); idx += 1 }
            if idx < ta.count { idx += 1 } // skip closing quote
        } else {
            while idx < ta.count && (ta[idx].isLetter || ta[idx].isNumber || ta[idx] == "_") {
                colName.append(ta[idx]); idx += 1
            }
        }

        // Rest of definition (may be empty)
        let rest: String
        if idx < ta.count {
            rest = String(ta[idx...])
        } else {
            rest = ""
        }
        let restTrimmed = rest.trimmingCharacters(in: .whitespacesAndNewlines)
        let restUpper = restTrimmed.uppercased()

        // Extract type: first word after name
        var typeName = ""
        let rtArr = Array(restTrimmed)
        var ti = 0
        while ti < rtArr.count && (rtArr[ti].isLetter || rtArr[ti].isNumber || rtArr[ti] == "_") {
            typeName.append(rtArr[ti]); ti += 1
        }

        // Check if type is followed by '(' → parameterized, not plain INTEGER
        let afterType: Character = ti < rtArr.count ? rtArr[ti] : Character(" ")
        let isPlainInteger = typeName.uppercased() == "INTEGER" && afterType != "("

        let hasPK = restUpper.contains("PRIMARY") && restUpper.contains("KEY")
        let isRowid = isPlainInteger && hasPK

        cols.append((colName, isRowid))
    }
    return cols
}

// MARK: - Read schema

struct TableInfo {
    let name: String
    let rootPage: Int
    let sql: String
}

let schemaRows = walkBTree(1)
var tables = [TableInfo]()

for (_, payload) in schemaRows {
    let fields = parseRecord(payload)
    guard fields.count >= 5 else { continue }
    // type, name, tbl_name, rootpage, sql
    let typeField = fields[0]
    let nameField = fields[1]
    let rootField = fields[3]
    let sqlField = fields[4]

    guard typeField.0 >= 12 && typeField.0 % 2 == 1 else { continue } // TEXT
    let typeStr = String(bytes: typeField.1, encoding: .utf8) ?? ""
    guard typeStr == "table" else { continue }

    guard nameField.0 >= 12 && nameField.0 % 2 == 1 else { continue }
    let nameStr = String(bytes: nameField.1, encoding: .utf8) ?? ""
    guard !nameStr.hasPrefix("sqlite_") else { continue }

    var rootPg = 0
    if rootField.0 >= 1 { rootPg = Int(extractInt(rootField.0, rootField.1)) }

    var sqlStr = ""
    if sqlField.0 >= 12 && sqlField.0 % 2 == 1 {
        sqlStr = String(bytes: sqlField.1, encoding: .utf8) ?? ""
    }

    tables.append(TableInfo(name: nameStr, rootPage: rootPg, sql: sqlStr))
}

// Sort by name byte-wise
tables.sort { a, b in
    let ab = Array(a.name.utf8)
    let bb = Array(b.name.utf8)
    let minLen = min(ab.count, bb.count)
    for i in 0..<minLen {
        if ab[i] < bb[i] { return true }
        if ab[i] > bb[i] { return false }
    }
    return ab.count < bb.count
}

// MARK: - Output

var output = ""
var firstTable = true

for tbl in tables {
    let cols = parseColumnDefs(tbl.sql)
    let rows = walkBTree(tbl.rootPage)
    // Sort by rowid ascending
    let sortedRows = rows.sorted { $0.0 < $1.0 }

    if !firstTable { output += "\n" }
    firstTable = false

    output += "TABLE \(tbl.name) rows=\(sortedRows.count)\n"
    output += "COLUMNS " + cols.map { $0.name }.joined(separator: ", ") + "\n"

    for (rowid, payload) in sortedRows {
        let fields = parseRecord(payload)
        var vals = [String]()
        for ci in 0..<cols.count {
            if ci < fields.count {
                let (st, d) = fields[ci]
                vals.append(formatValue(st, d, rowid, cols[ci].isRowidAlias))
            } else {
                // Missing column (ALTER TABLE ADD COLUMN)
                if cols[ci].isRowidAlias {
                    vals.append(String(rowid))
                } else {
                    vals.append("NULL")
                }
            }
        }
        output += "\(rowid): " + vals.joined(separator: ", ") + "\n"
    }
}

