// --- Compact JSON serializer for tool results ---
function serializeString(s: string): string {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const cp = s.codePointAt(i)!;
    if (cp === 0x22) out += '\\"';
    else if (cp === 0x5C) out += '\\\\';
    else if (cp === 0x08) out += '\\b';
    else if (cp === 0x0C) out += '\\f';
    else if (cp === 0x0A) out += '\\n';
    else if (cp === 0x0D) out += '\\r';
    else if (cp === 0x09) out += '\\t';
    else if (cp < 0x20) out += '\\u' + cp.toString(16).padStart(4, '0');
    else {
      out += String.fromCodePoint(cp);
      if (cp > 0xFFFF) i++;
    }
  }
  return out + '"';
}

function serializeJSON(obj: any): string {
  if (obj === null) return 'null';
  if (typeof obj === 'number') return String(obj);
  if (typeof obj === 'boolean') return obj ? 'true' : 'false';
  if (typeof obj === 'string') return serializeString(obj);
  if (Array.isArray(obj)) {
    return '[' + obj.map(serializeJSON).join(',') + ']';
  }
  if (typeof obj === 'object') {
    const keys = Object.keys(obj);
    return '{' + keys.map(k => serializeString(k) + ':' + serializeJSON(obj[k])).join(',') + '}';
  }
  return 'null';
}

// --- HTTP request ---
function makeRequest(baseUrl: string, apiKey: string, body: object): Promise<{ status: number; body: any }> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/chat/completions');
    const postData = JSON.stringify(body);
    const contentLength = Buffer.byteLength(postData, 'utf-8');

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: parseInt(url.port) || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Authorization': 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
        'Content-Length': String(contentLength),
        'Connection': 'close',
      },
    };

    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf-8');
        let parsed: any;
        try {
          parsed = JSON.parse(raw);
        } catch (e) {
          parsed = null;
        }
        resolve({ status: res.statusCode || 0, body: parsed });
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

// --- Tool execution ---
function executeTool(name: string, args: any, inventory: Map<string, string[]>, rates: { scale: number; rates: Record<string, number> }): string {
  if (name === 'inventory_lookup') {
    const sku: string = args.sku;
    const row = inventory.get(sku);
    if (!row) {
      return serializeJSON({ error: 'unknown sku: ' + sku });
    }
    return serializeJSON({
      sku: row[0],
      name: row[1],
      price_cents: parseInt(row[2], 10),
      currency: row[3],
      stock: parseInt(row[4], 10),
    });
  } else if (name === 'convert_currency') {
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates.rates[from]);
    const rateTo = BigInt(rates.rates[to]);
    const amount = BigInt(amountCents);
    // HALF_UP: (2 * amount * rateTo + rateFrom) / (2 * rateFrom)
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = numerator / denominator;
    return serializeJSON({
      amount_cents: Number(converted),
      currency: to,
    });
  } else {
    return serializeJSON({ error: 'unknown tool: ' + name });
  }
}

// --- Main ---
async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    process.exit(1);
  }
  const dataDir = args[0];
  const baseUrl = args[1];

  // Read task.json
  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8');
  const task = JSON.parse(taskRaw);
  const apiKey: string = task.api_key;
  const model: string = task.model;
  const systemPrompt: string = task.system;
  const userPrompt: string = task.user;
  const tools: any[] = task.tools;

  // Read inventory.csv
  const csvRaw = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const csvRows = parseCSV(csvRaw);
  const inventory = new Map<string, string[]>();
  // Skip header row
  for (let r = 1; r < csvRows.length; r++) {
    const row = csvRows[r];
    if (row.length >= 5) {
      inventory.set(row[0], row);
    }
  }

  // Read rates.json
  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8');
  const rates = JSON.parse(ratesRaw);

  // Conversation
  const messages: any[] = [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requestCount = 0;

  const outputLines: string[] = [];

  while (true) {
    const reqBody = {
      model: model,
      messages: messages,
      tools: tools,
      tool_choice: 'auto',
    };

    const resp = await makeRequest(baseUrl, apiKey, reqBody);
    requestCount++;

    if (resp.status !== 200) {
      // Error response
      for (const line of outputLines) {
        process.stdout.write(line + '\n');
      }
      const errMsg = resp.body && resp.body.error ? resp.body.error.message : '';
      process.stdout.write('ERROR ' + resp.status + ' ' + errMsg + '\n');
      process.exit(0);
    }

    const respBody = resp.body;

    // Accumulate usage
    if (respBody.usage) {
      totalPrompt += respBody.usage.prompt_tokens || 0;
      totalCompletion += respBody.usage.completion_tokens || 0;
      totalTotal += respBody.usage.total_tokens || 0;
    }

    const choice = respBody.choices[0];
    const finishReason: string = choice.finish_reason;
    const msg = choice.message;

    if (finishReason === 'tool_calls') {
      // Print SAY if content is a string
      if (typeof msg.content === 'string') {
        outputLines.push('SAY ' + msg.content);
      }

      // Build assistant message to append (keep role, content, tool_calls; drop refusal/annotations)
      const assistantMsg: any = {
        role: msg.role,
        content: msg.content !== undefined ? msg.content : null,
        tool_calls: msg.tool_calls,
      };
      messages.push(assistantMsg);

      // Execute tool calls
      const toolCalls = msg.tool_calls;
      for (const tc of toolCalls) {
        outputLines.push('CALL ' + tc.id + ' ' + tc.function.name);
      }

      for (const tc of toolCalls) {
        const parsedArgs = JSON.parse(tc.function.arguments);
        const result = executeTool(tc.function.name, parsedArgs, inventory, rates);
        outputLines.push('RESULT ' + tc.id + ' ' + result);
        messages.push({
          role: 'tool',
          tool_call_id: tc.id,
          content: result,
        });
      }
    } else {
      // finish_reason === 'stop'
      const finalContent: string = msg.content || '';
      outputLines.push('FINAL ' + finalContent);

      // Print all output
      for (const line of outputLines) {
        process.stdout.write(line + '\n');
      }
      process.stdout.write('USAGE prompt=' + totalPrompt + ' completion=' + totalCompletion + ' total=' + totalTotal + ' requests=' + requestCount + '\n');
      process.exit(0);
    }
  }
}

main().catch((e) => {
