        (hostport.to_string(), 80)
    };
    (host, port, path.to_string())
}

fn read_all(mut stream: TcpStream) -> Vec<u8> {
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).unwrap();
    buf
