fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut p = 0;
    loop {
        // read hex size line
        let line_start = p;
        while p < data.len() && data[p] != b'\n' { p += 1; }
        if p >= data.len() { break; }
        p += 1; // skip LF
        let line = std::str::from_utf8(&data[line_start..p-1]).unwrap_or("").trim();
        // strip optional chunk extension
        let hex_str = if let Some(sc) = line.find(';') { &line[..sc] } else { line };
        let size = usize::from_str_radix(hex_str.trim(), 16).unwrap_or(0);
        if size == 0 { break; }
        // read size bytes
        if p + size <= data.len() {
            out.extend_from_slice(&data[p..p+size]);
            p += size;
        } else {
            out.extend_from_slice(&data[p..]);
            break;
        }
        // skip trailing CRLF
        if p < data.len() && data[p] == b'\r' { p += 1; }
        if p < data.len() && data[p] == b'\n' { p += 1; }
    }
    out
}

fn http_post(base_url: &str, body: &str, api_key: &str) -> (u16, Vec<u8>) {
    let (host, port, path) = parse_url(base_url);
    let endpoint = format!("{}{}", path, "/v1/messages");
    let body_bytes = body.as_bytes();
    let mut req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n",
        endpoint, host, port, body_bytes.len(), api_key
    );
    req.push_str(body);

    let mut stream = TcpStream::connect((host.as_str(), port)).unwrap();
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let all = read_all(stream);

    // split headers and body
    let header_end = find_double_crlf(&all).unwrap_or(all.len());
    let header_str = std::str::from_utf8(&all[..header_end]).unwrap_or("");
    let body_bytes = if header_end < all.len() { &all[header_end+4..] } else { &[] };

    // parse status
    let first_line = header_str.lines().next().unwrap_or("");
    let status: u16 = first_line.split_whitespace().nth(1).unwrap_or("200").parse().unwrap_or(200);

    // check transfer-encoding
    let is_chunked = header_str.to_lowercase().contains("transfer-encoding: chunked");

