                                // surrogate pair
                                self.expect(b'\\');
                                self.expect(b'u');
                                let lo = self.parse_hex4();
                                let full = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                out.push(char::from_u32(full).unwrap_or('\u{FFFD}'));
                            } else if cp >= 0xDC00 && cp <= 0xDFFF {
                                out.push('\u{FFFD}');
                            } else {
                                out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => out.push(e as char),
                    }
                }
                _ => {
                    // handle multi-byte UTF-8
                    if c < 0x80 {
                        out.push(c as char);
                    } else {
                        let start = self.p - 1;
                        let len = if c < 0xE0 { 2 } else if c < 0xF0 { 3 } else { 4 };
                        let bytes = &self.s[start..start + len];
                        self.p = start + len;
                        out.push_str(std::str::from_utf8(bytes).unwrap_or("\u{FFFD}"));
                    }
                }
            }
        }
        out
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut v = 0u32;
        for _ in 0..4 {
            let c = self.s[self.p]; self.p += 1;
            v = v * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => unreachable!(),
            };
        }
        v
    }

    fn parse_num(&mut self) -> JVal {
        let start = self.p;
        while self.p < self.s.len() && matches!(self.s[self.p], b'-'|b'+'|b'.'|b'e'|b'E'|b'0'..=b'9') { self.p += 1; }
        JVal::Num(std::str::from_utf8(&self.s[start..self.p]).unwrap().parse::<f64>().unwrap())
    }
}

// ─── JSON Serializer ──────────────────────────────────────────────────────────

fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out
}

fn ser_json(v: &JVal, out: &mut String) {
    match v {
        JVal::Null => out.push_str("null"),
        JVal::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        JVal::Num(n) => {
            if *n == (*n as i64) as f64 && n.abs() < 1e15 {
                out.push_str(&format!("{}", *n as i64));
            } else {
                out.push_str(&format!("{}", n));
            }
        }
        JVal::Str(s) => { out.push('"'); out.push_str(&json_escape(s)); out.push('"'); }
        JVal::Arr(v) => {
            out.push('[');
            for (i, item) in v.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_json(item, out);
            }
            out.push(']');
        }
        JVal::Obj(v) => {
            out.push('{');
            for (i, (k, val)) in v.iter().enumerate() {
                if i > 0 { out.push(','); }
                out.push('"'); out.push_str(&json_escape(k)); out.push_str("\":");
                ser_json(val, out);
            }
            out.push('}');
        }
    }
}

// ─── Output escape ────────────────────────────────────────────────────────────

fn esc_out(s: &str) -> String {
    let mut out = String::new();
