struct SseEvent { event: String, data: String }

fn parse_sse(raw: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(raw);
    let mut events = Vec::new();
    let mut event_name = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let mut in_event = false;

    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        let line_start = i;
        while i < bytes.len() && bytes[i] != b'\n' { i += 1; }
        let mut line_end = i;
        if i < bytes.len() { i += 1; }
        if line_end > line_start && bytes[line_end - 1] == b'\r' { line_end -= 1; }
        let line = &text[line_start..line_end];

        if line.is_empty() {
            if in_event {
                events.push(SseEvent {
                    event: event_name.clone(),
                    data: data_lines.join("\n"),
                });
            }
            event_name.clear();
            data_lines.clear();
            in_event = false;
            continue;
        }

        if line.starts_with(':') { continue; }

        if let Some(rest) = line.strip_prefix("event:") {
            event_name = rest.trim_start().to_string();
            in_event = true;
        } else if let Some(rest) = line.strip_prefix("data:") {
            let val = if rest.starts_with(' ') { &rest[1..] } else { rest };
            data_lines.push(val.to_string());
            in_event = true;
        }
    }
    if in_event && !data_lines.is_empty() {
        events.push(SseEvent { event: event_name, data: data_lines.join("\n") });
    }
    events
}

// ─── Process SSE into blocks ──────────────────────────────────────────────────

struct ReplyInfo {
    blocks: Vec<CBlock>,
    stop_reason: String,
    input_tokens: i64,
    output_tokens: i64,
    cache_read: i64,
}

fn process_sse(raw: &[u8]) -> ReplyInfo {
    let events = parse_sse(raw);
    let mut blocks: Vec<Option<CBlock>> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens = 0i64;
    let mut output_tokens = 0i64;
    let mut cache_read = 0i64;

    for ev in &events {
        if ev.event == "ping" || ev.data.is_empty() { continue; }
        let mut jp = JP::new(&ev.data);
        let val = jp.parse();

        match ev.event.as_str() {
            "message_start" => {
                if let Some(msg) = val.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        input_tokens += usage.get("input_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                        cache_read += usage.get("cache_read_input_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                    }
                }
            }
            "content_block_start" => {
                let idx = val.get("index").map(|v| v.as_num() as usize).unwrap_or(0);
                let cb = val.get("content_block").unwrap();
                let btype = cb.get("type").map(|v| v.as_str().to_string()).unwrap_or_default();
                let block = CBlock {
                    btype: btype.clone(),
                    thinking: String::new(),
                    signature: String::new(),
                    text: String::new(),
                    tool_id: cb.get("id").map(|v| v.as_str().to_string()).unwrap_or_default(),
                    tool_name: cb.get("name").map(|v| v.as_str().to_string()).unwrap_or_default(),
                    raw_input: String::new(),
                };
                while blocks.len() <= idx { blocks.push(None); }
                blocks[idx] = Some(block);
            }
            "content_block_delta" => {
                let idx = val.get("index").map(|v| v.as_num() as usize).unwrap_or(0);
                let delta = val.get("delta").unwrap();
                let dtype = delta.get("type").map(|v| v.as_str()).unwrap_or("");
                if let Some(Some(block)) = blocks.get_mut(idx) {
                    match dtype {
                        "thinking_delta" => block.thinking.push_str(delta.get("thinking").map(|v| v.as_str()).unwrap_or("")),
                        "signature_delta" => block.signature.push_str(delta.get("signature").map(|v| v.as_str()).unwrap_or("")),
                        "text_delta" => block.text.push_str(delta.get("text").map(|v| v.as_str()).unwrap_or("")),
                        "input_json_delta" => block.raw_input.push_str(delta.get("partial_json").map(|v| v.as_str()).unwrap_or("")),
                        _ => {}
                    }
                }
            }
            "content_block_stop" => {}
            "message_delta" => {
                if let Some(delta) = val.get("delta") {
                    if let Some(sr) = delta.get("stop_reason") {
                        stop_reason = sr.as_str().to_string();
                    }
                }
                if let Some(usage) = val.get("usage") {
                    output_tokens += usage.get("output_tokens").map(|v| v.as_num() as i64).unwrap_or(0);
                }
            }
            "message_stop" => {}
            _ => {}
        }
    }

    let blocks = blocks.into_iter().filter_map(|b| b).collect();
    ReplyInfo { blocks, stop_reason, input_tokens, output_tokens, cache_read }
}

// ─── Tool Execution ───────────────────────────────────────────────────────────

fn run_tool(name: &str, input_json: &str) -> (String, bool) {
    let mut jp = JP::new(input_json);
    let input = jp.parse();

    match name {
        "measure" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let unit = input.get("unit").map(|v| v.as_str().to_string()).unwrap_or_default();
            match unit.as_str() {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.len().to_string(), false),
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let reversed: String = text.chars().rev().collect();
            (reversed, false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ─── Build Request Body ───────────────────────────────────────────────────────

fn build_request_body(model: &str, max_tokens: f64, thinking_budget: f64, system: &str, tools_json: &str, messages: &JVal) -> String {
    let mut body = String::new();
    body.push('{');
    body.push_str("\"model\":");
    body.push('"'); body.push_str(&json_escape(model)); body.push('"');
    body.push_str(",\"max_tokens\":");
    body.push_str(&format!("{}", max_tokens as i64));
    body.push_str(",\"stream\":true");
    body.push_str(",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    body.push_str(&format!("{}", thinking_budget as i64));
    body.push('}');
    body.push_str(",\"system\":");
    body.push('"'); body.push_str(&json_escape(system)); body.push('"');
    body.push_str(",\"tools\":");
    body.push_str(tools_json);
    body.push_str(",\"messages\":");
    ser_json(messages, &mut body);
    body.push('}');
    body
}

// ─── Print blocks ─────────────────────────────────────────────────────────────

fn print_blocks(blocks: &[CBlock]) {
    for b in blocks {
        match b.btype.as_str() {
            "thinking" => {
                println!("thinking {}", esc_out(&b.thinking));
                println!("signature {}", esc_out(&b.signature));
            }
            "text" => {
                println!("text {}", esc_out(&b.text));
            }
            "tool_use" => {
                println!("tool_use {} {} {}", esc_out(&b.tool_id), esc_out(&b.tool_name), esc_out(&b.raw_input));
            }
            _ => {}
        }
    }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

