                ]));
            }
            _ => {}
        }
    }

    let mut tool_result_content: Vec<JVal> = Vec::new();
    for (id, result, is_err) in &tool_results {
        let mut block = vec![
            ("type".to_string(), JVal::Str("tool_result".to_string())),
            ("tool_use_id".to_string(), JVal::Str(id.clone())),
            ("content".to_string(), JVal::Str(result.clone())),
        ];
        if *is_err {
            block.push(("is_error".to_string(), JVal::Bool(true)));
        }
        tool_result_content.push(JVal::Obj(block));
    }

    let messages2 = JVal::Arr(vec![
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("user".to_string())),
            ("content".to_string(), JVal::Str(prompt.clone())),
        ]),
        JVal::Obj(vec![
            ("role".to_string(), JVal::Str("assistant".to_string())),
