        private String parseStr() {
            pos++; // opening "
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char e = s.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); pos++; break;
                        case '\\': sb.append('\\'); pos++; break;
                        case '/': sb.append('/'); pos++; break;
                        case 'b': sb.append('\b'); pos++; break;
                        case 'f': sb.append('\f'); pos++; break;
                        case 'n': sb.append('\n'); pos++; break;
                        case 'r': sb.append('\r'); pos++; break;
                        case 't': sb.append('\t'); pos++; break;
                        case 'u': {
                            int hi = Integer.parseInt(s.substring(pos + 1, pos + 5), 16);
                            pos += 5; // move past 'u' and 4 hex digits
                            if (hi >= 0xD800 && hi <= 0xDBFF) {
                                // expect \uXXXX surrogate pair
                                // pos is now at '\'
                                if (pos + 5 < s.length() && s.charAt(pos) == '\\' && s.charAt(pos + 1) == 'u') {
                                    int lo = Integer.parseInt(s.substring(pos + 2, pos + 6), 16);
                                    pos += 6; // move past '\' + 'u' + 4 hex digits
                                    int cp = 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                                    sb.appendCodePoint(cp);
                                } else {
                                    sb.append((char) hi);
                                }
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                        default: sb.append(e); pos++;
                    }
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            throw new RuntimeException("unterminated string");
        }

        private Long parseNum() {
            int start = pos;
            if (pos < s.length() && s.charAt(pos) == '-') pos++;
            while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            if (pos < s.length() && s.charAt(pos) == '.') {
                pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            String num = s.substring(start, pos);
            if (num.contains(".") || num.contains("e") || num.contains("E")) {
                return (long) Double.parseDouble(num);
            }
            return Long.parseLong(num);
        }
    }

    // ==================== JSON Serializer ====================
    private static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    private static String ser(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof String) return "\"" + esc((String) obj) + "\"";
        if (obj instanceof Long) return obj.toString();
        if (obj instanceof Integer) return obj.toString();
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Map) {
            Map<String, Object> m = (Map<String, Object>) obj;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(',');
                sb.append('"').append(esc(e.getKey())).append("\":").append(ser(e.getValue()));
                first = false;
            }
            sb.append('}');
            return sb.toString();
        }
        if (obj instanceof List) {
            List<Object> l = (List<Object>) obj;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object o : l) {
                if (!first) sb.append(',');
                sb.append(ser(o));
                first = false;
            }
            sb.append(']');
            return sb.toString();
        }
        throw new RuntimeException("cannot serialize " + obj.getClass());
    }

    // ==================== CSV Parser ====================
    private static List<List<String>> parseCsv(byte[] data) {
        int start = 0;
        if (data.length >= 3 && (data[0] & 0xFF) == 0xEF && (data[1] & 0xFF) == 0xBB && (data[2] & 0xFF) == 0xBF) {
            start = 3;
        }
        String text = new String(data, start, data.length - start, StandardCharsets.UTF_8);
        List<List<String>> records = new ArrayList<>();
        List<String> cur = new ArrayList<>();
        StringBuilder field = new StringBuilder();
        int i = 0;
        boolean inQ = false;
        while (i < text.length()) {
            char c = text.charAt(i);
            if (inQ) {
                if (c == '"') {
                    if (i + 1 < text.length() && text.charAt(i + 1) == '"') {
                        field.append('"');
                        i += 2;
                    } else {
                        inQ = false;
                        i++;
                    }
                } else {
                    field.append(c);
                    i++;
                }
            } else {
                if (c == '"') {
                    inQ = true;
                    i++;
                } else if (c == ',') {
                    cur.add(field.toString());
                    field.setLength(0);
                    i++;
                } else if (c == '\r') {
                    cur.add(field.toString());
                    field.setLength(0);
                    records.add(cur);
                    cur = new ArrayList<>();
                    if (i + 1 < text.length() && text.charAt(i + 1) == '\n') i += 2;
                    else i++;
                } else if (c == '\n') {
                    cur.add(field.toString());
                    field.setLength(0);
                    records.add(cur);
                    cur = new ArrayList<>();
                    i++;
                } else {
                    field.append(c);
                    i++;
                }
            }
        }
        if (field.length() > 0 || !cur.isEmpty()) {
            cur.add(field.toString());
            records.add(cur);
        }
        return records;
    }

    // ==================== HTTP Client ====================
    private static String[] httpPost(String baseUrl, String apiKey, String body) throws Exception {
        URL url = new URL(baseUrl + "/chat/completions");
        String host = url.getHost();
        int port = url.getPort();
        if (port == -1) port = 80;
        String path = url.getPath();
        if (url.getQuery() != null) path += "?" + url.getQuery();

        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);

        try (Socket sock = new Socket(host, port)) {
            OutputStream out = sock.getOutputStream();
            StringBuilder req = new StringBuilder();
            req.append("POST ").append(path).append(" HTTP/1.1\r\n");
            req.append("Host: ").append(host);
            if (port != 80) req.append(':').append(port);
            req.append("\r\n");
            req.append("Authorization: Bearer ").append(apiKey).append("\r\n");
            req.append("Content-Type: application/json\r\n");
            req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
            req.append("Connection: close\r\n");
            req.append("\r\n");
            out.write(req.toString().getBytes(StandardCharsets.UTF_8));
            out.write(bodyBytes);
            out.flush();

            InputStream in = sock.getInputStream();
            String statusLine = readLine(in);
            int statusCode = Integer.parseInt(statusLine.split(" ")[1]);

            int contentLength = -1;
            while (true) {
                String h = readLine(in);
                if (h.isEmpty()) break;
                int ci = h.indexOf(':');
                if (ci > 0) {
                    String hn = h.substring(0, ci).trim().toLowerCase();
                    String hv = h.substring(ci + 1).trim();
                    if (hn.equals("content-length")) contentLength = Integer.parseInt(hv);
                }
            }

            byte[] raw = new byte[contentLength];
            int off = 0;
            while (off < contentLength) {
                int r = in.read(raw, off, contentLength - off);
                if (r == -1) break;
                off += r;
            }
            String respBody = new String(raw, 0, off, StandardCharsets.UTF_8);
            return new String[]{String.valueOf(statusCode), respBody};
        }
    }

    private static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int next = in.read();
                if (next == '\n') return sb.toString();
                sb.append('\r');
                if (next != -1) sb.append((char) next);
            } else if (c == '\n') {
                return sb.toString();
            } else {
                sb.append((char) c);
            }
        }
        return sb.toString();
    }

    // ==================== Tool Execution ====================
    @SuppressWarnings("unchecked")
    private static String executeTool(String name, String argsJson, List<List<String>> inventory, Map<String, Long> rates) {
        if (name.equals("inventory_lookup")) {
            Map<String, Object> args = (Map<String, Object>) new JsonParser(argsJson).parse();
            String sku = (String) args.get("sku");
            for (int i = 1; i < inventory.size(); i++) {
                List<String> row = inventory.get(i);
                if (row.size() >= 5 && row.get(0).equals(sku)) {
                    Map<String, Object> r = new LinkedHashMap<>();
                    r.put("sku", row.get(0));
                    r.put("name", row.get(1));
                    r.put("price_cents", Long.parseLong(row.get(2)));
                    r.put("currency", row.get(3));
                    r.put("stock", Long.parseLong(row.get(4)));
                    return ser(r);
                }
            }
            Map<String, Object> r = new LinkedHashMap<>();
            r.put("error", "unknown sku: " + sku);
            return ser(r);
        } else if (name.equals("convert_currency")) {
            Map<String, Object> args = (Map<String, Object>) new JsonParser(argsJson).parse();
            long amountCents = ((Long) args.get("amount_cents")).longValue();
            String from = (String) args.get("from");
            String to = (String) args.get("to");
            long rateFrom = rates.get(from);
            long rateTo = rates.get(to);
            long converted = (2 * amountCents * rateTo + rateFrom) / (2 * rateFrom);
            Map<String, Object> r = new LinkedHashMap<>();
            r.put("amount_cents", converted);
            r.put("currency", to);
            return ser(r);
        } else {
            Map<String, Object> r = new LinkedHashMap<>();
            r.put("error", "unknown tool: " + name);
            return ser(r);
        }
    }

    // ==================== Main ====================
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read task.json
        String taskRaw = new String(Files.readAllBytes(Paths.get(dataDir, "task.json")), StandardCharsets.UTF_8);
        Map<String, Object> task = (Map<String, Object>) new JsonParser(taskRaw).parse();
        String apiKey = (String) task.get("api_key");
        String model = (String) task.get("model");
        String system = (String) task.get("system");
        String user = (String) task.get("user");
        List<Object> tools = (List<Object>) task.get("tools");

        // Read inventory.csv
        byte[] csvBytes = Files.readAllBytes(Paths.get(dataDir, "inventory.csv"));
        List<List<String>> inventory = parseCsv(csvBytes);

        // Read rates.json
        String ratesRaw = new String(Files.readAllBytes(Paths.get(dataDir, "rates.json")), StandardCharsets.UTF_8);
        Map<String, Object> ratesObj = (Map<String, Object>) new JsonParser(ratesRaw).parse();
        Map<String, Long> rates = new LinkedHashMap<>();
        Map<String, Object> ratesMap = (Map<String, Object>) ratesObj.get("rates");
        for (Map.Entry<String, Object> e : ratesMap.entrySet()) {
            rates.put(e.getKey(), ((Long) e.getValue()).longValue());
        }

        // Build conversation
        List<Object> messages = new ArrayList<>();
        Map<String, Object> sysMsg = new LinkedHashMap<>();
        sysMsg.put("role", "system");
        sysMsg.put("content", system);
        messages.add(sysMsg);
        Map<String, Object> usrMsg = new LinkedHashMap<>();
        usrMsg.put("role", "user");
        usrMsg.put("content", user);
        messages.add(usrMsg);

        long totalPrompt = 0, totalCompletion = 0, totalTokens = 0;
        int numRequests = 0;
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.UTF_8)));

        while (true) {
            Map<String, Object> reqBody = new LinkedHashMap<>();
            reqBody.put("model", model);
            reqBody.put("messages", messages);
            reqBody.put("tools", tools);
            reqBody.put("tool_choice", "auto");
            String body = ser(reqBody);

            String[] resp = httpPost(baseUrl, apiKey, body);
            numRequests++;
            int status = Integer.parseInt(resp[0]);
            String respBody = resp[1];

            if (status != 200) {
                Map<String, Object> errObj = (Map<String, Object>) new JsonParser(respBody).parse();
                Map<String, Object> err = (Map<String, Object>) errObj.get("error");
                String errMsg = (String) err.get("message");
                pw.flush();
                System.out.println("ERROR " + status + " " + errMsg);
                System.out.flush();
                System.exit(0);
            }

            Map<String, Object> completion = (Map<String, Object>) new JsonParser(respBody).parse();

            // Usage
            Map<String, Object> usage = (Map<String, Object>) completion.get("usage");
            if (usage != null) {
                totalPrompt += ((Long) usage.get("prompt_tokens")).longValue();
                totalCompletion += ((Long) usage.get("completion_tokens")).longValue();
                totalTokens += ((Long) usage.get("total_tokens")).longValue();
            }

            List<Object> choices = (List<Object>) completion.get("choices");
            Map<String, Object> choice = (Map<String, Object>) choices.get(0);
            String finishReason = (String) choice.get("finish_reason");
            Map<String, Object> message = (Map<String, Object>) choice.get("message");

            if (finishReason.equals("stop")) {
                String content = (String) message.get("content");
                pw.println("FINAL " + content);
                pw.println("USAGE prompt=" + totalPrompt + " completion=" + totalCompletion + " total=" + totalTokens + " requests=" + numRequests);
                pw.flush();
                System.exit(0);
            }

            // finish_reason == "tool_calls"
            Object content = message.get("content");
            if (content instanceof String) {
                pw.println("SAY " + content);
            }

            List<Object> toolCalls = (List<Object>) message.get("tool_calls");

            // Print CALL lines
            for (Object tc : toolCalls) {
                Map<String, Object> tcMap = (Map<String, Object>) tc;
                String id = (String) tcMap.get("id");
                Map<String, Object> func = (Map<String, Object>) tcMap.get("function");
                String name = (String) func.get("name");
                pw.println("CALL " + id + " " + name);
            }

            // Execute tools, print RESULT lines
            List<Object> toolResults = new ArrayList<>();
            for (Object tc : toolCalls) {
                Map<String, Object> tcMap = (Map<String, Object>) tc;
                String id = (String) tcMap.get("id");
                Map<String, Object> func = (Map<String, Object>) tcMap.get("function");
                String name = (String) func.get("name");
                String arguments = (String) func.get("arguments");

                String result = executeTool(name, arguments, inventory, rates);
                pw.println("RESULT " + id + " " + result);

                Map<String, Object> toolMsg = new LinkedHashMap<>();
                toolMsg.put("role", "tool");
                toolMsg.put("tool_call_id", id);
                toolMsg.put("content", result);
                toolResults.add(toolMsg);
            }

            // Append assistant message (preserve tool_calls as received)
            Map<String, Object> assistantMsg = new LinkedHashMap<>();
            assistantMsg.put("role", message.get("role"));
            assistantMsg.put("content", content);
            assistantMsg.put("tool_calls", toolCalls);
            messages.add(assistantMsg);

            // Append tool result messages
            messages.addAll(toolResults);
        }
    }
}
