        if (i >= sql.length() || sql.charAt(i) != '(') return names;

        int openParen = i;
        int depth = 0;
        int closeParen = -1;
        for (int j = openParen; j < sql.length(); j++) {
            if (sql.charAt(j) == '(') depth++;
            else if (sql.charAt(j) == ')') { depth--; if (depth == 0) { closeParen = j; break; } }
        }
        if (closeParen < 0) return names;

        String defs = sql.substring(openParen + 1, closeParen);
        List<String> parts = splitTopLevel(defs);
        for (String part : parts) {
            part = part.trim();
            if (part.isEmpty()) continue;
            String name;
            if (part.charAt(0) == '"') {
                int end = part.indexOf('"', 1);
                name = part.substring(1, end);
            } else {
                int j = 0;
                while (j < part.length() && (Character.isLetterOrDigit(part.charAt(j)) || part.charAt(j) == '_')) j++;
                name = part.substring(0, j);
            }
            names.add(name);
        }
        return names;
    }

    static List<String> splitTopLevel(String s) {
        List<String> parts = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i));
                start = i + 1;
            }
        }
        parts.add(s.substring(start));
        return parts;
    }

    static List<Boolean> parseRowidAliases(String sql, int numCols) {
        List<Boolean> aliases = new ArrayList<>();
        for (int i = 0; i < numCols; i++) aliases.add(false);

        // Re-parse to get definitions
        int i = 0;
        String upper = sql.toUpperCase();
        i = upper.indexOf("CREATE");
        if (i < 0) return aliases;
        i += 6;
        while (i < sql.length() && Character.isWhitespace(sql.charAt(i))) i++;
        i = upper.indexOf("TABLE", i);
        if (i < 0) return aliases;
        i += 5;
        while (i < sql.length() && Character.isWhitespace(sql.charAt(i))) i++;
        if (upper.startsWith("IF", i)) {
            i = upper.indexOf("EXISTS", i);
            if (i >= 0) { i += 6; while (i < sql.length() && Character.isWhitespace(sql.charAt(i))) i++; }
        }
        if (i < sql.length() && sql.charAt(i) == '"') {
            i++;
            while (i < sql.length() && sql.charAt(i) != '"') i++;
            i++;
        } else {
            while (i < sql.length() && !Character.isWhitespace(sql.charAt(i)) && sql.charAt(i) != '(') i++;
        }
        while (i < sql.length() && Character.isWhitespace(sql.charAt(i))) i++;
        if (i >= sql.length() || sql.charAt(i) != '(') return aliases;

        int openParen = i;
        int depth = 0;
        int closeParen = -1;
        for (int j = openParen; j < sql.length(); j++) {
            if (sql.charAt(j) == '(') depth++;
            else if (sql.charAt(j) == ')') { depth--; if (depth == 0) { closeParen = j; break; } }
        }
        if (closeParen < 0) return aliases;
        String defs = sql.substring(openParen + 1, closeParen);
        List<String> parts = splitTopLevel(defs);

        for (int ci = 0; ci < parts.size() && ci < numCols; ci++) {
            String def = parts.get(ci).trim();
            if (def.isEmpty()) continue;
            // Skip column name
            int j = 0;
            if (def.charAt(0) == '"') {
                j = def.indexOf('"', 1) + 1;
            } else {
                while (j < def.length() && (Character.isLetterOrDigit(def.charAt(j)) || def.charAt(j) == '_')) j++;
            }
            while (j < def.length() && Character.isWhitespace(def.charAt(j))) j++;
            // Read type name
            int typeStart = j;
            while (j < def.length() && (Character.isLetterOrDigit(def.charAt(j)) || def.charAt(j) == '_')) j++;
            String typeName = def.substring(typeStart, j);

            if (typeName.equalsIgnoreCase("INTEGER")) {
                String defUpper = def.toUpperCase();
                if (defUpper.contains("PRIMARY") && defUpper.contains("KEY")) {
                    aliases.set(ci, true);
                }
            }
        }
        return aliases;
    }
