def read_varint(data, offset):
    result = 0
    for i in range(9):
        if offset + i >= len(data):
            return result, offset + i + 1
        byte = data[offset + i]
        if i == 8:
            result = (result << 8) | byte
            return result, offset + 9
        result = (result << 7) | (byte & 0x7F)
        if byte < 0x80:
            return result, offset + i + 1
    return result, offset + 9


def format_real(value):
    d = Decimal(value)
    s = str(d)
    if 'E' in s or 'e' in s:
        sign, digits, exp = d.as_tuple()
        digits_str = ''.join(str(x) for x in digits)
        if exp >= 0:
            s = ('-' if sign else '') + digits_str + '0' * exp
        else:
            int_digits = len(digits_str) + exp
            if int_digits > 0:
                int_part = digits_str[:int_digits]
                frac_part = digits_str[int_digits:]
            else:
                int_part = '0'
                frac_part = '0' * (-int_digits) + digits_str
            s = ('-' if sign else '') + int_part + '.' + frac_part
    if '.' not in s:
        s += '.0'
    int_p, frac_p = s.split('.', 1)
    frac_p = frac_p.rstrip('0')
    if not frac_p:
        frac_p = '0'
    return int_p + '.' + frac_p


def escape_text(data):
    text = data.decode('utf-8')
    result = []
    for ch in text:
        cp = ord(ch)
        if cp == 0x5C:
            result.append('\\\\')
        elif cp == 0x22:
            result.append('\\"')
        elif cp == 0x0A:
            result.append('\\n')
        elif cp == 0x0D:
            result.append('\\r')
        elif cp == 0x09:
            result.append('\\t')
        elif cp < 0x20 or cp == 0x7F:
            result.append('\\x{:02X}'.format(cp))
        else:
            result.append(ch)
    return '"' + ''.join(result) + '"'


def format_value(val):
    if val is None:
        return 'NULL'
    cls, data = val
    if cls == 'INT':
        return str(data)
    elif cls == 'REAL':
        return format_real(data)
    elif cls == 'TEXT':
        if len(data) <= 100:
            return escape_text(data)
        else:
            crc = zlib.crc32(data) & 0xFFFFFFFF
            return '<TEXT len={} crc32={:08x}>'.format(len(data), crc)
    elif cls == 'BLOB':
        if len(data) <= 100:
            return "X'" + data.hex().upper() + "'"
        else:
            crc = zlib.crc32(data) & 0xFFFFFFFF
            return '<BLOB len={} crc32={:08x}>'.format(len(data), crc)
    return 'NULL'


