        total_payload, off = read_varint(page, cell_offset)
        rowid, off = read_varint(page, off)

        max_local = self.usable_size - 35
        min_local = ((self.usable_size - 12) * 32 // 255) - 23

        if total_payload <= max_local:
            local_size = total_payload
            has_overflow = False
        else:
            k = min_local + (total_payload - min_local) % (self.usable_size - 4)
            if k <= max_local:
