typedef struct{int status;char*body;}http_resp;

static http_resp http_post(const char*url,const char*auth,const char*body){
    http_resp r={0,NULL};
    const char*p=url;
    if(strncmp(p,"http://",7)==0)p+=7;
    const char*slash=strchr(p,'/');
    char host[256]={0};int port=80;
    if(slash){
        size_t hlen=(size_t)(slash-p);
        const char*colon=memchr(p,':',hlen);
        if(colon){size_t hl=(size_t)(colon-p);memcpy(host,p,hl);host[hl]=0;port=atoi(colon+1);}
        else{memcpy(host,p,hlen);host[hlen]=0;}
    }else{
        const char*colon=strchr(p,':');
        if(colon){size_t hl=(size_t)(colon-p);memcpy(host,p,hl);host[hl]=0;port=atoi(colon+1);}
        else{strcpy(host,p);}
    }
    char path[512]={0};
    if(slash)snprintf(path,sizeof(path),"%s/chat/completions",slash);
    else snprintf(path,sizeof(path),"/chat/completions");

    int sock=socket(AF_INET,SOCK_STREAM,0);
    struct sockaddr_in addr={0};
    addr.sin_family=AF_INET;addr.sin_port=htons((unsigned short)port);
    inet_pton(AF_INET,host,&addr.sin_addr);
    if(connect(sock,(struct sockaddr*)&addr,sizeof(addr))<0){r.status=-1;close(sock);return r;}

    sbuf req;sb_init(&req);
    sb_str(&req,"POST ");sb_str(&req,path);sb_str(&req," HTTP/1.1\r\n");
    sb_str(&req,"Host: ");sb_str(&req,host);sb_c(&req,':');sb_int(&req,(long long)port);sb_str(&req,"\r\n");
    sb_str(&req,"Authorization: Bearer ");sb_str(&req,auth);sb_str(&req,"\r\n");
    sb_str(&req,"Content-Type: application/json\r\n");
    sb_str(&req,"Content-Length: ");sb_int(&req,(long long)strlen(body));sb_str(&req,"\r\n");
    sb_str(&req,"\r\n");
    sb_str(&req,body);

    size_t sent=0,total=req.len;
    while(sent<total){ssize_t w=write(sock,req.buf+sent,total-sent);if(w<=0)break;sent+=(size_t)w;}
    sb_free(&req);

    sbuf resp;sb_init(&resp);
    char tmp[8192];ssize_t n;
    while((n=read(sock,tmp,sizeof(tmp)))>0)sb_s(&resp,tmp,(size_t)n);
    close(sock);

    /* parse status line */
    resp.buf[resp.len]=0;
    if(strncmp(resp.buf,"HTTP/1.1 ",9)==0||strncmp(resp.buf,"HTTP/1.0 ",9)==0){
        r.status=atoi(resp.buf+9);
    }else r.status=-1;

    /* find body after \r\n\r\n */
    char*hdr_end=strstr(resp.buf,"\r\n\r\n");
    if(hdr_end)r.body=strdup(hdr_end+4);
    else r.body=strdup("");
    sb_free(&resp);
    return r;
}

/* ===== Conversation Messages ===== */
typedef struct{char*id;char*name;char*arguments;}tc_t;
typedef struct{char*role;char*content;tc_t*tcs;int n_tc;char*tc_id;}msg_t;

static msg_t*conv=NULL;static int conv_count=0,conv_cap=0;
static void conv_add(msg_t m){
    if(conv_count>=conv_cap){conv_cap=conv_cap?conv_cap*2:16;conv=realloc(conv,conv_cap*sizeof(msg_t));}
    conv[conv_count++]=m;
}

/* ===== Serialize Request ===== */
static void ser_msg(sbuf*sb,msg_t*m){
    sb_c(sb,'{');
    sb_str(sb,"\"role\":");enc_str(sb,m->role);
    if(strcmp(m->role,"tool")==0){
        sb_str(sb,",\"tool_call_id\":");enc_str(sb,m->tc_id);
        sb_str(sb,",\"content\":");enc_str(sb,m->content);
    }else if(strcmp(m->role,"assistant")==0){
        sb_str(sb,",\"content\":");
        if(m->content)enc_str(sb,m->content);else sb_str(sb,"null");
        if(m->n_tc>0){
            sb_str(sb,",\"tool_calls\":[");
            for(int i=0;i<m->n_tc;i++){
                if(i)sb_c(sb,',');
                sb_str(sb,"{\"id\":");enc_str(sb,m->tcs[i].id);
                sb_str(sb,",\"type\":\"function\",\"function\":{\"name\":");enc_str(sb,m->tcs[i].name);
                sb_str(sb,",\"arguments\":");enc_str(sb,m->tcs[i].arguments);
                sb_str(sb,"}}");
            }
            sb_c(sb,']');
        }
    }else{
        sb_str(sb,",\"content\":");enc_str(sb,m->content);
    }
    sb_c(sb,'}');
}

static char*build_body(const char*model,jval*tools){
    sbuf sb;sb_init(&sb);
    sb_str(&sb,"{\"model\":");enc_str(&sb,model);
    sb_str(&sb,",\"messages\":[");
    for(int i=0;i<conv_count;i++){if(i)sb_c(&sb,',');ser_msg(&sb,&conv[i]);}
    sb_str(&sb,"],\"tools\":");
    ser_json(&sb,tools);
    sb_str(&sb,",\"tool_choice\":\"auto\"}");
    return sb.buf;
}

/* ===== Tool Execution ===== */
static char*exec_tool(const char*name,const char*args_json){
    jval*args=NULL;
    if(args_json&&*args_json){const char*p=args_json;args=parse_val(&p);}
    if(strcmp(name,"inventory_lookup")==0){
        const char*sku=jstr(jobj_get(args,"sku"));
        if(!sku)sku="";
        for(int i=0;i<inv_count;i++){
            if(strcmp(inventory[i].sku,sku)==0){
                sbuf sb;sb_init(&sb);
                sb_str(&sb,"{\"sku\":");enc_str(&sb,inventory[i].sku);
                sb_str(&sb,",\"name\":");enc_str(&sb,inventory[i].name);
                sb_str(&sb,",\"price_cents\":");sb_int(&sb,inventory[i].price_cents);
                sb_str(&sb,",\"currency\":");enc_str(&sb,inventory[i].currency);
                sb_str(&sb,",\"stock\":");sb_int(&sb,inventory[i].stock);
                sb_c(&sb,'}');
                return sb.buf;
            }
        }
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"error\":\"unknown sku: ");enc_str(&sb,sku);sb_str(&sb,"\"}");
        return sb.buf;
    }else if(strcmp(name,"convert_currency")==0){
        long long amt=jint(jobj_get(args,"amount_cents"));
        const char*from=jstr(jobj_get(args,"from"));
        const char*to=jstr(jobj_get(args,"to"));
        if(!from)from="USD";if(!to)to="USD";
        long long rf=get_rate(from),rt=get_rate(to);
        /* HALF_UP: (2*amt*rt + rf) / (2*rf) */
        long long num=2*amt*rt+rf;
        long long den=2*rf;
        long long result=num/den;
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"amount_cents\":");sb_int(&sb,result);
        sb_str(&sb,",\"currency\":");enc_str(&sb,to);
        sb_c(&sb,'}');
        return sb.buf;
    }else{
        sbuf sb;sb_init(&sb);
        sb_str(&sb,"{\"error\":\"unknown tool: ");enc_str(&sb,name);sb_str(&sb,"\"}");
        return sb.buf;
    }
}

