/* ============ Dynamic String ============ */
typedef struct { char *data; int len, cap; } dstr;
static void dstr_init(dstr *s){ s->data=NULL; s->len=0; s->cap=0; }
static void dstr_free(dstr *s){ free(s->data); s->data=NULL; s->len=s->cap=0; }
static void dstr_res(dstr *s, int extra){
    if(s->len+extra+1>s->cap){ s->cap=(s->len+extra+1)*2; if(s->cap<64)s->cap=64; s->data=realloc(s->data,s->cap); }
}
static void dstr_ap(dstr *s, const char *p, int n){ dstr_res(s,n); memcpy(s->data+s->len,p,n); s->len+=n; s->data[s->len]='\0'; }
static void dstr_ach(dstr *s, char c){ dstr_res(s,1); s->data[s->len++]=c; s->data[s->len]='\0'; }
static void dstr_aps(dstr *s, const char *p){ dstr_ap(s,p,(int)strlen(p)); }

/* ============ JSON ============ */
typedef struct jval {
    int type; /* 0=null 1=true 2=false 3=num 4=str 5=arr 6=obj */
    double num;
    char *str;
    struct jval **arr; int alen;
    char **keys; struct jval **vals; int olen;
} jval;

static void skip_ws(const char **p){ while(**p==' '||**p=='\t'||**p=='\n'||**p=='\r')(*p)++; }

static char *jparse_str_raw(const char **p){
    (*p)++;
    dstr s; dstr_init(&s);
    while(**p && **p!='"'){
        if(**p=='\\'){
            (*p)++;
            switch(**p){
                case '"': dstr_ach(&s,'"'); break;
                case '\\': dstr_ach(&s,'\\'); break;
                case '/': dstr_ach(&s,'/'); break;
                case 'b': dstr_ach(&s,'\b'); break;
                case 'f': dstr_ach(&s,'\f'); break;
                case 'n': dstr_ach(&s,'\n'); break;
                case 'r': dstr_ach(&s,'\r'); break;
                case 't': dstr_ach(&s,'\t'); break;
                case 'u': {
                    (*p)++;
                    char hx[5]={0}; memcpy(hx,*p,4); *p+=4;
                    unsigned cp=(unsigned)strtol(hx,NULL,16);
                    if(cp>=0xD800&&cp<=0xDBFF && **p=='\\' && *(*p+1)=='u'){
                        *p+=2; char hx2[5]={0}; memcpy(hx2,*p,4); *p+=4;
                        unsigned lo=(unsigned)strtol(hx2,NULL,16);
                        if(lo>=0xDC00&&lo<=0xDFFF) cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    if(cp<0x80) dstr_ach(&s,(char)cp);
                    else if(cp<0x800){ dstr_ach(&s,(char)(0xC0|(cp>>6))); dstr_ach(&s,(char)(0x80|(cp&0x3F))); }
                    else if(cp<0x10000){ dstr_ach(&s,(char)(0xE0|(cp>>12))); dstr_ach(&s,(char)(0x80|((cp>>6)&0x3F))); dstr_ach(&s,(char)(0x80|(cp&0x3F))); }
                    else { dstr_ach(&s,(char)(0xF0|(cp>>18))); dstr_ach(&s,(char)(0x80|((cp>>12)&0x3F))); dstr_ach(&s,(char)(0x80|((cp>>6)&0x3F))); dstr_ach(&s,(char)(0x80|(cp&0x3F))); }
                    continue;
                }
                default: dstr_ach(&s,**p); break;
            }
            (*p)++;
        } else { dstr_ach(&s,**p); (*p)++; }
    }
    if(**p=='"') (*p)++;
    if(!s.data){ s.data=malloc(1); s.data[0]=0; }
    return s.data;
}

static jval *jparse(const char **p){
    skip_ws(p);
    jval *v=calloc(1,sizeof(jval));
    char c=**p;
    if(c=='"'){ v->type=4; v->str=jparse_str_raw(p); }
    else if(c=='{'){
        v->type=6; (*p)++; skip_ws(p);
        int cap=8; v->keys=malloc(cap*sizeof(char*)); v->vals=malloc(cap*sizeof(jval*)); v->olen=0;
        if(**p!='}'){
            for(;;){
                skip_ws(p); char *k=jparse_str_raw(p); skip_ws(p); (*p)++;
                jval *val=jparse(p);
                if(v->olen>=cap){cap*=2;v->keys=realloc(v->keys,cap*sizeof(char*));v->vals=realloc(v->vals,cap*sizeof(jval*));}
                v->keys[v->olen]=k; v->vals[v->olen]=val; v->olen++;
                skip_ws(p); if(**p==','){(*p)++;continue;} break;
            }
        }
        if(**p=='}')(*p)++;
    } else if(c=='['){
        v->type=5; (*p)++; skip_ws(p);
        int cap=8; v->arr=malloc(cap*sizeof(jval*)); v->alen=0;
        if(**p!=']'){
            for(;;){
                jval *item=jparse(p);
                if(v->alen>=cap){cap*=2;v->arr=realloc(v->arr,cap*sizeof(jval*));}
                v->arr[v->alen++]=item;
                skip_ws(p); if(**p==','){(*p)++;continue;} break;
            }
        }
        if(**p==']')(*p)++;
    } else if(c=='t'){v->type=1;*p+=4;}
    else if(c=='f'){v->type=2;*p+=5;}
    else if(c=='n'){v->type=0;*p+=4;}
    else { v->type=3; char *end; v->num=strtod(*p,&end); *p=end; }
    return v;
}

static void jfree(jval *v){
    if(!v)return;
    if(v->type==4)free(v->str);
    else if(v->type==5){for(int i=0;i<v->alen;i++)jfree(v->arr[i]);free(v->arr);}
    else if(v->type==6){for(int i=0;i<v->olen;i++){free(v->keys[i]);jfree(v->vals[i]);}free(v->keys);free(v->vals);}
    free(v);
}

static jval *jget(jval *o,const char *k){
    if(!o||o->type!=6)return NULL;
    for(int i=0;i<o->olen;i++) if(!strcmp(o->keys[i],k)) return o->vals[i];
    return NULL;
}
static const char *jstr(jval *v){return(v&&v->type==4)?v->str:"";}
static int jint(jval *v){return(v&&v->type==3)?(int)v->num:0;}

static void jesc_str(dstr *out, const char *s){
    dstr_ach(out,'"');
    for(const char *c=s;*c;c++){
        unsigned char uc=(unsigned char)*c;
        if(uc=='"') dstr_aps(out,"\\\"");
        else if(uc=='\\') dstr_aps(out,"\\\\");
        else if(uc=='\n') dstr_aps(out,"\\n");
        else if(uc=='\r') dstr_aps(out,"\\r");
        else if(uc=='\t') dstr_aps(out,"\\t");
        else if(uc<0x20){char b[8];snprintf(b,sizeof(b),"\\u%04x",uc);dstr_aps(out,b);}
        else dstr_ach(out,*c);
    }
    dstr_ach(out,'"');
}

static void jser(dstr *out, jval *v){
    if(!v){dstr_aps(out,"null");return;}
    switch(v->type){
        case 0:dstr_aps(out,"null");break;
        case 1:dstr_aps(out,"true");break;
        case 2:dstr_aps(out,"false");break;
        case 3:{
            if(v->num==(double)(long long)v->num && fabs(v->num)<1e15){
                char b[32];snprintf(b,sizeof(b),"%lld",(long long)v->num);dstr_aps(out,b);
            } else { char b[64];snprintf(b,sizeof(b),"%.17g",v->num);dstr_aps(out,b); }
            break;
        }
        case 4: jesc_str(out,v->str); break;
        case 5:
            dstr_ach(out,'[');
            for(int i=0;i<v->alen;i++){if(i)dstr_ach(out,',');jser(out,v->arr[i]);}
            dstr_ach(out,']');
            break;
        case 6:
            dstr_ach(out,'{');
            for(int i=0;i<v->olen;i++){
                if(i)dstr_ach(out,',');
                jesc_str(out,v->keys[i]);
                dstr_ach(out,':');
                jser(out,v->vals[i]);
            }
            dstr_ach(out,'}');
            break;
    }
}

/* ============ Buffered Socket Reader ============ */
typedef struct { int fd; unsigned char buf[65536]; int start,end,eof; } sreader;
static void sr_init(sreader *r,int fd){r->fd=fd;r->start=r->end=r->eof=0;}
static int sr_fill(sreader *r){
    if(r->start<r->end)return r->end-r->start;
    if(r->eof)return 0;
    r->start=0;
    int n=recv(r->fd,r->buf,sizeof(r->buf),0);
    if(n<=0){r->eof=1;return 0;}
    r->end=n;return n;
}
static int sr_getc(sreader *r){
    if(r->start>=r->end){if(sr_fill(r)==0)return -1;}
    return r->buf[r->start++];
}
static int sr_readline(sreader *r, dstr *line){
    line->len=0;
    for(;;){
        int c=sr_getc(r);
        if(c==-1){if(line->data)line->data[line->len]='\0';return -1;}
        if(c=='\n'){
            if(line->len>0&&line->data[line->len-1]=='\r')line->data[--line->len]='\0';
            else{dstr_res(line,1);line->data[line->len]='\0';}
            return 0;
        }
        dstr_ach(line,(char)c);
    }
}

/* ============ HTTP ============ */
typedef struct { char host[256]; int port; char path[512]; } url_info;
static void parse_url(const char *url, url_info *u){
    const char *p=strstr(url,"http://");
    if(p)p+=7;else p=url;
    const char *slash=strchr(p,'/');
    if(slash){
        int hlen=(int)(slash-p);
        if(hlen>255)hlen=255;
        memcpy(u->host,p,hlen);u->host[hlen]='\0';
        strncpy(u->path,slash,511);u->path[511]='\0';
    } else {
        strncpy(u->host,p,255);u->host[255]='\0';
        strcpy(u->path,"/");
    }
    char *colon=strrchr(u->host,':');
    if(colon){*colon='\0';u->port=atoi(colon+1);}
    else u->port=80;
}

static int http_connect(url_info *u){
    struct sockaddr_in sa; memset(&sa,0,sizeof(sa));
    sa.sin_family=AF_INET; sa.sin_port=htons(u->port);
    inet_pton(AF_INET,u->host,&sa.sin_addr);
    int fd=socket(AF_INET,SOCK_STREAM,0);
    if(connect(fd,(struct sockaddr*)&sa,sizeof(sa))<0){perror("connect");exit(1);}
    return fd;
}

static void send_all(int fd, const char *buf, int len){
    int off=0;
    while(off<len){int n=send(fd,buf+off,len-off,0);if(n<=0)break;off+=n;}
}

/* ============ Content Blocks ============ */
typedef struct {
    int type; /* 0=thinking 1=text 2=tool_use */
    dstr thinking, signature, text;
    char *id, *name;
    dstr input_json;
} cblock;

typedef struct {
    cblock blocks[64];
    int nblocks;
    char stop_reason[64];
    int input_tokens, output_tokens, cache_read;
} reply_state;

static void reply_init(reply_state *rs){
    memset(rs,0,sizeof(*rs));
    for(int i=0;i<64;i++){dstr_init(&rs->blocks[i].thinking);dstr_init(&rs->blocks[i].signature);dstr_init(&rs->blocks[i].text);dstr_init(&rs->blocks[i].input_json);}
}

/* ============ SSE Callback Context ============ */
typedef struct { reply_state *rs; } sse_ctx;

static void sse_cb(const char *event, const char *data, void *ctx){
    sse_ctx *sc=(sse_ctx*)ctx;
    reply_state *rs=sc->rs;
    const char *dp=data;
    jval *ev=jparse(&dp);
    if(!ev)return;

    if(!strcmp(event,"message_start")){
        jval *msg=jget(ev,"message");
        if(msg){
            jval *usage=jget(msg,"usage");
            if(usage){
                rs->input_tokens+=jint(jget(usage,"input_tokens"));
                rs->cache_read+=jint(jget(usage,"cache_read_input_tokens"));
            }
        }
    } else if(!strcmp(event,"content_block_start")){
        int idx=jint(jget(ev,"index"));
        jval *cb=jget(ev,"content_block");
        if(cb&&idx>=0&&idx<64){
            cblock *b=&rs->blocks[idx];
            const char *t=jstr(jget(cb,"type"));
            if(!strcmp(t,"thinking")){b->type=0;dstr_aps(&b->thinking,jstr(jget(cb,"thinking")));dstr_aps(&b->signature,jstr(jget(cb,"signature")));}
            else if(!strcmp(t,"text")){b->type=1;dstr_aps(&b->text,jstr(jget(cb,"text")));}
            else if(!strcmp(t,"tool_use")){b->type=2;b->id=strdup(jstr(jget(cb,"id")));b->name=strdup(jstr(jget(cb,"name")));}
            if(idx>=rs->nblocks)rs->nblocks=idx+1;
        }
    } else if(!strcmp(event,"content_block_delta")){
        int idx=jint(jget(ev,"index"));
        jval *delta=jget(ev,"delta");
        if(delta&&idx>=0&&idx<64){
            cblock *b=&rs->blocks[idx];
            const char *dt=jstr(jget(delta,"type"));
            if(!strcmp(dt,"thinking_delta")) dstr_aps(&b->thinking,jstr(jget(delta,"thinking")));
            else if(!strcmp(dt,"signature_delta")) dstr_aps(&b->signature,jstr(jget(delta,"signature")));
            else if(!strcmp(dt,"text_delta")) dstr_aps(&b->text,jstr(jget(delta,"text")));
            else if(!strcmp(dt,"input_json_delta")) dstr_aps(&b->input_json,jstr(jget(delta,"partial_json")));
        }
    } else if(!strcmp(event,"message_delta")){
        jval *delta=jget(ev,"delta");
        if(delta){
            const char *sr=jstr(jget(delta,"stop_reason"));
            if(sr)strncpy(rs->stop_reason,sr,63);
        }
        jval *usage=jget(ev,"usage");
        if(usage) rs->output_tokens+=jint(jget(usage,"output_tokens"));
    }
    jfree(ev);
}

/* ============ SSE Parser ============ */
static void parse_sse(const unsigned char *body, int len, void(*cb)(const char*,const char*,void*),void *ctx){
    int pos=0;
    dstr evname; dstr_init(&evname);
    dstr databuf; dstr_init(&databuf);
    int has_data=0;
    while(pos<len){
        dstr line; dstr_init(&line);
        while(pos<len && body[pos]!='\n'){
            if(body[pos]=='\r'&&pos+1<len&&body[pos+1]=='\n'){pos++;break;}
            dstr_ach(&line,(char)body[pos]);pos++;
        }
        if(pos<len&&body[pos]=='\n')pos++;

        if(line.len==0){
            if(has_data){
                cb(evname.data?evname.data:"message",databuf.data?databuf.data:"",ctx);
            }
            evname.len=0;if(evname.data)evname.data[0]=0;
            databuf.len=0;if(databuf.data)databuf.data[0]=0;
            has_data=0;
        } else if(line.data[0]==':'){
            /* comment */
        } else if(line.len>=6&&strncmp(line.data,"event:",6)==0){
            const char *v=line.data+6;
            if(*v==' ')v++;
            evname.len=0; if(!evname.data){evname.data=malloc(128);evname.cap=128;} evname.data[0]=0;
            dstr_aps(&evname,v);
        } else if(line.len>=5&&strncmp(line.data,"data:",5)==0){
            const char *v=line.data+5;
            if(*v==' ')v++;
            if(has_data)dstr_ach(&databuf,'\n');
            dstr_aps(&databuf,v);
            has_data=1;
        }
        dstr_free(&line);
    }
    if(has_data) cb(evname.data?evname.data:"message",databuf.data?databuf.data:"",ctx);
    dstr_free(&evname); dstr_free(&databuf);
}

/* ============ Read HTTP Response ============ */
static int read_response(sreader *r, dstr *body, int *status){
    dstr line; dstr_init(&line);
    /* status line */
    if(sr_readline(r,&line)<0){dstr_free(&line);return -1;}
    *status=atoi(line.data+9);
    int content_length=-1;
    int chunked=0;
    /* headers */
    for(;;){
        if(sr_readline(r,&line)<0)break;
        if(line.len==0)break;
        if(strncasecmp(line.data,"Content-Length:",13)==0) content_length=atoi(line.data+13);
        if(strncasecmp(line.data,"Transfer-Encoding:",16)==0){
            if(strcasestr(line.data,"chunked"))chunked=1;
        }
    }
    dstr_free(&line);

    body->len=0;
    if(*status==200 && chunked){
        /* read chunked body */
        dstr ln; dstr_init(&ln);
        for(;;){
            if(sr_readline(r,&ln)<0)break;
            int csz=(int)strtol(ln.data,NULL,16);
            if(csz==0){
                /* read trailer/final CRLF */
                for(;;){
                    if(sr_readline(r,&ln)<0)break;
                    if(ln.len==0)break;
                }
                break;
            }
            for(int i=0;i<csz;i++){
                int c=sr_getc(r);
                if(c==-1)break;
                dstr_ach(body,(char)c);
            }
            /* CRLF after chunk data */
            sr_readline(r,&ln);
        }
        dstr_free(&ln);
    } else if(content_length>=0){
        for(int i=0;i<content_length;i++){
            int c=sr_getc(r);
            if(c==-1)break;
            dstr_ach(body,(char)c);
        }
    } else {
        /* read until EOF */
        for(;;){int c=sr_getc(r);if(c==-1)break;dstr_ach(body,(char)c);}
    }
    return 0;
}

/* ============ Unicode ============ */
static int utf8_decode(const char *s, int slen, unsigned int **out){
    unsigned int *cps=malloc((slen+1)*sizeof(unsigned int));
    int n=0,i=0;
    while(i<slen){
        unsigned char c=(unsigned char)s[i];
        unsigned cp; int nb;
        if(c<0x80){cp=c;nb=1;}
        else if((c&0xE0)==0xC0){cp=c&0x1F;nb=2;}
        else if((c&0xF0)==0xE0){cp=c&0x0F;nb=3;}
        else if((c&0xF8)==0xF0){cp=c&0x07;nb=4;}
        else{cp=0xFFFD;nb=1;}
        i++;
        for(int j=1;j<nb&&i<slen;j++,i++) cp=(cp<<6)|((unsigned char)s[i]&0x3F);
        cps[n++]=cp;
    }
    *out=cps;return n;
}
static void utf8_enc(dstr *out, unsigned cp){
    if(cp<0x80)dstr_ach(out,(char)cp);
    else if(cp<0x800){dstr_ach(out,(char)(0xC0|(cp>>6)));dstr_ach(out,(char)(0x80|(cp&0x3F)));}
    else if(cp<0x10000){dstr_ach(out,(char)(0xE0|(cp>>12)));dstr_ach(out,(char)(0x80|((cp>>6)&0x3F)));dstr_ach(out,(char)(0x80|(cp&0x3F)));}
    else{dstr_ach(out,(char)(0xF0|(cp>>18)));dstr_ach(out,(char)(0x80|((cp>>12)&0x3F)));dstr_ach(out,(char)(0x80|((cp>>6)&0x3F)));dstr_ach(out,(char)(0x80|(cp&0x3F)));}
}

/* ============ Tools ============ */
static char *do_tool(const char *name, jval *input){
    if(!strcmp(name,"measure")){
        const char *text=jstr(jget(input,"text"));
        const char *unit=jstr(jget(input,"unit"));
        int tlen=(int)strlen(text);
        char buf[256];
        if(!strcmp(unit,"code_points")){
            unsigned *cps;int n=utf8_decode(text,tlen,&cps);free(cps);
            snprintf(buf,sizeof(buf),"%d",n);return strdup(buf);
        } else if(!strcmp(unit,"utf8_bytes")){
            snprintf(buf,sizeof(buf),"%d",tlen);return strdup(buf);
        } else if(!strcmp(unit,"utf16_units")){
            unsigned *cps;int n=utf8_decode(text,tlen,&cps);
            int units=0;for(int i=0;i<n;i++)units+=(cps[i]>0xFFFF)?2:1;
            free(cps);
            snprintf(buf,sizeof(buf),"%d",units);return strdup(buf);
        } else {
            snprintf(buf,sizeof(buf),"unsupported unit: %s",unit);return strdup(buf);
        }
    } else if(!strcmp(name,"reverse")){
        const char *text=jstr(jget(input,"text"));
        int tlen=(int)strlen(text);
        unsigned *cps;int n=utf8_decode(text,tlen,&cps);
        dstr out;dstr_init(&out);
        for(int i=n-1;i>=0;i--)utf8_enc(&out,cps[i]);
        free(cps);
        if(!out.data){out.data=malloc(1);out.data[0]=0;}
        return out.data;
    } else {
        char buf[256];snprintf(buf,sizeof(buf),"unknown tool: %s",name);return strdup(buf);
    }
}

/* ============ Output escaping ============ */
static void print_esc(const char *s){
    if(!s)return;
    for(const char *c=s;*c;c++){
        if(*c=='\\')printf("\\\\");
        else if(*c=='\n')printf("\\n");
        else if(*c=='\r')printf("\\r");
        else if(*c=='\t')printf("\\t");
        else putchar(*c);
    }
}

/* ============ Main ============ */
int main(int argc, char **argv){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char *data_dir=argv[1];
    const char *base_url=argv[2];

    /* Read request.json */
    char rpath[1024];
    snprintf(rpath,sizeof(rpath),"%s/request.json",data_dir);
    FILE *f=fopen(rpath,"rb");
    if(!f){perror("open request.json");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char *raw=malloc(fsz+1);
    fread(raw,1,fsz,f);raw[fsz]='\0';fclose(f);

    const char *rp=raw;
    jval *cfg=jparse(&rp);

    const char *api_key=jstr(jget(cfg,"api_key"));
    const char *model=jstr(jget(cfg,"model"));
    int max_tokens=jint(jget(cfg,"max_tokens"));
    int thinking_budget=jint(jget(cfg,"thinking_budget"));
    jval *system_v=jget(cfg,"system");
    jval *prompt_v=jget(cfg,"prompt");
    jval *tools_v=jget(cfg,"tools");

    url_info u; parse_url(base_url,&u);

    reply_state total; memset(&total,0,sizeof(total));
    total.input_tokens=total.output_tokens=total.cache_read=0;

    /* ---- Request 1 ---- */
    dstr body1; dstr_init(&body1);
    dstr_aps(&body1,"{\"model\":");jesc_str(&body1,model);
    dstr_aps(&body1,",\"max_tokens\":");{char b[32];snprintf(b,sizeof(b),"%d",max_tokens);dstr_aps(&body1,b);}
    dstr_aps(&body1,",\"stream\":true");
    dstr_aps(&body1,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");{char b[32];snprintf(b,sizeof(b),"%d",thinking_budget);dstr_aps(&body1,b);}
    dstr_aps(&body1,"}");
    dstr_aps(&body1,",\"system\":");jser(&body1,system_v);
    dstr_aps(&body1,",\"tools\":");jser(&body1,tools_v);
    dstr_aps(&body1,",\"messages\":[{\"role\":\"user\",\"content\":");jser(&body1,prompt_v);
    dstr_aps(&body1,"}]}");

