            }
        }

        char[] bridged = Arrays.copyOf(labels, numBlocks);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (labels[i] == '\0' && labels[i - 1] != '\0' && labels[i + 1] != '\0' && labels[i - 1] == labels[i + 1]) {
                bridged[i] = labels[i - 1];
            }
        }

        List<char[]> events = new ArrayList<>();
        List<Character> digits = new ArrayList<>();

        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] != '\0') {
                int j = i;
                while (j < numBlocks && bridged[j] == bridged[i]) j++;
                if (j - i >= 2) {
                    int startMs = 20 * i;
                    int endMs = 20 * j;
                    events.add(new char[]{bridged[i]});
