                while (j < numBlocks && bridged[j] == bridged[i]) j++;
                if (j - i >= 2) {
                    eventList.add(new int[]{bridged[i], 20 * i, 20 * j});
                    digitList.add(bridged[i]);
                }
                i = j;
            } else {
                i++;
            }
        }

