        for (int[] ev : eventList) {
            System.out.println((char) ev[0] + " " + ev[1] + " " + ev[2]);
        }
        StringBuilder sb = new StringBuilder("digits: ");
        for (char c : digitList) sb.append(c);
        System.out.println(sb.toString());
    }

    static double goertzel(int[] samples, int start, int N, int freq, int rate, long E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0.0, s2 = 0.0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / ((double) N * (double) E);
    }

    static int readLE16(byte[] b, int offset) {
        return (b[offset] & 0xFF) | ((b[offset + 1] & 0xFF) << 8);
    }

    static int readLE32(byte[] b, int offset) {
        return (b[offset] & 0xFF) | ((b[offset + 1] & 0xFF) << 8) | ((b[offset + 2] & 0xFF) << 16) | ((b[offset + 3] & 0xFF) << 24);
    }
