import * as path from 'path';

const dir = process.argv[2];

// Get all .wav files sorted by byte-wise ascending order of file name
const entries = fs.readdirSync(dir);
const wavFiles = entries.filter(f => f.endsWith('.wav')).sort((a, b) => {
    return Buffer.from(a, 'utf-8').compare(Buffer.from(b, 'utf-8'));
});

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];

const KEYPAD: string[][] = [
    ['1', '2', '3', 'A'],
    ['4', '5', '6', 'B'],
    ['7', '8', '9', 'C'],
    ['*', '0', '#', 'D'],
];

function parseWav(filePath: string): { channels: number; rate: number; samples: number[] } | null {
    const buf = fs.readFileSync(filePath);

    if (buf.length < 12) return null;
    if (buf.toString('ascii', 0, 4) !== 'RIFF') return null;
    if (buf.toString('ascii', 8, 12) !== 'WAVE') return null;

    let offset = 12;
    let fmtBody: Buffer | null = null;
    let dataBody: Buffer | null = null;
    let dataSize = 0;

    while (offset + 8 <= buf.length) {
        const chunkId = buf.toString('ascii', offset, offset + 4);
        const chunkSize = buf.readUInt32LE(offset + 4);
        const bodyStart = offset + 8;

        if (chunkId === 'fmt ') {
            fmtBody = buf.subarray(bodyStart, Math.min(bodyStart + chunkSize, buf.length));
        } else if (chunkId === 'data') {
            dataSize = chunkSize;
            dataBody = buf.subarray(bodyStart, Math.min(bodyStart + chunkSize, buf.length));
        }

        offset = bodyStart + chunkSize;
        if (chunkSize % 2 === 1) offset += 1;
    }

    if (!fmtBody || !dataBody) return null;

    const formatTag = fmtBody.readUInt16LE(0);
    const channels = fmtBody.readUInt16LE(2);
    const rate = fmtBody.readUInt32LE(4);
    const bitsPerSample = fmtBody.readUInt16LE(14);

    let effectiveFormat = formatTag;
    if (formatTag === 0xFFFE) {
        if (fmtBody.length < 26) return null;
        effectiveFormat = fmtBody.readUInt16LE(24);
    }

    if (effectiveFormat !== 1 || bitsPerSample !== 16) return null;
    if (channels !== 1 && channels !== 2) return null;
    if (rate !== 8000 && rate !== 16000) return null;

    const frameSize = 2 * channels;
    const numFrames = Math.floor(dataSize / frameSize);
    const samples: number[] = [];

    for (let i = 0; i < numFrames; i++) {
        const byteOffset = i * frameSize;
        if (byteOffset + 2 > dataBody.length) break;
        samples.push(dataBody.readInt16LE(byteOffset));
    }

    return { channels, rate, samples };
}

function goertzelPower(x: number[], f: number, rate: number, N: number): number {
    const c = 2 * Math.cos(2 * Math.PI * f / rate);
    let s1 = 0.0;
    let s2 = 0.0;
    for (let n = 0; n < N; n++) {
        const s = x[n] + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    return s1 * s1 + s2 * s2 - c * s1 * s2;
}

function detectDigit(x: number[], rate: number, N: number): string | null {
    let E = 0.0;
    for (let n = 0; n < N; n++) {
        E += x[n] * x[n];
    }

    if (E < 1000000.0 * N) return null;

    let maxLowR = -1.0;
    let maxLowIdx = -1;
    let maxHighR = -1.0;
    let maxHighIdx = -1;

    for (let i = 0; i < 4; i++) {
        const P = goertzelPower(x, LOW_FREQS[i], rate, N);
        const r = 2.0 * P / (N * E);
        if (r > maxLowR) {
            maxLowR = r;
            maxLowIdx = i;
        }
    }

    for (let i = 0; i < 4; i++) {
        const P = goertzelPower(x, HIGH_FREQS[i], rate, N);
        const r = 2.0 * P / (N * E);
        if (r > maxHighR) {
            maxHighR = r;
            maxHighIdx = i;
        }
    }

    if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
        return KEYPAD[maxLowIdx][maxHighIdx];
    }

    return null;
}

let firstFile = true;

for (const name of wavFiles) {
    if (!firstFile) console.log('');
    firstFile = false;

    const filePath = path.join(dir, name);
    const result = parseWav(filePath);

    if (!result) {
        console.log(`${name}: unsupported`);
        continue;
    }

    const { channels, rate, samples } = result;
    const N = rate / 50;
    const numBlocks = Math.floor(samples.length / N);

    console.log(`${name}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);

    // Step 3: Detect digits per block
    const labels: (string | null)[] = [];
    for (let i = 0; i < numBlocks; i++) {
        const blockStart = i * N;
        const block = samples.slice(blockStart, blockStart + N);
        labels.push(detectDigit(block, rate, N));
    }

    // Step 4: Bridging (decide from original labels)
    const bridged: (string | null)[] = [...labels];
    for (let i = 1; i < numBlocks - 1; i++) {
        if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
            bridged[i] = labels[i - 1];
        }
    }

    // Step 5: Events (runs of length >= 2)
    const events: { digit: string; start: number; end: number }[] = [];
    let i = 0;
    while (i < numBlocks) {
        if (bridged[i] !== null) {
            const digit = bridged[i]!;
            let j = i + 1;
            while (j < numBlocks && bridged[j] === digit) j++;
            const runLength = j - i;
            if (runLength >= 2) {
                events.push({ digit, start: 20 * i, end: 20 * j });
            }
            i = j;
        } else {
            i++;
        }
    }

    for (const ev of events) {
        console.log(`${ev.digit} ${ev.start} ${ev.end}`);
    }

    console.log(`digits: ${events.map(e => e.digit).join('')}`);
}

process.exit(0);

