import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const filePath = path.join(dir, 'db.sqlite');
const buf = fs.readFileSync(filePath);

const pageSizeRaw = buf.readUInt16BE(16);
const pageSize = pageSizeRaw === 1 ? 65536 : pageSizeRaw;
const reservedBytes = buf[20];
const usableSize = pageSize - reservedBytes;

const maxPayload = usableSize - 35;
const maxLocal = Math.floor(((usableSize - 12) * 64) / 255) - 23;
const minLocal = Math.floor(((usableSize - 12) * 32) / 255) - 23;

function getPage(pageNum: number): Buffer {
  return buf.slice((pageNum - 1) * pageSize, pageNum * pageSize);
}

function readVarint(b: Buffer, offset: number): [bigint, number] {
  let value = 0n;
  let i = 0;
  while (i < 8) {
    const byte = b[offset + i];
    if (byte & 0x80) {
      value = (value << 7n) | BigInt(byte & 0x7F);
      i++;
    } else {
      value = (value << 7n) | BigInt(byte & 0x7F);
      return [value, offset + i + 1];
    }
  }
  value = (value << 8n) | BigInt(b[offset + 8]);
  return [value, offset + 9];
}

function toSigned64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  if (v >= 0x8000000000000000n) {
    return v - 0x10000000000000000n;
  }
  return v;
}

function readSignedInt(b: Buffer, offset: number, numBytes: number): bigint {
  let value = 0n;
  for (let i = 0; i < numBytes; i++) {
    value = (value << 8n) | BigInt(b[offset + i]);
  }
  if (b[offset] & 0x80) {
    value -= (1n << BigInt(numBytes * 8));
  }
  return value;
}

type Value = null | bigint | number | { type: 'text' | 'blob'; data: Buffer };

function parseRecord(data: Buffer): Value[] {
  let offset = 0;
  const [headerSizeBig, o1] = readVarint(data, offset);
  const headerSize = Number(headerSizeBig);
  offset = o1;

  const serialTypes: number[] = [];
  while (offset < headerSize) {
    const [st, no] = readVarint(data, offset);
    serialTypes.push(Number(st));
    offset = no;
  }

  const values: Value[] = [];
  for (const st of serialTypes) {
    if (st === 0) {
      values.push(null);
    } else if (st >= 1 && st <= 4) {
      values.push(readSignedInt(data, offset, st));
      offset += st;
    } else if (st === 5) {
      values.push(readSignedInt(data, offset, 6));
      offset += 6;
    } else if (st === 6) {
      values.push(data.readBigInt64BE(offset));
      offset += 8;
    } else if (st === 7) {
      values.push(data.readDoubleBE(offset));
      offset += 8;
    } else if (st === 8) {
      values.push(0n);
    } else if (st === 9) {
      values.push(1n);
    } else if (st >= 12 && st % 2 === 0) {
      const len = (st - 12) / 2;
      values.push({ type: 'blob', data: data.slice(offset, offset + len) });
      offset += len;
    } else if (st >= 13 && st % 2 === 1) {
      const len = (st - 13) / 2;
      values.push({ type: 'text', data: data.slice(offset, offset + len) });
      offset += len;
    }
  }
  return values;
}

function walkBTree(rootPage: number): Array<{ rowid: bigint; payload: Buffer }> {
  const results: Array<{ rowid: bigint; payload: Buffer }> = [];

  function walk(pageNum: number) {
    const page = getPage(pageNum);
    const hdrOff = pageNum === 1 ? 100 : 0;
    const ptype = page[hdrOff];
    const numCells = page.readUInt16BE(hdrOff + 3);
    const cellPtrStart = hdrOff + (ptype === 5 ? 12 : 8);

    if (ptype === 5) {
      for (let i = 0; i < numCells; i++) {
        const cellOff = page.readUInt16BE(cellPtrStart + i * 2);
        const leftChild = page.readUInt32BE(cellOff);
        walk(leftChild);
      }
      const rightMost = page.readUInt32BE(hdrOff + 7);
      walk(rightMost);
    } else if (ptype === 13) {
      for (let i = 0; i < numCells; i++) {
        const cellOff = page.readUInt16BE(cellPtrStart + i * 2);
        let off = cellOff;
        const [psBig, o1] = readVarint(page, off);
        off = o1;
        const [rowidRaw, o2] = readVarint(page, off);
        off = o2;
        const rowid = toSigned64(rowidRaw);
        const ps = Number(psBig);

        let localSize: number;
        let overflowPage = 0;

        if (ps <= maxPayload) {
          localSize = ps;
        } else {
          const k = minLocal + ((ps - minLocal) % (usableSize - 4));
          if (k <= maxLocal) {
            localSize = k;
          } else {
            localSize = minLocal;
          }
          overflowPage = page.readUInt32BE(off + localSize);
        }

        let payload: Buffer;
        if (overflowPage > 0) {
          payload = Buffer.alloc(ps);
          page.copy(payload, 0, off, off + localSize);
          let remaining = ps - localSize;
          let dest = localSize;
          let op = overflowPage;
          while (op > 0 && remaining > 0) {
            const opPage = getPage(op);
            const nextOp = opPage.readUInt32BE(0);
            const chunkSize = Math.min(remaining, usableSize - 4);
            opPage.copy(payload, dest, 4, 4 + chunkSize);
            dest += chunkSize;
            remaining -= chunkSize;
            op = nextOp;
          }
        } else {
          payload = Buffer.alloc(ps);
          page.copy(payload, 0, off, off + localSize);
        }

        results.push({ rowid, payload });
      }
    }
  }

  walk(rootPage);
  return results;
}

function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
      else crc = crc >>> 1;
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(x: number): string {
  const negative = x < 0 || Object.is(x, -0);
  const abs = Math.abs(x);
  let intPart: string;
  let fracPart: string;

  if (Number.isInteger(abs)) {
    intPart = BigInt(abs).toString();
    fracPart = '0';
  } else {
    const s = abs.toFixed(8);
    const dotIdx = s.indexOf('.');
    intPart = s.substring(0, dotIdx);
    fracPart = s.substring(dotIdx + 1).replace(/0+$/, '') || '0';
  }

  return (negative ? '-' : '') + intPart + '.' + fracPart;
}

function escapeText(data: Buffer): string {
  const str = data.toString('utf-8');
  let result = '"';
  for (const ch of str) {
    const code = ch.codePointAt(0)!;
    if (ch === '\\') result += '\\\\';
    else if (ch === '"') result += '\\"';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\r') result += '\\r';
    else if (ch === '\t') result += '\\t';
    else if (code < 0x20 || code === 0x7F)
      result += '\\x' + code.toString(16).toUpperCase().padStart(2, '0');
    else result += ch;
  }
  result += '"';
  return result;
}

function formatValue(v: Value): string {
  if (v === null) return 'NULL';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'number') return formatReal(v);
  const data = v.data;
  const len = data.length;
  if (len <= 100) {
    if (v.type === 'text') return escapeText(data);
    else return "X'" + data.toString('hex').toUpperCase() + "'";
  } else {
    const crc = crc32(data).toString(16).padStart(8, '0');
    if (v.type === 'text') return `<TEXT len=${len} crc32=${crc}>`;
    else return `<BLOB len=${len} crc32=${crc}>`;
  }
}

function parseCreateTable(sql: string): { columns: string[]; ipkSet: Set<number> } {
  const columns: string[] = [];
  const ipkSet = new Set<number>();
  let i = 0;

  const skipWS = () => { while (i < sql.length && /\s/.test(sql[i])) i++; };

  const readIdent = (): string => {
    skipWS();
    if (i < sql.length && sql[i] === '"') {
      i++;
      let name = '';
      while (i < sql.length && sql[i] !== '"') { name += sql[i]; i++; }
      i++;
      return name;
    } else {
      let name = '';
      while (i < sql.length && /[a-zA-Z0-9_]/.test(sql[i])) { name += sql[i]; i++; }
      return name;
    }
  };

