    const ch = sql[i];
    if (ch === '(') { depth++; currentDef += ch; i++; }
    else if (ch === ')') {
      if (depth === 0) { if (currentDef.trim()) defs.push(currentDef); i++; break; }
      depth--; currentDef += ch; i++;
    } else if (ch === ',' && depth === 0) { defs.push(currentDef); currentDef = ''; i++; }
    else { currentDef += ch; i++; }
  }

