    const def = defs[di];
    let j = 0;
    while (j < def.length && /\s/.test(def[j])) j++;

    let colName: string;
    if (j < def.length && def[j] === '"') {
      j++;
      colName = '';
      while (j < def.length && def[j] !== '"') { colName += def[j]; j++; }
      j++;
    } else {
      colName = '';
      while (j < def.length && /[a-zA-Z0-9_]/.test(def[j])) { colName += def[j]; j++; }
    }
    columns.push(colName);

    let k = j;
    while (k < def.length && /\s/.test(def[k])) k++;
    let typeName = '';
    while (k < def.length && /[a-zA-Z0-9_]/.test(def[k])) { typeName += def[k]; k++; }

    const restNorm = def.substring(j).replace(/\s+/g, ' ').toUpperCase();
    if (typeName.toUpperCase() === 'INTEGER' && restNorm.includes('PRIMARY KEY')) {
