func parseHTTPResponse(_ raw: Data) -> (status: Int, headers: [String: String], body: Data) {
    let boundary = Data([0x0D, 0x0A, 0x0D, 0x0A])
    guard let range = raw.range(of: boundary) else { fatalError("bad HTTP") }
    let headerData = raw[raw.startIndex..<range.lowerBound]
    let rawBody = Data(raw[range.upperBound...])
    let headerStr = String(data: headerData, encoding: .utf8)!
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].components(separatedBy: " ")[1]) ?? 0
    var headers: [String: String] = [:]
    for i in 1..<lines.count {
        let line = lines[i]
        if let ci = line.firstIndex(of: ":") {
