            }
        case "content_block_start":
            let i = (j["index"] as? Int) ?? 0
            if let cb = j["content_block"] as? [String: Any] {
                var b = ContentBlock(type: cb["type"] as? String ?? "", index: i)
                b.id = cb["id"] as? String ?? ""
                b.name = cb["name"] as? String ?? ""
                blocks[i] = b
            }
        case "content_block_delta":
            let i = (j["index"] as? Int) ?? 0
            guard var b = blocks[i], let d = j["delta"] as? [String: Any] else { continue }
            switch d["type"] as? String ?? "" {
