            case "signature_delta": b.signature += (d["signature"] as? String) ?? ""
            case "text_delta": b.text += (d["text"] as? String) ?? ""
            case "input_json_delta": b.partialJson += (d["partial_json"] as? String) ?? ""
            default: break
            }
