    // Find \r\n\r\n
    var boundaryPos = -1
    if raw.count >= 4 {
        for i in 0...(raw.count - 4) {
            if raw[i] == 0x0D && raw[i+1] == 0x0A && raw[i+2] == 0x0D && raw[i+3] == 0x0A {
                boundaryPos = i
                break
            }
        }
    }
    guard boundaryPos >= 0 else { fatalError("bad HTTP") }
    let headerBytes = Array(raw[0..<boundaryPos])
    let bodyStart = boundaryPos + 4
    let rawBody = Array(raw[bodyStart...])

    let headerStr = String(decoding: headerBytes, as: UTF8.self)
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].components(separatedBy: " ")[1]) ?? 0
    var headers: [String: String] = [:]
    for i in 1..<lines.count {
        let line = lines[i]
        if let ci = line.firstIndex(of: ":") {
            let key = String(line[..<ci]).lowercased()
            let val = String(line[line.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[key] = val
        }
    }
    var body: [UInt8]
    if headers["transfer-encoding"]?.lowercased().contains("chunked") == true {
        body = dechunk(rawBody)
    } else {
        body = rawBody
    }
    return (status, headers, body)
}

// ===== SSE Parsing =====
struct SSEEvent {
    var name: String = ""
    var dataLines: [String] = []
}

func parseSSE(_ data: [UInt8]) -> [SSEEvent] {
    var events: [SSEEvent] = []
    var cur = SSEEvent()
    var hasFields = false
    var pos = 0
    while pos < data.count {
        // Read one line
        var lineBytes: [UInt8] = []
        while pos < data.count && data[pos] != 0x0A {
            lineBytes.append(data[pos])
            pos += 1
        }
        if pos < data.count { pos += 1 } // skip \n
        if lineBytes.last == 0x0D { lineBytes.removeLast() }
        let line = String(decoding: lineBytes, as: UTF8.self)

        if line.isEmpty {
            if hasFields {
                events.append(cur)
                cur = SSEEvent()
                hasFields = false
            }
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            cur.name = v
            hasFields = true
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            cur.dataLines.append(v)
            hasFields = true
        }
        // id:, retry:, etc. are ignored
    }
    // Emit last event if stream didn't end with blank line
    if hasFields { events.append(cur) }
    return events
}

// ===== Content Blocks =====
struct ContentBlock {
    var type: String
    var index: Int
    var id: String = ""
    var name: String = ""
    var thinking: String = ""
    var signature: String = ""
    var text: String = ""
    var partialJson: String = ""
    var input: Any?
}

func processReply(_ events: [SSEEvent]) -> (blocks: [ContentBlock], stopReason: String, inputTokens: Int, outputTokens: Int, cacheReadTokens: Int) {
    var blocks: [Int: ContentBlock] = [:]
    var stopReason = ""
    var inTok = 0, outTok = 0, cacheTok = 0
    for ev in events {
        guard !ev.dataLines.isEmpty else { continue }
        let ds = ev.dataLines.joined(separator: "\n")
        guard let jd = ds.data(using: .utf8),
              let j = try? JSONSerialization.jsonObject(with: jd) as? [String: Any] else { continue }
        switch ev.name {
        case "message_start":
            if let msg = j["message"] as? [String: Any],
               let u = msg["usage"] as? [String: Any] {
                inTok += (u["input_tokens"] as? Int) ?? 0
                cacheTok += (u["cache_read_input_tokens"] as? Int) ?? 0
            }
        case "content_block_start":
            let i = (j["index"] as? Int) ?? 0
            if let cb = j["content_block"] as? [String: Any] {
                var b = ContentBlock(type: cb["type"] as? String ?? "", index: i)
                b.id = cb["id"] as? String ?? ""
                b.name = cb["name"] as? String ?? ""
                blocks[i] = b
            }
        case "content_block_delta":
            let i = (j["index"] as? Int) ?? 0
            guard var b = blocks[i], let d = j["delta"] as? [String: Any] else { continue }
            switch d["type"] as? String ?? "" {
            case "thinking_delta": b.thinking += (d["thinking"] as? String) ?? ""
            case "signature_delta": b.signature += (d["signature"] as? String) ?? ""
            case "text_delta": b.text += (d["text"] as? String) ?? ""
            case "input_json_delta": b.partialJson += (d["partial_json"] as? String) ?? ""
            default: break
            }
            blocks[i] = b
        case "content_block_stop":
            let i = (j["index"] as? Int) ?? 0
            if var b = blocks[i], b.type == "tool_use" {
                if let pd = b.partialJson.data(using: .utf8),
                   let parsed = try? JSONSerialization.jsonObject(with: pd) {
                    b.input = parsed
                }
                blocks[i] = b
            }
        case "message_delta":
            if let d = j["delta"] as? [String: Any] {
                stopReason = (d["stop_reason"] as? String) ?? ""
            }
            if let u = j["usage"] as? [String: Any] {
                outTok += (u["output_tokens"] as? Int) ?? 0
            }
        case "message_stop": break
        default: break
        }
    }
    let sorted = blocks.values.sorted { $0.index < $1.index }
    return (sorted, stopReason, inTok, outTok, cacheTok)
}

// ===== Tools =====
func runTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        guard let text = input["text"] as? String, let unit = input["unit"] as? String else {
            return ("unknown tool: \(name)", true)
        }
        switch unit {
        case "code_points": return (String(text.unicodeScalars.count), false)
        case "utf8_bytes": return (String(text.utf8.count), false)
        case "utf16_units": return (String(text.utf16.count), false)
        default: return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        guard let text = input["text"] as? String else {
            return ("unknown tool: \(name)", true)
        }
        var rev = ""
        for s in text.unicodeScalars.reversed() { rev.unicodeScalars.append(s) }
        return (rev, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

// ===== Output =====
func esc(_ s: String) -> String {
    var r = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(c)
        }
    }
    return r
}

func printBlock(_ b: ContentBlock) {
    switch b.type {
    case "thinking":
        print("thinking \(esc(b.thinking))")
        print("signature \(esc(b.signature))")
    case "text":
        print("text \(esc(b.text))")
    case "tool_use":
        print("tool_use \(esc(b.id)) \(esc(b.name)) \(esc(b.partialJson))")
    default: break
    }
}

// ===== Request Execution =====
func doRequest(host: String, port: Int, path: String, apiKey: String, body: [UInt8]) -> ([ContentBlock], String, Int, Int, Int) {
    let fd = tcpConnect(host: host, port: port)
    tcpSendAll(fd: fd, bytes: buildHTTPRequest(host: host, port: port, path: path, apiKey: apiKey, body: body))
    let raw = tcpRecvAll(fd: fd)
    Darwin.close(fd)
    let (status, _, respBody) = parseHTTPResponse(raw)
    if status != 200 {
        if let j = try? JSONSerialization.jsonObject(with: Data(respBody)) as? [String: Any],
           let err = j["error"] as? [String: Any] {
            print("ERROR \(status) \(err["type"] as? String ?? ""): \(err["message"] as? String ?? "")")
        }
        fflush(stdout)
        exit(0)
    }
    let events = parseSSE(respBody)
    return processReply(events)
}

// ===== Main =====
func main() {
    let args = CommandLine.arguments
    guard args.count >= 3 else { exit(1) }
    let dataDir = args[1]
