function getOffsetAtTime(data: TZifData, t: number): { offset: number; abbr: string; isdst: number } {
  const { transitions, typeIndices, types, abbrs, footer } = data;

  if (transitions.length === 0) {
    return { offset: types[0].offset, abbr: abbrs[0], isdst: types[0].isdst };
  }

  if (t < transitions[0]) {
    return { offset: types[0].offset, abbr: abbrs[0], isdst: types[0].isdst };
  }

  if (t <= transitions[transitions.length - 1]) {
    let lo = 0, hi = transitions.length - 1;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (transitions[mid] <= t) lo = mid;
      else hi = mid - 1;
    }
    const ti = typeIndices[lo];
    return { offset: types[ti].offset, abbr: abbrs[ti], isdst: types[ti].isdst };
