        case 0x5B: return parseArr()
        case 0x22: return .string(parseStr())
        case 0x74: pos += 4; return .bool(true)
        case 0x66: pos += 5; return .bool(false)
        case 0x6E: pos += 4; return .null
        default: return .number(parseNum())
        }
    }

