        }
        return v
    }

    mutating func parseNum() -> String {
        let s = pos
        while pos < bytes.count {
            let b = bytes[pos]
            if (b>=0x30&&b<=0x39)||b==0x2D||b==0x2B||b==0x2E||b==0x65||b==0x45 { pos+=1 } else { break }
        }
        return String(decoding: bytes[s..<pos], as: UTF8.self)
    }

    mutating func parseObj() -> JSONValue {
        pos += 1; var pairs: [(String,JSONValue)] = []
        skipWS()
        if pos < bytes.count && bytes[pos]==0x7D { pos+=1; return .object(pairs) }
        while true {
            skipWS(); let k = parseStr(); skipWS(); pos+=1
            let v = parseValue(); pairs.append((k,v)); skipWS()
            if pos < bytes.count && bytes[pos]==0x2C { pos+=1 } else { break }
        }
        pos+=1; return .object(pairs)
    }

    mutating func parseArr() -> JSONValue {
        pos += 1; var items: [JSONValue] = []
        skipWS()
        if pos < bytes.count && bytes[pos]==0x5D { pos+=1; return .array(items) }
        while true {
            items.append(parseValue()); skipWS()
            if pos < bytes.count && bytes[pos]==0x2C { pos+=1 } else { break }
        }
        pos+=1; return .array(items)
    }
}

func parseJSON(_ d: [UInt8]) -> JSONValue { var p = JSONParser(d); return p.parseValue() }

// ========== JSON string encoder ==========
func encStr(_ s: String) -> String {
    var r = "\""
    for u in s.unicodeScalars {
        switch u {
        case 0x22: r += "\\\""
        case 0x5C: r += "\\\\"
        case 0x08: r += "\\b"
        case 0x0C: r += "\\f"
        case 0x0A: r += "\\n"
        case 0x0D: r += "\\r"
        case 0x09: r += "\\t"
        default:
            if u.value < 0x20 { r += String(format: "\\u%04x", u.value) }
            else { r.unicodeScalars.append(u) }
        }
    }
    r += "\""
    return r
}

// ========== Extract raw bytes for a top-level key ==========
func rawForKey(_ bytes: [UInt8], key: String) -> [UInt8]? {
    var p = JSONParser(bytes)
    p.skipWS()
    guard p.pos < p.bytes.count && p.bytes[p.pos] == 0x7B else { return nil }
    p.pos += 1; p.skipWS()
    while p.pos < p.bytes.count && p.bytes[p.pos] != 0x7D {
        let k = p.parseStr(); p.skipWS(); p.pos += 1; p.skipWS()
        let s = p.pos; _ = p.parseValue(); let e = p.pos
        if k == key { return Array(bytes[s..<e]) }
        p.skipWS()
        if p.pos < p.bytes.count && p.bytes[p.pos]==0x2C { p.pos+=1 }
        p.skipWS()
    }
    return nil
}

// ========== Extract raw text of choices[0].message ==========
func rawMessage(_ bytes: [UInt8]) -> String {
    guard let cRaw = rawForKey(bytes, key: "choices") else { fatalError("no choices") }
    var p = JSONParser(cRaw)
    p.skipWS()
    guard p.bytes[p.pos]==0x5B else { fatalError() }
    p.pos+=1; p.skipWS()
    guard p.bytes[p.pos]==0x7B else { fatalError() }
    p.pos+=1; p.skipWS()
    while p.pos < p.bytes.count && p.bytes[p.pos] != 0x7D {
        let k = p.parseStr(); p.skipWS(); p.pos+=1; p.skipWS()
        let s = p.pos; _ = p.parseValue(); let e = p.pos
        if k == "message" { return String(decoding: cRaw[s..<e], as: UTF8.self) }
        p.skipWS()
        if p.pos < p.bytes.count && p.bytes[p.pos]==0x2C { p.pos+=1 }
        p.skipWS()
    }
    fatalError("no message")
}

// ========== CSV Parser ==========
func parseCSV(_ data: [UInt8]) -> [[String]] {
    var recs: [[String]] = []
    var i = 0
    if data.count>=3 && data[0]==0xEF && data[1]==0xBB && data[2]==0xBF { i=3 }
    while i < data.count {
        var fields: [[UInt8]] = []
        var f: [UInt8] = []
        while true {
            if i < data.count && data[i]==0x22 {
                i+=1
                while i < data.count {
                    if data[i]==0x22 {
                        if i+1<data.count && data[i+1]==0x22 { f.append(0x22); i+=2 }
                        else { i+=1; break }
                    } else { f.append(data[i]); i+=1 }
                }
            } else {
                while i<data.count && data[i]!=0x2C && data[i]!=0x0D && data[i]!=0x0A {
                    f.append(data[i]); i+=1
                }
            }
            fields.append(f)
            if i<data.count && data[i]==0x2C { i+=1; continue }
            if i<data.count && data[i]==0x0D { i+=1; if i<data.count && data[i]==0x0A { i+=1 } }
            else if i<data.count && data[i]==0x0A { i+=1 }
            break
        }
        recs.append(fields.map { String(decoding: $0, as: UTF8.self) })
    }
    return recs
}

// ========== HTTP POST ==========
func httpPost(urlStr: String, body: Data, apiKey: String) -> (Int, Data) {
    let url = URL(string: urlStr)!
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    req.setValue("application/json", forHTTPHeaderField: "Content-Type")
    req.httpBody = body
    let sem = DispatchSemaphore(value: 0)
    var code = 0
    var resp = Data()
    URLSession.shared.dataTask(with: req) { d, r, _ in
        if let h = r as? HTTPURLResponse { code = h.statusCode }
        if let d = d { resp = d }
        sem.signal()
    }.resume()
    sem.wait()
    return (code, resp)
}

