            } else if c == "\"" {
                idx = text.index(after: idx)
                break
            } else {
                raw.append(c)
                idx = text.index(after: idx)
            }
        }
        results.append(raw)
        searchFrom = idx
    }
    return results
}

// RFC 4180 CSV parser
func parseCSV(_ data: Data) -> [[String]] {
    var bytes = [UInt8](data)
    if bytes.count >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF {
        bytes = Array(bytes[3...])
    }
    let text = String(decoding: bytes, as: UTF8.self)
    var records: [[String]] = []
    var rec: [String] = []
    var field = ""
    var inQ = false
    var i = text.startIndex
    while i < text.endIndex {
        let c = text[i]
        if inQ {
            if c == "\"" {
                let n = text.index(after: i)
                if n < text.endIndex && text[n] == "\"" {
                    field.append("\""); i = text.index(after: n)
                } else {
                    inQ = false; i = n
                }
            } else {
                field.append(c); i = text.index(after: i)
            }
        } else {
            if c == "\"" { inQ = true; i = text.index(after: i) }
            else if c == "," { rec.append(field); field = ""; i = text.index(after: i) }
            else if c == "\r" {
                let n = text.index(after: i)
                if n < text.endIndex && text[n] == "\n" { i = text.index(after: n) } else { i = n }
                rec.append(field); field = ""; records.append(rec); rec = []
            }
            else if c == "\n" {
                rec.append(field); field = ""; records.append(rec); rec = []
                i = text.index(after: i)
            }
            else { field.append(c); i = text.index(after: i) }
        }
    }
    if !field.isEmpty || !rec.isEmpty { rec.append(field); records.append(rec) }
    return records
}

