struct BufReader {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
}

impl BufReader {
    fn new(stream: TcpStream) -> Self { BufReader { stream, buf: Vec::new(), pos: 0 } }
    fn fill(&mut self) -> bool {
        self.buf.drain(..self.pos);
        self.pos = 0;
        let mut tmp = [0u8; 65536];
        match self.stream.read(&mut tmp) {
            Ok(0) => false,
            Ok(n) => { self.buf.extend_from_slice(&tmp[..n]); true }
            Err(_) => false,
        }
    }
    fn read_byte(&mut self) -> Option<u8> {
        if self.pos >= self.buf.len() { if !self.fill() { return None; } }
        let b = self.buf[self.pos]; self.pos += 1; Some(b)
    }
    fn read_exact(&mut self, n: usize) -> Option<Vec<u8>> {
        let mut r = Vec::with_capacity(n);
        while r.len() < n {
            if self.pos >= self.buf.len() { if !self.fill() { return None; } }
            let avail = self.buf.len() - self.pos;
            let need = n - r.len();
            let take = if avail < need { avail } else { need };
            r.extend_from_slice(&self.buf[self.pos..self.pos+take]);
            self.pos += take;
        }
        Some(r)
    }
    fn read_line(&mut self) -> Option<Vec<u8>> {
        let mut line = Vec::new();
        loop {
            match self.read_byte() {
                Some(b'\n') => { if line.last() == Some(&b'\r') { line.pop(); } return Some(line); }
                Some(b) => line.push(b),
                None => return None,
            }
        }
    }
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash = rest.find('/').unwrap_or(rest.len());
    let hp = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "/" };
    let colon = hp.rfind(':').unwrap();
    let host = hp[..colon].to_string();
    let port: u16 = hp[colon+1..].parse().unwrap();
    (host, port, path.to_string())
}

fn send_frame(stream: &mut TcpStream, opcode: u8, payload: &[u8]) {
    let mut mk = random_bytes(4);
    while mk == [0,0,0,0] { mk = random_bytes(4); }
    let mut frame = Vec::new();
    frame.push(0x80 | opcode);
    let len = payload.len();
    if len < 126 { frame.push(0x80 | len as u8); }
    else if len < 65536 { frame.push(0x80 | 126); frame.extend_from_slice(&(len as u16).to_be_bytes()); }
    else { frame.push(0x80 | 127); frame.extend_from_slice(&(len as u64).to_be_bytes()); }
    frame.extend_from_slice(&mk);
    for (i, &b) in payload.iter().enumerate() { frame.push(b ^ mk[i % 4]); }
    let _ = stream.write_all(&frame);
}

