      return line.substring(ci + 1).trim();
    }
  }
  return null;
}

async function handleSession(url: string): Promise<void> {
  const { host, port, path } = parseUrl(url);
  let socket: net.Socket;
  try {
    socket = net.createConnection(port, host);
    await new Promise<void>((resolve, reject) => {
      socket.on('connect', resolve);
      socket.on('error', reject);
    });
  } catch {
    return;
  }

  const bs = new BufferedSocket(socket);
  const wsKey = crypto.randomBytes(16).toString('base64');

  const req = `GET ${path} HTTP/1.1\r\nHost: ${host}:${port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${wsKey}\r\n\r\n`;
  socket.write(req);

  let respHeaders: string;
  try { respHeaders = await bs.readUntilDoubleCRLF(); }
  catch { socket.destroy(); return; }

  const lines = respHeaders.split('\r\n');
  const statusLine = lines[0];
  const sp = statusLine.split(' ');
  const statusCode = parseInt(sp[1], 10);
  const reasonPhrase = sp.slice(2).join(' ');

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
    socket.destroy();
    return;
  }

  const accept = getHeader(lines, 'sec-websocket-accept');
  const expected = crypto.createHash('sha1')
    .update(wsKey + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');

  if (!accept || accept !== expected) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  // Command loop
  let hasSentClose = false;
  let byeReceived = false;
  let msgOpcode = -1;
  let msgPayload: Buffer[] = [];
  let waitingSha1Bin = false;
  let sha1BinStarted = false;
  let sha1BinPayload: Buffer[] = [];

  while (true) {
    let frame: { fin: boolean; opcode: number; payload: Buffer };
    try { frame = await readFrame(bs); }
    catch { break; }

    // Control frames
    if (frame.opcode === 9) {
      socket.write(encodeFrame(10, frame.payload));
      continue;
    }
    if (frame.opcode === 10) { continue; }
    if (frame.opcode === 8) {
      let closeCode = 1005;
      let closeReason = '';
      if (frame.payload.length >= 2) {
        closeCode = frame.payload.readUInt16BE(0);
        closeReason = frame.payload.subarray(2).toString('utf8');
      }
      if (!hasSentClose) {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(closeCode);
        socket.write(encodeFrame(8, cp));
        hasSentClose = true;
      }
      console.log(closeReason ? `closed ${closeCode} ${closeReason}` : `closed ${closeCode}`);
      socket.destroy();
      return;
    }

    // Waiting for SHA1 binary payload
    if (waitingSha1Bin) {
      if (frame.opcode === 2) {
        sha1BinStarted = true;
        sha1BinPayload = [frame.payload];
      } else if (frame.opcode === 0 && sha1BinStarted) {
        sha1BinPayload.push(frame.payload);
      }
      if (frame.fin && sha1BinStarted) {
        const bin = Buffer.concat(sha1BinPayload);
        const hash = crypto.createHash('sha1').update(bin).digest('hex');
        socket.write(encodeFrame(1, Buffer.from(hash, 'utf8')));
        console.log(`SHA1 ${bin.length} -> ${hash}`);
        waitingSha1Bin = false;
        sha1BinStarted = false;
        sha1BinPayload = [];
      }
      continue;
    }

    // Data frames
    if (frame.opcode === 1 || frame.opcode === 2) {
      msgOpcode = frame.opcode;
      msgPayload = [frame.payload];
    } else if (frame.opcode === 0) {
      msgPayload.push(frame.payload);
    }

    if (frame.fin && msgOpcode !== -1) {
      const full = Buffer.concat(msgPayload);
      const op = msgOpcode;
      msgOpcode = -1;
      msgPayload = [];

      if (byeReceived) continue;

      if (op === 1) {
        const text = full.toString('utf8');
        if (text.startsWith('ADD ')) {
          const parts = text.split(' ');
          const sum = BigInt(parts[1]) + BigInt(parts[2]);
          socket.write(encodeFrame(1, Buffer.from(sum.toString(), 'utf8')));
          console.log(`${text} -> ${sum}`);
        } else if (text.startsWith('REV ')) {
          const input = text.substring(4);
          const rev = Array.from(input).reverse().join('');
          socket.write(encodeFrame(1, Buffer.from(rev, 'utf8')));
          console.log(`${text} -> ${rev}`);
        } else if (text === 'SHA1') {
          waitingSha1Bin = true;
          sha1BinStarted = false;
          sha1BinPayload = [];
        } else if (text === 'BYE') {
          socket.write(encodeFrame(8, Buffer.from([0x03, 0xE8])));
          hasSentClose = true;
          byeReceived = true;
        }
      }
    }
  }
  socket.destroy();
}

