            c if (c as u32) < 0x20 => { s.push_str(&format!("\\u{:04x}", c as u32)); }
            _ => s.push(c),
        }
    }
    s.push('"');
}

fn json_ser(s: &mut String, v: &JVal) {
    match v {
        JVal::Null => s.push_str("null"),
        JVal::Bool(b) => s.push_str(if *b { "true" } else { "false" }),
        JVal::Int(n) => s.push_str(&n.to_string()),
        JVal::Float(f) => {
            if *f == f.trunc() && f.abs() < 1e15 { s.push_str(&(*f as i64).to_string()); }
            else { s.push_str(&f.to_string()); }
        }
        JVal::Str(v2) => json_str(s, v2),
        JVal::Arr(items) => {
            s.push('[');
            for (i, item) in items.iter().enumerate() { if i > 0 { s.push(','); } json_ser(s, item); }
            s.push(']');
        }
        JVal::Obj(fields) => {
            s.push('{');
            for (i, (k, v2)) in fields.iter().enumerate() {
                if i > 0 { s.push(','); }
                json_str(s, k); s.push(':'); json_ser(s, v2);
            }
            s.push('}');
        }
    }
}

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let content = content.strip_prefix('\u{FEFF}').unwrap_or(content);
    let chars: Vec<char> = content.chars().collect();
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut cur_rec: Vec<String> = Vec::new();
    let mut cur_fld = String::new();
    let mut in_q = false;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if in_q {
            if c == '"' {
                if i + 1 < chars.len() && chars[i + 1] == '"' { cur_fld.push('"'); i += 2; }
                else { in_q = false; i += 1; }
            } else { cur_fld.push(c); i += 1; }
        } else {
            match c {
                '"' => { in_q = true; i += 1; }
                ',' => { cur_rec.push(std::mem::take(&mut cur_fld)); i += 1; }
                '\r' => {
                    cur_rec.push(std::mem::take(&mut cur_fld));
                    records.push(std::mem::take(&mut cur_rec));
                    i += 1;
                    if i < chars.len() && chars[i] == '\n' { i += 1; }
                }
                '\n' => {
                    cur_rec.push(std::mem::take(&mut cur_fld));
                    records.push(std::mem::take(&mut cur_rec));
                    i += 1;
                }
                _ => { cur_fld.push(c); i += 1; }
            }
        }
    }
    if !cur_fld.is_empty() || !cur_rec.is_empty() {
        cur_rec.push(cur_fld);
        records.push(cur_rec);
    }
    records
}

