fn http_post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> (u16, String) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        path, host, port, api_key, body.as_bytes().len(), body
    );
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut buf: Vec<u8> = Vec::new();
    let mut tmp = [0u8; 65536];
    loop {
        let n = stream.read(&mut tmp).unwrap();
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
        if buf.windows(4).any(|w| w == b"\r\n\r\n") { break; }
    }
    let hdr_end = buf.windows(4).position(|w| w == b"\r\n\r\n").unwrap() + 4;
    let hdr_str = std::str::from_utf8(&buf[..hdr_end]).unwrap();
    let status: u16 = hdr_str.lines().next().unwrap().split_whitespace().nth(1).unwrap().parse().unwrap();
    let cl: usize = hdr_str.lines()
        .find(|l| l.to_ascii_lowercase().starts_with("content-length:"))
        .map(|l| l[15..].trim().parse().unwrap())
        .unwrap_or(0);
    while buf.len() < hdr_end + cl {
        let n = stream.read(&mut tmp).unwrap();
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
    }
    let resp_body = String::from_utf8(buf[hdr_end..hdr_end + cl].to_vec()).unwrap();
    (status, resp_body)
}

