use std::collections::HashMap;

#[derive(Clone, Debug)]
enum JVal {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Parser { s: s.as_bytes(), i: 0 } }
    fn skip_ws(&mut self) {
        while self.i < self.s.len() && matches!(self.s[self.i], b' ' | b'\t' | b'\n' | b'\r') { self.i += 1; }
    }
    fn parse(&mut self) -> JVal { self.skip_ws(); self.parse_value() }
    fn parse_value(&mut self) -> JVal {
        self.skip_ws();
        match self.s[self.i] {
            b'"' => JVal::Str(self.parse_string()),
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b't' => { self.i += 4; JVal::Bool(true) }
            b'f' => { self.i += 5; JVal::Bool(false) }
            b'n' => { self.i += 4; JVal::Null }
            _ => self.parse_number(),
        }
    }
    fn parse_string(&mut self) -> String {
        self.i += 1;
        let mut result: Vec<u8> = Vec::new();
        while self.i < self.s.len() && self.s[self.i] != b'"' {
            if self.s[self.i] == b'\\' {
                self.i += 1;
                match self.s[self.i] {
                    b'"' => { result.push(b'"'); self.i += 1; }
                    b'\\' => { result.push(b'\\'); self.i += 1; }
                    b'/' => { result.push(b'/'); self.i += 1; }
                    b'n' => { result.push(b'\n'); self.i += 1; }
                    b'r' => { result.push(b'\r'); self.i += 1; }
                    b't' => { result.push(b'\t'); self.i += 1; }
                    b'b' => { result.push(0x08); self.i += 1; }
                    b'f' => { result.push(0x0C); self.i += 1; }
                    b'u' => {
                        self.i += 1;
                        let cp = self.parse_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.i += 1; // skip backslash
                            self.i += 1; // skip 'u'
                            let cp2 = self.parse_hex4();
                            let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                            let c = char::from_u32(combined).unwrap();
                            let mut buf = [0u8; 4];
                            result.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
                        } else {
                            let c = char::from_u32(cp).unwrap();
                            let mut buf = [0u8; 4];
                            result.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => { result.push(self.s[self.i]); self.i += 1; }
                }
            } else {
                result.push(self.s[self.i]);
                self.i += 1;
            }
        }
        self.i += 1;
        String::from_utf8(result).unwrap()
    }
    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.s[self.i];
            val = val * 16 + match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => 0,
            };
            self.i += 1;
        }
        val
    }
    fn parse_number(&mut self) -> JVal {
        let start = self.i;
        if self.s[self.i] == b'-' { self.i += 1; }
        while self.i < self.s.len() && self.s[self.i].is_ascii_digit() { self.i += 1; }
        let mut is_float = false;
        if self.i < self.s.len() && self.s[self.i] == b'.' {
            is_float = true; self.i += 1;
            while self.i < self.s.len() && self.s[self.i].is_ascii_digit() { self.i += 1; }
        }
        if self.i < self.s.len() && (self.s[self.i] == b'e' || self.s[self.i] == b'E') {
            is_float = true; self.i += 1;
            if self.i < self.s.len() && (self.s[self.i] == b'+' || self.s[self.i] == b'-') { self.i += 1; }
            while self.i < self.s.len() && self.s[self.i].is_ascii_digit() { self.i += 1; }
        }
        let ns = std::str::from_utf8(&self.s[start..self.i]).unwrap();
        if is_float { JVal::Float(ns.parse::<f64>().unwrap()) }
        else { JVal::Int(ns.parse::<i64>().unwrap()) }
    }
    fn parse_object(&mut self) -> JVal {
        self.i += 1;
        let mut fields = Vec::new();
        self.skip_ws();
        if self.i < self.s.len() && self.s[self.i] == b'}' { self.i += 1; return JVal::Obj(fields); }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.i += 1; // ':'
            let val = self.parse_value();
            fields.push((key, val));
            self.skip_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' { self.i += 1; } else { break; }
        }
        self.skip_ws();
        self.i += 1;
        JVal::Obj(fields)
    }
    fn parse_array(&mut self) -> JVal {
        self.i += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.i < self.s.len() && self.s[self.i] == b']' { self.i += 1; return JVal::Arr(items); }
        loop {
            let val = self.parse_value();
            items.push(val);
            self.skip_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' { self.i += 1; } else { break; }
        }
        self.skip_ws();
        self.i += 1;
        JVal::Arr(items)
    }
}

fn obj_get<'a>(v: &'a JVal, key: &str) -> Option<&'a JVal> {
    if let JVal::Obj(fields) = v {
        for (k, val) in fields { if k == key { return Some(val); } }
    }
    None
}

fn get_str<'a>(v: &'a JVal, key: &str) -> &'a str {
    obj_get(v, key).map_or("", |v2| if let JVal::Str(s) = v2 { s } else { "" })
}

fn get_int(v: &JVal, key: &str) -> i64 {
    obj_get(v, key).map_or(0, |v2| match v2 { JVal::Int(n) => *n, JVal::Float(f) => *f as i64, _ => 0 })
}

fn json_str(s: &mut String, v: &str) {
    s.push('"');
    for c in v.chars() {
        match c {
            '"' => s.push_str("\\\""),
            '\\' => s.push_str("\\\\"),
            '\n' => s.push_str("\\n"),
            '\r' => s.push_str("\\r"),
            '\t' => s.push_str("\\t"),
            '\u{08}' => s.push_str("\\b"),
            '\u{0C}' => s.push_str("\\f"),
            c if (c as u32) < 0x20 => { s.push_str(&format!("\\u{:04x}", c as u32)); }
            _ => s.push(c),
        }
    }
    s.push('"');
}

fn json_ser(s: &mut String, v: &JVal) {
    match v {
        JVal::Null => s.push_str("null"),
        JVal::Bool(b) => s.push_str(if *b { "true" } else { "false" }),
        JVal::Int(n) => s.push_str(&n.to_string()),
        JVal::Float(f) => {
            if *f == f.trunc() && f.abs() < 1e15 { s.push_str(&(*f as i64).to_string()); }
            else { s.push_str(&f.to_string()); }
        }
        JVal::Str(v2) => json_str(s, v2),
        JVal::Arr(items) => {
            s.push('[');
            for (i, item) in items.iter().enumerate() { if i > 0 { s.push(','); } json_ser(s, item); }
            s.push(']');
        }
        JVal::Obj(fields) => {
            s.push('{');
            for (i, (k, v2)) in fields.iter().enumerate() {
                if i > 0 { s.push(','); }
                json_str(s, k); s.push(':'); json_ser(s, v2);
            }
            s.push('}');
        }
    }
}

fn parse_csv(content: &str) -> Vec<Vec<String>> {
    let content = content.strip_prefix('\u{FEFF}').unwrap_or(content);
    let chars: Vec<char> = content.chars().collect();
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut cur_rec: Vec<String> = Vec::new();
    let mut cur_fld = String::new();
    let mut in_q = false;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if in_q {
            if c == '"' {
                if i + 1 < chars.len() && chars[i + 1] == '"' { cur_fld.push('"'); i += 2; }
                else { in_q = false; i += 1; }
            } else { cur_fld.push(c); i += 1; }
        } else {
            match c {
                '"' => { in_q = true; i += 1; }
                ',' => { cur_rec.push(std::mem::take(&mut cur_fld)); i += 1; }
                '\r' => {
                    cur_rec.push(std::mem::take(&mut cur_fld));
                    records.push(std::mem::take(&mut cur_rec));
                    i += 1;
                    if i < chars.len() && chars[i] == '\n' { i += 1; }
                }
                '\n' => {
                    cur_rec.push(std::mem::take(&mut cur_fld));
                    records.push(std::mem::take(&mut cur_rec));
                    i += 1;
                }
                _ => { cur_fld.push(c); i += 1; }
            }
        }
    }
    if !cur_fld.is_empty() || !cur_rec.is_empty() {
        cur_rec.push(cur_fld);
        records.push(cur_rec);
    }
    records
}

fn parse_url(url: &str) -> (String, u16, String) {
    let ws = url.strip_prefix("http://").unwrap_or(url);
    let sp = ws.find('/').unwrap_or(ws.len());
    let hp = &ws[..sp];
    let path = if sp < ws.len() { ws[sp..].to_string() } else { "/".to_string() };
    if let Some(ci) = hp.rfind(':') {
        (hp[..ci].to_string(), hp[ci + 1..].parse::<u16>().unwrap(), path)
    } else {
        (hp.to_string(), 80, path)
    }
}

fn http_post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> (u16, String) {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}:{}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
        path, host, port, api_key, body.as_bytes().len(), body
    );
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();
    let mut buf: Vec<u8> = Vec::new();
    let mut tmp = [0u8; 65536];
    loop {
        let n = stream.read(&mut tmp).unwrap();
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
        if buf.windows(4).any(|w| w == b"\r\n\r\n") { break; }
    }
    let hdr_end = buf.windows(4).position(|w| w == b"\r\n\r\n").unwrap() + 4;
    let hdr_str = std::str::from_utf8(&buf[..hdr_end]).unwrap();
    let status: u16 = hdr_str.lines().next().unwrap().split_whitespace().nth(1).unwrap().parse().unwrap();
    let cl: usize = hdr_str.lines()
        .find(|l| l.to_ascii_lowercase().starts_with("content-length:"))
        .map(|l| l[15..].trim().parse().unwrap())
        .unwrap_or(0);
    while buf.len() < hdr_end + cl {
        let n = stream.read(&mut tmp).unwrap();
        if n == 0 { break; }
        buf.extend_from_slice(&tmp[..n]);
    }
    let resp_body = String::from_utf8(buf[hdr_end..hdr_end + cl].to_vec()).unwrap();
    (status, resp_body)
}

fn execute_tool(name: &str, args_json: &str, inv: &HashMap<String, (String, i64, String, i64)>, rates: &HashMap<String, i64>) -> String {
    match name {
        "inventory_lookup" => {
            let mut p = Parser::new(args_json);
            let args = p.parse();
            let sku = get_str(&args, "sku");
            if let Some((nm, price, cur, stock)) = inv.get(sku) {
                let mut s = String::new();
                s.push('{');
                json_str(&mut s, "sku"); s.push(':'); json_str(&mut s, sku);
                s.push(','); json_str(&mut s, "name"); s.push(':'); json_str(&mut s, nm);
                s.push(','); json_str(&mut s, "price_cents"); s.push(':'); s.push_str(&price.to_string());
                s.push(','); json_str(&mut s, "currency"); s.push(':'); json_str(&mut s, cur);
                s.push(','); json_str(&mut s, "stock"); s.push(':'); s.push_str(&stock.to_string());
                s.push('}');
                s
            } else {
                let mut s = String::new();
                s.push('{');
                json_str(&mut s, "error"); s.push(':'); json_str(&mut s, &format!("unknown sku: {}", sku));
                s.push('}');
                s
            }
        }
        "convert_currency" => {
            let mut p = Parser::new(args_json);
            let args = p.parse();
            let amount = get_int(&args, "amount_cents");
            let from = get_str(&args, "from");
            let to = get_str(&args, "to");
            let rf = *rates.get(from).unwrap_or(&1000000);
            let rt = *rates.get(to).unwrap_or(&1000000);
            let converted = ((2i128 * amount as i128 * rt as i128 + rf as i128) / (2i128 * rf as i128)) as i64;
            let mut s = String::new();
            s.push('{');
            json_str(&mut s, "amount_cents"); s.push(':'); s.push_str(&converted.to_string());
            s.push(','); json_str(&mut s, "currency"); s.push(':'); json_str(&mut s, to);
            s.push('}');
            s
        }
        _ => {
            let mut s = String::new();
            s.push('{');
            json_str(&mut s, "error"); s.push(':'); json_str(&mut s, &format!("unknown tool: {}", name));
            s.push('}');
            s
        }
    }
}

