/* ── Case-insensitive header search in block ────────────────────────── */
static char *find_header(const char *block, size_t blen, const char *name, size_t *vlen) {
    size_t nlen = strlen(name);
    const char *p = block, *end = block + blen;
    while (p < end) {
        const char *nl = memchr(p, '\n', end - p);
        if (!nl) nl = end;
        const char *colon = memchr(p, ':', nl - p);
        if (colon) {
            size_t hlen = (size_t)(colon - p);
            if (hlen == nlen) {
                int ok = 1;
                for (size_t i = 0; i < nlen; i++) {
                    char a = p[i], b = name[i];
                    if (a >= 'A' && a <= 'Z') a += 32;
                    if (b >= 'A' && b <= 'Z') b += 32;
                    if (a != b) { ok = 0; break; }
                }
                if (ok) {
                    const char *vs = colon + 1;
                    while (vs < nl && (*vs == ' ' || *vs == '\t')) vs++;
                    const char *ve = nl;
                    while (ve > vs && (ve[-1] == '\r' || ve[-1] == '\n')) ve--;
                    *vlen = (size_t)(ve - vs);
                    return (char*)vs;
                }
            }
        }
        p = nl + 1;
    }
    *vlen = 0;
    return NULL;
}

