        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",
        u.path, u.host, u.port, key_b64);

    size_t sent = 0;
    while (sent < (size_t)rlen) {
        ssize_t n = write(fd, req + sent, (size_t)rlen - sent);
        if (n <= 0) { close(fd); return; }
        sent += (size_t)n;
    }

    /* Read response headers */
    RB rb; rb_init(&rb);
    int hdr_done = 0;
    size_t hdr_end = 0;
    while (!hdr_done) {
        if (rb.pos > 0) { memmove(rb.d, rb.d + rb.pos, rb.len - rb.pos); rb.len -= rb.pos; rb.pos = 0; }
        size_t nc = rb.cap;
        if (nc < 4096) nc = 4096;
        unsigned char *nd = realloc(rb.d, nc);
        if (!nd) { rb_free(&rb); close(fd); return; }
        rb.d = nd; rb.cap = nc;
        ssize_t n = read(fd, rb.d + rb.len, rb.cap - rb.len);
        if (n <= 0) { rb_free(&rb); close(fd); return; }
        rb.len += (size_t)n;
        for (size_t i = 0; i + 3 < rb.len; i++) {
            if (rb.d[i]=='\r' && rb.d[i+1]=='\n' && rb.d[i+2]=='\r' && rb.d[i+3]=='\n') {
                hdr_end = i + 4;
                hdr_done = 1;
                break;
            }
        }
    }

    /* Parse status line */
    int status_code = 0;
    char reason[256] = "";
    {
        char *status_line = (char*)rb.d;
        size_t sl_len = 0;
        for (size_t i = 0; i < hdr_end; i++) { if (rb.d[i]=='\n') { sl_len = i; break; } }
        const char *sp = strchr(status_line, ' ');
        if (sp) {
            status_code = atoi(sp + 1);
            const char *sp2 = strchr(sp + 1, ' ');
            if (sp2) {
                size_t rlen2 = (size_t)(status_line + sl_len - sp2 - 1);
                if (rlen2 >= sizeof(reason)) rlen2 = sizeof(reason) - 1;
                memcpy(reason, sp2 + 1, rlen2);
                reason[rlen2] = '\0';
                if (rlen2 > 0 && reason[rlen2-1]=='\r') reason[rlen2-1]='\0';
            }
        }
    }

    if (status_code != 101) {
        printf("handshake failed: %d %s\n", status_code, reason);
        fflush(stdout);
        rb_free(&rb); close(fd); return;
    }

    /* Validate Sec-WebSocket-Accept */
    {
        char expected[32];
        char concat[128];
        int clen = snprintf(concat, sizeof(concat), "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key_b64);
        unsigned char sha[20];
        CC_SHA1((const unsigned char*)concat, (CC_LONG)clen, sha);
        b64_encode(sha, 20, expected);

        size_t vlen;
        char *val = find_header((char*)rb.d, hdr_end, "Sec-WebSocket-Accept", &vlen);
        if (!val || vlen != 28 || memcmp(val, expected, 28) != 0) {
            printf("handshake failed: bad Sec-WebSocket-Accept\n");
            fflush(stdout);
            rb_free(&rb); close(fd); return;
        }
    }

    rb.pos = hdr_end;

    /* ── Frame processing loop ── */
    int sent_close = 0;
    int bye_sent = 0;
    int pending_sha1 = 0;

    int msg_active = 0;
    int msg_opcode = 0;
    unsigned char *msg_buf = NULL;
    size_t msg_len = 0, msg_cap = 0;

    while (1) {
        int fin, opcode;
        unsigned char *payload;
        size_t plen;
        if (ws_read_frame(fd, &rb, &fin, &opcode, &payload, &plen)) break;

        if (opcode == 9) { /* ping */
            ws_send_frame(fd, 10, payload, plen);
            continue;
        }
        if (opcode == 10) { /* pong */
            continue;
        }
        if (opcode == 8) { /* close */
            int code = 1005;
            size_t rl = 0;
            const unsigned char *rptr = NULL;
            if (plen >= 2) {
                code = ((int)payload[0] << 8) | payload[1];
                if (plen > 2) {
                    rl = plen - 2;
                    rptr = payload + 2;
                }
            }
            if (rl > 0)
                printf("closed %d %.*s\n", code, (int)rl, rptr);
            else
                printf("closed %d\n", code);
            fflush(stdout);
            if (!sent_close) {
                unsigned char cp[2] = { (unsigned char)(code >> 8), (unsigned char)(code & 0xFF) };
                ws_send_frame(fd, 8, cp, 2);
            }
            break;
        }

        if (opcode == 1 || opcode == 2) {
            /* start new message */
            msg_active = 1;
            msg_opcode = opcode;
            msg_cap = plen + 1;
            msg_buf = malloc(msg_cap);
            msg_len = 0;
            if (plen > 0) { memcpy(msg_buf, payload, plen); msg_len = plen; }
            if (fin) {
                int bye = process_message(fd, msg_opcode, msg_buf, msg_len, &pending_sha1);
                free(msg_buf); msg_buf = NULL; msg_active = 0;
                if (bye) { sent_close = 1; bye_sent = 1; }
            }
            continue;
        }
        if (opcode == 0) { /* continuation */
            if (!msg_active) continue;
            if (msg_len + plen + 1 > msg_cap) {
                msg_cap = msg_len + plen + 1;
                msg_buf = realloc(msg_buf, msg_cap);
            }
            if (plen > 0) { memcpy(msg_buf + msg_len, payload, plen); msg_len += plen; }
            if (fin) {
                int bye = process_message(fd, msg_opcode, msg_buf, msg_len, &pending_sha1);
                free(msg_buf); msg_buf = NULL; msg_active = 0;
                if (bye) { sent_close = 1; bye_sent = 1; }
            }
            continue;
        }
    }

    if (msg_buf) free(msg_buf);
    rb_free(&rb);
    close(fd);
}

