            } else {
                long W = wallToSec(val);
                Set<Integer> offs = new LinkedHashSet<>();
                for (TypeRecord tr : tz.types) offs.add(tr.utcOffset);
                offs.add(rule.stdOffset);
                if (rule.hasDst) offs.add(rule.dstOffset);

                TreeMap<Long, TypeRecord> sols = new TreeMap<>();
                for (int off : offs) {
                    long t = W - off;
                    TypeRecord tr = getOffsetAt(tz, rule, t);
                    if (tr.utcOffset == off) {
                        sols.put(t, tr);
                    }
                }

                if (sols.size() == 1) {
                    Map.Entry<Long, TypeRecord> e = sols.firstEntry();
                    System.out.println(q + " -> " + e.getKey() + " " + fmtOffset(e.getValue().utcOffset) + " " + e.getValue().abbr);
                } else if (sols.size() >= 2) {
                    Iterator<Map.Entry<Long, TypeRecord>> it = sols.entrySet().iterator();
                    Map.Entry<Long, TypeRecord> e1 = it.next();
                    Map.Entry<Long, TypeRecord> e2 = it.next();
                    System.out.println(q + " -> " + e1.getKey() + " " + fmtOffset(e1.getValue().utcOffset) + " " + e1.getValue().abbr
                            + " | " + e2.getKey() + " " + fmtOffset(e2.getValue().utcOffset) + " " + e2.getValue().abbr);
                } else {
                    boolean found = false;
                    int oldOff = 0;
                    for (int i = 0; i < tz.transitions.size() && !found; i++) {
                        Transition tr = tz.transitions.get(i);
                        int newOff = tz.types.get(tr.typeIndex).utcOffset;
                        int prevOff = (i == 0) ? tz.types.get(0).utcOffset : tz.types.get(tz.transitions.get(i - 1).typeIndex).utcOffset;
                        if (newOff > prevOff) {
                            if (W >= tr.time + prevOff && W < tr.time + newOff) { oldOff = prevOff; found = true; }
                        }
                    }
                    if (!found && rule.hasDst) {
                        int yr = yearFromUnix(W);
                        for (int y = yr - 1; y <= yr + 1 && !found; y++) {
                            long st = footerTrans(rule, y, true);
                            long en = footerTrans(rule, y, false);
                            if (rule.dstOffset > rule.stdOffset) {
                                if (W >= st + rule.stdOffset && W < st + rule.dstOffset) { oldOff = rule.stdOffset; found = true; }
                            }
                            if (rule.stdOffset > rule.dstOffset) {
                                if (W >= en + rule.dstOffset && W < en + rule.stdOffset) { oldOff = rule.dstOffset; found = true; }
                            }
                        }
                    }
                    long t = W - oldOff;
                    TypeRecord tr = getOffsetAt(tz, rule, t);
                    System.out.println(q + " -> GAP " + t + " " + fmtLocal(t, tr.utcOffset) + fmtOffset(tr.utcOffset) + " " + tr.abbr);
                }
            }
        }
    }
