        int[] typeIdx = new int[timecnt2];
        for (int i = 0; i < timecnt2; i++) { typeIdx[i] = data[pos] & 0xFF; pos += 1; }

        int[] utcOffsets = new int[typecnt2];
        boolean[] isDsts = new boolean[typecnt2];
        int[] abbrIdxs = new int[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            utcOffsets[i] = readInt32(data, pos); pos += 4;
            isDsts[i] = (data[pos] & 0xFF) != 0; pos += 1;
            abbrIdxs[i] = data[pos] & 0xFF; pos += 1;
        }

        int abbrStart = pos;
        pos += charcnt2;
        pos += leapcnt2 * 12;
        pos += isstdcnt2;
        pos += isutcnt2;

        pos++;
        int fs = pos;
        while (pos < data.length && data[pos] != '\n') pos++;
        String footer = new String(data, fs, pos - fs, java.nio.charset.StandardCharsets.US_ASCII);

        TzData tz = new TzData();
        tz.transitions = new ArrayList<>();
        for (int i = 0; i < timecnt2; i++) tz.transitions.add(new Transition(times[i], typeIdx[i]));
        tz.types = new ArrayList<>();
        for (int i = 0; i < typecnt2; i++) {
            int ae = abbrStart + abbrIdxs[i];
            while (ae < data.length && data[ae] != 0) ae++;
            String abbr = new String(data, abbrStart + abbrIdxs[i], ae - abbrStart - abbrIdxs[i], java.nio.charset.StandardCharsets.US_ASCII);
            tz.types.add(new TypeRecord(utcOffsets[i], isDsts[i], abbr));
        }
        tz.footer = footer;
        return tz;
    }

    static PosixRule parsePosix(String s) {
        PosixRule r = new PosixRule();
        int pos = 0, len = s.length();
        if (pos < len && s.charAt(pos) == '<') {
            int e = s.indexOf('>', pos);
            r.stdName = s.substring(pos + 1, e); pos = e + 1;
        } else {
            int st = pos;
            while (pos < len && Character.isLetter(s.charAt(pos))) pos++;
            r.stdName = s.substring(st, pos);
        }
        int[] ro = parseOffset(s, pos);
        r.stdOffset = -ro[0]; pos = ro[1];

        if (pos >= len) { r.hasDst = false; r.dstName = null; r.dstOffset = r.stdOffset; return r; }

        if (s.charAt(pos) == '<') {
            int e = s.indexOf('>', pos);
            r.dstName = s.substring(pos + 1, e); pos = e + 1;
        } else {
            int st = pos;
            while (pos < len && Character.isLetter(s.charAt(pos))) pos++;
            r.dstName = s.substring(st, pos);
        }
        r.hasDst = true;

        if (pos < len && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
            ro = parseOffset(s, pos);
            r.dstOffset = -ro[0]; pos = ro[1];
        } else {
            r.dstOffset = r.stdOffset + 3600;
        }

        if (pos < len && s.charAt(pos) == ',') {
            pos++;
            int[] sr = parseRule(s, pos);
            r.startMonth = sr[0]; r.startWeek = sr[1]; r.startDay = sr[2]; r.startTime = sr[3]; pos = sr[4];
            pos++;
            int[] er = parseRule(s, pos);
            r.endMonth = er[0]; r.endWeek = er[1]; r.endDay = er[2]; r.endTime = er[3];
        } else {
            r.startMonth = 3; r.startWeek = 2; r.startDay = 0; r.startTime = 2 * 3600;
            r.endMonth = 11; r.endWeek = 1; r.endDay = 0; r.endTime = 2 * 3600;
        }
        return r;
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) {
            if (s.charAt(pos) == '-') sign = -1;
            pos++;
        }
        int h = 0, m = 0, sec = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) h = h * 10 + (s.charAt(pos++) - '0');
        if (pos < s.length() && s.charAt(pos) == ':') { pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
            if (pos < s.length() && s.charAt(pos) == ':') { pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) sec = sec * 10 + (s.charAt(pos++) - '0');
            }
        }
        return new int[]{sign * (h * 3600 + m * 60 + sec), pos};
    }

    static int[] parseRule(String s, int pos) {
        pos++;
        int m = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
        pos++;
        int w = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) w = w * 10 + (s.charAt(pos++) - '0');
        pos++;
        int d = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) d = d * 10 + (s.charAt(pos++) - '0');
        int time = 2 * 3600;
        if (pos < s.length() && s.charAt(pos) == '/') { pos++; int[] tr = parseOffset(s, pos); time = tr[0]; pos = tr[1]; }
        return new int[]{m, w, d, time, pos};
    }

    static int dayOfMonth(int year, int month, int week, int dow) {
        LocalDate first = LocalDate.of(year, month, 1);
        int firstDow = first.getDayOfWeek().getValue() % 7;
        int off = (dow - firstDow + 7) % 7;
        int firstOcc = 1 + off;
        if (week == 5) {
            return firstOcc + 7 * ((first.lengthOfMonth() - firstOcc) / 7);
        }
        return firstOcc + 7 * (week - 1);
    }

    static TypeRecord getOffsetAt(TzData tz, PosixRule rule, long t) {
        List<Transition> tr = tz.transitions;
        if (tr.isEmpty()) return getFooterType(rule, t);
        if (t < tr.get(0).time) return tz.types.get(0);
        if (t > tr.get(tr.size() - 1).time) return getFooterType(rule, t);
        int lo = 0, hi = tr.size() - 1;
        while (lo < hi) { int mid = (lo + hi + 1) / 2; if (tr.get(mid).time <= t) lo = mid; else hi = mid - 1; }
        return tz.types.get(tr.get(lo).typeIndex);
    }

    static TypeRecord getFooterType(PosixRule rule, long t) {
        if (!rule.hasDst) return new TypeRecord(rule.stdOffset, false, rule.stdName);
        int year = yearFromUnix(t);
        for (int y = year - 1; y <= year + 1; y++) {
            long st = footerTrans(rule, y, true);
            long en = footerTrans(rule, y, false);
            if (st < en) {
                if (t >= st && t < en) return new TypeRecord(rule.dstOffset, true, rule.dstName);
            } else {
                if (t >= st || t < en) return new TypeRecord(rule.dstOffset, true, rule.dstName);
            }
        }
        return new TypeRecord(rule.stdOffset, false, rule.stdName);
    }

    static long footerTrans(PosixRule rule, int year, boolean start) {
        int mo, wk, dy, tm, off;
        if (start) { mo = rule.startMonth; wk = rule.startWeek; dy = rule.startDay; tm = rule.startTime; off = rule.stdOffset; }
        else { mo = rule.endMonth; wk = rule.endWeek; dy = rule.endDay; tm = rule.endTime; off = rule.dstOffset; }
        int dom = dayOfMonth(year, mo, wk, dy);
        long midnight = LocalDate.of(year, mo, dom).toEpochDay() * 86400L;
        return midnight + tm - off;
    }

    static int yearFromUnix(long t) {
        return LocalDateTime.ofInstant(Instant.ofEpochSecond(t), ZoneOffset.UTC).getYear();
    }

    static String fmtOffset(int off) {
        int sign = off >= 0 ? 1 : -1;
        int a = Math.abs(off);
        int h = a / 3600, m = (a % 3600) / 60, s = a % 60;
        String p = sign >= 0 ? "+" : "-";
        if (s != 0) return String.format("%s%02d:%02d:%02d", p, h, m, s);
        return String.format("%s%02d:%02d", p, h, m);
    }

    static String fmtLocal(long unix, int off) {
        long ls = unix + off;
        long days = ls / 86400;
        long rem = ls % 86400;
        if (rem < 0) { days--; rem += 86400; }
        LocalDate d = LocalDate.ofEpochDay(days);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", d.getYear(), d.getMonthValue(), d.getDayOfMonth(),
                (int) (rem / 3600), (int) (rem % 3600 / 60), (int) (rem % 60));
    }

    static long wallToSec(String s) {
        int y = Integer.parseInt(s.substring(0, 4)), mo = Integer.parseInt(s.substring(5, 7)), d = Integer.parseInt(s.substring(8, 10));
        int h = Integer.parseInt(s.substring(11, 13)), mi = Integer.parseInt(s.substring(14, 16)), se = Integer.parseInt(s.substring(17, 19));
        return LocalDate.of(y, mo, d).toEpochDay() * 86400L + h * 3600L + mi * 60L + se;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> queries = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(dir + "/queries.txt"))) {
            String line;
            while ((line = br.readLine()) != null) if (!line.trim().isEmpty()) queries.add(line);
        }

        Map<String, TzData> tzCache = new HashMap<>();
        Map<String, PosixRule> ruleCache = new HashMap<>();

        for (String q : queries) {
            String[] p = q.split(" ");
            String type = p[0], file = p[1], val = p[2];

            if (!tzCache.containsKey(file)) {
                TzData tz = parseTzif(dir + "/" + file);
                tzCache.put(file, tz);
                ruleCache.put(file, parsePosix(tz.footer));
            }
            TzData tz = tzCache.get(file);
            PosixRule rule = ruleCache.get(file);

            if (type.equals("UTC")) {
                long t = Long.parseLong(val);
                TypeRecord tr = getOffsetAt(tz, rule, t);
                System.out.println(q + " -> " + fmtLocal(t, tr.utcOffset) + fmtOffset(tr.utcOffset) + " " + tr.abbr);
            } else {
                long W = wallToSec(val);
                Set<Integer> offs = new LinkedHashSet<>();
                for (TypeRecord tr : tz.types) offs.add(tr.utcOffset);
                offs.add(rule.stdOffset);
                if (rule.hasDst) offs.add(rule.dstOffset);

                TreeMap<Long, TypeRecord> sols = new TreeMap<>();
                for (int off : offs) {
                    long t = W - off;
                    TypeRecord tr = getOffsetAt(tz, rule, t);
                    if (tr.utcOffset == off) {
                        sols.put(t, tr);
                    }
                }

                if (sols.size() == 1) {
                    Map.Entry<Long, TypeRecord> e = sols.firstEntry();
                    System.out.println(q + " -> " + e.getKey() + " " + fmtOffset(e.getValue().utcOffset) + " " + e.getValue().abbr);
                } else if (sols.size() >= 2) {
                    Iterator<Map.Entry<Long, TypeRecord>> it = sols.entrySet().iterator();
                    Map.Entry<Long, TypeRecord> e1 = it.next();
                    Map.Entry<Long, TypeRecord> e2 = it.next();
                    System.out.println(q + " -> " + e1.getKey() + " " + fmtOffset(e1.getValue().utcOffset) + " " + e1.getValue().abbr
                            + " | " + e2.getKey() + " " + fmtOffset(e2.getValue().utcOffset) + " " + e2.getValue().abbr);
                } else {
                    boolean found = false;
                    int oldOff = 0;
                    for (int i = 0; i < tz.transitions.size() && !found; i++) {
                        Transition tr = tz.transitions.get(i);
                        int newOff = tz.types.get(tr.typeIndex).utcOffset;
                        int prevOff = (i == 0) ? tz.types.get(0).utcOffset : tz.types.get(tz.transitions.get(i - 1).typeIndex).utcOffset;
                        if (newOff > prevOff) {
                            if (W >= tr.time + prevOff && W < tr.time + newOff) { oldOff = prevOff; found = true; }
                        }
                    }
                    if (!found && rule.hasDst) {
                        int yr = yearFromUnix(W);
                        for (int y = yr - 1; y <= yr + 1 && !found; y++) {
                            long st = footerTrans(rule, y, true);
                            long en = footerTrans(rule, y, false);
                            if (rule.dstOffset > rule.stdOffset) {
                                if (W >= st + rule.stdOffset && W < st + rule.dstOffset) { oldOff = rule.stdOffset; found = true; }
                            }
                            if (rule.stdOffset > rule.dstOffset) {
                                if (W >= en + rule.dstOffset && W < en + rule.stdOffset) { oldOff = rule.dstOffset; found = true; }
                            }
                        }
                    }
                    long t = W - oldOff;
                    TypeRecord tr = getOffsetAt(tz, rule, t);
                    System.out.println(q + " -> GAP " + t + " " + fmtLocal(t, tr.utcOffset) + fmtOffset(tr.utcOffset) + " " + tr.abbr);
                }
            }
        }
    }
