static void free_tzif(tzif_t*tz){
    free(tz->trans);free(tz->types);free(tz->utc_offset);
    free(tz->isdst);free(tz->abbr_idx);free(tz->abbrs);
}

static void footer_offset_abbr(int64_t t,tzif_t*tz,int*offset,char*abbr){
    if(!tz->has_dst||!tz->has_rules){
        *offset=tz->std_utc_offset;strcpy(abbr,tz->std_name);return;
    }
    int y,mo,d,h,mi,s;
    unix_to_ymd(t,&y,&mo,&d,&h,&mi,&s);
    int dom_s=mwd_to_dom(y,tz->start_m,tz->start_w,tz->start_d);
    int dom_e=mwd_to_dom(y,tz->end_m,tz->end_w,tz->end_d);
    int64_t su=days_from_epoch(y,tz->start_m,dom_s)*86400+tz->start_time_sec-tz->std_utc_offset;
    int64_t eu=days_from_epoch(y,tz->end_m,dom_e)*86400+tz->end_time_sec-tz->dst_utc_offset;
    int in_dst;
    if(su<eu)in_dst=(t>=su&&t<eu);
    else in_dst=(t>=su||t<eu);
    if(in_dst){*offset=tz->dst_utc_offset;strcpy(abbr,tz->dst_name);}
    else{*offset=tz->std_utc_offset;strcpy(abbr,tz->std_name);}
}

static void get_offset_abbr(int64_t t,tzif_t*tz,int*offset,char*abbr){
    if(tz->timecnt==0){footer_offset_abbr(t,tz,offset,abbr);return;}
    if(t<tz->trans[0]){
        *offset=tz->utc_offset[0];strcpy(abbr,tz->abbrs+tz->abbr_idx[0]);return;}
    if(t>tz->trans[tz->timecnt-1]){footer_offset_abbr(t,tz,offset,abbr);return;}
    int lo=0,hi=tz->timecnt-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->trans[mid]<=t)lo=mid;else hi=mid-1;}
    int ti=tz->types[lo];
    *offset=tz->utc_offset[ti];strcpy(abbr,tz->abbrs+tz->abbr_idx[ti]);
}

